-- quest_extra.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[3861] = {id=3861,name="CLUCK!",level=1,requiredLevel=1,faction="both",expansion=1,zoneID=3703,description="\"Cluck... cluck... cluck... BACAW! Cluck... cluck... cluck.\" The chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.",starts={{npcID=620,x=0.776,y=0.444,zoneID=10},{npcID=620,x=0.428,y=0.656,zoneID=12},{npcID=620,x=0.662,y=0.472,zoneID=17},{npcID=620,x=0.56,y=0.316,zoneID=40},{npcID=620,x=0.21,y=0.43,zoneID=44},{npcID=620,x=0.59,y=0.504,zoneID=85},{npcID=620,x=0.306,y=0.422,zoneID=495},{npcID=620,x=0.47,y=0.702,zoneID=3524},{npcID=620,x=0.59,y=0.694,zoneID=3703}},ends={{npcID=620,x=0.776,y=0.444,zoneID=10},{npcID=620,x=0.428,y=0.656,zoneID=12},{npcID=620,x=0.662,y=0.472,zoneID=17},{npcID=620,x=0.56,y=0.316,zoneID=40},{npcID=620,x=0.21,y=0.43,zoneID=44},{npcID=620,x=0.59,y=0.504,zoneID=85},{npcID=620,x=0.306,y=0.422,zoneID=495},{npcID=620,x=0.47,y=0.702,zoneID=3524},{npcID=620,x=0.59,y=0.694,zoneID=3703}},coords={x=0.776,y=0.444,source="quest_giver",zoneID=10},questType="standard"},
[8325] = {id=8325,name="Reclaiming Sunstrider Isle",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=6455,description="The sooner you begin your education, , the better for us all. There is little room for error, so listen closely. The Burning Crystals - the green floating objects to the west of the Sunspire here - have long been used to power the isle's experimentations. The mana wyrms were their guardians, but the Scourge invasion of Quel'Thalas has driven them errant from our lack of magical control over them. There is little choice but to thin their numbers for reclamation. Do this, then return to me.",starts={{npcID=15278,x=0.38,y=0.21,zoneID=3430},{npcID=15278,x=0.61,y=0.452,zoneID=6455}},ends={{npcID=15278,x=0.38,y=0.21,zoneID=3430},{npcID=15278,x=0.61,y=0.452,zoneID=6455}},coords={x=0.38,y=0.21,source="quest_giver",zoneID=3430},questType="standard"},
[8326] = {id=8326,name="Unfortunate Measures",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=6455,description="Your effort has made something clear that, honestly, I wish were not true. The unchecked power of the Burning Crystals has maligned a much larger swath of the isle's natural balance than I thought. We must now take on more unfortunate measures to reclaim control. The nearby lynxes have succumbed to the influence of the crystals, and they must be put down. Bring their collars, , as I may yet be able to fashion a magical restraint to turn some back from being uncontrolled.",starts={{npcID=15278,x=0.38,y=0.21,zoneID=3430},{npcID=15278,x=0.61,y=0.452,zoneID=6455}},ends={{npcID=15278,x=0.38,y=0.21,zoneID=3430},{npcID=15278,x=0.61,y=0.452,zoneID=6455}},coords={x=0.38,y=0.21,source="quest_giver",zoneID=3430},questType="standard"},
[8327] = {id=8327,name="Report to Lanthan Perilon",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=6455,description="You are to report to my assistant, Lanthan Perilon . He will instruct you on what needs to be done next. While we here at the Sunspire will continue to rein in the Burning Crystals, you will be focused on a more pressing matter concerning Falthrien Academy. Lanthan will explain fully when you speak to him. Simply walk west of here along the path, and you should see him standing close by. Good luck, - your continued successes shall be rewarded.",starts={{npcID=15278,x=0.38,y=0.21,zoneID=3430},{npcID=15278,x=0.61,y=0.452,zoneID=6455}},ends={{npcID=15281,x=0.354,y=0.224,zoneID=3430},{npcID=15281,x=0.528,y=0.496,zoneID=6455}},coords={x=0.38,y=0.21,source="quest_giver",zoneID=3430},questType="standard"},
[8334] = {id=8334,name="Aggression",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=6455,description="Before sending you to the Academy, I want you on another task that needs to be dealt with immediately. Once used to aid us in the gardening of Sunstrider Isle , the bestial tenders now have grown out of our control. Clear them out with due haste, but be warned - their lack of control has made them aggressive. It is such aggression that forces us to put down these once-gentle servants. It doesn't please me to ask you to do such a task, but survival is survival. I'll mourn later.",starts={{npcID=15281,x=0.354,y=0.224,zoneID=3430},{npcID=15281,x=0.528,y=0.496,zoneID=6455}},ends={{npcID=15281,x=0.354,y=0.224,zoneID=3430},{npcID=15281,x=0.528,y=0.496,zoneID=6455}},coords={x=0.354,y=0.224,source="quest_giver",zoneID=3430},questType="standard"},
[8335] = {id=8335,name="Felendren the Banished",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=6455,description="A betrayer of our people resides atop Falthrien Academy to the southwest. Felendren is his name, and he was banished from blood elf lands for failing to heed the warnings of our teachers and elders. He is the worst of our society, as he lives only to feed his insatiable magical addictions. He refused to learn control; he is a shell of his former self - one of the Wretched - and he is a threat to the Sunspire. Destroy him and the wraiths he uses as minions.",starts={{npcID=15281,x=0.354,y=0.224,zoneID=3430},{npcID=15281,x=0.528,y=0.496,zoneID=6455}},ends={{npcID=15281,x=0.354,y=0.224,zoneID=3430},{npcID=15281,x=0.528,y=0.496,zoneID=6455}},coords={x=0.354,y=0.224,source="quest_giver",zoneID=3430},questType="standard"},
[8338] = {id=8338,name="Tainted Arcane Sliver",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=6455,description="You've found an odd sliver of crystallized mana on the corpse of the tainted arcane wraith. The sliver is different than others you may have seen in that it is as dark and sinister-looking as the wraith you looted it from. Just holding it gives you a sense of unnatural foreboding. Arcanist Helion at the gazebo of the Sunspire on Sunstrider Isle just might be someone who would have a use for the sliver.",ends={{npcID=15297,x=0.372,y=0.19,zoneID=3430},{npcID=15297,x=0.586,y=0.388,zoneID=6455}},questType="standard"},
[8347] = {id=8347,name="Aiding the Outrunners",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=6455,description="Magistrix Erona wanted you to head over to Silvermoon City in order to aid our reclamation efforts there... that is, once you had successfully addressed the situation at Falthrien Academy. You did not disappoint us, . On your way to Falconwing Square, south of here, you should speak with Outrunner Alarion . She's not far from the bridge. The Outrunners take care of shuttling goods between here and the mainland, and since you've proven to be so resourceful, they could use your assistance.",starts={{npcID=15281,x=0.354,y=0.224,zoneID=3430},{npcID=15281,x=0.528,y=0.496,zoneID=6455}},ends={{npcID=15301,x=0.404,y=0.322,zoneID=3430}},coords={x=0.354,y=0.224,source="quest_giver",zoneID=3430},questType="standard"},
[8350] = {id=8350,name="Completing the Delivery",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The death of another outrunner is a true tragedy, but it's a risk we all accept when we take the job. Magistrix Erona at the Sunspire needs to get this package to the inn at Falconwing Square, and she needs it there as soon as possible. We're short handed and I don't have anyone else available that can cover for us. I'm not going to lie to you; the path to Falconwing Square can be extremely dangerous if you leave the safety of Dawning Lane. Do you feel up to the task, ?",starts={{npcID=15301,x=0.404,y=0.322,zoneID=3430}},ends={{npcID=15433,x=0.48,y=0.476,zoneID=3430}},coords={x=0.404,y=0.322,source="quest_giver",zoneID=3430},questType="standard"},
[8463] = {id=8463,name="Unstable Mana Crystals",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="A group of Wretched recently raided a supply of unstable mana crystals from one of our arcane sanctums. If not handled properly, the crystals could explode with enough force to blow a hole into the city walls. Now, , I don't quite care if they blow themselves up while tapping unstable arcane sources, but the whole incident would make my men look bad. Bring me back any remaining stolen crystals you find; they might still be inside their original crates.",starts={{npcID=15403,x=0.48,y=0.46,zoneID=3430}},ends={{npcID=15403,x=0.48,y=0.46,zoneID=3430}},coords={x=0.48,y=0.46,source="quest_giver",zoneID=3430},questType="standard"},
[8468] = {id=8468,name="WANTED: Thaelis the Hungerer",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The city of Silvermoon hereby issues a reward for the head of Thaelis the Hungerer, notorious Wretched ringleader. He is wanted for repeated crimes against the general populace of Silvermoon City, including the murder of two city guards. Report to Sergeant Kan'ren to collect the reward.",starts={{npcID=180918,x=0.481,y=0.463,zoneID=3430}},ends={{npcID=16924,x=0.478,y=0.464,zoneID=3430}},coords={x=0.481,y=0.463,source="quest_giver",zoneID=3430},questType="standard"},
[8472] = {id=8472,name="Major Malfunction",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The arcane patrollers crafted by our forefathers to protect the city have fallen into a dangerous state of disrepair. They fail to recognize us as their masters and will attack us on sight! Even though they were created many years ago, the arcane cores that power them are still quite useful and valuable to us. I want you to gather these cores and bring them to me so I can put them to good use again. You will find the patrollers in the ruined section of Silvermoon, to the northwest.",starts={{npcID=15418,x=0.472,y=0.462,zoneID=3430}},ends={{npcID=15418,x=0.472,y=0.462,zoneID=3430}},coords={x=0.472,y=0.462,source="quest_giver",zoneID=3430},questType="standard"},
[8473] = {id=8473,name="A Somber Task",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="These are difficult times for us, . It was a very hard decision to burn the woods bordering the Ghostlands to prevent the Scourge's expansion. The treants, who have been our friends for years, are now trying to foster the regrowth of the forest along the Scorched Grove. This is a painful thing to ask of you, , but we've failed to convince our former allies to cease their endeavors. I need you to stop them by the only means that remain to us: force.",starts={{npcID=15398,x=0.34,y=0.8,zoneID=3430}},ends={{npcID=15398,x=0.34,y=0.8,zoneID=3430}},coords={x=0.34,y=0.8,source="quest_giver",zoneID=3430},questType="standard"},
[8474] = {id=8474,name="Old Whitebark's Pendant",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The pendant has the initials L.R. etched on to it. Perhaps these letters will lead to the pendant's maker.",ends={{npcID=15398,x=0.34,y=0.8,zoneID=3430}},questType="standard"},
[8475] = {id=8475,name="The Dead Scar",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The black swath of soil that cuts through Eversong Woods is a permanent reminder of the day Arthas led the Scourge into our beloved city. This blemish is more than an eyesore as even today it brings Scourge from the Ghostlands to Silvermoon. Go, , and give my men a hand in killing the mindless undead that walk down the Dead Scar.",starts={{npcID=15416,x=0.502,y=0.508,zoneID=3430}},ends={{npcID=15416,x=0.502,y=0.508,zoneID=3430}},coords={x=0.502,y=0.508,source="quest_giver",zoneID=3430},questType="standard"},
[8476] = {id=8476,name="Amani Encroachment",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Ours are not the vast kingdoms of the humans and orcs. All we have left of our lands in Azeroth lies mostly before your eyes, . Until we can reach Outland, we must defend what little land we have at any cost. Our uncivilized neighbors to the southeast, the Amani trolls, certainly have a different opinion regarding the ownership of these lands. Their daily raids are something we can't tolerate anymore. Go to their settlements, Zeb'Watha and Tor'Watha, and teach them a lesson.",starts={{npcID=15399,x=0.602,y=0.626,zoneID=3430}},ends={{npcID=15399,x=0.602,y=0.626,zoneID=3430}},coords={x=0.602,y=0.626,source="quest_giver",zoneID=3430},questType="standard"},
[8477] = {id=8477,name="The Spearcrafter's Hammer",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The Amani and the sin'dorei have a long history of mutual dislike and open hostility. That doesn't prevent me from appreciating a fellow craftsman's work, . I've come across pieces of Amani weaponry and I must admit I'm impressed by the quality of their work. It is rumored that Spearcrafter Otembe wields a magical hammer that is so light and well-balanced it allows him to work with great dexterity and efficiency. If you bring me this tool I'll use it to craft you a weapon.",starts={{npcID=15400,x=0.596,y=0.626,zoneID=3430}},ends={{npcID=15400,x=0.596,y=0.626,zoneID=3430}},coords={x=0.596,y=0.626,source="quest_giver",zoneID=3430},questType="standard"},
[8479] = {id=8479,name="Zul'Marosh",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Come closer, mon. Don't be 'fraid, Ven'jashi not gonna hurt you. Us Darkspears be mortal enemies of the Amani just like you. Their boss Zul'Marosh is evil troll. He give me the bad poison and leave me in this cage to die. I not scared of dyin', mon. I seen death in the eye an' I laugh at her. I cannot die in peace yet, mon. Not 'til Zul'Marosh be dead too. You find him 'cross the lake in Zeb'Watha. I hold this poison off 'til you bring me his big ugly head, mon. Only then I die peacefully.",starts={{npcID=15406,x=0.704,y=0.724,zoneID=3430}},ends={{npcID=15406,x=0.704,y=0.724,zoneID=3430}},coords={x=0.704,y=0.724,source="quest_giver",zoneID=3430},questType="standard"},
[8480] = {id=8480,name="Lost Armaments",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The Wretched grow bolder every day, . They've achieved enough coordination to launch an attack on Sunsail Anchorage. As if that weren't embarrassing enough, most of our weapons were left behind when they attacked. Bring me back our armaments so that we may show those ruffians who's boss.",starts={{npcID=15404,x=0.362,y=0.668,zoneID=3430}},ends={{npcID=15404,x=0.362,y=0.668,zoneID=3430}},coords={x=0.362,y=0.668,source="quest_giver",zoneID=3430},questType="standard"},
[8482] = {id=8482,name="Incriminating Documents",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The documents contain detailed maps of different strategic buildings in Eversong Woods. A diagram of an arcane sanctum is also sketched in good detail. There seem to be numerous notes in a language you don't recognize. As these were carried by a Darnassian spy, it might be a good idea to bring them to the Captain of the Guard - Aeldon Sunbrand .",ends={{npcID=15403,x=0.48,y=0.46,zoneID=3430}},questType="standard"},
[8483] = {id=8483,name="The Dwarven Spy",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Listen, . This is a very delicate situation; even though we've identified the spy, we cannot kill him out in the open. We cannot try to capture him either as the risk of him escaping is too great. I want you to go find Prospector Anvilward at the North Sanctum and kill him. Do this in a quiet manner, we don't want word to spread that we allowed a spy into our city. Bring me his head as proof. Ironforge will learn not to meddle with the sin'dorei.",starts={{npcID=15403,x=0.48,y=0.46,zoneID=3430}},ends={{npcID=15403,x=0.48,y=0.46,zoneID=3430}},coords={x=0.48,y=0.46,source="quest_giver",zoneID=3430},questType="standard"},
[8486] = {id=8486,name="Arcane Instability",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="It's about time that dimwit, Caidanis, sent someone this way. I warned of the dangers of increasing the load on the West Sanctum! Now one of our energy converters is destroyed and arcane wraiths are pouring out of the sanctum! I'm going to need you to take care of these creatures before we send anyone in for repairs. Make haste!",starts={{npcID=15401,x=0.366,y=0.574,zoneID=3430}},ends={{npcID=15401,x=0.366,y=0.574,zoneID=3430}},coords={x=0.366,y=0.574,source="quest_giver",zoneID=3430},questType="standard"},
[8487] = {id=8487,name="Corrupted Soil",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="This was a fully functional arcane sanctum before Arthas and his army of Scourge decided to plow through it on their way to Silvermoon. Now it's as useful to us as any part of the Dead Scar. The soil is tainted, undead are drawn to it and the energy in the ley lines is completely disrupted. What I want to know, , is whether this taint is reversible or not. I want you to collect soil samples from this area so I can study them. Perhaps with time we can set things back to normal.",starts={{npcID=15402,x=0.542,y=0.71,zoneID=3430}},ends={{npcID=15402,x=0.542,y=0.71,zoneID=3430}},coords={x=0.542,y=0.71,source="quest_giver",zoneID=3430},questType="standard"},
[8488] = {id=8488,name="Unexpected Results",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Something's wrong, . I sense the presence of Scourge. Be ready to fight them!",starts={{npcID=15402,x=0.542,y=0.71,zoneID=3430}},ends={{npcID=15402,x=0.542,y=0.71,zoneID=3430}},coords={x=0.542,y=0.71,source="quest_giver",zoneID=3430},questType="standard"},
[8490] = {id=8490,name="Powering our Defenses",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Ancient runestones once powered a protective barrier across the Eversong border. Many were destroyed during Arthas' attack; others were stolen. Of the three that remain, only this one has retained its powers. The runestone to the east might be salvageable, though. Take this crystal and instill its energy on the Eastern Runestone. The process should take but a minute. Beware though, nearby Scourge will be drawn to it and will seek to destroy it. Do not let them!",starts={{npcID=16362,x=0.442,y=0.854,zoneID=3430}},ends={{npcID=16362,x=0.442,y=0.854,zoneID=3430}},coords={x=0.442,y=0.854,source="quest_giver",zoneID=3430},questType="standard"},
[8491] = {id=8491,name="Pelt Collection",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The springpaw that inhabit this region are known for their high quality pelts. We've even seen night elf scum travel to these lands just to poach them. Our skirmishes with the Amani have put a bit of a strain on our supply of gear and our rangers don't have much time to hunt for pelts anymore. If you'd be willing to lend a hand by collecting springpaw pelts , I'd be happy to reward you with a hand-crafted piece of armor. You'll find springpaw stalkers all around the woods north of here.",starts={{npcID=15417,x=0.446,y=0.696,zoneID=3430}},ends={{npcID=15417,x=0.446,y=0.696,zoneID=3430}},coords={x=0.446,y=0.696,source="quest_giver",zoneID=3430},questType="standard"},
[8884] = {id=8884,name="Fish Heads, Fish Heads...",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Greetings, . Take a look toward the shore; what do you see? That's right, our beach... our Tranquil Shore, has been infested with the malignancy known as the murloc. This blight will not stand! I have a task for you. If you feel that you're up to it, I would have their heads! Let us see if we can put a dent in their numbers so large that, if they have any sense at all, they will return to the murky depths from which they sprang!",starts={{npcID=15920,x=0.302,y=0.584,zoneID=3430}},ends={{npcID=15920,x=0.302,y=0.584,zoneID=3430}},coords={x=0.302,y=0.584,source="quest_giver",zoneID=3430},questType="standard"},
[8885] = {id=8885,name="The Ring of Mmmrrrggglll",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The Grimscale murlocs have not been scared off by your efforts. But, I think I know what will send them packing, as well as get me some personal retribution. They have a murloc chieftain that calls itself Mmmrrrggglll. It wanders the Golden Strand south of the river inlet. The beast once slew a compatriot of mine, and now wears his ring in open defiance and mockery. Slay Mmmrrrggglll, and bring back my friend's ring. Then we shall see these monsters cowed!",starts={{npcID=15920,x=0.302,y=0.584,zoneID=3430}},ends={{npcID=15920,x=0.302,y=0.584,zoneID=3430}},coords={x=0.302,y=0.584,source="quest_giver",zoneID=3430},questType="standard"},
[8886] = {id=8886,name="Grimscale Pirates!",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Thank goodness for you, ! Those slimy Grimscale murlocs have pirated away my cargo! It's bad enough that the Wretched have stolen what little magical goods I had, but the murlocs took the rest! What has this land come to? Could you retrieve my cargo? I can't expect that you'd be able to get all of it back, but I'll be grateful for any of it at this point. It was the Grimscale murlocs in the huts, just to the west and south of the anchorage on the Golden Strand, I'm sure of it!",starts={{npcID=15921,x=0.362,y=0.666,zoneID=3430}},ends={{npcID=15921,x=0.362,y=0.666,zoneID=3430}},coords={x=0.362,y=0.666,source="quest_giver",zoneID=3430},questType="standard"},
[8887] = {id=8887,name="Captain Kelisendra's Lost Rutters",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Interesting... what you have found here is a water-proofed, leather tube containing a number of sheets of parchment. By the markings upon them, the pages are clearly navigation rutters, and each bears the signature of one Captain Kelisendra . You've heard of a small, defended camp just east of the nearby Sunsail Anchorage. Maybe the captain is there?",ends={{npcID=15921,x=0.362,y=0.666,zoneID=3430}},questType="standard"},
[8888] = {id=8888,name="The Magister's Apprentice",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description=", hear my request. For reasons that I cannot go into now, I decided to shut down my nearby school. A few days ago, I sent one of my pupils, Apprentice Loralthalis , there with this very task. I have not heard back from her since. Will you go to Duskwither Spire and check in on her, to make sure that she is well? You'll find it by heading north on the path out of Farstrider Retreat, then go to the right when the road branches.",starts={{npcID=15951,x=0.602,y=0.614,zoneID=3430}},ends={{npcID=15924,x=0.678,y=0.564,zoneID=3430}},coords={x=0.602,y=0.614,source="quest_giver",zoneID=3430},questType="standard"},
[8889] = {id=8889,name="Deactivating the Spire",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="As you may know, Magister Duskwither sent me back here to shut down the power sources that feed the Spire. There are three of them, each located in a different place inside. Unfortunately, I appear to be too late, and Duskwither Spire has been overrun with strange, magical creatures. While I haven't the expertise to accomplish this task, surely a , such as yourself, could do so easily?",starts={{npcID=15924,x=0.678,y=0.564,zoneID=3430}},ends={{npcID=15924,x=0.678,y=0.564,zoneID=3430}},coords={x=0.678,y=0.564,source="quest_giver",zoneID=3430},questType="standard"},
[8890] = {id=8890,name="Word from the Spire",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description=", I have one last favor to ask of you. Would you please relay what's transpired here to Magister Duskwither , back at the Farstrider Retreat? Let him know that I am well, but make certain that he is aware that some of the apprentices have become Wretched. Thank you for your help!",starts={{npcID=15924,x=0.678,y=0.564,zoneID=3430}},ends={{npcID=15951,x=0.602,y=0.614,zoneID=3430}},coords={x=0.678,y=0.564,source="quest_giver",zoneID=3430},questType="standard"},
[8891] = {id=8891,name="Abandoned Investigations",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="You have discovered what appears to be an investigative journal left behind by Magister Duskwither . A brief scan of its contents reveal some shocking attempts at filtering corrupted magical flows, which might explain what has happened here at Duskwither Spire. The magister is sure to want this brought back to him.",starts={{npcID=181011,x=0.692,y=0.521,zoneID=3430}},ends={{npcID=15951,x=0.602,y=0.614,zoneID=3430}},coords={x=0.692,y=0.521,source="quest_giver",zoneID=3430},questType="standard"},
[8892] = {id=8892,name="Situation at Sunsail Anchorage",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Sunsail Anchorage has been overrun by Wretched scum. As soon as we manage to get reinforcements to the area we'll show those thugs who's boss, . In the meantime you can help by showing them a bit of discipline. Go in there and show them we are not to be trifled with. You will find Sunsail Anchorage just to the west of Fairbreeze Village.",starts={{npcID=15939,x=0.434,y=0.708,zoneID=3430}},ends={{npcID=15939,x=0.434,y=0.708,zoneID=3430}},coords={x=0.434,y=0.708,source="quest_giver",zoneID=3430},questType="standard"},
[8894] = {id=8894,name="Cleaning up the Grounds",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="It's horrible, I tell you! Strange things happening in the spire, the magister and his apprentices run off, and then the next thing that you know, the whole grounds are overrun with these magical beasties! And who told Wyllithen? No one, that's who! , you've got to help me clear some of these things out... I cannot maintain the grounds while these 'anomalies' are running amok!",starts={{npcID=15969,x=0.686,y=0.47,zoneID=3430}},ends={{npcID=15969,x=0.686,y=0.47,zoneID=3430}},coords={x=0.686,y=0.47,source="quest_giver",zoneID=3430},questType="standard"},
[8895] = {id=8895,name="Delivery to the North Sanctum",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="I'm pleased to discover that you're at least somewhat competent, . I'll give you another task since you seem so eager to prove yourself. This is a letter to Ley-Keeper Caidanis , the arcanist in charge of the upkeep of the North Sanctum. Go southwest of Falconwing Square and you will find him. He is a very important person, so I hope you don't bother him too much with trivial chatter.",starts={{npcID=15418,x=0.472,y=0.462,zoneID=3430}},ends={{npcID=15405,x=0.446,y=0.53,zoneID=3430}},coords={x=0.472,y=0.462,source="quest_giver",zoneID=3430},questType="standard"},
[9035] = {id=9035,name="Roadside Ambush",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="You, there! You must help me, please! A fellow apprentice and I were attacked by the Wretched! In their mad hunger for magic, they took everything they could get their hands on: mana crystals, wands, spellbooks... everything! Meledor gave chase after them; I had to stay behind and look after what they didn't take. Continue down the road and see if you can lend him a hand.",starts={{npcID=15941,x=0.452,y=0.564,zoneID=3430}},ends={{npcID=15945,x=0.448,y=0.61,zoneID=3430}},coords={x=0.452,y=0.564,source="quest_giver",zoneID=3430},questType="standard"},
[9062] = {id=9062,name="Soaked Pages",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Those blasted Wretched sure can run fast at the sight of someone who'll stand up to them. But let's not worry about that now. I need to find my instructor's elemental grimoire. I'm certain I saw one of those cowards throw it into the river but I cannot seem to be able to locate it. I could use another set of eyes. I'll throw in a bit of coin if you spot it.",starts={{npcID=15945,x=0.448,y=0.61,zoneID=3430}},ends={{npcID=15945,x=0.448,y=0.61,zoneID=3430}},coords={x=0.448,y=0.61,source="quest_giver",zoneID=3430},questType="standard"},
[9064] = {id=9064,name="Taking the Fall",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Antheol is going to fly off his rocker when he finds out his book is ruined. I've got a little proposal for you; don't worry, I'll make it worth your while. Take this book to him and tell him nothing of this incident. If he asks, just tell him you dropped the book into a puddle. He has no direct authority over you, so there's not much he can do. Antheol delivers his lectures at Stillwhisper Pond, southeast of Silvermoon. You'll do this for us, right? I'll reward you handsomely for this favor!",starts={{npcID=15945,x=0.448,y=0.61,zoneID=3430}},ends={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},coords={x=0.448,y=0.61,source="quest_giver",zoneID=3430},questType="standard"},
[9066] = {id=9066,name="Swift Discipline",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="I hope you learn a valuable lesson today, . Never trust someone else to lie for you. Now I want you to go back to my two dimwitted students and discipline them using this wand. My magic tells me that you'll find them along the road to the west on the other side of the Dead Scar. Come back to me after you've done this. I'll give you a small reward for your troubles.",starts={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},ends={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},coords={x=0.556,y=0.544,source="quest_giver",zoneID=3430},questType="standard"},
[9067] = {id=9067,name="The Party Never Ends",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="I like to throw parties... just a little something to celebrate the magnificence that is Quel'Thalas! But, I'm in a bit of a bind. I need you to gather up more party supplies. From Vinemaster Suntouched at the Silvermoon City inn, bring me a bottle of Suntouched Special Reserve . From Zalene Firstlight at Farstrider Retreat acquire more of those delicious Springpaw Appetizers . And you can pick up my delivery of fireworks from Halis Dawnstrider at Fairbreeze Village. Be quick about it!",starts={{npcID=16144,x=0.382,y=0.734,zoneID=3430}},ends={{npcID=16144,x=0.382,y=0.734,zoneID=3430}},coords={x=0.382,y=0.734,source="quest_giver",zoneID=3430},questType="standard"},
[9076] = {id=9076,name="Wretched Ringleader",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The Wretched are so oblivious, gorging on foul magic, that they haven't realized we've recovered most of our weapons. We can't expect them to remain in their stupor, though. Now is the time for a decisive attack. Let us make an example of their leader, Aldaron. He was spotted on the top floor of the building by the anchorage. Bring me his head; I'll reward you suitably.",starts={{npcID=15404,x=0.362,y=0.668,zoneID=3430}},ends={{npcID=15404,x=0.362,y=0.668,zoneID=3430}},coords={x=0.362,y=0.668,source="quest_giver",zoneID=3430},questType="standard"},
[9119] = {id=9119,name="Malfunction at the West Sanctum",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Since you're here, , I've a favor to ask you. Ley-Keeper Velania 's apprentice dropped by earlier to ask for assistance. Apparently there's some malfunction happening at the West Sanctum. I've been a bit busy entertaining our... most pleasant... dwarven guest. See if you can give her a hand. You'll find the West Sanctum southwest of here.",starts={{npcID=15405,x=0.446,y=0.53,zoneID=3430}},ends={{npcID=15401,x=0.366,y=0.574,zoneID=3430}},coords={x=0.446,y=0.53,source="quest_giver",zoneID=3430},questType="standard"},
[9130] = {id=9130,name="Goods from Silvermoon City",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Welcome volunteer! We're running low on supplies here, but Silvermoon has promised us materiel assistance. That's where you come in. Take this list over to Skymaster Brightdawn . He'll have further instructions for you on how best to get up to Silvermoon City.",starts={{npcID=16261,x=0.436,y=0.714,zoneID=3430}},ends={{npcID=44036,x=0.44,y=0.7,zoneID=3430}},coords={x=0.436,y=0.714,source="quest_giver",zoneID=3430},questType="standard"},
[9133] = {id=9133,name="Fly to Silvermoon City",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3487,description=", for a very modest amount of coin, I can send you swiftly flying through the air on one of these magnificent beasts. And, it's safer than walking there, I can assure you! When you arrive in Silvermoon City, seek out Sathren Azuredawn in the Bazaar. Speak with me once more when you've decided you're ready to brave the skies.",starts={{npcID=44036,x=0.44,y=0.7,zoneID=3430}},ends={{npcID=16191,x=0.54,y=0.71,zoneID=3487}},coords={x=0.44,y=0.7,source="quest_giver",zoneID=3430},questType="standard"},
[9134] = {id=9134,name="Skymistress Gloaming",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="It doesn't look as if you have a cart or a beast of burden with you, so I'd better send you back only with what you can carry. If you've spoken with Skymaster Brightdawn at Fairbreeze Village, then you should get this to Sathiel as soon as possible by flying back. Take these goods for final inspection to Skymistress Gloaming just outside Silvermoon City's Shepherd's Gate.",starts={{npcID=16191,x=0.54,y=0.71,zoneID=3487}},ends={{npcID=16192,x=0.544,y=0.508,zoneID=3430}},coords={x=0.54,y=0.71,source="quest_giver",zoneID=3487},questType="standard"},
[9135] = {id=9135,name="Return to Sathiel",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="It all checks out as far as I can tell. So, the question is, have you already spoken to Skymaster Brightdawn in Fairbreeze Village? If so, then this can be as simple as you paying the small fare and quickly flying back. Let me know when you're ready.",starts={{npcID=16192,x=0.544,y=0.508,zoneID=3430}},ends={{npcID=16261,x=0.436,y=0.714,zoneID=3430}},coords={x=0.544,y=0.508,source="quest_giver",zoneID=3430},questType="standard"},
[9138] = {id=9138,name="Suncrown Village",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="We're surrounded here, . The outlying villages have all been overrun by the Scourge! You must head northeast to Suncrown Village immediately and deal with the Nerubian Scourge menace. You can't miss them - they're spider-like creatures. There's no time to waste.... Quel'Thalas must be reclaimed!",starts={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},ends={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},coords={x=0.464,y=0.284,source="quest_giver",zoneID=3433},questType="standard"},
[9139] = {id=9139,name="Goldenmist Village",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="We've had one success, but there are two more villages that must be reclaimed! Goldenmist Village is our next target. It lies to the northwest, and has been taken by the ghosts of the high elves that used to live there. Gruesome, I know, but these are apparently the sorts of tactics that the Scourge like to employ. Go and defeat these ghosts and wraiths, . Take the west road out of Tranquillien to get there.",starts={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},ends={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},coords={x=0.464,y=0.284,source="quest_giver",zoneID=3433},questType="standard"},
[9140] = {id=9140,name="Windrunner Village",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description=", the final battle against the Ghostlands villages is upon you. Windrunner Village to the southwest has been overrun by a large force of the more powerful Scourge shocktroopers; shades and gargoyles. You will be the spearpoint of our offensive by thinning out their numbers. The magisters at the nearby Sanctum of the Sun have made a special request this time; they want the remains from these Scourge to study in hopes of finding creative ways of fighting them. Good hunting!",starts={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},ends={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},coords={x=0.464,y=0.284,source="quest_giver",zoneID=3433},questType="standard"},
[9143] = {id=9143,name="Dealing with Zeb'Sora",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The lieutenant here rushed us into battle with the trolls across the lake instead of scouting the situation first. We were decimated by his stupidity! You hear me Tomathren? You're an idiot! Will you help us, ? Those trolls still need to be dealt with. I need to stay here and nursemaid him -- I think he's lost his mind. Just head east to the other side of the lake into Zeb'Sora. I want revenge... bring me their ears so that I can fashion a nice necklace!",starts={{npcID=16219,x=0.694,y=0.15,zoneID=3433}},ends={{npcID=16219,x=0.694,y=0.15,zoneID=3433}},coords={x=0.694,y=0.15,source="quest_giver",zoneID=3433},questType="standard"},
[9144] = {id=9144,name="Missing in the Ghostlands",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="My nephew was sent into the Ghostlands a few days ago. He never mentioned anything about his task, except that it was of an extremely secret nature. He never returned and I fear for the worst, . A missing messenger might not mean much to the callous magisters of Silvermoon, but he's like a son to me. Please, , will you look for him?",starts={{npcID=16210,x=0.44,y=0.706,zoneID=3430}},ends={{npcID=16183,x=0.49,y=0.89,zoneID=3430}},coords={x=0.44,y=0.706,source="quest_giver",zoneID=3430},questType="standard"},
[9145] = {id=9145,name="Help Ranger Valanna!",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description=", I can't just sit here waiting for an audience with the high executor or Dame Auriferous! This cannot wait! We were dealing with the Shadowpine trolls of Zeb'Sora to the northeast across Lake Elrendar. But the lieutenant mishandled the attack and we lost a lot of Farstriders. Then he just fell to pieces afterward. Ranger Valanna sent me here, and Ranger Salissa to the Farstrider Enclave for help. Please find them, . Valanna was badly injured and the lieutenant's useless.",starts={{npcID=16213,x=0.454,y=0.324,zoneID=3433}},ends={{npcID=16219,x=0.694,y=0.15,zoneID=3433}},coords={x=0.454,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9146] = {id=9146,name="Report to Captain Helios",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="I need one last favor of you, . Just in case Ranger Salissa didn't make it back to Farstrider Enclave on the south edge of the lake, I need you to go there and get help. Just check in with Captain Helios and let him know what's happened here. I'm sure he'll send help back as soon as he can.",starts={{npcID=16219,x=0.694,y=0.15,zoneID=3433}},ends={{npcID=16220,x=0.722,y=0.296,zoneID=3433}},coords={x=0.694,y=0.15,source="quest_giver",zoneID=3433},questType="standard"},
[9147] = {id=9147,name="The Fallen Courier",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="What are you standing around for? Can't you see this boy needs immediate attention? By the looks of it, the plague is beginning to take over his body. Within minutes not even a master apothecary like me will be able to save him. The animals south of the river all carry the plague in their blood. Go across the bridge and hunt the plagued beasts there. Bring me enough plagued blood samples and I'll distill a serum capable of saving this blood elf. Hurry!",starts={{npcID=16196,x=0.49,y=0.89,zoneID=3430}},ends={{npcID=16196,x=0.49,y=0.89,zoneID=3430}},coords={x=0.49,y=0.89,source="quest_giver",zoneID=3430},questType="standard"},
[9148] = {id=9148,name="Delivery to Tranquillien",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="I... I'm too weak to continue. I carry a dire warning from Regent Lord Theron, in the form of a letter. You'll have to deliver it for me. Take it to Arcanist Vandril in Tranquillien. You'll find the town further to the south along this road. Go there and... find Vandril...",starts={{npcID=16183,x=0.49,y=0.89,zoneID=3430}},ends={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},coords={x=0.49,y=0.89,source="quest_giver",zoneID=3430},questType="standard"},
[9149] = {id=9149,name="The Plagued Coast",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="To find a cure for the plague we need to understand how it affects different creatures, from the most complex life forms to the lowliest subspecies. I've come here to study the murlocs since, like us, they've retained free will in undeath. What makes these lowly mongrels so special? I need to find out, ! Travel northwest and bring me their spines so that I may study the accumulation of plague in their marrow. Who knows what secrets their little bones hold?",starts={{npcID=16198,x=0.476,y=0.348,zoneID=3433}},ends={{npcID=16198,x=0.476,y=0.348,zoneID=3433}},coords={x=0.476,y=0.348,source="quest_giver",zoneID=3433},questType="standard"},
[9150] = {id=9150,name="Salvaging the Past",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Can you believe it? We have an actual functioning arcane sanctum up and running southeast of here: the Sanctum of the Sun. All manner of important magisters have come to take part in running it. Of course they've all forgotten about the Sanctum of the Moon. Not much remains of it and its energies have given rise to bizarre creatures. I'm not one to let good resources go to waste, however. Go to the Sanctum of the Moon and see if you can recover the crystallized essences from the creatures there.",starts={{npcID=16199,x=0.46,y=0.318,zoneID=3433}},ends={{npcID=16199,x=0.46,y=0.318,zoneID=3433}},coords={x=0.46,y=0.318,source="quest_giver",zoneID=3433},questType="standard"},
[9151] = {id=9151,name="The Sanctum of the Sun",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="You've proven your loyalty to Tranquillien and have helped us defend it against the threat of the Scourge. Some of our most powerful magisters have come from Silvermoon to help us take the fight to the enemy's doorstep. They've rebuilt the arcane sanctum to the south and have driven the Scourge away from the surrounding area. They plan to launch an offensive into Deatholme, Dar'Khan's stronghold. You would do well to join them, . I'm sure they can make use of a seasoned like yourself.",starts={{npcID=16199,x=0.46,y=0.318,zoneID=3433}},ends={{npcID=16204,x=0.548,y=0.484,zoneID=3433}},coords={x=0.46,y=0.318,source="quest_giver",zoneID=3433},questType="standard"},
[9152] = {id=9152,name="Tomber's Supplies",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="How am I supposed to supply the war effort when I cannot even safely get my supplies here? I was promised an escort that never came. And then, I had to leave one of my carts behind to the west when I was attacked by a band of ghouls! Want to help out, and get me open for business in the process? Go down the western road out of town and past the graveyard. On the other side of the Dead Scar is a fork in the road. The hill that my cart had to be left on lies just beyond.",starts={{npcID=16224,x=0.472,y=0.286,zoneID=3433}},ends={{npcID=16224,x=0.472,y=0.286,zoneID=3433}},coords={x=0.472,y=0.286,source="quest_giver",zoneID=3433},questType="standard"},
[9155] = {id=9155,name="Down the Dead Scar",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="If you've made it this far then you probably know about the Dead Scar and how to this day mindless Scourge follow the path of destruction that Arthas created on his way to Silvermoon City. Make yourself useful and thin down the Scourge's numbers in the Scar. If you prove to be worth your salt I'll put in a good word for you.",starts={{npcID=16200,x=0.46,y=0.334,zoneID=3433}},ends={{npcID=16200,x=0.46,y=0.334,zoneID=3433}},coords={x=0.46,y=0.334,source="quest_giver",zoneID=3433},questType="standard"},
[9156] = {id=9156,name="WANTED: Knucklerot and Luzran",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="A bounty is hereby declared for the abominations known as Knucklerot and Luzran. These dreadful creations of Dar'Khan are extremely dangerous and have been sighted patrolling near the Howling and Bleeding Ziggurats. Individuals seeking to claim the reward must present the abominations' heads to Deathstalker Rathiel as proof of the deed.",starts={{npcID=181147,x=0.483,y=0.316,zoneID=3433}},ends={{npcID=16200,x=0.46,y=0.334,zoneID=3433}},coords={x=0.483,y=0.316,source="quest_giver",zoneID=3433},questType="group"},
[9157] = {id=9157,name="Forgotten Rituals",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Every year we, the denizens of Suncrown Village, would take part in a ritual to keep the different aspects of nature under our control. Dominion over the element of water was symbolized by the summoning and enslavement of an elemental named Aquantion. Through a wicked perversion of our magic, the scoundrel broke his bonds and enslaved us instead! We wore medallions shaped like waves during the ritual. Seek them at the bottom of the lake; we'll need them to free my compatriots' spirits!",starts={{npcID=16201,x=0.722,y=0.19,zoneID=3433}},ends={{npcID=16201,x=0.722,y=0.19,zoneID=3433}},coords={x=0.722,y=0.19,source="quest_giver",zoneID=3433},questType="standard"},
[9158] = {id=9158,name="Bearers of the Plague",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="You show courage coming to the Ghostlands , . There is much work to be done here and not enough brave souls to do it. I've a thankless task to offer you, should you have the inclination to aid our cause. The very wildlife in this land has been tainted by the plague and we must stop it from spreading. Hunt the ghostclaw lynxes to the east and south of here and return when you've slain enough of them.",starts={{npcID=16202,x=0.724,y=0.322,zoneID=3433}},ends={{npcID=16202,x=0.724,y=0.322,zoneID=3433}},coords={x=0.724,y=0.322,source="quest_giver",zoneID=3433},questType="standard"},
[9159] = {id=9159,name="Curbing the Plague",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="You've proven your worth as an ally, . I need you to continue your task and track down more plagued wildlife. This time seek out some of the more dangerous beasts. Hunt the spindleweb lurkers west of the Dead Scar and the vampiric mistbats just south of here. Return to me when you're done.",starts={{npcID=16202,x=0.724,y=0.322,zoneID=3433}},ends={{npcID=16202,x=0.724,y=0.322,zoneID=3433}},coords={x=0.724,y=0.322,source="quest_giver",zoneID=3433},questType="standard"},
[9160] = {id=9160,name="Investigate An'daroth",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description=", we are having difficulty with a group of night elves that have recently taken over a nearby island. They've set up a small camp at the old high elf ley-line nexus, An'daroth, to the northwest. There is a dirt path that leads up to it just past the Dead Scar. I suggest that you lend us your aid by going there, investigating what they are up to, and slaying as many of the conceited night elves as you can.",starts={{npcID=16231,x=0.448,y=0.324,zoneID=3433}},ends={{npcID=16231,x=0.448,y=0.324,zoneID=3433}},coords={x=0.448,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9161] = {id=9161,name="The Traitor's Shadow",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Dar'Khan Drathir is believed to have returned from the dead to rule over the armies of the Scourge in the Ghostlands . Dar'Khan aligned himself with the Scourge long ago... yet he was once a living, breathing elf. Much of his time was spent inside Dawnstar Spire, northeast of here. He hid there for many nights, scheming against his own. Search the tower for more information, . Perhaps he had a journal or kept notes. One never knows where useful information might present itself.",starts={{npcID=16203,x=0.718,y=0.326,zoneID=3433}},ends={{npcID=181150,x=0.796,y=0.177,zoneID=3433}},coords={x=0.718,y=0.326,source="quest_giver",zoneID=3433},questType="standard"},
[9162] = {id=9162,name="Hints of the Past",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="As you skim through the pages in the journal you're overcome by an unnerving sense of being watched. The contents are unsettling. Dar'Khan's soul was one filled with hatred and contempt for his own people. The extent of his machinations and plots are all documented in great detail. Perhaps there is something here that Vynna will find useful.",starts={{npcID=181150,x=0.796,y=0.177,zoneID=3433}},ends={{npcID=16203,x=0.718,y=0.326,zoneID=3433}},coords={x=0.796,y=0.177,source="quest_giver",zoneID=3433},questType="standard"},
[9163] = {id=9163,name="Into Occupied Territory",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Now, the more direct course of action that we are going to take, to figure out what these night elves are really up to, is to have you go to their island and steal any information that you can come by. I want you to head west down the road out of town to Shalandis Isle, just off the coast. Go there and recover any plans they might have on the island or on their ship.",starts={{npcID=16231,x=0.448,y=0.324,zoneID=3433}},ends={{npcID=16231,x=0.448,y=0.324,zoneID=3433}},coords={x=0.448,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9164] = {id=9164,name="Captives at Deatholme",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Ah, yes. I possess a draught that will break most forms of alchemically induced stupor. Side effects include confusion, nausea and - in rare cases - temporary blindness. All much preferable to whatever the Scourge plans to do to those prisoners in Deatholme, if you ask me. Best of luck, brave . You are going to need it.",starts={{npcID=16198,x=0.476,y=0.348,zoneID=3433},{npcID=16240,x=0.548,y=0.484,zoneID=3433}},ends={{npcID=16240,x=0.548,y=0.484,zoneID=3433}},coords={x=0.476,y=0.348,source="quest_giver",zoneID=3433},questType="standard"},
[9166] = {id=9166,name="Deliver the Plans to An'telas",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="You must deliver the recovered night elf plans to An'telas for me. It is to the east, on the southern slopes of Sungraze Peak, just to the northeast of the Sanctum of the Sun. Magister Sylastor is there conducting ongoing studies into the ley-line nexus energy for potential use in our fight against the Scourge. Have him look at these plans to shed some light on what it is that these night elves are up to.",starts={{npcID=16231,x=0.448,y=0.324,zoneID=3433}},ends={{npcID=16237,x=0.602,y=0.358,zoneID=3433}},coords={x=0.448,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9167] = {id=9167,name="The Traitor's Destruction",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Everything we've done in the Ghostlands has been done with the goal of taking back what is rightfully ours. The Scourge have maintained their chokehold on the region for far too long. The time has come for payback, . Thanks to your help and the help of our new allies, the Forsaken, vengeance will soon be ours. He who sought to steal the power of the Sunwell must die. Go to Deatholme, the Scourge stronghold south of the Dead Scar. Bring me Dar'Khan's head and your deeds will go down in history!",starts={{npcID=16239,x=0.55,y=0.488,zoneID=3433}},ends={{npcID=16239,x=0.55,y=0.488,zoneID=3433}},coords={x=0.55,y=0.488,source="quest_giver",zoneID=3433},questType="group"},
[9169] = {id=9169,name="Deactivate An'owyn",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Their moon crystals are scrying devices -- they're going to spy on us! I know that An'daroth can't provide enough power for that, but An'owyn, directly to the south, most definitely can! From the plans I now have a basic knowledge of how these moon crystals work; enough to shut them down. They're keyed so that they can be turned off. You must go to An'owyn, retrieve the controlling orb from one of the night elves and then use it on the moon crystal to stop them from enacting their plan! Hurry, !",starts={{npcID=16237,x=0.602,y=0.358,zoneID=3433}},ends={{npcID=16237,x=0.602,y=0.358,zoneID=3433}},coords={x=0.602,y=0.358,source="quest_giver",zoneID=3433},questType="standard"},
[9170] = {id=9170,name="Dar'Khan's Lieutenants",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The odious traitor, Dar'Khan, has risen to great power among the ranks of the Scourge. His lieutenants command vast armies of undead against our dwindling numbers. Masophet the Black , Jurion the Deceiver , Borgoth the Bloodletter , Mirdoran the Fallen . Learn these names well for in the Ghostlands these Scourge leaders are second only to Dar'Khan himself. Slay them and their mindless armies will be thrown into disarray.",starts={{npcID=16204,x=0.548,y=0.484,zoneID=3433}},ends={{npcID=16204,x=0.548,y=0.484,zoneID=3433}},coords={x=0.548,y=0.484,source="quest_giver",zoneID=3433},questType="standard"},
[9171] = {id=9171,name="Culinary Crunch",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="This is intolerable! I have nothing to work with here! Milady asks me to come from Silvermoon City; she deserves cuisine as befits her station. No? But I get here and there is no food. You must go out, , and bring back fresh kills so that I have something to prepare. Dame Auriferous prefers a crunchy texture to her food. There are plenty of spindleweb lurkers to the southwest on the other side of the Dead Scar. Disgusting, I know, but that's what we have to work with.",starts={{npcID=16253,x=0.484,y=0.31,zoneID=3433}},ends={{npcID=16253,x=0.484,y=0.31,zoneID=3433}},coords={x=0.484,y=0.31,source="quest_giver",zoneID=3433},questType="standard"},
[9172] = {id=9172,name="Report to Magister Kaendris",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The magisters at the Sanctum of the Sun have made great progress in analyzing the Scourge's weaknesses with the aid of the Forsaken. Magister Kaendris will know what to do with this information. You'll find the Sanctum of the Sun southwest of here. You must hurry, . Dar'Khan is a cunning enemy and watches our every move!",starts={{npcID=16203,x=0.718,y=0.326,zoneID=3433}},ends={{npcID=16239,x=0.55,y=0.488,zoneID=3433}},coords={x=0.718,y=0.326,source="quest_giver",zoneID=3433},questType="standard"},
[9173] = {id=9173,name="Retaking Windrunner Spire",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description=", I want you to reclaim Windrunner Spire! It's an honor, really. Windrunner Spire is the original home of Lady Sylvanas Windrunner, queen of the Forsaken and former ranger-general of the elves. But now it's been overrun by the mindless Scourge. To get there take the road south until it branches. Take the right fork and after crossing the Dead Scar continue southwest. You can't miss it.",starts={{npcID=16252,x=0.448,y=0.324,zoneID=3433}},ends={{npcID=16252,x=0.448,y=0.324,zoneID=3433}},coords={x=0.448,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9174] = {id=9174,name="Vanquishing Aquantion",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="That willful elemental ended many lives that fateful day when he revolted against us. By calling to the lowly murloc to sabotage our rites he subverted our magic and turned it against us. Show him our thirst for vengeance has not waned! Take these medallions and lay them at the Altar of Tidal Mastery at the bottom of the lake. Aquantion shall immediately answer your summons! Beware, ! Without our magic controlling him, his wrath will be unrestrained. Destroy Aquantion so we may rest!",starts={{npcID=16201,x=0.722,y=0.19,zoneID=3433}},ends={{npcID=16201,x=0.722,y=0.19,zoneID=3433}},coords={x=0.722,y=0.19,source="quest_giver",zoneID=3433},questType="standard"},
[9175] = {id=9175,name="The Lady's Necklace",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The necklace shimmers, a remarkable piece of jewelry that doesn't seem to succumb to the gloom that permeates the Ghostlands . Given the inscription, and where you found it, it must be the lost property of Lady Sylvanas Windrunner herself! Perhaps it would be best to first take it to High Executor Mavren at Tranquillien? He seems to be the highest ranking Forsaken in the area and is sure to know what to do with it.",ends={{npcID=16252,x=0.448,y=0.324,zoneID=3433}},questType="standard"},
[9176] = {id=9176,name="The Twin Ziggurats",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="According to this journal, Dar'Khan promised the Scourge two powerful elven artifacts: the stone of light and the stone of flame . These were imbued with the magical energies of the Sunwell and attuned to have warding powers against the Scourge. The crystals were to be transported to where the Howling Ziggurat and the Bleeding Ziggurat now stand, in the middle of the Dead Scar. If they're still held there, we need to recover them. Their power will be greatly useful in our struggle against the enemy.",starts={{npcID=16239,x=0.55,y=0.488,zoneID=3433}},ends={{npcID=16239,x=0.55,y=0.488,zoneID=3433}},coords={x=0.55,y=0.488,source="quest_giver",zoneID=3433},questType="standard"},
[9180] = {id=9180,name="Journey to Undercity",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=1497,description="This is quite extraordinary! It appears to be a gift to Lady Sylvanas Windrunner from her sister, Alleria! You must take it to her in the Undercity at once! The lady holds court in the Royal Quarter. To get there, use the orb of translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to the Undercity . Once there, take the elevator ride down into the city proper. Use your maps if you need help finding the Royal Quarter.",starts={{npcID=16252,x=0.448,y=0.324,zoneID=3433}},ends={{npcID=10181,x=0.578,y=0.916,zoneID=1497}},coords={x=0.448,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9192] = {id=9192,name="Trouble at the Underlight Mines",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The Underlight Mines to the southwest have been overrun by a clan of gnolls calling themselves the Blackpaw. I don't need to remind you how important those mines are to us as a strategic asset in our ongoing campaign here in the Ghostlands ! Take the south road out of town and follow the fork to the right. Just past the ziggurat on the right there will be a short dirt path to the west. Follow it. The ore must flow!",starts={{npcID=16251,x=0.448,y=0.324,zoneID=3433}},ends={{npcID=16251,x=0.448,y=0.324,zoneID=3433}},coords={x=0.448,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9193] = {id=9193,name="Investigate the Amani Catacombs",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3510,description=", our sources tell us that the trolls buried in the Amani Catacombs inside Sungraze Peak have been rising from the dead. I need you to investigate these catacombs and put to the torch any of the unanimated remains you come across so as to prevent any more of these creatures from rising. The fastest way there is to head northwest out of the enclave. This will put you near the western entrance to the catacombs.",starts={{npcID=16203,x=0.718,y=0.326,zoneID=3433},{npcID=16289,x=0.448,y=0.326,zoneID=3433}},ends={{npcID=16203,x=0.718,y=0.326,zoneID=3433},{npcID=16289,x=0.448,y=0.326,zoneID=3433}},coords={x=0.718,y=0.326,source="quest_giver",zoneID=3433},questType="standard"},
[9199] = {id=9199,name="Troll Juju",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The corpses of trolls buried inside the Amani Catacombs have been rising from the dead! I want you to go there and bring back proof of their final demise. Some of these mummy trolls, and their living counterparts, carry juju; glowing objects that house an unknown power source. It's probably what is animating them! The catacombs lie within Sungraze Peak, directly to the east. I am told that the easiest way in lies on the north face of the mountain. See to it, !",starts={{npcID=16251,x=0.448,y=0.324,zoneID=3433},{npcID=16464,x=0.726,y=0.316,zoneID=3433}},ends={{npcID=16251,x=0.448,y=0.324,zoneID=3433},{npcID=16464,x=0.726,y=0.316,zoneID=3433}},coords={x=0.448,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9207] = {id=9207,name="Underlight Ore Samples",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="I was sent here from the Sanctum of the Sun to collect some ore samples, but the gnolls have overrun the place! It's going to be my head on a platter if I don't get those samples to the magister soon. Maybe you could help, ? You can find the ore in the tin and copper veins here, and the gnolls are carrying it around, too. When you have enough, take it to Magister Quallestis at the Sanctum of the Sun directly to the east. Go across the Dead Scar and you'll find the sanctum just south of Sungraze Peak.",starts={{npcID=16293,x=0.314,y=0.482,zoneID=3433}},ends={{npcID=16291,x=0.55,y=0.486,zoneID=3433}},coords={x=0.314,y=0.482,source="quest_giver",zoneID=3433},questType="standard"},
[9212] = {id=9212,name="Escape from the Catacombs",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3510,description="These trolls ambushed me and have been keeping me in this cage. I think they're planning to sacrifice me! Help me get out of here! The lock on the cage isn't that complex... I just can't get to it from this side. Please escort me back to the Farstrider Enclave. I'm sure Captain Helios will reward you, and you'll have my undying gratitude!",starts={{npcID=16295,x=0.628,y=0.326,zoneID=3433},{npcID=16295,x=0.602,y=0.806,zoneID=3433},{npcID=16295,x=0.63,y=0.326,zoneID=3510}},ends={{npcID=16220,x=0.722,y=0.296,zoneID=3433}},coords={x=0.628,y=0.326,source="quest_giver",zoneID=3433},questType="standard"},
[9214] = {id=9214,name="Shadowpine Weaponry",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description=", I want you to kill as many Shadowpine trolls as you can. We need their numbers greatly reduced before we can shift our attention toward Deatholme. And while you're at it, we might as well kill two birds with one stone, so bring me back a load of their weapons. Better that they not go to waste, and we can use them in the fight against the Scourge. Hit their camps hard to the east and the south at Zeb'Tela and Zeb'Nowa.",starts={{npcID=16220,x=0.722,y=0.296,zoneID=3433}},ends={{npcID=16220,x=0.722,y=0.296,zoneID=3433}},coords={x=0.722,y=0.296,source="quest_giver",zoneID=3433},questType="standard"},
[9215] = {id=9215,name="Bring Me Kel'gash's Head!",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="WANTED: Bring the head of Kel'gash the Wicked , chieftain of the Shadowpine trolls, to Captain Helios . No questions asked. Kel'gash is known to dwell somewhere to the south in Zeb'Nowa. REWARD: Yes, but no advances!",starts={{npcID=181153,x=0.722,y=0.312,zoneID=3433}},ends={{npcID=16220,x=0.722,y=0.296,zoneID=3433}},coords={x=0.722,y=0.312,source="quest_giver",zoneID=3433},questType="group"},
[9216] = {id=9216,name="Rotting Hearts",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="I hear the Amani trolls eat their enemies' hearts to steal their strength. They might just be on to something, . With the proper treatment, the hearts of the unliving can produce potent elixirs. Hunt down the zombies that roam the Dead Scar and bring me their hearts. I'll show you the kind of enhancement we can perform to your physical prowess against the undead.",starts={{npcID=16205,x=0.488,y=0.314,zoneID=3433}},ends={{npcID=16205,x=0.488,y=0.314,zoneID=3433}},coords={x=0.488,y=0.314,source="quest_giver",zoneID=3433},questType="standard"},
[9217] = {id=9217,name="More Rotting Hearts",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,starts={{npcID=16205,x=0.488,y=0.314,zoneID=3433}},ends={{npcID=16205,x=0.488,y=0.314,zoneID=3433}},coords={x=0.488,y=0.314,source="quest_giver",zoneID=3433},questType="standard"},
[9218] = {id=9218,name="Spinal Dust",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The dark energy that flows through the bodies of reanimated skeletons tends to accumulate primarily in their spine. I've discovered a method of instilling this energy into a potion that boosts our magical abilities against the undead. Bring me some spinal dust and I'll be glad to provide you with a sample. You'll find an ample number of skeletons wandering the Dead Scar, west of here.",starts={{npcID=16205,x=0.488,y=0.314,zoneID=3433}},ends={{npcID=16205,x=0.488,y=0.314,zoneID=3433}},coords={x=0.488,y=0.314,source="quest_giver",zoneID=3433},questType="standard"},
[9219] = {id=9219,name="More Spinal Dust",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,starts={{npcID=16205,x=0.488,y=0.314,zoneID=3433}},ends={{npcID=16205,x=0.488,y=0.314,zoneID=3433}},coords={x=0.488,y=0.314,source="quest_giver",zoneID=3433},questType="standard"},
[9220] = {id=9220,name="War on Deatholme",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="If you seek to aid our cause there is no better place to start than here and no better time to do it than now. By rebuilding the Sanctum of the Sun we've raised a banner of defiance in front of our enemy's seat of power: Deatholme. Go forth and fight the hordes of undead that inhabit the vile Scourge fortress.",starts={{npcID=16204,x=0.548,y=0.484,zoneID=3433}},ends={{npcID=16204,x=0.548,y=0.484,zoneID=3433}},coords={x=0.548,y=0.484,source="quest_giver",zoneID=3433},questType="standard"},
[9252] = {id=9252,name="Defending Fairbreeze Village",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="We've experienced a marked increase in Scourge attacks, . Our defenses are barely holding and there's no sign of reinforcements from Silvermoon City. Lend us a hand in defending the village by thinning the numbers of the undead roaming the Dead Scar nearby.",starts={{npcID=15942,x=0.468,y=0.718,zoneID=3430}},ends={{npcID=15942,x=0.468,y=0.718,zoneID=3430}},coords={x=0.468,y=0.718,source="quest_giver",zoneID=3430},questType="standard"},
[9253] = {id=9253,name="Runewarden Deryan",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="This increase in Scourge attacks leads me to believe there might be a malfunction at one of the protective runestones at the border with the Ghostlands. We used these ancient stones to protect us against the undead. Most of them were destroyed or lost after the attack on the Sunwell. Follow the road south, towards the Ghostlands, and look to the west for a small path. You will find Runewarden Deryan by the runestone nearby; he will know whether anything's wrong.",starts={{npcID=15942,x=0.468,y=0.718,zoneID=3430}},ends={{npcID=16362,x=0.442,y=0.854,zoneID=3430}},coords={x=0.468,y=0.718,source="quest_giver",zoneID=3430},questType="standard"},
[9254] = {id=9254,name="The Wayward Apprentice",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Thank you for your help, . While I get things back in order here, I'd like to ask you for a favor. One of my former apprentices embarked in a very dangerous line of research. She journeyed to the East Sanctum, in the middle of the Dead Scar. I worry for her well-being. See if you can find her and convince her to return to her senses.",starts={{npcID=16210,x=0.44,y=0.706,zoneID=3430}},ends={{npcID=15402,x=0.542,y=0.71,zoneID=3430}},coords={x=0.44,y=0.706,source="quest_giver",zoneID=3430},questType="standard"},
[9255] = {id=9255,name="Research Notes",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="As discouraging as my research results are, they still contain valuable data. I must have a Magister review my work before it is taken seriously. Please, take these notes to Magistrix Landra Dawnstrider at Fairbreeze Village, west of here.",starts={{npcID=15402,x=0.542,y=0.71,zoneID=3430}},ends={{npcID=16210,x=0.44,y=0.706,zoneID=3430}},coords={x=0.542,y=0.71,source="quest_giver",zoneID=3430},questType="standard"},
[9256] = {id=9256,name="Fairbreeze Village",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="I have another task for you, . Ranger Degolien was sent to Fairbreeze Village to find out more about a Wretched attack on a nearby shipyard. He has requested reinforcements which we cannot yet provide. Seek him out and grant him whatever aid you can. Fairbreeze Village can be reached by following the road out of Falconwing Square all the way towards the south. Good luck, .",starts={{npcID=15403,x=0.48,y=0.46,zoneID=3430}},ends={{npcID=15939,x=0.434,y=0.708,zoneID=3430}},coords={x=0.48,y=0.46,source="quest_giver",zoneID=3430},questType="standard"},
[9258] = {id=9258,name="The Scorched Grove",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="A foul taint in the soil precedes the expansion of the Scourge into a new area. The protective runestones along the border with the Ghostlands have warded the land against this taint in the past. The westernmost runestone was destroyed during a Scourge attack, which forced us to burn the ground around it to prevent the taint from spreading. My sister, Larianna Riverwind , watches over the Scorched Grove. Go find her; she might have some work for you.",starts={{npcID=16397,x=0.436,y=0.712,zoneID=3430}},ends={{npcID=15398,x=0.34,y=0.8,zoneID=3430}},coords={x=0.436,y=0.712,source="quest_giver",zoneID=3430},questType="standard"},
[9274] = {id=9274,name="Spirits of the Drowned",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The lake to the north has been haunted by the ghosts of my ancestors for as long as I can remember, . The poor souls were victims of a tragic incident in which scores of them drowned at the bottom of the lake. The details of the event are mostly forgotten, but their haunting cries serve as a constant reminder of their curse. If you're up to the task, I want you to go to the lake and put an end to their suffering, . You will have my gratitude as well as theirs... I'm sure.",starts={{npcID=16462,x=0.722,y=0.298,zoneID=3433}},ends={{npcID=16462,x=0.722,y=0.298,zoneID=3433}},coords={x=0.722,y=0.298,source="quest_giver",zoneID=3433},questType="standard"},
[9275] = {id=9275,name="A Little Dash of Seasoning",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="I'm on loan to the Farstriders in an attempt to help with their troll difficulties. I believe that I have a solution to their problem. At my disposal are a number of potent poisons. The trolls, as you know, are living creatures and therefore must eat. If we combine my poison with their food... well, I'm sure that the results will be entertaining! Care to help rid us of the Shadowpine trolls at Zeb'Nowa to the south? The camp straddles both the north and south sides of the road to Zul'Aman.",starts={{npcID=16464,x=0.726,y=0.316,zoneID=3433}},ends={{npcID=16464,x=0.726,y=0.316,zoneID=3433}},coords={x=0.726,y=0.316,source="quest_giver",zoneID=3433},questType="standard"},
[9276] = {id=9276,name="Attack on Zeb'Tela",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Our resources are spread pretty thin here, , so your help is going to be invaluable. The captain has tasked me with overseeing the harassment of the local Shadowpine troll camps. We have a policy of keeping them off balance until the day when we can launch a brutal offensive to wipe them out. Until then, we need all of the volunteers that we can get so that those Shadowpine troll numbers are decreased. Think you could head east to Zeb'Tela and hurt them a little?",starts={{npcID=16463,x=0.722,y=0.312,zoneID=3433}},ends={{npcID=16463,x=0.722,y=0.312,zoneID=3433}},coords={x=0.722,y=0.312,source="quest_giver",zoneID=3433},questType="standard"},
[9277] = {id=9277,name="Assault on Zeb'Nowa",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Time for something a little more challenging. Zeb'Nowa, to the south, is where the more powerful Shadowpine trolls make their home. In our continuing effort to keep the troll numbers to a minimum I'm dispatching you to go down there and assail them by whatever means you have at your disposal. What do you say, ? Ready to deal with some more trolls?",starts={{npcID=16463,x=0.722,y=0.312,zoneID=3433}},ends={{npcID=16463,x=0.722,y=0.312,zoneID=3433}},coords={x=0.722,y=0.312,source="quest_giver",zoneID=3433},questType="standard"},
[9279] = {id=9279,name="You Survived!",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="Nevermind my injuries, . It's a miracle that any of us are alive! It didn't look like you'd pull through; you've been in suspension for weeks. Something happened and the Exodar crashed. Many have died. But I'm relieved that you are alive, . With you leading our efforts, I'm sure we'll get to safety soon! Proenitus asked me to send you to him when you awoke. He's waiting for you at the bottom of the hill. Just follow the path southwest.",starts={{npcID=16475,x=0.842,y=0.43,zoneID=3524},{npcID=16475,x=0.614,y=0.294,zoneID=6456}},ends={{npcID=16477,x=0.804,y=0.458,zoneID=3524},{npcID=16477,x=0.528,y=0.358,zoneID=6456}},coords={x=0.842,y=0.43,source="quest_giver",zoneID=3524},questType="standard"},
[9280] = {id=9280,name="Replenishing the Healing Crystals",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="Our immediate concern is the depleted state of our healing crystals. We must replenish them quickly! Unfortunately, the only way to do this at this point is to extract the blood from the local vale moths. Their blood will make for a suitable substitute. The moths can be found in many places around the vale, but they are mostly concentrated in the northwest.",starts={{npcID=16477,x=0.804,y=0.458,zoneID=3524},{npcID=16477,x=0.528,y=0.358,zoneID=6456}},ends={{npcID=16477,x=0.804,y=0.458,zoneID=3524},{npcID=16477,x=0.528,y=0.358,zoneID=6456}},coords={x=0.804,y=0.458,source="quest_giver",zoneID=3524},questType="standard"},
[9281] = {id=9281,name="Clearing the Way",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Magister Kaendris sent me down here to clear the area of any hostile wildlife. Once this area is secured, the magisters plan to turn it into some sort of advance outpost against the Scourge. Now if there's one thing I've learned as an apprentice it's to delegate responsibility - especially in matters that endanger one's life! If you're interested, I'll pay you well to kill the greater spindlewebs and ghostclaw ravagers to the west and south of here.",starts={{npcID=16480,x=0.464,y=0.564,zoneID=3433}},ends={{npcID=16480,x=0.464,y=0.564,zoneID=3433}},coords={x=0.464,y=0.564,source="quest_giver",zoneID=3433},questType="standard"},
[9282] = {id=9282,name="The Farstrider Enclave",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Magisters and Farstriders may not see eye to eye all the time, . When it comes to Dar'Khan, however, we're all in agreement that a way must be found to defeat him and his legions. Ranger Vynna , at the Farstrider Enclave northeast of here, has come across important information regarding our enemy. Speak to her and see if you can be of assistance.",starts={{npcID=16239,x=0.55,y=0.488,zoneID=3433}},ends={{npcID=16203,x=0.718,y=0.326,zoneID=3433}},coords={x=0.55,y=0.488,source="quest_giver",zoneID=3433},questType="standard"},
[9283] = {id=9283,name="Rescue the Survivors!",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="The healing crystals are replenished, but that is not the only way we can help the injured. All draenei can tap the gift of the Naaru to heal. You must use this ability to heal one of the crash survivors. You'll find most of the survivors in the areas to the west and northwest, but the crash scattered us all over the vale. The survivors have suffered from exposure to the irradiated power crystals, so you should be able to find them by the red glow that surround them. You must save them, .",starts={{npcID=16502,x=0.8,y=0.49,zoneID=3524},{npcID=16502,x=0.52,y=0.42,zoneID=6456}},ends={{npcID=16502,x=0.8,y=0.49,zoneID=3524},{npcID=16502,x=0.52,y=0.42,zoneID=6456}},coords={x=0.8,y=0.49,source="quest_giver",zoneID=3524},questType="standard"},
[9290] = {id=9290,name="Mage Training",level=5,requiredLevel=5,faction="alliance",expansion=1,zoneID=6456,mapID=97,starts={{npcID=16500,x=0.51,y=0.424,mapID=97}},ends={{npcID=16500,x=0.51,y=0.424,mapID=97}},coords={x=0.51,y=0.424,source="quest_giver",mapID=97},questType="standard"},
[9291] = {id=9291,name="Priest Training",level=5,requiredLevel=5,faction="alliance",expansion=1,zoneID=6456,mapID=97,starts={{npcID=16502,x=0.8,y=0.49,mapID=97},{npcID=16502,x=0.52,y=0.42,mapID=97}},ends={{npcID=16502,x=0.8,y=0.49,mapID=97},{npcID=16502,x=0.52,y=0.42,mapID=97}},coords={x=0.8,y=0.49,source="quest_giver",mapID=97},questType="standard"},
[9293] = {id=9293,name="What Must Be Done...",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="The nearby lake has been contaminated by one of the ship's power crystals. Many of the plants and animals of Ammen Vale have been mutated because of this. I have a theory on how to heal the lake, but I must have samples from the mutated lashers for analysis. They can be found to the west in the Ammen Fields. Will you help me, ?",starts={{npcID=16514,x=0.792,y=0.464,zoneID=3524},{npcID=16514,x=0.498,y=0.372,zoneID=6456}},ends={{npcID=16514,x=0.792,y=0.464,zoneID=3524},{npcID=16514,x=0.498,y=0.372,zoneID=6456}},coords={x=0.792,y=0.464,source="quest_giver",zoneID=3524},questType="standard"},
[9294] = {id=9294,name="Healing the Lake",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="Thank goodness, I think it'll work! I have an agent for you to spread at Silverline Lake to the south. It will neutralize the effects of the irradiated ship's power crystal that fell there. Swim out and scatter the neutralizing agent near it. Don't worry, you won't be exposed long enough to become irradiated.",starts={{npcID=16514,x=0.792,y=0.464,zoneID=3524},{npcID=16514,x=0.498,y=0.372,zoneID=6456}},ends={{npcID=16514,x=0.792,y=0.464,zoneID=3524},{npcID=16514,x=0.498,y=0.372,zoneID=6456}},coords={x=0.792,y=0.464,source="quest_giver",zoneID=3524},questType="standard"},
[9303] = {id=9303,name="Inoculation",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="Zhanaa needs our help to salvage parts from the Exodar. Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage. Just get close to the unaffected ones and use the crystal on them. Unfortunately, you'll have to kill the others. You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.",starts={{npcID=16535,x=0.794,y=0.514,zoneID=3524},{npcID=16535,x=0.506,y=0.486,zoneID=6456}},ends={{npcID=16535,x=0.794,y=0.514,zoneID=3524},{npcID=16535,x=0.506,y=0.486,zoneID=6456}},coords={x=0.794,y=0.514,source="quest_giver",zoneID=3524},questType="standard"},
[9305] = {id=9305,name="Spare Parts",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale . There were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. , you must go south to Nestlewood Thicket and Hills to find the spare parts.",starts={{npcID=17071,x=0.794,y=0.512,zoneID=3524},{npcID=17071,x=0.504,y=0.48,zoneID=6456}},ends={{npcID=17071,x=0.794,y=0.512,zoneID=3524},{npcID=17071,x=0.504,y=0.48,zoneID=6456}},coords={x=0.794,y=0.512,source="quest_giver",zoneID=3524},questType="standard"},
[9309] = {id=9309,name="The Missing Scout",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="We now have several separate confirmations of unusual activity up on the Shadow Ridge. This is disturbing; we thought that the scouting missions already undertaken had been thorough. One of my scouts hasn't reported back yet. , I need you to head southwest to the other side of Silverline Lake and find Tolaan , and see what has delayed him.",starts={{npcID=16535,x=0.794,y=0.514,zoneID=3524},{npcID=16535,x=0.506,y=0.486,zoneID=6456}},ends={{npcID=16546,x=0.72,y=0.608,zoneID=3524},{npcID=16546,x=0.338,y=0.692,zoneID=6456}},coords={x=0.794,y=0.514,source="quest_giver",zoneID=3524},questType="standard"},
[9311] = {id=9311,name="Blood Elf Spy",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="I have a plan. We must kill their leader. Without their master, perhaps they will retreat to regroup. We just need to buy time until the repairs are completed. Then Vindicator Aldar must know of this. Kill the surveyor, then return and tell him what we've found.",starts={{npcID=16546,x=0.72,y=0.608,zoneID=3524},{npcID=16546,x=0.338,y=0.692,zoneID=6456}},ends={{npcID=16535,x=0.794,y=0.514,zoneID=3524},{npcID=16535,x=0.506,y=0.486,zoneID=6456}},coords={x=0.72,y=0.608,source="quest_giver",zoneID=3524},questType="standard"},
[9312] = {id=9312,name="The Emitter",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description=", while you were out investigating the Shadow Ridge, Zhanaa here has been going on about the holographic emitter. You might want to speak with her.",starts={{npcID=16535,x=0.794,y=0.514,zoneID=3524},{npcID=16535,x=0.506,y=0.486,zoneID=6456}},ends={{npcID=17071,x=0.794,y=0.512,zoneID=3524},{npcID=17071,x=0.504,y=0.48,zoneID=6456}},coords={x=0.794,y=0.514,source="quest_giver",zoneID=3524},questType="standard"},
[9313] = {id=9313,name="Travel to Azure Watch",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="By all that is good, , you must go at once to this Azure Watch and speak with Dyvuun! There is a path that leads west off of this tiny isle. Follow it and cross the Crystalbrook River to arrive on the larger part of the isle. Continue to follow the path and you should find Azure Watch. See if you can convince them to send us some aid and supplies. The rest of us will follow when we can. Thank you, we wouldn't have made it without you!",starts={{npcID=17071,x=0.794,y=0.512,zoneID=3524},{npcID=17071,x=0.504,y=0.48,zoneID=6456}},ends={{npcID=16551,x=0.486,y=0.502,zoneID=3524}},coords={x=0.794,y=0.512,source="quest_giver",zoneID=3524},questType="standard"},
[9314] = {id=9314,name="Word from Azure Watch",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="! A couple mutated beasts jumped me and my leg is injured. I was sent on a scouting mission from Azure Watch after we received word from Zhanaa. Please, could you go speak with Caregiver Chellan in my stead? She needs to know how many people to expect in Azure Watch. Just cross the Crystalbrook River here and continue following the road until you get to Azure Watch. Be sure to ask her for a place for yourself to stay in.",starts={{npcID=16554,x=0.646,y=0.54,zoneID=3524}},ends={{npcID=16553,x=0.484,y=0.492,zoneID=3524}},coords={x=0.646,y=0.54,source="quest_giver",zoneID=3524},questType="standard"},
[9315] = {id=9315,name="Anok'suten",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Come closer, I am ... dying. I was sent here ... to slay these Nerubians, but Vandril didn't ... know that they have a leader. dying blood elf coughs up a good amount of blood.> You must find and ... slay Anok'suten . Get help. She wanders around ... Suncrown Village.",starts={{npcID=16601,x=0.574,y=0.15,zoneID=3433}},ends={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},coords={x=0.574,y=0.15,source="quest_giver",zoneID=3433},questType="group"},
[9324] = {id=9324,name="Stealing Orgrimmar's Flame",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3703,description="This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...",ends={{npcID=16817,x=0.496,y=0.72,zoneID=1519},{npcID=16817,x=0.64,y=0.258,zoneID=1537},{npcID=16817,x=0.622,y=0.486,zoneID=1657},{npcID=16817,x=0.414,y=0.252,zoneID=3557},{npcID=16817,x=0.612,y=0.322,zoneID=3703}},questType="standard"},
[9325] = {id=9325,name="Stealing Thunder Bluff's Flame",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3703,description="This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...",ends={{npcID=16817,x=0.496,y=0.72,zoneID=1519},{npcID=16817,x=0.64,y=0.258,zoneID=1537},{npcID=16817,x=0.622,y=0.486,zoneID=1657},{npcID=16817,x=0.414,y=0.252,zoneID=3557},{npcID=16817,x=0.612,y=0.322,zoneID=3703}},questType="standard"},
[9326] = {id=9326,name="Stealing the Undercity's Flame",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3703,description="This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...",ends={{npcID=16817,x=0.496,y=0.72,zoneID=1519},{npcID=16817,x=0.64,y=0.258,zoneID=1537},{npcID=16817,x=0.622,y=0.486,zoneID=1657},{npcID=16817,x=0.414,y=0.252,zoneID=3557},{npcID=16817,x=0.612,y=0.322,zoneID=3703}},questType="standard"},
[9327] = {id=9327,name="The Forsaken",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="I know it seems strange, but these Forsaken are here to help. You should speak with their leader, High Executor Mavren . He's in the tower on the west side of town. And, , when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!",starts={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},ends={{npcID=16252,x=0.448,y=0.324,zoneID=3433}},coords={x=0.464,y=0.284,source="quest_giver",zoneID=3433},questType="standard"},
[9328] = {id=9328,name="Hero of the Sin'dorei",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3487,description="This is the beginning of a new chapter in the history of our race, . Our lands will be reclaimed and we shall cement our bond with Sylvanas and her allies. Take the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City. He'll be eager to hear the news.",starts={{npcID=16239,x=0.55,y=0.488,zoneID=3433}},ends={{npcID=16802,x=0.54,y=0.204,zoneID=3487}},coords={x=0.55,y=0.488,source="quest_giver",zoneID=3433},questType="standard"},
[9329] = {id=9329,name="The Forsaken",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren . He's in the tower on the west side of town. And, , when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!",starts={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},ends={{npcID=16252,x=0.448,y=0.324,zoneID=3433}},coords={x=0.464,y=0.284,source="quest_giver",zoneID=3433},questType="standard"},
[9330] = {id=9330,name="Stealing Stormwind's Flame",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3703,description="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...",ends={{npcID=16818,x=0.62,y=0.668,zoneID=85},{npcID=16818,x=0.674,y=0.08,zoneID=1497},{npcID=16818,x=0.478,y=0.384,zoneID=1637},{npcID=16818,x=0.214,y=0.278,zoneID=1638},{npcID=16818,x=0.698,y=0.426,zoneID=3487},{npcID=16818,x=0.62,y=0.322,zoneID=3703}},questType="standard"},
[9331] = {id=9331,name="Stealing Ironforge's Flame",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3703,description="This flame, stolen from the heart of Ironforge itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...",ends={{npcID=16818,x=0.62,y=0.668,zoneID=85},{npcID=16818,x=0.674,y=0.08,zoneID=1497},{npcID=16818,x=0.478,y=0.384,zoneID=1637},{npcID=16818,x=0.214,y=0.278,zoneID=1638},{npcID=16818,x=0.698,y=0.426,zoneID=3487},{npcID=16818,x=0.62,y=0.322,zoneID=3703}},questType="standard"},
[9332] = {id=9332,name="Stealing Darnassus's Flame",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3703,description="This flame, stolen from the shores of Teldrassil, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...",ends={{npcID=16818,x=0.62,y=0.668,zoneID=85},{npcID=16818,x=0.674,y=0.08,zoneID=1497},{npcID=16818,x=0.478,y=0.384,zoneID=1637},{npcID=16818,x=0.214,y=0.278,zoneID=1638},{npcID=16818,x=0.698,y=0.426,zoneID=3487},{npcID=16818,x=0.62,y=0.322,zoneID=3703}},questType="standard"},
[9339] = {id=9339,name="A Thief's Reward",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3703,mapID=111,starts={{npcID=16818,x=0.62,y=0.668,mapID=18},{npcID=16818,x=0.674,y=0.08,mapID=90},{npcID=16818,x=0.478,y=0.384,mapID=85},{npcID=16818,x=0.214,y=0.278,mapID=88},{npcID=16818,x=0.698,y=0.426,mapID=110},{npcID=16818,x=0.62,y=0.322,mapID=111}},ends={{npcID=16818,x=0.62,y=0.668,mapID=18},{npcID=16818,x=0.674,y=0.08,mapID=90},{npcID=16818,x=0.478,y=0.384,mapID=85},{npcID=16818,x=0.214,y=0.278,mapID=88},{npcID=16818,x=0.698,y=0.426,mapID=110},{npcID=16818,x=0.62,y=0.322,mapID=111}},coords={x=0.62,y=0.668,source="quest_giver",mapID=111},questType="standard"},
[9340] = {id=9340,name="The Great Fissure",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="We're dangerously close to becoming fenced in by Alliance forces. With the influx of sin'dorei pilgrims from Azeroth, we must establish a route that's safe from our enemies' prying eyes. I've given it some thought and have arrived at a solution. We're to establish a secret path through the Great Fissure. Yes, even though the area is crawling with brutal rock flayers, they are merely beasts and can be taught to fear us. I want you to go and kill a good number of them. They shall learn fear.",starts={{npcID=16789,x=0.284,y=0.602,zoneID=3483}},ends={{npcID=16789,x=0.284,y=0.602,zoneID=3483}},coords={x=0.284,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[9345] = {id=9345,name="Preparing the Salve",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Just as Zeth'Gor came into view, a Legion patrol caught sight of me. I ran, hoping to duck into one of the towers in the distance, but one of their felhounds caught up with me and nearly hamstrung me! I managed to escape, but my leg is in terrible shape. Stone Guard Ambelan found me and brought me here. Now, I have to find a way to tend to my leg. Spineleaf grows in and around the Valley of Bones to the north . A salve made from it will dull the pain enough for me to travel.",starts={{npcID=16858,x=0.61,y=0.816,zoneID=3483}},ends={{npcID=16858,x=0.61,y=0.816,zoneID=3483}},coords={x=0.61,y=0.816,source="quest_giver",zoneID=3483},questType="standard"},
[9349] = {id=9349,name="Ravager Egg Roundup",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3519,description="I'm starving! There's irony in that, wouldn't you say? A starving cook? Legassi laughs half-heartedly and taps a folded piece of parchment he has in his pocket.> According to this tourist map we were following - before we were so rudely shot down - there's an area to the southwest, near Terokkar Forest. It's called the Razorthorn Trail, and supposedly it's brimming with delicious ravager eggs ! I could cook up quite a feast if only someone were brave enough to go down there and get me some!",starts={{npcID=19344,x=0.492,y=0.748,zoneID=3483}},ends={{npcID=19344,x=0.492,y=0.748,zoneID=3483}},coords={x=0.492,y=0.748,source="quest_giver",zoneID=3483},questType="standard"},
[9351] = {id=9351,name="Voidwalkers Gone Wild",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="Even if I can get the zeppelin's frame repaired, I'll have to find something else to power the engine. I'm all out of fuel and there's no place to fill up around here! To the south of us is an area of broken land called the Warp Fields. It's full of rogue and uncontrolled voidwalkers, but I like to think of them as walking batteries. If you can bring me enough of their essence, I can convert the zeppelin's engine to run on it. Five gold says I'll even get better mileage out of it, too!",starts={{npcID=19367,x=0.49,y=0.748,zoneID=3483}},ends={{npcID=19367,x=0.49,y=0.748,zoneID=3483}},coords={x=0.49,y=0.748,source="quest_giver",zoneID=3483},questType="standard"},
[9352] = {id=9352,name="Darnassian Intrusions",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Besides the constant threat that the Wretched represent, I also have to deal with all kind of fictitious reports of night elf sightings. Though most reports are unfounded, one recent incident demands further investigation. The West Sanctum, one of our primary energy sources, has suffered a terrible malfunction and rumors of Darnassian sabotage are rampant. Travel there and deal with anyone that looks suspicious. Report back to Ley-Keeper Velania , who watches over the sanctum.",starts={{npcID=15403,x=0.48,y=0.46,zoneID=3430}},ends={{npcID=15401,x=0.366,y=0.574,zoneID=3430}},coords={x=0.48,y=0.46,source="quest_giver",zoneID=3430},questType="standard"},
[9355] = {id=9355,name="A Job for an Intelligent Man",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Well met, . Now that reinforcements are finally arriving, we can recapture some semblance of a normal life. One of our first goals is to restore the flow of men and goods along the road to the southwest, but it must be reclaimed from the crust bursters that've overrun the area. If you're willing to help us deal with this menace, you would have the gratitude of the Sons. Watch carefully for the disturbed ground they leave in their wake.",starts={{npcID=16837,x=0.52,y=0.624,zoneID=3483}},ends={{npcID=16837,x=0.52,y=0.624,zoneID=3483}},coords={x=0.52,y=0.624,source="quest_giver",zoneID=3483},questType="standard"},
[9356] = {id=9356,name="Smooth as Butter",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="Screed likes to say his flying is as \"smooth as butter.\" I think \"butterfingered\" is more like it! Take a look at the wreckage over there. He calls it a \"rough\" landing. Sure, we got shot at, but I'd be willing to cut him a little more slack if he didn't brag about his piloting skills so often! I think I'm going to make him a batch of wings to drive the point home. To the east, in the Valley of Bones, you'll find bonestripper buzzards. Their wings are plump, juicy, and perfect for my needs.",starts={{npcID=19344,x=0.492,y=0.748,zoneID=3483}},ends={{npcID=19344,x=0.492,y=0.748,zoneID=3483}},coords={x=0.492,y=0.748,source="quest_giver",zoneID=3483},questType="standard"},
[9358] = {id=9358,name="Ranger Sareyn",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Don't take the safety of this village for granted. We're under siege by the Scourge on the east and the Wretched to the west. Ranger Sareyn keeps our borders safe from the undead that pour in from the Dead Scar. Follow the road eastwards out of town and see if you can lend her a hand.",starts={{npcID=15397,x=0.436,y=0.712,zoneID=3430}},ends={{npcID=15942,x=0.468,y=0.718,zoneID=3430}},coords={x=0.436,y=0.712,source="quest_giver",zoneID=3430},questType="standard"},
[9359] = {id=9359,name="Farstrider Retreat",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Your help in subduing the Wretched has been invaluable. The Farstriders would surely have use for someone like you in their fight against the Amani trolls. Look for the Farstrider Retreat to the northeast of here, speak to Lieutenant Dawnrunner and see what assistance she might need.",starts={{npcID=15939,x=0.434,y=0.708,zoneID=3430}},ends={{npcID=15399,x=0.602,y=0.626,zoneID=3430}},coords={x=0.434,y=0.708,source="quest_giver",zoneID=3430},questType="standard"},
[9360] = {id=9360,name="Amani Invasion",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Though you don't understand the language in these battle plans, you clearly make out a map marking the positions of the Farstrider Retreat and Fairbreeze Village. You'd best let Lieutenant Dawnrunner at the Farstrider Retreat know about this.",ends={{npcID=15399,x=0.602,y=0.626,zoneID=3430}},questType="standard"},
[9361] = {id=9361,name="Helboar, the Other White Meat",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="Those eggs are superb, but what do you say we kick it up another notch? A side of bacon would round out the meal perfectly and I know just where to get it. This place is littered with helboars. Of course, there's no one here to inspect and tenderize the meat, but we're in luck! Legassi rummages around in his pack and produces a flask.> This wasn't made for use on pork, but cooking is as much about improvisation as anything else!",starts={{npcID=19344,x=0.492,y=0.748,zoneID=3483}},ends={{npcID=19344,x=0.492,y=0.748,zoneID=3483}},coords={x=0.492,y=0.748,source="quest_giver",zoneID=3483},questType="standard"},
[9363] = {id=9363,name="Warning Fairbreeze Village",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Go to Fairbreeze Village and notify Ranger Degolien of the Amani plans. Even with Zul'Marosh dead, Fairbreeze must prepare for a troll attack. Tell Degolien I will send him reinforcements as soon as possible.",starts={{npcID=15399,x=0.602,y=0.626,zoneID=3430}},ends={{npcID=15939,x=0.434,y=0.708,zoneID=3430}},coords={x=0.602,y=0.626,source="quest_giver",zoneID=3430},questType="standard"},
[9365] = {id=9365,name="A Thief's Reward",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3703,mapID=111,starts={{npcID=16817,x=0.496,y=0.72,mapID=84},{npcID=16817,x=0.64,y=0.258,mapID=87},{npcID=16817,x=0.622,y=0.486,mapID=89},{npcID=16817,x=0.414,y=0.252,mapID=103},{npcID=16817,x=0.612,y=0.322,mapID=111}},ends={{npcID=16817,x=0.496,y=0.72,mapID=84},{npcID=16817,x=0.64,y=0.258,mapID=87},{npcID=16817,x=0.622,y=0.486,mapID=89},{npcID=16817,x=0.414,y=0.252,mapID=103},{npcID=16817,x=0.612,y=0.322,mapID=111}},coords={x=0.496,y=0.72,source="quest_giver",mapID=111},questType="standard"},
[9366] = {id=9366,name="In Need of Felblood",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Northeast of here lie the Pools of Aggonar. Once a sacred site to the draenei, their waters were corrupted after the blood from the demon Aggonar was spilled into them. That blood, though old and diluted, still possesses tremendous power. Terrorfiends now walk the area, empowered by the pure demonic energies of the original blood. Slay them and retrieve as much felblood as you can. I'll make it worth your while.",starts={{npcID=16791,x=0.27,y=0.596,zoneID=3483}},ends={{npcID=16791,x=0.27,y=0.596,zoneID=3483}},coords={x=0.27,y=0.596,source="quest_giver",zoneID=3483},questType="standard"},
[9369] = {id=9369,name="Replenishing the Healing Crystals",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="We are the draenei. Our ship crashed and, since we have many wounded, our immediate concern is the depleted state of our healing crystals. We must replenish them quickly! Unfortunately, the only way to do this at this point is to extract the blood from the local vale moths. Their blood will make for a suitable substitute. The moths can be found in many places around the vale, but mostly in the northwest.",starts={{npcID=16477,x=0.804,y=0.458,zoneID=3524},{npcID=16477,x=0.528,y=0.358,zoneID=6456}},ends={{npcID=16477,x=0.804,y=0.458,zoneID=3524},{npcID=16477,x=0.528,y=0.358,zoneID=6456}},coords={x=0.804,y=0.458,source="quest_giver",zoneID=3524},questType="standard"},
[9370] = {id=9370,name="The Cleansing Must Be Stopped",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Our scouts captured a draenei paladin at the Pools of Aggonar. He was to take part in a cleansing ritual to purify the pools. We must stop the draenei from succeeding or we will lose our supply of felblood! He was carrying this signaling gem , looking to mark a spot where a priest - or \"anchorite\" as they call themselves - could perform their rituals in safety. Place the gem near the Altar of Aggonar and be ready to ambush any approaching draenei. I suggest that you take a friend or two along.",starts={{npcID=16791,x=0.27,y=0.596,zoneID=3483}},ends={{npcID=16791,x=0.27,y=0.596,zoneID=3483}},coords={x=0.27,y=0.596,source="quest_giver",zoneID=3483},questType="standard"},
[9371] = {id=9371,name="Botanist Taerix",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description=", Botanist Taerix is in need of your assistance. You'll find her with her apprentices to the west, outside the ship.",starts={{npcID=16477,x=0.804,y=0.458,zoneID=3524},{npcID=16477,x=0.528,y=0.358,zoneID=6456}},ends={{npcID=16514,x=0.792,y=0.464,zoneID=3524},{npcID=16514,x=0.498,y=0.372,zoneID=6456}},coords={x=0.804,y=0.458,source="quest_giver",zoneID=3524},questType="standard"},
[9372] = {id=9372,name="Demonic Contamination",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="Welcome to the Cenarion Post, . We don't often get company out here, but I'm grateful for the visit. My work with the creatures of this desolate land requires me to travel to many remote places. The Cenarion Expedition has dispatched me to study some of the most dangerous wildlife in Outland, and I've made a startling discovery. While many creatures here have already undergone radical changes, they continue to mutate. I'm collecting blood samples to document the changes, and any help would be welcome.",starts={{npcID=16991,x=0.156,y=0.522,zoneID=3483}},ends={{npcID=16991,x=0.156,y=0.522,zoneID=3483}},coords={x=0.156,y=0.522,source="quest_giver",zoneID=3483},questType="standard"},
[9373] = {id=9373,name="Missing Missive",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="Upon examining the battered leather case, it becomes apparent that the container's damage must've been caused by the caustic fluid of the worm's digestive tract. The leather appears to have been intricately tooled at one time, but the details of its adornment can no longer be made out. The only recognizable feature of the case is a worn logo of the Cenarion Circle. Knowing nothing about the contents of the case, you decide the best course of action would be to deliver it to a Circle member.",ends={{npcID=16991,x=0.156,y=0.522,zoneID=3483}},questType="standard"},
[9374] = {id=9374,name="Arelion's Journal",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="My husband, Arelion, had been fascinated with the Pools of Aggonar ever since we arrived in Outland. He spent much of his time studying slimes, of all things! He went missing in there a few days ago. They say he's dead and there's nothing I can do about it. One thing I can do is try to ensure that his research doesn't die with him. Go northeast to the pools and look for his journal. He always carried it inside a brown knapsack.",starts={{npcID=16793,x=0.264,y=0.604,zoneID=3483}},ends={{npcID=16793,x=0.264,y=0.604,zoneID=3483}},coords={x=0.264,y=0.604,source="quest_giver",zoneID=3483},questType="standard"},
[9375] = {id=9375,name="The Road to Falcon Watch",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Please, , get me out of this cage! I foolishly set out from Thrallmar ahead of the main group, despite Martik Tor'seldori's warnings. I was set upon by horrible creatures that could only be the ravagers he talked about. I managed to drive them off, but that was only the beginning of my troubles. As I bound my wounds, those bird men found me, dragged me back to this cave, and locked me in this cage! I must get to Falcon Watch!",starts={{npcID=16993,x=0.246,y=0.76,zoneID=3483}},ends={{npcID=17015,x=0.27,y=0.618,zoneID=3483}},coords={x=0.246,y=0.76,source="quest_giver",zoneID=3483},questType="standard"},
[9376] = {id=9376,name="A Pilgrim's Plight",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="That wounded pilgrim seems to be shouting something about a pack. When you encountered her, did you see a pack nearby? Hmm... She must've left it when fleeing from her attackers. The quillfang ravagers, in their ravine to the south, are known to attack solitary travelers. If she doesn't calm down, I won't be able to tend her wounds. Her stubbornness may just cost her her life. Go to Dustquill Ravine and see if you can find her campsite. I'm willing to bet she left it there.",starts={{npcID=17015,x=0.27,y=0.618,zoneID=3483}},ends={{npcID=17015,x=0.27,y=0.618,zoneID=3483}},coords={x=0.27,y=0.618,source="quest_giver",zoneID=3483},questType="standard"},
[9381] = {id=9381,name="Trueflight Arrows",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="With the influx of pilgrims and the encroachment of Alliance forces, things around Falcon Watch have gotten quite busy lately. In my spare time, I usually help prepare batches of arrows for the rangers, but I haven't had the chance to gather feathers for the fletching in a long time. I could offer you a bit of coin if you'd be willing to gather the tail feathers of the bonestripper vultures. In the past, I've found them circling the bones of large beasts to the north of Falcon Watch.",starts={{npcID=16790,x=0.276,y=0.604,zoneID=3483}},ends={{npcID=16790,x=0.276,y=0.604,zoneID=3483}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=3483},questType="standard"},
[9383] = {id=9383,name="An Ambitious Plan",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The blood elves epitomize the irresponsible use of magic, . They do not control magical energy. Rather, they are slaves to it and will suffer nothing to stand between them and their addiction. They consume the energies of Outland's voidwalkers to power their demonic magics. I've prepared a crystal charged with a spell that will allow us to neutralize a voidwalker and sever its link to this world when destroyed. I've mostly seen the voidwalkers in the Warp Fields to the southeast of Hellfire Citadel.",starts={{npcID=17006,x=0.232,y=0.366,zoneID=3483}},ends={{npcID=17006,x=0.232,y=0.366,zoneID=3483}},coords={x=0.232,y=0.366,source="quest_giver",zoneID=3483},questType="standard"},
[9385] = {id=9385,name="Rampaging Ravagers",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="So Honor Hold sends us to deal with the arakkoa and we set up camp here thinking hey isn't this a great spot. Little did we know how close we were to the quillfang ravagers . They are relentless predators and have made any sort of work on our part impossible. There's a bit of coin in it for you if you can deal with them for us. Do you feel up to it?",starts={{npcID=16850,x=0.238,y=0.72,zoneID=3483}},ends={{npcID=16850,x=0.238,y=0.72,zoneID=3483}},coords={x=0.238,y=0.72,source="quest_giver",zoneID=3483},questType="standard"},
[9387] = {id=9387,name="Source of the Corruption",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Uncorrupted draenei, like this unlucky fellow here, are virtuous champions of the Light. What corruption caused their great race to devolve into the Broken and Lost Ones? I've heard a theory that exposure to fel energies is what caused the mutation. I would like to put that theory to the test. Northwest of here lie the Ruins of Sha'naar. There you will find lowly Broken commanded by Illidari taskmasters. Bring me demonic essences from the taskmasters so that I can test them on this draenei.",starts={{npcID=16794,x=0.268,y=0.596,zoneID=3483}},ends={{npcID=16794,x=0.268,y=0.596,zoneID=3483}},coords={x=0.268,y=0.596,source="quest_giver",zoneID=3483},questType="standard"},
[9390] = {id=9390,name="In Search of Sedai",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Hear my plight, . My brother, Sedai, left long ago to contact the orcs of Mag'har Post. Ever the idealist, he thought the time was ripe to set our differences aside and negotiate a peace with them. He's been missing for days and I fear for the worst. Would you set my mind to rest and look for him? Sedai must be somewhere nearby to the east.",starts={{npcID=16834,x=0.23,y=0.404,zoneID=3483}},ends={{npcID=16852,x=0.268,y=0.374,zoneID=3483}},coords={x=0.23,y=0.404,source="quest_giver",zoneID=3483},questType="standard"},
[9391] = {id=9391,name="Marking the Path",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="With the rock flayer population thinned, all that's left is to signal the safe path to our pilgrims. Return to the Great Fissure with this torch and seek the three beacons that mark the path from the east. Light the three beacons and return to me. Be warned that the beacons will attract any nearby rock flayers when you first light them.",starts={{npcID=16789,x=0.284,y=0.602,zoneID=3483}},ends={{npcID=16789,x=0.284,y=0.602,zoneID=3483}},coords={x=0.284,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[9394] = {id=9394,name="Where's Wyllithen?",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="The Duskwither groundskeeper has gone missing! Someone must have forgotten to tell him to leave when the magister and everyone else did. I know that he's still somewhere around here on the grounds, but I dare not go looking for him myself with all of these magical creatures roaming about. Will you find him for me, , and make sure that he's alright?",starts={{npcID=15924,x=0.678,y=0.564,zoneID=3430}},ends={{npcID=15969,x=0.686,y=0.47,zoneID=3430}},coords={x=0.678,y=0.564,source="quest_giver",zoneID=3430},questType="standard"},
[9395] = {id=9395,name="Saltheril's Haven",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="I swear that I'm going to fireball someone if I get one more request from Lord Saltheril concerning supplies for his party! Do I look like a party planner?! Between you and me, that fool and his sycophants are living in denial that we're under attack here! Some of us are actually busy with, oh, I don't know, defending what's left of Quel'Thalas! , would you please head over to Saltheril's Haven and see if you can shut him up? It's just down the road to the west.",starts={{npcID=16210,x=0.44,y=0.706,zoneID=3430}},ends={{npcID=16144,x=0.382,y=0.734,zoneID=3430}},coords={x=0.44,y=0.706,source="quest_giver",zoneID=3430},questType="standard"},
[9396] = {id=9396,name="Magic of the Arakkoa",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Outland holds many secrets, . It's only a matter of time before we uncover them all. The half-bird, half-man species of the arakkoa possesses ancient arcane knowledge that would aid us greatly in our exploration of this world. Travel to the Den of Haal'esh, south of here. Obtain any magical scrolls that the Haal'eshi might be carrying on them and bring them to me.",starts={{npcID=16792,x=0.27,y=0.598,zoneID=3483}},ends={{npcID=16792,x=0.27,y=0.598,zoneID=3483}},coords={x=0.27,y=0.598,source="quest_giver",zoneID=3483},questType="standard"},
[9397] = {id=9397,name="Birds of a Feather",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="The Haal'eshi arakkoa have domesticated a beautiful bird species called the kaliri. I've managed to capture a young male and they appear to be trainable. The females are much rarer, but if I had one I could attempt to breed them. She has to be young, though... a hatchling. An older wild bird wouldn't survive in captivity. Take this cage and travel south, to the Den of Haal'esh. Search the nests for eggs that are ready to hatch. If you bring me back a female hatchling, I'll reward you handsomely.",starts={{npcID=16790,x=0.276,y=0.604,zoneID=3483}},ends={{npcID=16790,x=0.276,y=0.604,zoneID=3483}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=3483},questType="standard"},
[9398] = {id=9398,name="Deadly Predators",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The Broken that live in Outland have endured endless violence. It is of little surprise that as soon as the Dark Portal opened they flocked to it in droves with hopes of escaping this land. Unfortunately for our confused brothers and sisters coming from the south, the rock flayers that inhabit the Great Fissure see them as easy prey. Go there and thin the rock flayer population, so that our kin might have a chance.",starts={{npcID=16797,x=0.234,y=0.402,zoneID=3483}},ends={{npcID=16797,x=0.234,y=0.402,zoneID=3483}},coords={x=0.234,y=0.402,source="quest_giver",zoneID=3483},questType="standard"},
[9399] = {id=9399,name="Cruel Taskmasters",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="You probably think most Broken are evil, don't you? In reality many just lack guidance. Before I met the Omenai, I too was lost. Our minds suffered terrible pain from the orcs' demonic magic. We are easily confused and taken advantage of. Demons allied with Illidan raid Hellfire daily and capture our kind as slaves. With the Omenai we now have hope. Travel to the Ruins of Sha'naar, southwest of here, and slay the Illidari taskmasters so my people may be free!",starts={{npcID=16799,x=0.23,y=0.402,zoneID=3483}},ends={{npcID=16799,x=0.23,y=0.402,zoneID=3483}},coords={x=0.23,y=0.402,source="quest_giver",zoneID=3483},questType="standard"},
[9400] = {id=9400,name="The Assassin",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description=", we recently uncovered a plot to assassinate our envoy to Falcon Watch. Hellfire Citadel learned of our plans to send an expedition there earlier this morning and set up an ambush. Our scouts have informed me that an assassin known as Krun Spinebreaker waits along the road north of the Citadel. Go there and slay this assassin. Show the fel orcs we're not to be trifled with!",starts={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=17062,x=0.336,y=0.436,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[9401] = {id=9401,name="A Strange Weapon",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="You pull the stone axe out of the body to examine it more closely. There's something unusual about the craftsmanship of the weapon. Its origin appears orcish, though the materials aren't like anything you've seen before. Nazgrel might be interested in seeing the weapon.",starts={{npcID=17062,x=0.336,y=0.436,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.336,y=0.436,source="quest_giver",zoneID=3483},questType="standard"},
[9402] = {id=9402,name="Fetch!",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="So... is it? Don't be flattered I know your name, one of my students has been fawning over you and won't shut up. Hmm... if you'd like to impress , why don't you do something for me? There's an azure phial at the bottom of the pond behind me. Dive in, retrieve it, and bring it here.",starts={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},ends={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},coords={x=0.556,y=0.544,source="quest_giver",zoneID=3430},questType="standard"},
[9403] = {id=9403,name="The Purest Water",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="Now that you've learned a little lesson, I'll offer you something more substantial. It concerns your ability to defend yourself in close combat. Of course, you should only resort to melee in the most dire of circumstances, but that is no excuse to be unprepared. I can assist you in creating a staff befitting a mage of your learning. Simply take the phial you retrieved for me and fill it at the base of Elrendar Falls. Just follow the river southeast from here.",starts={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},ends={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},coords={x=0.556,y=0.544,source="quest_giver",zoneID=3430},questType="standard"},
[9404] = {id=9404,name="Recently Living",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="You may have noticed the walking trees near Elrendar Falls. As the keepers of nature, they are infused with a primal magic we can reform to our own purposes using the pure water you have already brought to me. Unfortunately, the green keepers are gnarled and twisted creatures, so you may need to kill a few before you find a useable branch.",starts={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},ends={{npcID=15970,x=0.556,y=0.544,zoneID=3430}},coords={x=0.556,y=0.544,source="quest_giver",zoneID=3430},questType="standard"},
[9405] = {id=9405,name="The Warchief's Mandate",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="As you know, the warchief put his power behind this expedition for one reason. This is the world we came from. This is where our roots lie. This journey means different things to orcs and blood elves. To them it's a search for the promised land. To us it's more like returning home. Whoever made this axe is familiar with the old ways and we must contact them. This is too important for us to use ordinary tracking methods. Show the weapon to Far Seer Regulkut ; she will know what to do.",starts={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=16574,x=0.542,y=0.378,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[9406] = {id=9406,name="The Mag'har",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="This news you bring from beyond the Dark Portal... you want us to believe the son of Durotan ruled over the lands beyond it... free from any demonic taint? And that now his people have returned to this world? I hope for your sake that this isn't some manner of joke, . What this means to my people... cannot be described. I must send word to Nagrand at once! Hellscream must hear about this. Take this letter back to your leader in Thrallmar. Tell him the Mag'har welcome them!",starts={{npcID=16845,x=0.32,y=0.278,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.32,y=0.278,source="quest_giver",zoneID=3483},questType="standard"},
[9407] = {id=9407,name="Burning Crusade: Through the Dark Portal",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="For years the Dark Portal loomed silent... forgotten. But it is silent no longer. After stopping the demonic assault here, our forces breached the portal and met the demons on their own ground! Now, we are locked in a savage war, and there are some who think we might not win. So it is our duty, our grim pleasure, to battle the fiends of Outland and ensure our victory, . If you would help us, then report to Lieutenant General Orion at once. He awaits you in the Outland...",starts={{npcID=19254,x=0.544,y=0.504,zoneID=4}},ends={{npcID=19253,x=0.874,y=0.498,zoneID=3483}},coords={x=0.544,y=0.504,source="quest_giver",zoneID=4},questType="standard"},
[9409] = {id=9409,name="Urgent Delivery!",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="Now that you've gathered all that we need to replenish our healing crystals, I need you to deliver the vials to Zalduun , our priest. You'll find him tending to our wounded inside the central chamber of the ship.",starts={{npcID=16477,x=0.804,y=0.458,zoneID=3524},{npcID=16477,x=0.528,y=0.358,zoneID=6456}},ends={{npcID=16502,x=0.8,y=0.49,zoneID=3524},{npcID=16502,x=0.52,y=0.42,zoneID=6456}},coords={x=0.804,y=0.458,source="quest_giver",zoneID=3524},questType="standard"},
[9410] = {id=9410,name="A Spirit Guide",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Even our best tracking wolves' senses can fail them, . The spirits have a way of seeing the world differently than ours. The being you will call forth will find the person you seek, for they'll be drawn not to their scent but their essence. Go now, , take this totem with you and use it at the location you found the stone axe.",starts={{npcID=16574,x=0.542,y=0.378,zoneID=3483}},ends={{npcID=16845,x=0.32,y=0.278,zoneID=3483}},coords={x=0.542,y=0.378,source="quest_giver",zoneID=3483},questType="standard"},
[9417] = {id=9417,name="The Arakkoa Threat",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The arakkoa are smart creatures... smart as any gnome you ever met. They have this way with magic and a violent temper, however. Lately they've taken to attacking Honor Hold patrols, which is why we were sent here. See, Mirren and I are world-famous marksmen, we are! But fowl and game are what we specialize in... not these... lightning-invoking birdmen. So what do you say you give us a hand in this one assignment? You'll find the Den of Haal'esh to the southeast.",starts={{npcID=16850,x=0.238,y=0.72,zoneID=3483}},ends={{npcID=16850,x=0.238,y=0.72,zoneID=3483}},coords={x=0.238,y=0.72,source="quest_giver",zoneID=3483},questType="standard"},
[9418] = {id=9418,name="Avruu's Orb",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="I sense you're not of the arakkoa, so I will attempt to barter for my freedom. My name is Aeranas . I once ruled over the eastern winds. The Haal'eshi mage, Avruu, trapped me inside this orb. Find the altar the arakkoa used to enslave me. It is hidden to the southeast of the arakkoa's den. Approach it with the orb and give it to me once I'm free. In exchange for my liberty I'll reward you with powerful treasure!",ends={{npcID=17085,x=0.288,y=0.814,zoneID=3483}},questType="standard"},
[9420] = {id=9420,name="The Finest Down",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The arakkoa at the Den of Haal'esh, south of here, breed a magnificent species of birds called kaliri. Their feathers would fetch a bundle at the trading posts back in Azeroth. Just think of all the ale I could buy then! Tell you what, you bring me a stack of kaliri feathers and I'll give you my very own hat. What do you say? You'll never find a hat like this one! Do we have a deal?",starts={{npcID=16851,x=0.24,y=0.722,zoneID=3483}},ends={{npcID=16851,x=0.24,y=0.722,zoneID=3483}},coords={x=0.24,y=0.722,source="quest_giver",zoneID=3483},questType="standard"},
[9421] = {id=9421,name="Shaman Training",level=5,requiredLevel=5,faction="alliance",expansion=1,zoneID=6456,mapID=97,starts={{npcID=17089,x=0.792,y=0.49,mapID=97},{npcID=17089,x=0.502,y=0.43,mapID=97}},ends={{npcID=17089,x=0.792,y=0.49,mapID=97},{npcID=17089,x=0.502,y=0.43,mapID=97}},coords={x=0.792,y=0.49,source="quest_giver",mapID=97},questType="standard"},
[9423] = {id=9423,name="Return to Obadei",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="With Sedai's death confirmed, you're left with the unpleasant task of returning to Obadei with the grim news.",starts={{npcID=16852,x=0.268,y=0.374,zoneID=3483}},ends={{npcID=16834,x=0.23,y=0.404,zoneID=3483}},coords={x=0.268,y=0.374,source="quest_giver",zoneID=3483},questType="standard"},
[9424] = {id=9424,name="Makuru's Vengeance",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Sedai was like a brother to Makuru . We owe him our lives and more! They call Makuru crazy but if the Omenai are not going to do anything about his death then they're the crazy ones! Makuru doesn't have much to call his own in this world, but he will give you his only possession if you avenge Sedai. I've seen the brown orc Mag'har grunts before, up in the hills to the northeast. They hate us! They don't deserve our mercy! Go, avenge Sedai! Bring me their ancestral beads as proof!",starts={{npcID=16833,x=0.232,y=0.402,zoneID=3483}},ends={{npcID=16833,x=0.232,y=0.402,zoneID=3483}},coords={x=0.232,y=0.402,source="quest_giver",zoneID=3483},questType="standard"},
[9426] = {id=9426,name="The Pools of Aggonar",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Much has changed since the days when we called this land Draenor. Parts of the land have been forever changed by the demons' taint. One such place is known as the Pools of Aggonar. It was once the location of our people's sacred springs. The blood of the demon Aggonar fouled the very essence of the holy waters. This fel blood has spawned foul beings that must be cleansed if we're ever to reclaim the pools. Travel east of here and slay the Terrorfiends and slimes that wander the pools.",starts={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},ends={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},coords={x=0.234,y=0.366,source="quest_giver",zoneID=3483},questType="standard"},
[9427] = {id=9427,name="Cleansing the Waters",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="I must ask that you finish what we've set in motion. Now that the demonic influence has weakened you must take this cleansing vial and pour it at the very source of the taint - Aggonar's own corpse. You will find the demon's bones at the northern end of the pools. Beware, I sense that Aggonar's essence has not quite left this world.",starts={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},ends={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},coords={x=0.234,y=0.366,source="quest_giver",zoneID=3483},questType="standard"},
[9430] = {id=9430,name="Sha'naar Relics",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="As I've told you before, I do not require eyes to see what others cannot. I will not pass judgment on what you did on Makuru's behalf, yet I think you need to see beyond what your eyes show you. Travel southwest to the Ruins of Sha'naar and salvage any relics you find. If fate wills it you will find what we need. The meaning of my request might not be immediately apparent. Have faith though, . Clarity comes to those with patience.",starts={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},ends={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},coords={x=0.234,y=0.366,source="quest_giver",zoneID=3483},questType="standard"},
[9452] = {id=9452,name="Red Snapper - Very Tasty!",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="I've found that these waters are bustling with red snapper , a very tasty fish. With a fishing net, I can catch enough to feed dozens of draenei! Unfortunately, I was recently attacked by a creature known as a murloc while netting in the river and have suffered some injuries that prevent me from doing my job. I need help! Use this fishing net near schools of red snapper , found in the Crystalbrook river to the east, to catch the fish. What do you say? Remember to return the net when you are finished.",starts={{npcID=17101,x=0.61,y=0.542,zoneID=3524}},ends={{npcID=17101,x=0.61,y=0.542,zoneID=3524}},coords={x=0.61,y=0.542,source="quest_giver",zoneID=3524},questType="standard"},
[9453] = {id=9453,name="Find Acteon!",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You did a wonderful job, . Our people will be thankful for this bounty. With that said, would you mind taking this haul of red snapper to Acteon at Azure Watch? He shouldn't be hard to find as he is awaiting this catch.",starts={{npcID=17101,x=0.61,y=0.542,zoneID=3524}},ends={{npcID=17110,x=0.498,y=0.518,zoneID=3524}},coords={x=0.61,y=0.542,source="quest_giver",zoneID=3524},questType="standard"},
[9454] = {id=9454,name="The Great Moongraze Hunt",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You're starting to make a name for yourself, . How about trying your hand at hunting? Back on Draenor, our greatest hunters would hunt a beast that resembled the moongraze stag of this region known as a talbuk. If you think yourself draenei enough, go out into the wilds and kill enough stags to fill your pack with meat. You will find them grazing south of Azure Watch. Watch out for their horns!",questType="standard"},
[9455] = {id=9455,name="Strange Findings",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="The crystal you found on the nightstalker runt's body appears to be a piece of the Exodar. This may help explain the unusual appearance and demeanor of some of the animals in this region. Take the crystal back to Azure Watch. The exarch will surely want to know about this discovery.",ends={{npcID=17116,x=0.472,y=0.506,zoneID=3524}},questType="standard"},
[9456] = {id=9456,name="Nightstalker Clean Up, Isle 2...",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="I'm not going to make any excuses for what you've found. This is clearly our fault. We had gotten reports of crushed crystal fragments showing up in the river to the east but chose to ignore the implications. Now we can either sit around on this island and cry about the tragedy that has befallen this land or we can do something about it and prevent it from spreading. If you've got the stomach for it, I want you to go back into the wilds and kill as many of the infected nightstalkers as you can find.",starts={{npcID=17116,x=0.472,y=0.506,zoneID=3524}},ends={{npcID=17116,x=0.472,y=0.506,zoneID=3524}},coords={x=0.472,y=0.506,source="quest_giver",zoneID=3524},questType="standard"},
[9463] = {id=9463,name="Medicinal Purpose",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="I have found that lashers milling about on the island hold restorative medicinal properties in their vines. Through proper treatment, the vines can be broken down into a powerful healing ointment. Unfortunately, with so many injured draenei passing through Azure Watch, we are always in short supply. Our delicate guest was found injured and unconscious by the Crystalbrook only yesterday. If you bring me vines, we may be able to save her. You will find root trappers both south and east of Azure Watch.",starts={{npcID=17214,x=0.484,y=0.518,zoneID=3524}},ends={{npcID=17214,x=0.484,y=0.518,zoneID=3524}},coords={x=0.484,y=0.518,source="quest_giver",zoneID=3524},questType="standard"},
[9466] = {id=9466,name="WANTED: Blacktalon the Savage",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="By order of the Ranger Captain, a reward is hereby offered for the slaying of the vicious rockflayer matriarch known as Blacktalon the Savage. Blacktalon was last sighted inside a cave in the Great Fissure. Individuals seeking the reward are to present the creature's claws as proof of the deed.",starts={{npcID=181638,x=0.28,y=0.603,zoneID=3483}},ends={{npcID=16789,x=0.284,y=0.602,zoneID=3483}},coords={x=0.28,y=0.603,source="quest_giver",zoneID=3483},questType="standard"},
[9472] = {id=9472,name="Arelion's Mistress",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="With all the important matters at hand Arelion still found time in his schedule to see a mistress! It's all becoming perfectly clear. Viera Sunwhisper , that filthy wench... we'll show her to never cross a magistrix again. Take this scroll and find Viera. Find a way to lure her away from town and use the scroll on her. Arelion mentioned she couldn't resist a particular wine harvested by the cenarion druids. You might find some at Cenarion Refuge, just inside Zangarmarsh, west of here.",starts={{npcID=16793,x=0.264,y=0.604,zoneID=3483}},ends={{npcID=16793,x=0.264,y=0.604,zoneID=3483}},coords={x=0.264,y=0.604,source="quest_giver",zoneID=3483},questType="standard"},
[9473] = {id=9473,name="An Alternative Alternative",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="The girl is too far gone for mere ointments to be effective. There may be another way... The forest of Azuremyst holds many secrets, one of those being a rare plant known as the azure snapdragon that some claim to be a panacea - a cure all. You can identify the plant by its stark contrast to the other plants of Azuremyst and its need to grow at the base of the azure pine trees. Make haste! And , be wary of the root threshers of the region as they consume snapdragon for sustenance.",starts={{npcID=17215,x=0.484,y=0.514,zoneID=3524}},ends={{npcID=17215,x=0.484,y=0.514,zoneID=3524}},coords={x=0.484,y=0.514,source="quest_giver",zoneID=3524},questType="standard"},
[9483] = {id=9483,name="Life's Finer Pleasures",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,starts={{npcID=17226,x=0.27,y=0.62,zoneID=3483}},ends={{npcID=17226,x=0.27,y=0.62,zoneID=3483}},coords={x=0.27,y=0.62,source="quest_giver",zoneID=3483},questType="standard"},
[9487] = {id=9487,name="Arcane Reavers",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Arcane reavers are magical creations of brute strength. They are heavily armored and deliver stunning blows. You, however, can bypass their defenses and avoid their attacks. Your spellcraft is not without many advantages, . Travel to Dawnstar Spire and blast apart the arcane reavers. From their remains, collect the crystallized fragments of magical energy and return to me. Dawnstar Spire is found to the east, across the lake.",starts={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},ends={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},coords={x=0.464,y=0.284,source="quest_giver",zoneID=3433},questType="standard"},
[9488] = {id=9488,name="A Simple Robe",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="The arcane fragments you collected will do nicely. Nicely for what, you ask? For making a splendid robe fit for a like yourself! All we need now is some linen cloth and a spindleweb silk gland . You can find the silk gland from any spindleweb spider, preferably after killing them.",starts={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},ends={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},coords={x=0.464,y=0.284,source="quest_giver",zoneID=3433},questType="standard"},
[9490] = {id=9490,name="The Rock Flayer Matriarch",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Rock flayers are mean, nasty, violent creatures. But the plain ones are like tame beasts when compared to their matriarch, Blacktalon the Savage. My cousin got eaten by her and it wasn't pretty. I swore that one day Blacktalon would pay for that. You bring back proof of that monster's death and I will give you my life's savings. Deal? You'll find her inside a cave in the Great Fissure. Good luck!",starts={{npcID=16799,x=0.23,y=0.402,zoneID=3483}},ends={{npcID=16799,x=0.23,y=0.402,zoneID=3483}},coords={x=0.23,y=0.402,source="quest_giver",zoneID=3483},questType="standard"},
[9498] = {id=9498,name="Falcon Watch",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="My people recently finished building Falcon Watch, a base of operations in the southwestern region of Hellfire Peninsula - beyond Hellfire Citadel. You are welcome there as an ally, . If you're looking for work, go there and tell Ranger Captain Venn'ren that I sent you. He will see to it that you're given tasks worthy of someone of your caliber.",starts={{npcID=16577,x=0.552,y=0.39,zoneID=3483}},ends={{npcID=16789,x=0.284,y=0.602,zoneID=3483}},coords={x=0.552,y=0.39,source="quest_giver",zoneID=3483},questType="standard"},
[9499] = {id=9499,name="Falcon Watch",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="What are you still doing here, ? Didn't you hear we built a proper sin'dorei outpost here in Hellfire Peninsula ? Surely you'd rather be among fellow blood elves and away from all this... smell. You'll find Falcon Watch in the southwest, beyond Hellfire Citadel. Report to Ranger Captain Venn'ren ; he will take care of you. The road ahead is dangerous and heavily patrolled by Alliance scouts. I would recommend travelling with companions. Blood elves, preferably.",starts={{npcID=16577,x=0.552,y=0.39,zoneID=3483}},ends={{npcID=16789,x=0.284,y=0.602,zoneID=3483}},coords={x=0.552,y=0.39,source="quest_giver",zoneID=3483},questType="standard"},
[9505] = {id=9505,name="The Prophecy of Velen",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="The Prophet spoke of this day: That on this island, in this new world, our allies would find us. \"We will be tested. They will ask that we pay for the sins of our fathers...\" At the time, I did not understand the meaning behind his words, but seeing this creature and her reaction to us, it is now coming into focus. The corruption of our people has been felt even here. Venture south. It is there that we found this being. Find its kin and tell them of our people.",starts={{npcID=17215,x=0.484,y=0.514,zoneID=3524}},ends={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},coords={x=0.484,y=0.514,source="quest_giver",zoneID=3524},questType="standard"},
[9506] = {id=9506,name="A Small Start",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="I am Admiral Odesyus of Alliance Naval Command. Our ship was forced to port on your island due to an infestation of sorts. It's embarrassing to even talk about, but goblins somehow managed to stow away in the holds of both of my ships. Last night, while most of the ship's crew was asleep below deck, they struck! Stranger still, they took our navigation gear and jumped ship! They disappeared into the thicket, east of here. Will you go in search of our gear? It will make for a strong gesture.",starts={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},ends={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},coords={x=0.47,y=0.702,source="quest_giver",zoneID=3524},questType="standard"},
[9512] = {id=9512,name="Cookie's Jumbo Gumbo",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=457,description="The Admiral be right, ye are a resourceful one. Mayhap ye could help Cookie out? If I serve the crew chicken for dinner again, I'll be sent to the brig fer sure. I noticed that thar be crawlers all along the coastline - lots o' crawlers! Bring me crawler meats and I'll be forever indebted to ya. Help a reformed pirate out?",starts={{npcID=17246,x=0.466,y=0.704,zoneID=3524}},ends={{npcID=17246,x=0.466,y=0.704,zoneID=3524}},coords={x=0.466,y=0.704,source="quest_giver",zoneID=3524},questType="standard"},
[9513] = {id=9513,name="Reclaiming the Ruins",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="While some may look at our current predicament as an unfortunate turn of events, I sense that we are here for a reason. The invisible hand of fate has pushed us in this direction. The reason why will become evident in time. To the west lies an ancient night elf city, now in ruin and overrun with naga. It would be remiss of me to sit idly by as the naga tainted my ancestral lands. You have shown yourself a capable . Honor my people and cleanse the ruins of their unwelcome inhabitants.",questType="standard"},
[9514] = {id=9514,name="Rune Covered Tablet",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You cannot make out any of the symbols on the tablet. Perhaps the priestess would be able to decipher the mysterious runes.",ends={{npcID=17241,x=0.47,y=0.702,zoneID=3524}},questType="standard"},
[9515] = {id=9515,name="Warlord Sriss'tiz",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="A naga invasion would be disastrous, . I've seen what naga can do and I would not want to see such a catastrophe befall any being. If I were to guess, this Warlord Sriss'tiz will be hidden in a cave - probably along the coast to the west. Find Warlord Sriss'tiz and put an end to his reign.",questType="standard"},
[9523] = {id=9523,name="Precious and Fragile Things Need Special Handling",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="The priestess tells me that the ruins to the west are what's left of a night elf civilization. That got me thinking about what my pappy used to always say about night elf ruins, \"Sonny, whenever you see night elf ruins, night elf relics are sure to be close by.\" Now what kind of a dwarf would I be if I didn't hire the first person I saw to go digging up night elf relics for me? Now get going!",starts={{npcID=17242,x=0.472,y=0.7,zoneID=3524}},ends={{npcID=17242,x=0.472,y=0.7,zoneID=3524}},coords={x=0.472,y=0.7,source="quest_giver",zoneID=3524},questType="standard"},
[9527] = {id=9527,name="All That Remains",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="We had lived peacefully among the Owlbeasts of this island for many years. You can imagine my surprise when they stormed the beach and attacked us. I fought tooth and nail but was easily overpowered. As I blacked out from the vicious blows that I had been dealt, I prayed that my family not suffer. When I awoke, all was quiet. The sand was soaked red with blood - their blood. They were devoured whole. I care not for vengeance, . I only ask that their remains be returned to me for proper burial.",starts={{npcID=17311,x=0.288,y=0.326,zoneID=457},{npcID=17311,x=0.166,y=0.944,zoneID=3524}},ends={{npcID=17311,x=0.288,y=0.326,zoneID=457},{npcID=17311,x=0.166,y=0.944,zoneID=3524}},coords={x=0.288,y=0.326,source="quest_giver",zoneID=457},questType="standard"},
[9528] = {id=9528,name="A Cry For Help",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=457,description="My family was attacked by the murlocs and owlkin of this island several weeks ago. I managed to escape but I think that both my mother and father have been slain. I don't know what I'm going to do now, but I must try and get back to my home - or what's left of it... Will you help me get through the forest?",starts={{npcID=17312,x=0.136,y=0.732,zoneID=3524}},ends={{npcID=17311,x=0.166,y=0.944,zoneID=3524},{npcID=17311,x=0.288,y=0.326,zoneID=457}},coords={x=0.136,y=0.732,source="quest_giver",zoneID=3524},questType="standard"},
[9530] = {id=9530,name="I've Got a Plant",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="I've wondered about this for some time now, but this proves it to be true. There is a traitor among us. The plans left behind by the goblins document the conspiracy. Since I don't know who it could be, I'm going to need your help in finding the traitor. None of my crew can be trusted. If this is going to work, I'm going to need a hollowed out tree and leaves. Search near the loggers north of us for the tree. You'll need to find the leaves by yourself. Check the forest.",starts={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},ends={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},coords={x=0.47,y=0.702,source="quest_giver",zoneID=3524},questType="standard"},
[9531] = {id=9531,name="Tree's Company",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="According to the plans, the traitor and the leader of the goblins, Geezle, are to meet at a cove on the western island. I need you to be at that meeting, . Remember the tree and leaves? You're going to wear them! It's a perfect disguise. Go to the cove and look for a naga flag. If the flag is there, it means a meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the traitor will show up. Let the meeting finish then return to me with the identity of the scoundrel.",starts={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},ends={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},coords={x=0.47,y=0.702,source="quest_giver",zoneID=3524},questType="standard"},
[9537] = {id=9537,name="Show Gnomercy",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="Spark must be brought to justice! I need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him! If a high ranking official of the Alliance has committed treasonous acts, who knows how many others are corrupt? And , use force if you have to...",starts={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},ends={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},coords={x=0.47,y=0.702,source="quest_giver",zoneID=3524},questType="standard"},
[9538] = {id=9538,name="Learning the Language",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="I think I've cracked it, ! All that we need to know about the Stillpine furbolg language is imprinted on their totems. With just a rudimentary understanding of how their symbols work, we can study the totems and learn to communicate with the furbolgs. I've written down the basics of the symbol matrix on this parchment. Study it and then examine the totem. It should lead you to the next language totem. Speak to Arugoo when you return an educated !",starts={{npcID=17232,x=0.494,y=0.51,zoneID=3524}},ends={{npcID=17360,x=0.494,y=0.51,zoneID=3524}},coords={x=0.494,y=0.51,source="quest_giver",zoneID=3524},questType="standard"},
[9539] = {id=9539,name="Totem of Coo",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You begin to read the totem, barely able to pronounce the awkward words and phrases. Slowly, words start to form in your head. You think that the totem is telling you to go up the nearby hill, to the northeast.",starts={{npcID=17360,x=0.494,y=0.51,zoneID=3524}},ends={{npcID=17361,x=0.552,y=0.416,zoneID=3524}},coords={x=0.494,y=0.51,source="quest_giver",zoneID=3524},questType="standard"},
[9540] = {id=9540,name="Totem of Tikti",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You begin to read the totem, better able to pronounce the words and phrases. Words start to form in your head. You think that the totem is telling you to go across the Crystalbrook river to the east. Perhaps your destination is on the other side of the river.",starts={{npcID=17361,x=0.552,y=0.416,zoneID=3524}},ends={{npcID=17362,x=0.644,y=0.398,zoneID=3524}},coords={x=0.552,y=0.416,source="quest_giver",zoneID=3524},questType="standard"},
[9541] = {id=9541,name="Totem of Yor",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="The symbols on this totem seem to translate much faster. The patterns and imagery all seem to blend into familiar words. You are fairly certain the totem is pointing you south, down the river. Something is at the bottom of the river itself.",starts={{npcID=17362,x=0.644,y=0.398,zoneID=3524}},ends={{npcID=17363,x=0.63,y=0.678,zoneID=3524}},coords={x=0.644,y=0.398,source="quest_giver",zoneID=3524},questType="standard"},
[9542] = {id=9542,name="Totem of Vark",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You no longer see unrecognizable symbology in the totems. The totem of Yor reads to you just as easily as your native tongue. The markings identify another furbolg den, due west of here. You are able to expertly decipher the language on the totem and know that your destination is Bristlelimb Village. Yor will guide you but if you get lost, you know that you are able to take the ancient elven road in the forest leading west to reach your destination.",starts={{npcID=17363,x=0.63,y=0.678,zoneID=3524}},ends={{npcID=17364,x=0.282,y=0.624,zoneID=3524}},coords={x=0.63,y=0.678,source="quest_giver",zoneID=3524},questType="standard"},
[9543] = {id=9543,name="Atonement",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Our history with the orcs is one of constant conflict, . We were once near driven to extinction due to their bloodlust and have since then avoided them even when not under demonic influence. Yet, this retaliation... it's not what Sedai would've wanted. Speak with our elder, Amaan the Wise . He will help shed light on these events.",starts={{npcID=16834,x=0.23,y=0.404,zoneID=3483}},ends={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},coords={x=0.23,y=0.404,source="quest_giver",zoneID=3483},questType="standard"},
[9544] = {id=9544,name="The Prophecy of Akida",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="The images on this totem depict a war between the Stillpine and the Bristlelimb furbolg tribes. The etchings show that the Bristlelimb have done unconscionable things to the furbolgs of Stillpine. Amidst the chaos, a prophecy has begun to unfold: A hero will rise - not of furbolg blood - and save the Stillpine tribe. Slay Bristlelimb furbolgs at Bristlelimb Village for their keys. Use the keys to free the Stillpine captives . Return to Arugoo of the Stillpine when you have freed them all!",questType="standard"},
[9545] = {id=9545,name="The Seer's Relic",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The stubborn close their mind and convince themselves of one truth. The wise keep an open mind to the different possibilities leading to and stemming from the present. Take this relic with you to where you found Sedai. See not with your eyes, , but with your mind.",starts={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},ends={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},coords={x=0.234,y=0.366,source="quest_giver",zoneID=3483},questType="standard"},
[9548] = {id=9548,name="Pilfered Equipment",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Shh! Keep your voice down and don't call attention to me. If the murlocs detect my presence, the experiment will be ruined! I've already come perilously close to contaminating my data. While I was foraging yesterday, one of them must've wandered too close and discovered my camp. I returned just in time to see two of them carrying off a crate with most of my equipment! It's bound to be in one of their settlements around here, but I can't risk revealing my presence. Are you willing to help?",starts={{npcID=17421,x=0.42,y=0.212,zoneID=3525}},ends={{npcID=17421,x=0.42,y=0.212,zoneID=3525}},coords={x=0.42,y=0.212,source="quest_giver",zoneID=3525},questType="standard"},
[9549] = {id=9549,name="Artifacts of the Blacksilt",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="My observations and writings about the Blacksilt murlocs are quite illuminating, , but they are just the beginning. I plan to return to Ironforge with items produced by the Blacksilts' rudimentary crafting skills. The problem is that the Blacksilt carry these items with them at all times, and I can't have their blood on my conscience. If you're willing to help me gather the idols carried by Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won't ask how you came by them.",starts={{npcID=17421,x=0.42,y=0.212,zoneID=3525}},ends={{npcID=17421,x=0.42,y=0.212,zoneID=3525}},coords={x=0.42,y=0.212,source="quest_giver",zoneID=3525},questType="standard"},
[9550] = {id=9550,name="A Map to Where?",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,mapID=106,description="The crudely-drawn map reveals nothing of its maker, but it appears to have been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion with broken columns located to the west of a partially submerged tower. If the map is to be believed, this cluster of ruins appears to be located on the eastern coast of the island. You have no idea what you'll find, but it was important enough for the map's creator to record.",ends={{npcID=181756,x=0.612,y=0.418,mapID=106}},questType="standard"},
[9557] = {id=9557,name="Deciphering the Book",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Lacking the means to read the book's contents, you think about who might be able to help you separate the author's words from the mapmaker's scrawl. Remembering Anchorite Paetheus 's collection of artifacts from countless cultures, you wonder if his experienced eye might be able to help you decipher the book's contents.",starts={{npcID=181756,x=0.612,y=0.418,zoneID=3525}},ends={{npcID=17424,x=0.546,y=0.54,zoneID=3525}},coords={x=0.612,y=0.418,source="quest_giver",zoneID=3525},questType="standard"},
[9558] = {id=9558,name="The Longbeards",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="We were having a problem with arakkoa bandits raiding many of our supply caravans, so I hired some dwarves to take care of them. They were brothers; Gremni Longbeard was the oldest. I'm a little worried about them. Those crazy dwarves packed more ale than food or ammunition! Maybe you can go check up on them? The arakkoa's hideout, the Den of Haal'esh, can be found to the far west of here - beyond the Great Fissure. They set up camp northwest of there, south of Dustquill Ravine.",starts={{npcID=16826,x=0.542,y=0.634,zoneID=3483}},ends={{npcID=16850,x=0.238,y=0.72,zoneID=3483}},coords={x=0.542,y=0.634,source="quest_giver",zoneID=3483},questType="standard"},
[9559] = {id=9559,name="Stillpine Hold",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="Promised one, you must travel north to the home of my people - Stillpine Hold. It is there that you will face your most daunting challenge. Go now, High Chief Stillpine awaits your arrival.",starts={{npcID=17114,x=0.494,y=0.51,zoneID=3524}},ends={{npcID=17440,x=0.466,y=0.206,zoneID=3524}},coords={x=0.494,y=0.51,source="quest_giver",zoneID=3524},questType="standard"},
[9560] = {id=9560,name="Beasts of the Apocalypse!",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="My brother and I were hunting in the woods to the east when we were ambushed by strange, insect-like beasts. Such aberrations have never before been seen in Azuremyst! Could they be a sign of the coming apocalypse? The apocalypse that YOU are destined to prevent? If you truly are the Promised One, you will strike the creatures of the apocalypse down... and bring me their hides. From their hides, I can fashion armor of great power! Find them to the east, beyond the road.",starts={{npcID=17442,x=0.448,y=0.238,zoneID=3524}},ends={{npcID=17442,x=0.448,y=0.238,zoneID=3524}},coords={x=0.448,y=0.238,source="quest_giver",zoneID=3524},questType="standard"},
[9561] = {id=9561,name="Nolkai's Words",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="The translation is ready now, . Anchorite Paetheus points out a block of text at the end of his translation.> 'The enemy is nearly upon us. We've gathered up all the survivors and retreated to the temple to the east. It's the last ground we truly hold on the island, and there is a sense among the survivors that we will make our last stand here. I've taken care to bury my last few possessions on the grounds of the temple, with the hope that someone will find them and know what happened here.'",starts={{npcID=17424,x=0.546,y=0.54,zoneID=3525}},ends={{npcID=181758,x=0.612,y=0.496,zoneID=3525}},coords={x=0.546,y=0.54,source="quest_giver",zoneID=3525},questType="standard"},
[9562] = {id=9562,name="Murlocs... Why Here? Why Now?",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="These are dark days, Promised One. Even the murlocs are kicking our tails - literally. Unfortunately, more than just my ego has been bruised. While our relationship with the Siltfin murlocs had always been tenuous, never could we have imagined that they would have the gall to attack us and steal from our food stores! Travel west to the Silting Shore and recover our stolen food-stuffs! And if you see a dark-skinned murloc with a patch of white fur stuck in between his webbed toes...",starts={{npcID=17441,x=0.446,y=0.234,zoneID=3524}},ends={{npcID=17441,x=0.446,y=0.234,zoneID=3524}},coords={x=0.446,y=0.234,source="quest_giver",zoneID=3524},questType="standard"},
[9563] = {id=9563,name="Gaining Mirren's Trust",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="So you want to gain our trust? I don't trust many people these days. We lost one of our own not long ago to the arakkoa. It's got me a bit on edge. Tell you what, if you can prove your loyalty to Honor Hold and... bring me a mug of Nethergarde Bitter ... yes, that sounds rather good about now... I'll have a deal to offer you then. Bernie at Nethergarde Keep keeps the bitter in stock.",starts={{npcID=16851,x=0.24,y=0.722,zoneID=3483}},ends={{npcID=16851,x=0.24,y=0.722,zoneID=3483}},coords={x=0.24,y=0.722,source="quest_giver",zoneID=3483},questType="standard"},
[9564] = {id=9564,name="Gurf's Dignity",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You recover the piece of fur that Gurf had \"lost\" in his struggle with the murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been slain.",ends={{npcID=17441,x=0.446,y=0.234,zoneID=3524}},questType="standard"},
[9565] = {id=9565,name="Search Stillpine Hold",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="As High Chief, my immediate concern is the root of the corruption in Stillpine Hold. Why did the wildkin - once our allies - attack us? Why have they taken residence in Stillpine Hold? Perhaps something inside will hold the answer. Search Stillpine Hold for clues as to the source of corruption.",questType="standard"},
[9566] = {id=9566,name="Blood Crystals",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="On the surface, the crystal appears to be a piece of the Exodar. Something has gone terribly wrong with this crystal, however, as it is blood red and rapidly dissolving into the water supply of the cave. This may explain the unusually aggressive behavior of the creatures in Azuremyst. Return to High Chief Stillpine with this information.",questType="standard"},
[9567] = {id=9567,name="Know Thine Enemy",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="It's good to see another new face here in Blood Watch, . Although the blood elves are the most immediate threat, there are other sinister creatures that call Bloodmyst Isle home. The Nazzivus satyr are of particular concern. They are foul, demonic creatures, commanding dark magics and feeding on the corruption created by the Exodar's crash. We must hold them in check, but first we must learn more about them. Go southwest to Nazzivian and learn what you can from their grotesque monument.",starts={{npcID=17433,x=0.55,y=0.58,zoneID=3525}},ends={{npcID=17433,x=0.55,y=0.58,zoneID=3525}},coords={x=0.55,y=0.58,source="quest_giver",zoneID=3525},questType="standard"},
[9569] = {id=9569,name="Containing the Threat",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion's hounds in these lands. Too long have the draenei fled in the wake of the Legion and its minions, . Wherever they have found us, they have shown no mercy. We must not permit the satyr to exploit the Exodar's crash and use the corrupted crystals as weapons. Go north to where their leader resides in Axxarien, destroy him, and recover the corrupted crystals he has been gathering!",starts={{npcID=17433,x=0.55,y=0.58,zoneID=3525}},ends={{npcID=17433,x=0.55,y=0.58,zoneID=3525}},coords={x=0.55,y=0.58,source="quest_giver",zoneID=3525},questType="standard"},
[9570] = {id=9570,name="The Kurken is Lurkin'",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="After the crystal storm had subsided, a beast of myth appeared in our village. Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. Many Stillpine were slain in defense of our lands by this fiend and many have since lost their lives attempting to subdue the beast. In my visions, I have seen one defeat the Kurken. The one must be you, . You are our only hope. Enter Stillpine Hold and slay the Kurken. Bring me his hide as proof of deed.",questType="standard"},
[9571] = {id=9571,name="The Kurken's Hide",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="Take the Kurken's hide to Moordo , on the other side of the village. He will fashion the hide into an item of your choice.",starts={{npcID=17443,x=0.468,y=0.222,zoneID=3524}},ends={{npcID=17442,x=0.448,y=0.238,zoneID=3524}},coords={x=0.468,y=0.222,source="quest_giver",zoneID=3524},questType="standard"},
[9573] = {id=9573,name="Chieftain Oomooroo",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="I am Stillpine the Younger , heir to the Stillpine legacy. As you can see, my defenders have set up a death trap for the raving wildkin that attack from inside Stillpine Hold. While we are able to hold them off out here, none of my defenders have been able to infiltrate the hold. If you could get inside and slay their leader, it might give us an opportunity to strike! Find Chieftain Oomooroo and destroy him. Slay any crazed wildkin that you encounter inside as well.",questType="standard"},
[9574] = {id=9574,name="Victims of Corruption",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Bloodmyst Isle was forever changed by our arrival. The Exodar's crash scattered debris all over the islands and I think it's beginning to have an adverse effect on the wildlife. Before I can be certain of my conclusion, I'll need to get a closer look. The crystals seem to have affected the trees the fastest, so it seems that the treants would be the most likely to show symptoms. If you bring me samples of bark from corrupted treants, I can begin my in-depth studies.",starts={{npcID=17434,x=0.532,y=0.576,zoneID=3525}},ends={{npcID=17434,x=0.532,y=0.576,zoneID=3525}},coords={x=0.532,y=0.576,source="quest_giver",zoneID=3525},questType="standard"},
[9576] = {id=9576,name="Cruelfin's Necklace",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Examining the crudely constructed pendant, you notice the crystal pulsating softly. Though it emits little light, you can almost feel the crystal radiating a sense of wrongness. You're not quite sure what might have possessed Cruelfin to create this pendant, but the find is too important to ignore. You should probably show it to someone at Blood Watch.",ends={{npcID=17434,x=0.532,y=0.576,zoneID=3525}},questType="standard"},
[9578] = {id=9578,name="Searching for Galaen",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Do you think often of your family, ? There were a number of families aboard the Exodar, but I've heard of very few being reunited. I, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it's swarming with blood elves! I must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.",starts={{npcID=17434,x=0.532,y=0.576,zoneID=3525}},ends={{npcID=17508,x=0.374,y=0.614,zoneID=3525}},coords={x=0.532,y=0.576,source="quest_giver",zoneID=3525},questType="standard"},
[9579] = {id=9579,name="Galaen's Fate",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="You have no means of identifying the corpse as Galaen with the information Morae gave you, but the clothing appears to have been torn in search of valuables. The blood elves in the area would've claimed anything of value from the wreckage, including Galaen's jeweled amulet. Although her husband did not survive the crash, you believe that Morae would be grateful if you recovered her husband's amulet from the blood elves.",starts={{npcID=17508,x=0.374,y=0.614,zoneID=3525}},ends={{npcID=17434,x=0.532,y=0.576,zoneID=3525}},coords={x=0.374,y=0.614,source="quest_giver",zoneID=3525},questType="standard"},
[9580] = {id=9580,name="The Bear Necessities",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="As I'm sure you've seen in your time on Bloodmyst Isle , very little remains unchanged by our arrival. My training and experience has taught me that even the products of an environment like this one can be put to use. With so few resources, we must rely on our ingenuity to provide for us. I've been supplementing our stores with meat from the bears that wander this island. With the proper preparation, it can safely be eaten. If you're going to be out in the field, why not help replenish our stocks?",starts={{npcID=17642,x=0.558,y=0.568,zoneID=3525}},ends={{npcID=17642,x=0.558,y=0.568,zoneID=3525}},coords={x=0.558,y=0.568,source="quest_giver",zoneID=3525},questType="standard"},
[9581] = {id=9581,name="Learning from the Crystals",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Welcome to Blood Watch, . Seeing to the defenses of the outpost is my primary concern, but I've also been tasked with a variety of other duties by our leaders at the Exodar. The problem is that it's hardly safe to send out large amounts of researchers when the island is this dangerous. I need someone to gather a series of crystal samples from various sites on the island. The first sample I need must come from the ravager infested ship debris south of the town and across the bridge.",starts={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},ends={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},coords={x=0.526,y=0.532,source="quest_giver",zoneID=3525},questType="standard"},
[9582] = {id=9582,name="Strength of One",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3524,description="When the ship crashed, our menagerie was scattered on the northeast beaches of this isle. I have been handed a key that unlocks the cage holding one of the deadlier specimens, a death ravager . The creature is little armored but resistant to most magic. It must be killed by a simple blade. Take this key and release the creature from both its prison and its pain. We cannot afford to have it escape and cause even more damage to the ecology than we already have.",starts={{npcID=17480,x=0.498,y=0.504,zoneID=3524}},ends={{npcID=17480,x=0.498,y=0.504,zoneID=3524}},coords={x=0.498,y=0.504,source="quest_giver",zoneID=3524},questType="standard"},
[9584] = {id=9584,name="The Second Sample",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Now that we have the baseline crystal, we're going to need samples from more dangerous areas of the island to complete the set I'll be sending to the Exodar. The next sample must come from the crystals controlled by the blood elves in the Bladewood area to the northwest of Blood Watch. I have heard reports that they alter and harvest the crystals for use in some magical apparatus. See if you can find one that has not yet been incorporated into one of their devices, and mine a sample from it.",starts={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},ends={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},coords={x=0.526,y=0.532,source="quest_giver",zoneID=3525},questType="standard"},
[9585] = {id=9585,name="The Final Sample",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="There's just one sample remaining before I can send this set of crystals to the Exodar, . The final sample must come from the satyr stronghold of Axxarien to the northwest. I'm not certain what to expect from this crystal sample, but I'm sure there will be some signs of corruption. Take care to mine your shard from the crystal that looks like the ones you took your previous samples from, or else our researchers cannot make a valid comparison.",starts={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},ends={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},coords={x=0.526,y=0.532,source="quest_giver",zoneID=3525},questType="standard"},
[9594] = {id=9594,name="Signs of the Legion",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="The armor scrap is forged from a deep black metal that seems to absorb light. Although it doesn't appear to be enchanted, there is an unmistakable sense of wrongness about it. Such armor is only used by one force - the Burning Legion. The Legion's presence here can only mean that they're intending to mobilize the island's satyr against the draenei. Take action against the local satyr, then return to Blood Watch and show this armor scrap to Vindicator Aalesia .",ends={{npcID=17433,x=0.55,y=0.58,zoneID=3525}},questType="standard"},
[9602] = {id=9602,name="Deliver Them From Evil...",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You must get this information to your people, . While your brave acts have certainly slowed down the plans of Kael'thas and his dark master, the attacks will undoubtedly continue. Take the traitor's communication to your leaders. They must see this for themselves. Perhaps they will be able to better understand some of what was written.",starts={{npcID=17240,x=0.47,y=0.702,zoneID=3524}},ends={{npcID=17116,x=0.472,y=0.506,zoneID=3524}},coords={x=0.47,y=0.702,source="quest_giver",zoneID=3524},questType="standard"},
[9603] = {id=9603,name="Beds, Bandages, and Beyond",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Welcome to Azure Watch, . Please excuse the disorder you see around you. It's easy to take simple things for granted, like a fully furnished and stocked inn, until you're forced to build one from nothing. We've managed to salvage this pod for a building, but without the proper furnishings and first aid supplies, the inn is little more than a glorified tent. Nurguni at the Exodar has offered to put together a package to help with our most immediate needs, but I need someone to deliver this list to him.",starts={{npcID=16553,x=0.484,y=0.492,zoneID=3524},{npcID=17553,x=0.556,y=0.596,zoneID=3525}},ends={{npcID=43991,x=0.496,y=0.492,zoneID=3524},{npcID=17554,x=0.576,y=0.54,zoneID=3525}},coords={x=0.484,y=0.492,source="quest_giver",zoneID=3524},questType="standard"},
[9604] = {id=9604,name="On the Wings of a Hippogryph",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3557,description="For a small fee, you can rent one of my hippogryphs to fly you to the Exodar. Taking the hippogryph is a faster, not to mention safer, alternative for someone carrying an important message. If you'd like to take a ride, speak to me again and I'll make the arrangements.",starts={{npcID=17554,x=0.576,y=0.54,zoneID=3525},{npcID=43991,x=0.496,y=0.492,zoneID=3524}},ends={{npcID=16768,x=0.568,y=0.498,zoneID=3557}},coords={x=0.576,y=0.54,source="quest_giver",zoneID=3525},questType="standard"},
[9605] = {id=9605,name="Hippogryph Master Stephanos",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3557,description="Here's the box, . That should be enough for Chellan to get the inn up and running. Let her know that she can keep sending in orders as the need arises. Azure Watch urgently needs a place to care for the wounded and put up any travelers they receive. When you're ready to return to Azure Watch, seek out Stephanos near the Seat of the Naaru in the Exodar.",starts={{npcID=16768,x=0.568,y=0.498,zoneID=3557}},ends={{npcID=17555,x=0.544,y=0.366,zoneID=3557}},coords={x=0.568,y=0.498,source="quest_giver",zoneID=3557},questType="standard"},
[9606] = {id=9606,name="Return to Caregiver Chellan",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="If I remember correctly, Azure Watch's hippogryph master is Zaldaan. If you've spoken to him before, then you can take one of my hippogryphs to him. That's a good lesson to know: hippogryphs are always trained to fly to their capital city, but they'll only take you to a remote hippogryph master after you've already been there. Since you arrived on one of Zaldaan's hippogryphs, you can also use that route to return to Azure Watch with the caregiver's supplies.",starts={{npcID=17555,x=0.544,y=0.366,zoneID=3557}},ends={{npcID=16553,x=0.484,y=0.492,zoneID=3524}},coords={x=0.544,y=0.366,source="quest_giver",zoneID=3557},questType="standard"},
[9612] = {id=9612,name="A Hearty Thanks!",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You saved my life, ! Thank you so much! That beast would have torn me to shreds if it weren't for you. If you see the exarch at Azure Watch, tell him of what you did. I'm sure he'll be pleased to hear such news!",starts={{npcID=17587,x=0.376,y=0.182,zoneID=3524}},ends={{npcID=17116,x=0.472,y=0.506,zoneID=3524}},coords={x=0.376,y=0.182,source="quest_giver",zoneID=3524},questType="standard"},
[9616] = {id=9616,name="Bandits!",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="This appears to be a bounty ledger. You cannot understand the blood elf language but you note that there is a picture depicting a dead draenei, a smiling blood elf standing over the corpse, and a symbol of what you think is some sort of blood elf currency. They've put a hit out on draenei! You must inform the exarch.",ends={{npcID=17116,x=0.472,y=0.506,zoneID=3524}},questType="standard"},
[9620] = {id=9620,name="The Missing Survey Team",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="As we've gotten ourselves established here at Blood Watch, I've been sending out survey teams to create more reliable maps of the island. In most cases, they returned unharmed with the data we need, but the team I sent east to the ruins hasn't reported back. I worry about what might have happened to them, but I can't spare the men to send another mission after them. Find them, , and lend them any assistance they require to return with their survey data.",starts={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},ends={{npcID=17600,x=0.612,y=0.484,zoneID=3525}},coords={x=0.526,y=0.532,source="quest_giver",zoneID=3525},questType="standard"},
[9621] = {id=9621,name="Envoy to the Horde",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=1497,description="There were doubts about our capabilities among our potential new allies. Of what use could we be to them when perceived as unable to deal with our problems at home? This changes everything. No longer will our power be questioned. We'll be able to join the Horde as equals. Take this letter to Sylvanas, ruler of the Forsaken. She's already on our side but the news of Dar'Khan's death will be music to her ears. Prepare for a long trip, . If all goes well she will send you to Orgrimmar.",starts={{npcID=16802,x=0.54,y=0.204,zoneID=3487}},ends={{npcID=10181,x=0.578,y=0.916,zoneID=1497}},coords={x=0.54,y=0.204,source="quest_giver",zoneID=3487},questType="standard"},
[9622] = {id=9622,name="Warn Your People",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="The Hold is saved and soon my people will make their way back to the ancestral home. The prophecy has come to pass and a new age of prosperity begins for the Stillpine. But I fear that darkness looms ahead for your own people. There are questions left unanswered - visions of prophecy unseen. Return to your leaders and tell them of what you have seen here. And Promised One, should you ever require the aid of Stillpine, you have merely to ask.",starts={{npcID=17440,x=0.466,y=0.206,zoneID=3524}},ends={{npcID=17116,x=0.472,y=0.506,zoneID=3524}},coords={x=0.466,y=0.206,source="quest_giver",zoneID=3524},questType="standard"},
[9623] = {id=9623,name="Coming of Age",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3557,description="You have survived the wilds of our new home and shown yourself a cut above the others. I believe that you have come of age to assist those battling on the front lines of Bloodmyst. The Hand of Argus could use a like you. Report to Torallius the Pack Handler . You will find him outside the Exodar, tending to the elekk. Give him these orders so that he may direct you towards your new duties on Bloodmyst.",starts={{npcID=17116,x=0.472,y=0.506,zoneID=3524}},ends={{npcID=17584,x=0.814,y=0.518,zoneID=3557}},coords={x=0.472,y=0.506,source="quest_giver",zoneID=3524},questType="standard"},
[9624] = {id=9624,name="A Favorite Treat",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="I've made a wonderful discovery, . On the uncorrupted part of the island grows a remarkable fruit called the sand pear . They're found near the bottoms of the trees. I've been preparing pies from them, but if I'm not careful, the elekk will start to wander over and steal my fruit. I've taken to gathering enough to share with the animals, but my stores are gone and the craving for pie has returned. Would you be willing to help gather the fruit I need for another batch of pies? I promise I'll share!",starts={{npcID=17599,x=0.634,y=0.886,zoneID=3525}},ends={{npcID=17599,x=0.634,y=0.886,zoneID=3525}},coords={x=0.634,y=0.886,source="quest_giver",zoneID=3525},questType="standard"},
[9625] = {id=9625,name="Elekks Are Serious Business",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Is he crazy? Entrusting something like this to some no-named youngling! Just remember this kid: You'll never make it as a Hand of Argus! You don't have the guts! I guess I'll have to humor him this time. Speak with Vorkhan at Kessel's Crossing on Bloodmyst Isle . Just follow the road north from here, and when it forks, just keep on going north.",starts={{npcID=17584,x=0.814,y=0.518,zoneID=3557}},ends={{npcID=17586,x=0.63,y=0.878,zoneID=3525}},coords={x=0.814,y=0.518,source="quest_giver",zoneID=3557},questType="standard"},
[9628] = {id=9628,name="Salvaging the Data",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="It's too late to assist the cartographers in completing their mission, but it appears they collected the data Harbinger Mikolaas was expecting. The crystal storing their survey information was not among their ransacked packs, so it must be in the hands of the Wrathscale naga. You know that Harbinger Mikolaas will be saddened by the loss of the survey crew, but would want to salvage the survey data.",starts={{npcID=17600,x=0.612,y=0.484,zoneID=3525}},ends={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},coords={x=0.612,y=0.484,source="quest_giver",zoneID=3525},questType="standard"},
[9629] = {id=9629,name="Catch and Release",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="The Blacksilt murlocs on the southwestern coast are curious creatures. In some ways, they act barely sentient, yet in others, they show a remarkable degree of organization. I have a few theories about that, but no real way to test them until recently. I've devised a method that will allow me to track the murlocs I'm interested in without doing any lasting harm or interfering with their natural behavior. If you're willing to help with the marking, I'll gladly pay you for your assistance.",starts={{npcID=17434,x=0.532,y=0.576,zoneID=3525}},ends={{npcID=17434,x=0.532,y=0.576,zoneID=3525}},coords={x=0.532,y=0.576,source="quest_giver",zoneID=3525},questType="standard"},
[9634] = {id=9634,name="Alien Predators",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="One thing we've learned in our travels is that extreme care must be taken when introducing wildlife from one world to another. When the Exodar crashed, it was carrying specimens of various Outland species, including an insectoid predator called the ravager. Some of the specimens were lost, but many others survived and took to the wild. If we don't keep them in check, they will upset the natural balance here on the islands. You'll find these ravagers to the west of Kessel's Crossing, near the coast.",starts={{npcID=17586,x=0.63,y=0.878,zoneID=3525}},ends={{npcID=17586,x=0.63,y=0.878,zoneID=3525}},coords={x=0.63,y=0.878,source="quest_giver",zoneID=3525},questType="standard"},
[9635] = {id=9635,name="The Zapthrottle Mote Extractor!",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="The swamp gas is truly amazing, and can be very useful, mon! But first, you gotta be able to suck it up, and that, my friend, requires a Zapthrottle Mote Extractor. Now, I could just give you the schematics, but I'll need something in return first. How about some spare parts? Last time I checked, there were plenty lying around near the broken steam pump at the Dead Mire, far to the northeast. I heard that the withered giants spread the pieces all over that dried-out lake bed.",starts={{npcID=17637,x=0.34,y=0.51,zoneID=3521}},ends={{npcID=17637,x=0.34,y=0.51,zoneID=3521}},coords={x=0.34,y=0.51,source="quest_giver",zoneID=3521},questType="standard"},
[9636] = {id=9636,name="The Zapthrottle Mote Extractor!",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="Have you seen the swamp gas? Isn't it just shiny? It takes a Zapthrottle Mote Extractor to suck 'em dry though. I could give you the plans to make one, but I really need some spare parts to fix stuff 'round here. Last time I checked, there were plenty of parts lying around near the steam pump at the Dead Mire to the northeast. I think the withered giants broke the pump out there. Shall we help each other out?",starts={{npcID=17634,x=0.686,y=0.502,zoneID=3521}},ends={{npcID=17634,x=0.686,y=0.502,zoneID=3521}},coords={x=0.686,y=0.502,source="quest_giver",zoneID=3521},questType="standard"},
[9641] = {id=9641,name="Irradiated Crystal Shards",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="The Exodar's crash scattered pieces of fouled crystals all over Bloodmyst Isle , corrupting the water and the landscape. We've even begun finding pieces of the crystals inside the flesh of animals taken for meat. I've uncovered a way to purify the shard and turn them into functional crystals, so if you bring me enough shards, I'll trade one of my completed crystals for them. So far I've found the shards in the bodies of bears, ravagers, flutterers, and treants inhabiting the corrupted part of the island.",starts={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},ends={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},coords={x=0.554,y=0.552,source="quest_giver",zoneID=3525},questType="standard"},
[9642] = {id=9642,name="More Irradiated Crystal Shards",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,starts={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},ends={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},coords={x=0.554,y=0.552,source="quest_giver",zoneID=3525},questType="standard"},
[9643] = {id=9643,name="Constrictor Vines",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="A good woodsman makes use of every available resource, . Even the most bizarre creatures possess attributes we can use to our advantage. With Blood Watch under constant assault from the Sunhawks, we're looking to a variety of natural defenses including traps. The lasher's thorny vines are perfectly suited to the construction of the traps I have in mind. The combination of sharp spines and deadly toxin will fell unwary attackers. Bring me the vines of mutated constrictors so that I can begin my work.",starts={{npcID=17642,x=0.558,y=0.568,zoneID=3525}},ends={{npcID=17642,x=0.558,y=0.568,zoneID=3525}},coords={x=0.558,y=0.568,source="quest_giver",zoneID=3525},questType="standard"},
[9646] = {id=9646,name="WANTED: Deathclaw",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="By order of Harbinger Mikolaas : A bounty to be paid to the brave soul who returns with proof of the marauding bear Deathclaw's demise. Deathclaw should be considered extremely dangerous and is responsible for the killing of a survey team on the coast to the northwest of Blood Watch. Travelers are advised to avoid the area.",starts={{npcID=181889,x=0.552,y=0.591,zoneID=3525}},ends={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},coords={x=0.552,y=0.591,source="quest_giver",zoneID=3525},questType="standard"},
[9647] = {id=9647,name="Culling the Flutterers",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="When we first encountered flutterers, they showed few signs of mutation. As the corruption got progressively worse, the moths and other species began to show signs of contamination. It has progressed to the point where they damage nearly everything they come in contact with. They're amplifying the damage being done by the crystal shards scattered by the Exodar's crash. We have no choice but to begin culling their population in the lands north of Blood Watch.",starts={{npcID=17642,x=0.558,y=0.568,zoneID=3525}},ends={{npcID=17642,x=0.558,y=0.568,zoneID=3525}},coords={x=0.558,y=0.568,source="quest_giver",zoneID=3525},questType="standard"},
[9648] = {id=9648,name="Maatparm Mushroom Menagerie",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Did you know mushroom hunting is far more dangerous than mushroom consumption? Mushroom hunters expose themselves to many unknowns - not including potential wildlife dangers! What would life be without a little danger? I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn , a blood mushroom , a ruinous polyspore , and a fel cone fungus . They are each unique to various regions in Bloodmyst. Bring them to me.",starts={{npcID=17663,x=0.562,y=0.568,zoneID=3525}},ends={{npcID=17663,x=0.562,y=0.568,zoneID=3525}},coords={x=0.562,y=0.568,source="quest_giver",zoneID=3525},questType="standard"},
[9649] = {id=9649,name="Ysera's Tears",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Good to see you again, ! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another? To the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera's tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.",starts={{npcID=17663,x=0.562,y=0.568,zoneID=3525}},ends={{npcID=17663,x=0.562,y=0.568,zoneID=3525}},coords={x=0.562,y=0.568,source="quest_giver",zoneID=3525},questType="standard"},
[9663] = {id=9663,name="The Kessel Run",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="You're just in time, . Blood elf activity in this area has doubled in the past week. Our agents have informed us that the blood elves that call themselves Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning out to our allies and compatriots. Warn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing. Time is of the essence so I am lending you my elekk. Be sure to keep it out of water.",starts={{npcID=17649,x=0.63,y=0.876,zoneID=3525}},ends={{npcID=17649,x=0.63,y=0.876,zoneID=3525}},coords={x=0.63,y=0.876,source="quest_giver",zoneID=3525},questType="standard"},
[9666] = {id=9666,name="Declaration of Power",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Have you seen the serpent men? The ones that call themselves naga? Kessel spits.> They dared make an advance upon this camp under cover of darkness only three nights ago. Can you believe the audacity of those primitive beasts? I need you to deliver a message to their leadership, . To the northeast is Wrathscale Lair, home to Lord Xiz . Find him, slay him where he stands and drive this banner through his corpse. Let them know fear whenever they should see our standard!",starts={{npcID=17649,x=0.63,y=0.876,zoneID=3525}},ends={{npcID=17649,x=0.63,y=0.876,zoneID=3525}},coords={x=0.63,y=0.876,source="quest_giver",zoneID=3525},questType="standard"},
[9667] = {id=9667,name="Saving Princess Stillpine",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Help me, ! The Bristlelimb captured me and are planning to sacrifice me to their foul gods! High Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key! My father will richly reward you if you can save me!",starts={{npcID=17682,x=0.682,y=0.812,zoneID=3525}},ends={{npcID=18803,x=0.552,y=0.56,zoneID=3525}},coords={x=0.682,y=0.812,source="quest_giver",zoneID=3525},questType="standard"},
[9668] = {id=9668,name="Report to Exarch Admetius",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="A Hand of Argus soldier is many things: Obedient, brave, intelligent, and above all, honorable. You may yet exhibit some of these traits, . Report to Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and his subordinates will further train you in the ways of the draenei soldier. And remember this, : Honorable people do not always perform honorably. Sometimes they cannot. You will find Blood Watch just up this road, to the north.",starts={{npcID=17649,x=0.63,y=0.876,zoneID=3525}},ends={{npcID=17658,x=0.526,y=0.532,zoneID=3525}},coords={x=0.63,y=0.876,source="quest_giver",zoneID=3525},questType="standard"},
[9669] = {id=9669,name="The Missing Expedition",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="About a week ago, my research team and I were out exploring the western wilds of Bloodmyst when we were attacked by bloodthirsty spiders. The effect of the crystal contamination was clearly evident as these spiders were massive and extremely aggressive. I managed to escape but my team wasn't so lucky. We must not let the same fate befall others. Go west to the Amberweb Pass and destroy the spiders and their matriarch, Zarakh .",starts={{npcID=17676,x=0.532,y=0.57,zoneID=3525}},ends={{npcID=17676,x=0.532,y=0.57,zoneID=3525}},coords={x=0.532,y=0.57,source="quest_giver",zoneID=3525},questType="standard"},
[9670] = {id=9670,name="They're Alive! Maybe...",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="It was a bloody mess, . We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons. After we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD! I managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand? Destroy those cocoons! Hopefully some of our team is still alive!",starts={{npcID=17686,x=0.248,y=0.344,zoneID=3525}},ends={{npcID=17686,x=0.248,y=0.344,zoneID=3525}},coords={x=0.248,y=0.344,source="quest_giver",zoneID=3525},questType="standard"},
[9671] = {id=9671,name="Urgent Delivery",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,mapID=106,starts={{npcID=17703,x=0.55,y=0.592,mapID=106}},ends={{npcID=17703,x=0.55,y=0.592,mapID=106}},coords={x=0.55,y=0.592,source="quest_giver",mapID=106},questType="standard"},
[9672] = {id=9672,name="The Bloodcurse Legacy",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Dear friend, My hand trembles as I ink this letter. I pray that it reaches you in time. Last night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago. This apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of your base? Regards, Admiral Odesyus",ends={{npcID=17712,x=0.79,y=0.226,zoneID=3525}},questType="standard"},
[9674] = {id=9674,name="The Bloodcursed Naga",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="They say when the world was sundered, this land cried the loudest. It was here that thousands of night elves faded into oblivion and in their place rose terrible creatures of hate - the naga. Obedient to their twisted queen, Azshara, they would destroy all that would dare pass through their sea. It would remain this way for thousands of years - until now. The first order of business is to remove the bloodcursed naga from the reef.",starts={{npcID=17712,x=0.79,y=0.226,zoneID=3525}},ends={{npcID=17712,x=0.79,y=0.226,zoneID=3525}},coords={x=0.79,y=0.226,source="quest_giver",zoneID=3525},questType="standard"},
[9682] = {id=9682,name="The Hopeless Ones...",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="On a ledge of the reef, deeper than where you found the bloodcursed naga, you will find the hopeless ones: The bloodcursed voyagers, ghosts of those taken by the bloodcurse. It is regrettable, what I ask of you now... but they must be destroyed and their cursed shells brought back to me. Their souls must be put to rest. Return to me when you have done as asked and I shall give you one final task.",starts={{npcID=17712,x=0.79,y=0.226,zoneID=3525}},ends={{npcID=17712,x=0.79,y=0.226,zoneID=3525}},coords={x=0.79,y=0.226,source="quest_giver",zoneID=3525},questType="standard"},
[9683] = {id=9683,name="Ending the Bloodcurse",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="To the south you will find Bloodcurse Isle. Atop the island you will find a shrine dedicated to the beloved queen of the naga, Azshara. Destroy the statue - burn it in effigy! This will surely draw the ire of Atoph, the Bloodcursed leader. Slay Atoph and return to me!",starts={{npcID=17712,x=0.79,y=0.226,zoneID=3525}},ends={{npcID=17712,x=0.79,y=0.226,zoneID=3525}},coords={x=0.79,y=0.226,source="quest_giver",zoneID=3525},questType="standard"},
[9687] = {id=9687,name="Restoring Sanctity",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Not long ago, the once tranquil owlkin of the region appeared on the shores of this island. One by one they would come to steal the bones of the fallen dragons. I do not know what would cause these creatures such distress or why they would want the bones of the deceased, but the spirits of the brood have grown restless due to this sacrilege. To the west, across the Crimson Reach, you will find Ragefeather Ridge. Venture to the owlkin encampments and recover the pilfered dragon bones .",starts={{npcID=17674,x=0.74,y=0.346,zoneID=3525}},ends={{npcID=17674,x=0.74,y=0.346,zoneID=3525}},coords={x=0.74,y=0.346,source="quest_giver",zoneID=3525},questType="standard"},
[9688] = {id=9688,name="Into the Dream",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="The whelps that you see on this island are the agitated spirits of the green dragonflight. Like me, they are bound to the land, unable to ascend to their final resting place in the Dream. Recovering the bones of the fallen has settled them somewhat but you must take further action. Destroy their ethereal manifestations. I cannot leave this place until it is done. They must be released!",starts={{npcID=17674,x=0.74,y=0.346,zoneID=3525}},ends={{npcID=17674,x=0.74,y=0.346,zoneID=3525}},coords={x=0.74,y=0.346,source="quest_giver",zoneID=3525},questType="standard"},
[9689] = {id=9689,name="Razormaw",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Many of the black dragonflight were slain during the attacks. One of them, a lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, you can see his spectral countenance circling the skies. His hatred is so great that he remains even in death. Take the bones that you gathered for me earlier to the top of the mountain on this island and place them in the ever-burning pyre. This act should signal Razormaw to descend. When he does, slay his undead form.",starts={{npcID=17674,x=0.74,y=0.346,zoneID=3525}},ends={{npcID=17674,x=0.74,y=0.346,zoneID=3525}},coords={x=0.74,y=0.346,source="quest_giver",zoneID=3525},questType="standard"},
[9693] = {id=9693,name="What Argus Means to Me",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="What does Argus mean to you, ? Many draenei probably do not know or remember our home planet. It is there that we split from the man'ari: the twisted demonic reflections of ourselves that were 'gifted' by Sargeras. Or as they call themselves, eredar. Eredar... this word once held meaning. Disgusting. Let us not waste anymore time. Find Vindicator Boros to begin your training.",starts={{npcID=17658,x=0.526,y=0.532,zoneID=3525}},ends={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},coords={x=0.526,y=0.532,source="quest_giver",zoneID=3525},questType="standard"},
[9694] = {id=9694,name="Blood Watch",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Blood Watch is one of two forward bases operated by the Hand of Argus. You have already been to the other base, Azure Watch; things are completely different in Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even called it Silvergale but now sickness is spreading across the land, worse yet, the blood elves that we were battling on the Exodar survived the crash. This brings me to your assignment: Venture northwest into Bladewood and terminate any blood elves that you find.",starts={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},ends={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},coords={x=0.554,y=0.552,source="quest_giver",zoneID=3525},questType="standard"},
[9696] = {id=9696,name="Translations...",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Our chief interrogator, Elysia, is fluent in Thalassian. Take the document to her and see what she has to say.",starts={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},ends={{npcID=17825,x=0.544,y=0.544,zoneID=3525}},coords={x=0.554,y=0.552,source="quest_giver",zoneID=3525},questType="standard"},
[9697] = {id=9697,name="Watcher Leesa'oh",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="There's important research to be conducted into the ecology of the local creatures, especially the sporelings and bog lords of the marsh. And trust me, once you get out into the field, you'll find the work to be challenging. Seek out Watcher Leesa'oh at the Cenarion Watchpost in the western region of the marsh toward the south. Follow the path west and you will eventually find her. She can be a bit -- studious -- but don't let that get to you. Oh, and watch out for her cat.",starts={{npcID=17834,x=0.786,y=0.63,zoneID=3521}},ends={{npcID=17831,x=0.232,y=0.662,zoneID=3521}},coords={x=0.786,y=0.63,source="quest_giver",zoneID=3521},questType="standard"},
[9698] = {id=9698,name="Audience with the Prophet",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3557,description="I need you to deliver the translated documents to Velen personally, . I don't trust that deranged messenger. Explain to the Prophet that the blood elves are receiving reinforcements from the Outland and that they have a spy amongst the draenei at the Exodar. Velen resides in the Vault of Lights inside the Exodar. Make haste!",starts={{npcID=17825,x=0.544,y=0.544,zoneID=3525}},ends={{npcID=17468,x=0.54,y=0.554,zoneID=3525},{npcID=17468,x=0.326,y=0.542,zoneID=3557}},coords={x=0.544,y=0.544,source="quest_giver",zoneID=3525},questType="standard"},
[9699] = {id=9699,name="Truth or Fiction",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3557,description="I thank you for the timely delivery, . You are turning out to be one of the Hand's better agents. If only we knew who they reported to in Bloodmyst and more importantly, where this sun portal was... They seem to have it tightly guarded - wherever it may be. Would you be interested in some reconnaissance work? If so, take these orders back to Vindicator Boros . He will give you your next mission.",starts={{npcID=17468,x=0.54,y=0.554,zoneID=3525},{npcID=17468,x=0.326,y=0.542,zoneID=3557}},ends={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},coords={x=0.54,y=0.554,source="quest_giver",zoneID=3525},questType="standard"},
[9700] = {id=9700,name="I Shoot Magic Into the Darkness",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Velen states that if the blood elves have been opening rifts between this island and the Outland, there will be residue or anomalies left in the areas where the portals have been opened. You must search the island for locations that exhibit or display these anomalies. Be warned, ; some of these anomalies will be creatures from the void itself. Should you find void anomalies, slay them! Report back to me with any new information that you may find. Begin your search to the north, near the Warp Piston.",starts={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},ends={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},coords={x=0.554,y=0.552,source="quest_giver",zoneID=3525},questType="standard"},
[9701] = {id=9701,name="Observing the Sporelings",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="We need to learn all that we can of the sporelings at Sporeggar and their relationship to the creatures around them. One way to do that is what I'm doing; passive observation while making a note of their interactions. I need you to head over to the Spawning Glen to the west. Investigate the whole area and then return to tell me what you saw.",starts={{npcID=17831,x=0.232,y=0.662,zoneID=3521}},ends={{npcID=17831,x=0.232,y=0.662,zoneID=3521}},coords={x=0.232,y=0.662,source="quest_giver",zoneID=3521},questType="standard"},
[9702] = {id=9702,name="A Question of Gluttony",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="I was wondering why the bog lords were crossing the road to go to the Spawning Glen - they must be starving for some reason. This just will not do! I mean, normally I wouldn't get involved, but if they continue to eat all of the sporeling pods they'll wipe them out! Here's what we'll do: I'll stay here and you head to the Quagg Ridge to the east and look for dietary clues as to why they're raiding the sporelings.",starts={{npcID=17831,x=0.232,y=0.662,zoneID=3521}},ends={{npcID=17831,x=0.232,y=0.662,zoneID=3521}},coords={x=0.232,y=0.662,source="quest_giver",zoneID=3521},questType="standard"},
[9703] = {id=9703,name="The Cryo-Core",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="We have others pursuing leads on the sun portals, . I need you to focus on the task at hand. Boros has received new reports of another crash site. What we've since discovered is that the crash site is actually the Exodar's cryo-core. This is a pod holding area that houses pods exactly like the ones we draenei crawled out of in Ammen Vale. This area also holds medical supplies . Head to the Cryo-Core, directly west of Blood Watch. Search for supplies and search for survivors.",starts={{npcID=17843,x=0.556,y=0.552,zoneID=3525}},ends={{npcID=17843,x=0.556,y=0.552,zoneID=3525}},coords={x=0.556,y=0.552,source="quest_giver",zoneID=3525},questType="standard"},
[9704] = {id=9704,name="Slain by the Wretched",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="It's hard work being an outrunner between Sunstrider Isle and Falconwing Square. Tight deadlines, long hours and worst of all... the Wretched! The road south goes through the ruins of Silvermoon... the place is crawling with Wretched ready to kill you for a few mana crystals. Unfortunately, I think that's what happened to the last outrunner we sent with one of Erona's packages. I see you're eager to prove yourself. Venture into Dawning Lane and see if you can find any traces of our outrunner.",starts={{npcID=15301,x=0.404,y=0.322,zoneID=3430}},ends={{npcID=17849,x=0.42,y=0.356,zoneID=3430}},coords={x=0.404,y=0.322,source="quest_giver",zoneID=3430},questType="standard"},
[9705] = {id=9705,name="Package Recovery",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="You take the package and confirm that indeed it comes from Magistrix Erona. Alarion would probably want you to bring it to her.",starts={{npcID=17849,x=0.42,y=0.356,zoneID=3430}},ends={{npcID=15301,x=0.404,y=0.322,zoneID=3430}},coords={x=0.42,y=0.356,source="quest_giver",zoneID=3430},questType="standard"},
[9706] = {id=9706,name="Galaen's Journal - The Fate of Vindicator Saruan",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Your hands tremble as you pick up the book. Kuros must be told about this tragedy. Return the book to him.",starts={{npcID=182032,x=0.376,y=0.613,zoneID=3525}},ends={{npcID=17843,x=0.556,y=0.552,zoneID=3525}},coords={x=0.376,y=0.613,source="quest_giver",zoneID=3525},questType="standard"},
[9709] = {id=9709,name="Stealing Back the Mushrooms",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description=", I've got an idea. I want you to head north again, this time into the heart of ogre territory! Northwest of the Hewn Bog there is a place named Ango'rosh Stronghold, which sits on a floating island across a large mushroom bridge. The ogres must be storing the harvested mushrooms there. I bet you'll find them all over the place, and probably on the ogres themselves, too! Bring me a sufficient number and I will try to do something about providing the bog lords with a new source of nourishment.",starts={{npcID=17831,x=0.232,y=0.662,zoneID=3521}},ends={{npcID=17831,x=0.232,y=0.662,zoneID=3521}},coords={x=0.232,y=0.662,source="quest_giver",zoneID=3521},questType="standard"},
[9711] = {id=9711,name="Matis the Cruel",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Matis will be brought to justice, ; and I want you to be the one to find him and bring him back to the Triumvirate. Scour the island for this killer. Should you find him, use this flare gun . When my trackers see the flare, they'll come and assist in capturing Matis. Return to me after he's been captured.",starts={{npcID=17843,x=0.556,y=0.552,zoneID=3525}},ends={{npcID=17843,x=0.556,y=0.552,zoneID=3525}},coords={x=0.556,y=0.552,source="quest_giver",zoneID=3525},questType="standard"},
[9716] = {id=9716,name="Disturbance at Umbrafen Lake",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="We came to Outland expecting to find small pockets of life. What we discovered in Zangarmarsh was a lush environment with a thriving ecosystem. Our initial assessment of the area was deceiving, however. The water levels at the lakes and marshes have consistently been going down since we started taking measurements. The impact this could have on the local animal and plant life is disastrous. Go to Umbrafen Lake, southwest of here, and look for clues related to this water depletion.",starts={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},ends={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},coords={x=0.784,y=0.62,source="quest_giver",zoneID=3521},questType="standard"},
[9718] = {id=9718,name="As the Crow Flies",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="We must determine how widespread the naga's activity truly is and react accordingly. Exploring each body of water in Zangarmarsh could be a lengthy undertaking. If you allow me to, I will use my magic to mold your shape to one more suited to scouting the marsh. Hold this amulet above the balcony near me when you're ready to begin. I will guide your way back to safety after we're done.",starts={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},ends={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},coords={x=0.784,y=0.62,source="quest_giver",zoneID=3521},questType="standard"},
[9720] = {id=9720,name="Balance Must Be Preserved",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="I cannot begin to comprehend why the naga would drain the water out of their own habitat. What I do understand is a need to put a stop to their operations. These seeds carry with them the rage of the earth. Take them to the steam pumps operated by the naga and use them on their controls. The vines that grow from the seeds will be as thick as your arm and as strong as iron. Go, . Restore the balance that the naga have upset.",starts={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},ends={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},coords={x=0.784,y=0.62,source="quest_giver",zoneID=3521},questType="standard"},
[9724] = {id=9724,name="Warning the Cenarion Circle",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="The Cenarion Expedition has become a large organization with a good degree of autonomy. These events are important enough that we need to warn the Cenarion Circle. Do not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.",starts={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},ends={{npcID=16885,x=0.16,y=0.522,zoneID=3483}},coords={x=0.784,y=0.62,source="quest_giver",zoneID=3521},questType="standard"},
[9726] = {id=9726,name="Now That We're Friends...",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="The naga of the Bloodscale Enclave to the northeast have begun to kill our people. We cannot allow this to continue, ! We suggest that you teach them a lesson as proof of our friendship.",starts={{npcID=17856,x=0.194,y=0.5,zoneID=3521}},ends={{npcID=17856,x=0.194,y=0.5,zoneID=3521}},coords={x=0.194,y=0.5,source="quest_giver",zoneID=3521},questType="standard"},
[9727] = {id=9727,name="Now That We're Still Friends...",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Reports have come in that the naga of the Bloodscale Enclave to the northeast continue to kill our people. We thought that you had dealt with this, ! I suggest that you to teach them a lesson as proof of our continued friendship.",starts={{npcID=17856,x=0.194,y=0.5,zoneID=3521}},ends={{npcID=17856,x=0.194,y=0.5,zoneID=3521}},coords={x=0.194,y=0.5,source="quest_giver",zoneID=3521},questType="standard"},
[9728] = {id=9728,name="A Warm Welcome",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="While the druids from the expedition have made themselves busy studying plants and researching the lakes, I've made it my business to deal with the hostiles in the area. Ever since we set foot in Zangarmarsh , the naga have launched lethal attacks against us without warning. We've done our best to keep them at bay, but our resources are limited. I want you to go to the various naga strongholds in Zangarmarsh and show them that we're not to be crossed. Bring me their claws as proof of your victories.",starts={{npcID=17858,x=0.79,y=0.652,zoneID=3521}},ends={{npcID=17858,x=0.79,y=0.652,zoneID=3521}},coords={x=0.79,y=0.652,source="quest_giver",zoneID=3521},questType="standard"},
[9729] = {id=9729,name="Fhwoor Smash!",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Little naga make Fhwoor angry! Sporelings good friend to Fhwoor , so Fhwoor get naga ark. We go into nearby naga village. You help?",starts={{npcID=17877,x=0.196,y=0.508,zoneID=3521}},ends={{npcID=17856,x=0.194,y=0.5,zoneID=3521}},coords={x=0.196,y=0.508,source="quest_giver",zoneID=3521},questType="standard"},
[9730] = {id=9730,name="Leader of the Darkcrest",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="A bounty is hereby declared by the Cenarion Expedition on Rajah Haghazed , leader of the Darkcrest naga. Haghazed was last sighted by Cenarion scouts at the Lagoon, in the central southern region of Zangarmarsh . The Darkcrest have been linked to numerous attacks against the Cenarion Expedition and their leader is considered extremely dangerous. Those seeking to claim the bounty are advised to report to Warden Hamoot .",starts={{npcID=182115,x=0.791,y=0.648,zoneID=3521}},ends={{npcID=17858,x=0.79,y=0.652,zoneID=3521}},coords={x=0.791,y=0.648,source="quest_giver",zoneID=3521},questType="standard"},
[9731] = {id=9731,name="Drain Schematics",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="The schematics you've obtained show an underground system of drains and pumps that connect the lakes in the region to Serpent Lake. If the schematics are correct, there is a giant drain in the center of Serpent Lake. Confirm this and bring the news to Cenarion Refuge.",ends={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},questType="standard"},
[9732] = {id=9732,name="Return to the Marsh",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Return to Ysiel and let her know that help will be extended to her as soon as it is possible. Affairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.",starts={{npcID=16885,x=0.16,y=0.522,zoneID=3483}},ends={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},coords={x=0.16,y=0.522,source="quest_giver",zoneID=3483},questType="standard"},
[9739] = {id=9739,name="The Sporelings' Plight",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="You there! You must help us! The fungal giants are devouring all of our spore sacs! You must do something, or we'll lose our young! The spore sacs start out large and become smaller as the air inside them is depleted. Look for the small, mature spore sacs and save as many of them as you can!",starts={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},ends={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},coords={x=0.19,y=0.626,source="quest_giver",zoneID=3521},questType="standard"},
[9740] = {id=9740,name="The Sun Gate",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Thanks to you and the work you did, my scouts were able to find the sun gate . The elves keep the portal location mobile so that they can move it at a moment's notice. That's why the site you investigated was empty. The strength of such a system is also its greatest weakness. The sun gate is stabilized by portal controllers. If we can take down the controllers, the portal will be ours to destroy. The current sun gate location can be found west of here, south of the Vector Coil. Find it and destroy it!",starts={{npcID=17844,x=0.556,y=0.554,zoneID=3525}},ends={{npcID=17844,x=0.556,y=0.554,zoneID=3525}},coords={x=0.556,y=0.554,source="quest_giver",zoneID=3525},questType="standard"},
[9741] = {id=9741,name="Critters of the Void",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Aesom sent my squad out on a reconnaissance mission to search for the sun gate a few days ago. Needless to say, we found it... Whatever those fool elves are transporting through that portal is causing void energy to be released. The area is teaming with void critters . We must destroy them before they have a chance to grow into void anomalies. You'll find the source of the creatures southwest of here, near the sun gate. Kill them and report back to Aesom when you're done.",starts={{npcID=17926,x=0.302,y=0.46,zoneID=3525}},ends={{npcID=17844,x=0.556,y=0.554,zoneID=3525}},coords={x=0.302,y=0.46,source="quest_giver",zoneID=3525},questType="standard"},
[9742] = {id=9742,name="More Spore Sacs",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,starts={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},ends={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},coords={x=0.19,y=0.626,source="quest_giver",zoneID=3521},questType="standard"},
[9743] = {id=9743,name="Natural Enemies",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Us sporelings and the bog lords have never gotten along well. In the past, we've managed to keep them at bay with spears and stones. Lately they seem to have become more aggressive... or more desperate. They do not fear us or our weapons. You are much scarier and better armed than us. If you were to fight the boglords for us, we'd be forever in your debt! Bring me their tendrils so I know how many you've killed.",starts={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},ends={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},coords={x=0.19,y=0.626,source="quest_giver",zoneID=3521},questType="standard"},
[9744] = {id=9744,name="More Tendrils!",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,starts={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},ends={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},coords={x=0.19,y=0.626,source="quest_giver",zoneID=3521},questType="standard"},
[9746] = {id=9746,name="Limits of Physical Exhaustion",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Victory is close at hand, . With the discovery of the sun gate, it won't be long until their supply lines are completely closed off. Now is the time to strike at their numbers. To the west you will find numerous Sunhawk camps. The Sunhawk pyromancers and defenders occupy the vast majority of the area. Find them, kill them and return to me.",starts={{npcID=17844,x=0.556,y=0.554,zoneID=3525}},ends={{npcID=17844,x=0.556,y=0.554,zoneID=3525}},coords={x=0.556,y=0.554,source="quest_giver",zoneID=3525},questType="standard"},
[9747] = {id=9747,name="The Umbrafen Tribe",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="The naga are terrible, yes. But even more terrible are the traitor tribes of Broken and Lost Ones that helped them! The worst of all are the Lost Ones of the Umbrafen tribe; they use dark magic to trap and enslave others. They're especially cruel to escaped slaves and would slit my throat if I left the refuge even for a day. Travel to Umbrafen Village south of here and kill them and their leader, Kataru . Until then I will fear for my life every single day.",starts={{npcID=17956,x=0.804,y=0.642,zoneID=3521}},ends={{npcID=17956,x=0.804,y=0.642,zoneID=3521}},coords={x=0.804,y=0.642,source="quest_giver",zoneID=3521},questType="standard"},
[9748] = {id=9748,name="Don't Drink the Water",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Our shaman claim that the elements of water have become greatly agitated by the pollution of the water source. We know that the Exodar's power core is lodged into the mountain to the west. It must be leaking volatile fluids into the water supply! I need you to get me more information. You are to take this flask and follow the beach north until you reach the area where the rivers of Bloodmyst drain into the ocean. Take a sample from that location and return to me.",starts={{npcID=17844,x=0.556,y=0.554,zoneID=3525}},ends={{npcID=17844,x=0.556,y=0.554,zoneID=3525}},coords={x=0.556,y=0.554,source="quest_giver",zoneID=3525},questType="standard"},
[9752] = {id=9752,name="Escape from Umbrafen",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="You must help me get out of here! I was gathering herbs nearby when a handful of these little savages abducted me. I tried to fight them off, but there were too many of them. Help me return to the Cenarion Refuge and away from these cruel wretches and their vile magic!",starts={{npcID=17969,x=0.832,y=0.854,zoneID=3521}},ends={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},coords={x=0.832,y=0.854,source="quest_giver",zoneID=3521},questType="standard"},
[9753] = {id=9753,name="What We Know...",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="We've learned much of our enemies in recent days. The blood elves are led by a being known as Sironas and plot to destroy us. Ultimately, they seek to enslave O'ros and regain control of the Exodar. Light be praised, we have stopped their supply line by destroying the sun gate. Unfortunately, they continue to use the contaminant of the Vector Coil to poison the land, using the mutagenic properties of the fallout to their advantage. With this knowledge, Admetius has devised a plan. Seek him out.",starts={{npcID=17844,x=0.556,y=0.554,zoneID=3525}},ends={{npcID=17658,x=0.526,y=0.532,zoneID=3525}},coords={x=0.556,y=0.554,source="quest_giver",zoneID=3525},questType="standard"},
[9756] = {id=9756,name="What We Don't Know...",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Our attempts at interrogation have failed miserably, . Torture is - of course - out of the question. What we need is a on the inside. I can cast a spell upon you that would make you appear blood elf and adjust your language. Through subterfuge, we may be able to get the information we need out of the captured agent. Under this guise, I want you to get whatever information you can out of the prisoner. And , do not leave Blood Watch while disguised as the spell will fail.",starts={{npcID=17658,x=0.526,y=0.532,zoneID=3525}},ends={{npcID=17658,x=0.526,y=0.532,zoneID=3525}},coords={x=0.526,y=0.532,source="quest_giver",zoneID=3525},questType="standard"},
[9758] = {id=9758,name="Return to Arcanist Vandril",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3433,description="Now my friend, if you would be so kind as to return to Arcanist Vandril , I know that he is very anxious to send you out on your first mission here in the Ghostlands . We're counting on you, . Don't let us down.",starts={{npcID=16252,x=0.448,y=0.324,zoneID=3433}},ends={{npcID=16197,x=0.464,y=0.284,zoneID=3433}},coords={x=0.448,y=0.324,source="quest_giver",zoneID=3433},questType="standard"},
[9759] = {id=9759,name="Ending Their World",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Don't accept this assignment if you value your life. You see that gigantic power core jutting out of the mountain side over yonder? Whoever takes on this burden will need to fight their way through that mountain, battling an army of Sunhawks while protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up there as well. I won't think less of you if you just walk away, . But maybe you're the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?",starts={{npcID=17982,x=0.308,y=0.466,zoneID=3525}},ends={{npcID=17658,x=0.526,y=0.532,zoneID=3525}},coords={x=0.308,y=0.466,source="quest_giver",zoneID=3525},questType="standard"},
[9760] = {id=9760,name="Vindicator's Rest",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="I would not ask you to single-handedly bear the burden of destroying the Vector Coil and slaying Sironas, ; however, I believe that you can be of some help in clearing the way for others that might take on such a dangerous assignment. Take the road going north out of Blood Watch and follow it until you get to the fork. Once there, take the left road and follow it until you see Vindicator's Rest - it will be slightly west of the road itself. Corin will be waiting for you.",starts={{npcID=17658,x=0.526,y=0.532,zoneID=3525}},ends={{npcID=17986,x=0.306,y=0.466,zoneID=3525}},coords={x=0.526,y=0.532,source="quest_giver",zoneID=3525},questType="standard"},
[9761] = {id=9761,name="Clearing the Way",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Only the most battle hardened, noble and positively fearless will submit to Legoso's mission. The exarch will not order any agent of the Hand to take on the task of destroying the Vector Coil and dispatching Sironas. He refuses to send any draenei to their death - which is what the mission is: suicide... My job is to soften up the Sunhawk defenses. You are to slay Sunhawks near the Vector Coil and keep the path clear for our champion - whoever that may be.",starts={{npcID=17986,x=0.306,y=0.466,zoneID=3525}},ends={{npcID=17986,x=0.306,y=0.466,zoneID=3525}},coords={x=0.306,y=0.466,source="quest_giver",zoneID=3525},questType="standard"},
[9762] = {id=9762,name="The Unwritten Prophecy",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3557,mapID=103,starts={{npcID=17468,x=0.54,y=0.554,mapID=106},{npcID=17468,x=0.326,y=0.542,mapID=103}},ends={{npcID=17468,x=0.54,y=0.554,mapID=106},{npcID=17468,x=0.326,y=0.542,mapID=103}},coords={x=0.54,y=0.554,source="quest_giver",mapID=103},questType="standard"},
[9769] = {id=9769,name="There's No Explanation for Fashion",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Magasha chuckles softly to herself.> I bet if they knew they were wearing bug parts, the fashion trend would end very quickly. We first started killing the bugs 'round here 'cause they were getting in the way of our construction. Some enterprising merchant stops here, spends the night, and next thing you know he's buyin' up all the bug wings we have! Says he makes clothes out of 'em. I be stickin' to my armor, thanks. But if you gather the wings of any of the fireflies, I'll gladly buy 'em.",starts={{npcID=18016,x=0.844,y=0.544,zoneID=3521}},ends={{npcID=18016,x=0.844,y=0.544,zoneID=3521}},coords={x=0.844,y=0.544,source="quest_giver",zoneID=3521},questType="standard"},
[9770] = {id=9770,name="Menacing Marshfangs",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Sometimes I wish Denjai had sent a shaman with us, or at least given us a totem to keep the marshfang rippers at bay. The whole place is crawling with the pests! It's just not right. Shouldn't something be eating these despicable things? We've all been taking turns playing exterminator. You showed up at just the right time, . Congratulations! Now get out there and mop up some marshfangs!",starts={{npcID=18012,x=0.85,y=0.54,zoneID=3521}},ends={{npcID=18012,x=0.85,y=0.54,zoneID=3521}},coords={x=0.85,y=0.54,source="quest_giver",zoneID=3521},questType="standard"},
[9771] = {id=9771,name="Searching for Scout Jyoba",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Now that you're familiar with the terrain, I'd like to ask your help with something else. The Dead Mire, we've taken to calling the area to the northwest, is an eerie place. No one has ever reported seeing anything alive there, but they didn't stay for very long, either. Scout Jyoba volunteered to investigate the area and report on his findings. He left the post three days ago and hasn't returned. It's not like him to be gone that long without sending some kind of report. Will you search for him, ?",starts={{npcID=18011,x=0.852,y=0.546,zoneID=3521}},ends={{npcID=18035,x=0.808,y=0.362,zoneID=3521}},coords={x=0.852,y=0.546,source="quest_giver",zoneID=3521},questType="standard"},
[9772] = {id=9772,name="Jyoba's Report",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Flecks of withered fungus dot the body of Scout Jyoba . Whatever killed him must've been made of the same dying fungus as the giant wilting mushrooms of the Dead Mire. Perhaps one of the withered giants caught him by surprise as he sat writing his report. Without the text of the report, it's nearly impossible to tell what the scout discovered. If the report can be found, it should be returned to Zurai .",starts={{npcID=18035,x=0.808,y=0.362,zoneID=3521}},ends={{npcID=18011,x=0.852,y=0.546,zoneID=3521}},coords={x=0.808,y=0.362,source="quest_giver",zoneID=3521},questType="standard"},
[9773] = {id=9773,name="No More Mushrooms!",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Mushroom soup, mushroom stew, mushroom sauce! Mushroom, mushroom, mushroom! It's all there is to eat around here. If you say you're hungry, the cook hands you an axe and tells you to go chop down your dinner! Well, I'm tired of mushrooms. I've seen fish in the lakes around here. Sure, they look like a nasty piece of work, but they've got to be better than mushrooms! How much will it cost me to hire you to bring me my first decent meal in weeks?",starts={{npcID=18016,x=0.844,y=0.544,zoneID=3521}},ends={{npcID=18016,x=0.844,y=0.544,zoneID=3521}},coords={x=0.844,y=0.544,source="quest_giver",zoneID=3521},questType="standard"},
[9774] = {id=9774,name="Thick Hydra Scales",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Reavij was wise to bring leather armor. This swamp will render my mail useless before long. I've been replacing the scales bit by bit as I'm able. The hydra in the marsh have thick, protective scales that stand up well to the dampness of their home. Finding suitable ones is a tedious process, though. All too often, the best scales are torn or worn too thin for use in armor. Bring me any good ones that you might get from the hydra in the larger lakes.",starts={{npcID=18011,x=0.852,y=0.546,zoneID=3521}},ends={{npcID=18011,x=0.852,y=0.546,zoneID=3521}},coords={x=0.852,y=0.546,source="quest_giver",zoneID=3521},questType="standard"},
[9775] = {id=9775,name="Report to Shadow Hunter Denjai",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Shadow Hunter Denjai will no doubt expect to receive a report about my progress in establishing our outpost. I've prepared a short summary of what we've accomplished here already, but with the loss of Scout Jyoba, I can't spare a runner to take the report to Denjai's base of Zabra'jin to the west. If you're headed that way, would you mind bringing this to him? Shadow Hunter Denjai can be a little intimidating at first, but once you get used to him, he's not so bad.",starts={{npcID=18011,x=0.852,y=0.546,zoneID=3521}},ends={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},coords={x=0.852,y=0.546,source="quest_giver",zoneID=3521},questType="standard"},
[9776] = {id=9776,name="The Orebor Harborage",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="As you know, many of Telredor's inhabitants are refugees from the war that decimated the draenei. It is my goal to maintain Telredor as a safe haven for all of our allies in this struggle. There are some who desire to join us, but feel they are not yet ready. We owe them whatever help we can provide, . A group of Broken under the leadership of Ikuti have taken shelter in the ruins of an old temple to the northwest of Serpent Lake. Seek them out and extend your hand in friendship to them.",starts={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},ends={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},coords={x=0.682,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9777] = {id=9777,name="Fulgor Spores",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="There is little in this swamp that will burn, , so we must resort to other means for lighting Telredor. Many of the creatures and plants in the marsh emit a soft glow. It's difficult and cruel to confine the glowing creatures, so we've turned to a species of mushroom for our light source. We pick and cultivate the fulgor mushroom here, but our needs require us to gather new crops occasionally. The small green mushrooms often grow at the base of larger ones near Telredor.",starts={{npcID=18007,x=0.686,y=0.488,zoneID=3521}},ends={{npcID=18007,x=0.686,y=0.488,zoneID=3521}},coords={x=0.686,y=0.488,source="quest_giver",zoneID=3521},questType="standard"},
[9778] = {id=9778,name="Warden Hamoot",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Before you leave Cenarion Refuge, make sure you speak with Warden Hamoot . He's in charge of the expedition's security. He would never forgive me if I didn't send a seasoned adventurer like you his way.",starts={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},ends={{npcID=17858,x=0.79,y=0.652,zoneID=3521}},coords={x=0.784,y=0.62,source="quest_giver",zoneID=3521},questType="standard"},
[9779] = {id=9779,name="Intercepting the Message",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="It is good to see you again, . I have a quandary that you might be able to solve. Our agents situated behind Sunhawk lines have reported seeing Sunhawk soldiers parsing an unusual document. Unfortunately, we have been unsuccessful in acquiring a copy of the document for ourselves. I need you to go out in the field and try to recover the document. I am certain that if you apply enough pressure, a Sunhawk agent will turn over the information we seek. I leave the use of force to your discretion.",starts={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},ends={{npcID=17684,x=0.554,y=0.552,zoneID=3525}},coords={x=0.554,y=0.552,source="quest_giver",zoneID=3525},questType="standard"},
[9780] = {id=9780,name="Umbrafen Eel Filets",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="It's good to see another fresh face here. When Haalrun and I first came to Telredor, we were the only outsiders, but that seems like a lifetime ago. Still, we try to welcome newcomers and ensure that there's always enough food and supplies. We can never fully repay the kindness of the Telredor anchorites, but we can follow their example and extend it to others. If you would like to help, the nearby lakes are populated with a fish called the Umbrafen eel, whose meat is a staple of our diet.",starts={{npcID=18006,x=0.676,y=0.478,zoneID=3521}},ends={{npcID=18006,x=0.676,y=0.478,zoneID=3521}},coords={x=0.676,y=0.478,source="quest_giver",zoneID=3521},questType="standard"},
[9781] = {id=9781,name="Too Many Mouths to Feed",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="On my last hunting trip, I caught sight of a new outpost being built by a group of trolls. No doubt they've begun hunting these lands, too. If they establish a permanent presence out here, the competition for food will be fierce. We cannot take direct action against them without provocation, but we can remove some of the natural competition for food. For each mire hydra you kill, that's three fewer mouths to feed!",starts={{npcID=18005,x=0.678,y=0.48,zoneID=3521}},ends={{npcID=18005,x=0.678,y=0.48,zoneID=3521}},coords={x=0.678,y=0.48,source="quest_giver",zoneID=3521},questType="standard"},
[9782] = {id=9782,name="The Dead Mire",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="I have lived among the anchorites of Telredor for some time, , and in that time I've come to know the marsh quite well. Recently, I've started to notice a disturbing change in the land to the northeast. Virtually all life there has begun to wither and die, seemingly without explanation. I have a few ideas as to what might be happening, but they are little more than speculation. If you were to bring me a sample of the soil in that area, I may be able to get to the bottom of this mystery.",starts={{npcID=18004,x=0.682,y=0.5,zoneID=3521}},ends={{npcID=18004,x=0.682,y=0.5,zoneID=3521}},coords={x=0.682,y=0.5,source="quest_giver",zoneID=3521},questType="standard"},
[9783] = {id=9783,name="An Unnatural Drought",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="The soil sample you brought me is nearly devoid of moisture, . If the soil itself is losing moisture, then the creatures that live in the Dead Mire must be suffering terribly. I've seen what happens when the region's fungal giants begin to wither and die. The pain drives them mad, causing them to attack anything in their path. These creatures have no idea what's happening to them. They're beyond our ability to save, so the best we can do is to end their suffering.",starts={{npcID=18004,x=0.682,y=0.5,zoneID=3521}},ends={{npcID=18004,x=0.682,y=0.5,zoneID=3521}},coords={x=0.682,y=0.5,source="quest_giver",zoneID=3521},questType="standard"},
[9784] = {id=9784,name="Identify Plant Parts",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,starts={{npcID=17909,x=0.802,y=0.642,zoneID=3521}},ends={{npcID=17909,x=0.802,y=0.642,zoneID=3521}},coords={x=0.802,y=0.642,source="quest_giver",zoneID=3521},questType="standard"},
[9785] = {id=9785,name="Blessings of the Ancients",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="You've earned the trust of the Cenarion Expedition, . It is time you spoke to the ancients allied with our cause, Ashyen and Keleth , and asked for their blessing. Carrying the mark of an ancient will fill you with great power. These boons will become more powerful as your renown among us increases. Go, , and ask the ancients for their blessing.",starts={{npcID=18070,x=0.804,y=0.646,zoneID=3521}},ends={{npcID=18070,x=0.804,y=0.646,zoneID=3521}},coords={x=0.804,y=0.646,source="quest_giver",zoneID=3521},questType="standard"},
[9786] = {id=9786,name="The Boha'mu Ruins",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="Before my people were decimated by the orcs, Telredor served as a retreat for draenei anchorites and spiritualists. A small order of anchorites and vindicators maintained a number of shrines in this region. During the war, we lost contact with the anchorites assigned to the shrines, particularly the Boha'mu temple to the southwest. I've heard reports that a tribe of Lost Ones has settled in the area and may even be using the ruins. Visit the Boha'mu Ruins and tell me of what you find there.",starts={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},ends={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},coords={x=0.682,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9787] = {id=9787,name="Idols of the Feralfen",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="From what you've told me about your observations at the Boha'mu Ruins, it seems this tribe of Lost Ones has reverted to the worship of animal spirits. Before we can approach them, we must know more of their beliefs. Return to Feralfen Village and discreetly gather some of their idols so that I may study them. Try to avoid angering them, , as it may hurt our chances of making contact with them.",starts={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},ends={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},coords={x=0.682,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9788] = {id=9788,name="A Damp, Dark Place",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Soon after I escaped the Umbrafen tribe, I holed up in a cave south of their village. Little did I know that the cave was being fought over by marsh beasts and spore men! I had to leave in a hurry and left behind a box containing my only worldly possessions. After managing to sneak out of Umbrafen with my belongings it was terrible irony that I would lose them so soon after. If you're willing to bring them back to me I'll give you one of my very own personal items. What do you say, ?",starts={{npcID=17956,x=0.804,y=0.642,zoneID=3521}},ends={{npcID=17956,x=0.804,y=0.642,zoneID=3521}},coords={x=0.804,y=0.642,source="quest_giver",zoneID=3521},questType="standard"},
[9789] = {id=9789,name="Clefthoof Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="You want to earn a place in this safari? You'll have to prove yourself. I don't care what you've hunted before, you haven't hunted until you hunt what we hunt here. Start with the clefthoof if you're enough. I know that I've seen them in the immediate area around the safari and also close by to the south.",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[9790] = {id=9790,name="Diaphanous Wings",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="Living in such a remote location has taught us to make use of everything available. Of course, you have to learn to stop thinking about where some of these materials come from first. I've found that the wings of the umbraglow stingers are very helpful for waterproofing. They're strong, thin, and flexible. Haalrun chuckles.> I see the look on your face. Like I said, it takes time to get used to the idea. If you're going to be out and about, would you mind bringing me some of the wings?",starts={{npcID=18005,x=0.678,y=0.48,zoneID=3521}},ends={{npcID=18005,x=0.678,y=0.48,zoneID=3521}},coords={x=0.678,y=0.48,source="quest_giver",zoneID=3521},questType="standard"},
[9791] = {id=9791,name="Menacing Marshfangs",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="During the orcs' war against my people, gatherers rarely left Telredor for fear of being attacked or captured. Now, we venture out more often, but the marsh is no less perilous. It seems that the nether rays have grown bolder in recent months. I don't know if it has something to do with more competition for their normal prey, but they've been attacking our foraging parties on a regular basis. If we can thin their ranks in the area around Telredor, perhaps they would learn to leave us alone.",starts={{npcID=18006,x=0.676,y=0.478,zoneID=3521}},ends={{npcID=18006,x=0.676,y=0.478,zoneID=3521}},coords={x=0.676,y=0.478,source="quest_giver",zoneID=3521},questType="standard"},
[9792] = {id=9792,name="A Message to Telaar",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="You've been honorable in our dealings, , at a time when trust is hard to win among my people. A large group of my brethren have made their home in the old draenei city of Telaar in Nagrand , to the south. To reach Telaar, take the road south into Nagrand , then continue southeast until you find yourself in the cliffs east of Oshu'gun. Anyone who has aided us, as you have, would be welcome among the people of Telaar. Seek out Warden Moi'bff Jill and tell him you have earned my trust.",starts={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},ends={{npcID=18408,x=0.548,y=0.708,zoneID=3518}},coords={x=0.418,y=0.272,source="quest_giver",zoneID=3521},questType="standard"},
[9793] = {id=9793,name="The Fate of Tuurem",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="Prophet Velen's search for allies has emboldened those draenei remaining in Outland to begin a search of their own. The Legion's war on my people drove us from our cities and temples, but they have not destroyed the traces of our civilization. Tuurem, my former home in the Terokkar Forest , was one of the first cities overrun by the orcs. It's been too long since I've received news of its status. Take this letter to Andarl in the Allerian Stronghold within Terokkar and see what you can find out.",starts={{npcID=18004,x=0.682,y=0.5,zoneID=3521}},ends={{npcID=18252,x=0.584,y=0.536,zoneID=3519}},coords={x=0.682,y=0.5,source="quest_giver",zoneID=3521},questType="standard"},
[9794] = {id=9794,name="No Time for Curiosity",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description=", I have a favor to ask of you. Normally, I would do this myself, but my hands are already beyond full. I have an associate named Kialon at Sylvanaar in the Blade's Edge Mountains to the north. He's expecting to hear from me in the near future, although I suspect he won't like what I have to say. If you would deliver my response to him, you would have my gratitude. I must insist, and this is very important, that you not attempt to read the letter. It is for Kialon's eyes alone.",starts={{npcID=18019,x=0.412,y=0.286,zoneID=3521}},ends={{npcID=18098,x=0.36,y=0.678,zoneID=3522}},coords={x=0.412,y=0.286,source="quest_giver",zoneID=3521},questType="standard"},
[9795] = {id=9795,name="The Ogre Threat",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="As if the naga and their allies weren't enough, the ogres are extending their reach in the marsh. They've already conquered most of the area to the northwest and there isn't much of a buffer left. For each one we kill, several more take their place. I'm not sure how long we'll be able to hold Zabra'jin once they decide to attack. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Nekthar know of our plight. Any help he can spare would be most welcome.",starts={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},ends={{npcID=18248,x=0.518,y=0.578,zoneID=3522}},coords={x=0.306,y=0.508,source="quest_giver",zoneID=3521},questType="standard"},
[9796] = {id=9796,name="News from Zangarmarsh",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="Shadow Hunter Denjai isn't the only one expecting a report from me. Mokasa at Stonebreaker Hold in Terokkar is eager to hear of our progress, especially since most of her messengers travel through here. She asked me to send word once Swamprat Post was completed. If you wouldn't mind delivering the news, I'd be very grateful. We may be up and running, but there is still much to be done. To get to Stonebreaker Hold, follow the road south out of Zangarmarsh, into Terokkar Forest and beyond Tuurem.",starts={{npcID=18011,x=0.852,y=0.546,zoneID=3521}},ends={{npcID=18249,x=0.496,y=0.434,zoneID=3519}},coords={x=0.852,y=0.546,source="quest_giver",zoneID=3521},questType="standard"},
[9797] = {id=9797,name="Reinforcements for Garadar",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="They may not survive, ! Get to Garadar as quickly as your legs will carry you. The home of the Mag'har, lies to the south, in Nagrand . Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake. Find our commander, Captain Kroghan , there and offer him what assistance you can. Garadar must not fall!",starts={{npcID=18091,x=0.32,y=0.504,zoneID=3521}},ends={{npcID=18090,x=0.554,y=0.374,zoneID=3518}},coords={x=0.32,y=0.504,source="quest_giver",zoneID=3521},questType="standard"},
[9798] = {id=9798,name="Blood Elf Plans",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="These plans seem important. You should take them to Vindicator Aldar at the crash site.",ends={{npcID=16535,x=0.794,y=0.514,zoneID=3524},{npcID=16535,x=0.506,y=0.486,zoneID=6456}},questType="standard"},
[9799] = {id=9799,name="Botanical Legwork",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=457,description="The Ammen Fields to the west are the primary breeding ground of the local lasher population. With the corruption of the water table from the nearby lake, Botanist Taerix is worried that the lashers will not be able to repopulate themselves once we've cleansed the lake. Go to the Ammen Fields and pick some of the corrupted flowers for me so that I might take a look at them and see what can be done. You should be able to identify them by their uncharacteristic red petals.",starts={{npcID=20233,x=0.79,y=0.464,zoneID=3524},{npcID=20233,x=0.498,y=0.372,zoneID=6456}},ends={{npcID=20233,x=0.79,y=0.464,zoneID=3524},{npcID=20233,x=0.498,y=0.372,zoneID=6456}},coords={x=0.79,y=0.464,source="quest_giver",zoneID=3524},questType="standard"},
[9800] = {id=9800,name="A Rare Bean",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="You are ill-equipped to face the restless elements of Nagrand . Before you can help the Earthen Ring, you must help yourself. To the west you will find dung heaps left behind by the wildlife of Nagrand . You must search the dung for the digested remnants of the Nagrand caracoli. From this bean I am able to make a tablet that will aid you in your battle against the restless forces of nature. Return to me when you have collected no less than two fists worth of caracoli... Ogre sized fists.",starts={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},ends={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},coords={x=0.608,y=0.224,source="quest_giver",zoneID=3518},questType="standard"},
[9801] = {id=9801,name="Gathering the Reagents",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="I have a feeling that these Lost Ones may not respond well to a draenei, but would welcome an arakkoa. I can create a potion that will allow you to take on the form of an arakkoa for a short time. It requires a couple of reagents which cannot be stored and must be used within hours of being gathered. You will need to bring me a handful of sporebat eyes and some fen strider tentacles . Both species dwell in the wilderness surrounding Telredor.",starts={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},ends={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},coords={x=0.682,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9802] = {id=9802,name="Plants of Zangarmarsh",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="The lakes of Zangarmarsh are slowly being drained of their water. We don't quite know why, but we do know that many plants species are in danger of becoming extinct. As the expedition's cataloguer, it is my job to track and identify these plants so we can better understand what's happening to them. If you'd like to help, bring me unidentified plant parts . They can be picked right from the ground if you're an herbalist, and the indigenous creatures of the swamp may also carry plant parts on them.",starts={{npcID=17909,x=0.802,y=0.642,zoneID=3521}},ends={{npcID=17909,x=0.802,y=0.642,zoneID=3521}},coords={x=0.802,y=0.642,source="quest_giver",zoneID=3521},questType="standard"},
[9803] = {id=9803,name="Messenger to the Feralfen",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="The time has come for us to embrace the Feralfen and teach them that the Light has not forsaken them. Take the potion I've prepared and carry it with you to the Boha'mu Ruins. Once you arrive at the ruins, drink the potion to assume the form of one of their bird spirits. Speak with Elder Kuruti and let him know the draenei are ready to welcome his people as our long lost brothers.",starts={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},ends={{npcID=18003,x=0.682,y=0.494,zoneID=3521}},coords={x=0.682,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9804] = {id=9804,name="Agitated Spirits of Skysong",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="The disturbance in the ebb and flow of the waters of Nagrand has greatly agitated the water spirits of Skysong Lake. They have in turn begun sowing destruction throughout the waterways of the area. Watoosun of the Water has come to us in a vision and granted us permission to remedy the problem - so long as the source of the disturbance is also dealt with... We will get to the source, but first you must deal with the problems immediate to the Throne. Destroy the agitated lake spirits and return to me.",starts={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},ends={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},coords={x=0.608,y=0.224,source="quest_giver",zoneID=3518},questType="standard"},
[9805] = {id=9805,name="Blessing of Incineratus",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="The wretched Lost Ones, heretofore banished to the swamps of Zangarmarsh, are seeking to spread their filth to other parts of our world. I have sought the wisdom of the furies and gained their blessing. To stop the source, we must unleash the elements upon them! I give you living fire , plucked from the fiery essence of Incineratus himself. Travel to Windyreed Village, southeast of here, and unleash the living fire upon their huts! Let them see the fury of the elements!",starts={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},ends={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},coords={x=0.608,y=0.224,source="quest_giver",zoneID=3518},questType="standard"},
[9806] = {id=9806,name="Fertile Spores",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Spore bats and marsh walkers accumulate fertile spores on their appendages from wandering around the tallstalk mushrooms in the marsh. As you can see, we're a short people so our options for gathering these spores are limited. Seek out the spore bats and marsh walkers and gather the fertile spores . All of Sporeggar will be in your debt.",starts={{npcID=17925,x=0.192,y=0.494,zoneID=3521}},ends={{npcID=17925,x=0.192,y=0.494,zoneID=3521}},coords={x=0.192,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9807] = {id=9807,name="More Fertile Spores",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,starts={{npcID=17925,x=0.192,y=0.494,zoneID=3521}},ends={{npcID=17925,x=0.192,y=0.494,zoneID=3521}},coords={x=0.192,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9808] = {id=9808,name="Glowcap Mushrooms",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="I've seen your kind use shiny round pieces of metal to trade for things that you need. We're not so different from you. We use shiny round mushrooms as our currency. Glowcap mushrooms grow everywhere in the marsh, you just have to know how to pick them from the ground without wrecking them. I'll teach you how to do it, if you promise to bring us some for our reserves. What do you say, ?",starts={{npcID=17924,x=0.196,y=0.52,zoneID=3521}},ends={{npcID=17924,x=0.196,y=0.52,zoneID=3521}},coords={x=0.196,y=0.52,source="quest_giver",zoneID=3521},questType="standard"},
[9809] = {id=9809,name="More Glowcaps",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,starts={{npcID=17924,x=0.196,y=0.52,zoneID=3521}},ends={{npcID=17924,x=0.196,y=0.52,zoneID=3521}},coords={x=0.196,y=0.52,source="quest_giver",zoneID=3521},questType="standard"},
[9810] = {id=9810,name="The Spirit Polluted",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Watoosun was able to shed the stink of corruption; but in doing so, created a twisted spirit essence. A spirit essence composed of the vilest corruption found amongst the elements! You will find this polluted spirit of the swamp southwest of here, hidden in the depths of Lake Sunspring. Find and destroy the polluted essence of Watoosun and any corrupt offspring that it may have created.",starts={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},ends={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},coords={x=0.608,y=0.224,source="quest_giver",zoneID=3518},questType="standard"},
[9811] = {id=9811,name="Friend of the Sin'dorei",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3487,description="This is the beginning of a new chapter in blood elf history, . You've helped cement the bond between my race and yours, . Take the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City. He'll be eager to hear the news.",starts={{npcID=16239,x=0.55,y=0.488,zoneID=3433}},ends={{npcID=16802,x=0.54,y=0.204,zoneID=3487}},coords={x=0.55,y=0.488,source="quest_giver",zoneID=3433},questType="standard"},
[9812] = {id=9812,name="Envoy to the Horde",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=1497,description="There were doubts about our capabilities among our potential new allies. Of what use could we be to them when perceived as unable to deal with our problems at home? This changes everything. No longer will our power be questioned. We'll be able to join the Horde as equals. Take this letter to Sylvanas, ruler of the Forsaken. She's already on our side but the news of Dar'Khan's death will be music to her ears. Prepare for a long trip, . If all goes well she will send you to Orgrimmar.",starts={{npcID=16802,x=0.54,y=0.204,zoneID=3487}},ends={{npcID=10181,x=0.578,y=0.916,zoneID=1497}},coords={x=0.54,y=0.204,source="quest_giver",zoneID=3487},questType="standard"},
[9814] = {id=9814,name="Burstcap Mushrooms, Mon!",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="You like mushrooms, mon? There be a powerful one here in Zangarmarsh , growin' real close to Zabra'jin. You gotta be careful, though, mon. They be callin' it the burstcap for a reason. If you be gettin' too close without takin' the proper precautions, it'll blow right up on you! Poof! Right into a cloud o' toxic spores. I been usin' them for readin' the omens, but they be almost gone now.",starts={{npcID=18014,x=0.328,y=0.488,zoneID=3521}},ends={{npcID=18014,x=0.328,y=0.488,zoneID=3521}},coords={x=0.328,y=0.488,source="quest_giver",zoneID=3521},questType="standard"},
[9815] = {id=9815,name="Muck Diving",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="The most affected elements of water can be found in the Halaani Basin, southwest of here, beneath the abandoned city of Halaa. While some distressed elements can be destroyed without any impact upon the environment, spawns of muck must be physically removed from the world once destroyed. You see, muck spawns leave behind globules of tainted debris that if left untouched will spread and further contaminate the environment. Destroy these muck spawns and bring back their muck-ridden cores .",starts={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},ends={{npcID=18073,x=0.608,y=0.224,zoneID=3518}},coords={x=0.608,y=0.224,source="quest_giver",zoneID=3518},questType="standard"},
[9816] = {id=9816,name="Have You Ever Seen One of These?",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="This marsh be missin' one thing, mon! There be no murlocs here. Don't worry, mon, I got a plan to fix the problem. See Gargle 'n' Gurgle over there? I plan to give the gift o' murlocs to the Lost Ones! Take this cage with you to Daggerfen Village an' release 'em in the northeastern cluster of huts. Now you know I can't be riskin' Gargle 'n' Gurgle with you, but I'll give you a cage full o' colorful young murlocs. Just set it on the flat rock you be findin' up there and open the door!",starts={{npcID=18014,x=0.328,y=0.488,zoneID=3521}},ends={{npcID=18014,x=0.328,y=0.488,zoneID=3521}},coords={x=0.328,y=0.488,source="quest_giver",zoneID=3521},questType="standard"},
[9817] = {id=9817,name="Leader of the Bloodscale",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="A bounty is hereby declared by the Cenarion Expedition on Rajis Fyashe , leader of the Bloodscale naga. The naga sorceress was last sighted at Serpent Lake, in the northern region of Zangarmarsh . The Bloodscale are to be considered extremely dangerous and their leader is to be approached with extreme caution. Those seeking to claim the bounty are advised to report to Warden Hamoot at Cenarion Refuge.",starts={{npcID=182115,x=0.791,y=0.648,zoneID=3521}},ends={{npcID=17858,x=0.79,y=0.652,zoneID=3521}},coords={x=0.791,y=0.648,source="quest_giver",zoneID=3521},questType="standard"},
[9818] = {id=9818,name="The Underneath",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Something rails the underneath. It beats the ground as if to punish. *Thud* It makes this sound a hundred-thousand times. Endlessly it beats. The earth reels. It is calling out to us now. Gordawg speaks to me. Gordawg knows that something forces the elements out. Something from the underneath. Go now and speak to Gordawg . No, listen to Gordawg , do not speak. Hear Gordawg ...",starts={{npcID=18071,x=0.606,y=0.226,zoneID=3518}},ends={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},coords={x=0.606,y=0.226,source="quest_giver",zoneID=3518},questType="standard"},
[9819] = {id=9819,name="The Tortured Earth",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Bring up the usurper. You will find him. Follow earthen path. First you put to rest tortured earth spirits . Must sleep once more. Gordawg smashes his fist into the ground and brings up very foul smelling soil.> Must sleep! Gordawg points southeast.> Find spirits near mountains. Near hills. Near rocks. Near earth. Put to sleep. Telaari Basin... Southeast.",starts={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},ends={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},coords={x=0.612,y=0.222,source="quest_giver",zoneID=3518},questType="standard"},
[9820] = {id=9820,name="WANTED: Boss Grog'ak",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Wanted - Dead or Alive: Boss Grog'ak, overseer of the Ango'rosh mushroom-cutting operation. This brute and his axe-wielding cronies are responsible for chopping down the mushrooms to the north of town. Unless he is stopped, he and his band will cut a path to the walls of Zabra'jin. who presents the head of Boss Grog'ak to Shadow Hunter Denjai shall be well-rewarded.",starts={{npcID=182165,x=0.32,y=0.494,zoneID=3521}},ends={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},coords={x=0.32,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9821] = {id=9821,name="Eating Damnation",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Gordawg picks up a rock and begins to chew on it.> Gordawg tastes. Gordawg knows where this earth has been. Gordawg raises one of his massive legs and stomps the ground.> Look. See Nagrand . Gordawg directs you to the imprint of his foot. Within the imprint you see what appears to be a perfect geological map of Nagrand , marked with the locations of where you can find the elementals Gordawg wants you to destroy.> BREAK THEM! Bring Gordawg the pieces to eat. Take the map.",starts={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},ends={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},coords={x=0.612,y=0.222,source="quest_giver",zoneID=3518},questType="standard"},
[9822] = {id=9822,name="Impending Attack",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="The position of the ogres' mushroom-cutting operation can't be an accident. I can't escape the suspicion that they're preparing for an attack on Zabra'jin. I must know for certain, . The ogres have another outpost to the northwest, the Ango'rosh Grounds. If they're staging for an attack, there will be evidence of their plans there. Go there, and search the camp for signs of their intentions. Return to me with anything that might be suspicious.",starts={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},ends={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},coords={x=0.306,y=0.508,source="quest_giver",zoneID=3521},questType="standard"},
[9823] = {id=9823,name="Us or Them",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="In order to end the Ango'rosh threat, we must kill their leader, Overlord Gorefist . We'll do better than that, though. We'll make an example of the overlord and his followers. Go to the Ango'rosh Stronghold and deal with our foes. The stronghold is located in a cave on a small island to the northwest of Zabra'jin. You'll see a bridge made from a fallen mushroom beyond the Ango'rosh Camp. Show no mercy, . They certainly wouldn't spare any of us.",starts={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},ends={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},coords={x=0.306,y=0.508,source="quest_giver",zoneID=3521},questType="standard"},
[9827] = {id=9827,name="Withered Basidium",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform. Perhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.",ends={{npcID=18007,x=0.686,y=0.488,zoneID=3521}},questType="standard"},
[9828] = {id=9828,name="Withered Basidium",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform. Perhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.",ends={{npcID=18012,x=0.85,y=0.54,zoneID=3521}},questType="standard"},
[9830] = {id=9830,name="Stinger Venom",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="When I speak to draenei, I often get the sense that they consider themselves removed from their environment. Many seem to pity my brethren, the Broken, who they say have lost something. We Broken may have lost our inclination toward the Light, but our experiences have brought us closer to the land. My people see opportunities where few draenei do. Take, for example, the venom of the marshlight bleeders that live to the south and west. It has a wide variety of uses from hunting to healing.",starts={{npcID=18009,x=0.408,y=0.286,zoneID=3521}},ends={{npcID=18009,x=0.408,y=0.286,zoneID=3521}},coords={x=0.408,y=0.286,source="quest_giver",zoneID=3521},questType="standard"},
[9833] = {id=9833,name="Lines of Communication",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3518,description="One of the reasons Ikuti led us to Zangarmarsh was to help open the lines of communication between the draenei and the Kurenai home city of Telaar in Nagrand. In order for messengers to pass swiftly between Telaar and Telredor, the roads must be secured. On our way here, we were attacked repeatedly by marshfang slicers . We were able to fight them off, but they would pose a formidable threat to a solitary messenger. Reducing their numbers will help ensure the safety of our messengers.",starts={{npcID=18009,x=0.408,y=0.286,zoneID=3521}},ends={{npcID=18009,x=0.408,y=0.286,zoneID=3521}},coords={x=0.408,y=0.286,source="quest_giver",zoneID=3521},questType="standard"},
[9834] = {id=9834,name="Natural Armor",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="Maktu can always see a draenei approaching in his shiny armor from a mile away, even in this murky swamp! Maktu wants to laugh at them, but then he remembers that they have been kind to the Kurenai and he wants to teach them about how Kurenai make armor. The dark, scaly hides of the fenclaw thrashers make some of the best armor Maktu has ever worn. If can bring Maktu some of these hides from the fenclaw thrashers deep in Serpent Lake, he'll be happy to share some of his armor.",starts={{npcID=18010,x=0.416,y=0.274,zoneID=3521}},ends={{npcID=18010,x=0.416,y=0.274,zoneID=3521}},coords={x=0.416,y=0.274,source="quest_giver",zoneID=3521},questType="standard"},
[9835] = {id=9835,name="Ango'rosh Encroachment",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="The small band of Broken you see here is a mission from a larger settlement in Nagrand. The Kurenai, as we call ourselves, are Broken who desire to reunite with our draenei brothers. My group has come here to strengthen Kurenai ties to the draenei of Telredor. If the Ango'rosh ogres have their way, this temple will not stand much longer. They have cleared the Hewn Bog of its towering mushrooms and draw ever closer to our refuge. If you would call yourself our friend, aid us in fighting this enemy.",starts={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},ends={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},coords={x=0.418,y=0.272,source="quest_giver",zoneID=3521},questType="standard"},
[9839] = {id=9839,name="Overlord Gorefist",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="The centerpiece of any ogre tribe is its leader. Without leadership, the Ango'rosh's organization will disappear and they'll resort to infighting to determine who will lead next. Although we've seen the ogres out and about in this area, their true strength is concentrated in their Ango'rosh Stronghold to the northwest. It's located in a cave on a small island connected to the marsh by a fallen mushroom. Go there and defeat Overlord Gorefist . That should provide us with a well-deserved respite.",starts={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},ends={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},coords={x=0.418,y=0.272,source="quest_giver",zoneID=3521},questType="standard"},
[9841] = {id=9841,name="Stinging the Stingers",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="It's impossible to work with all this infernal buzzing! Do you hear it? I can't get it out of my head! I know exactly what's making the noise, too. It's those damnable marshlight bleeders ! The noise always comes from the south and west of the village. They're too big to swat, crush underfoot, or wave away. The only way to stop that unholy droning is to kill them. I don't care how you do it, , just quiet them!",starts={{npcID=18015,x=0.316,y=0.492,zoneID=3521}},ends={{npcID=18015,x=0.316,y=0.492,zoneID=3521}},coords={x=0.316,y=0.492,source="quest_giver",zoneID=3521},questType="standard"},
[9842] = {id=9842,name="The Sharpest Blades",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3518,description="The damp atmosphere of the marsh has taken a toll on my metal tools. It's made woodworking a lot more difficult than it ought to be, so I've given up on metal blades. It turns out that the marshfang slicers living to the south and west of town grow blades that are sharper than any steel I've ever owned. They're also resistant to rust and wear. It's just a little tricky to attach them to a handle, but I think I've got it figured out. I'd appreciate any blades you could bring me.",starts={{npcID=18015,x=0.316,y=0.492,zoneID=3521}},ends={{npcID=18015,x=0.316,y=0.492,zoneID=3521}},coords={x=0.316,y=0.492,source="quest_giver",zoneID=3521},questType="standard"},
[9845] = {id=9845,name="Angling to Beat the Competition",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="It's a relief to be in someplace with water after trekking through the wasteland of Hellfire Peninsula. I was worried there might not be any respectable fishing holes in Outland. Now I'm glad I lugged my fishing supplies along. For the most part, the fishing's been good, except for those no good fenclaw thrashers in Serpent Lake. Not only do they scare the fish away, but they're bold enough to snap the bait right off my hook. I spend more time re-baiting the hook than I do catching anything!",starts={{npcID=18018,x=0.322,y=0.496,zoneID=3521}},ends={{npcID=18018,x=0.322,y=0.496,zoneID=3521}},coords={x=0.322,y=0.496,source="quest_giver",zoneID=3521},questType="standard"},
[9846] = {id=9846,name="Spirits of the Feralfen",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="The most powerful tribe of Lost Ones in the marsh, the Feralfen, are said to possess powerful medicine. There may be no truth to such rumors, but anything that might help me channel the spirits of this world cannot be ignored. Find the Feralfen mystics, hunters and druids, , and capture their totems. Everything I need to know should be apparent from the carvings.",starts={{npcID=18017,x=0.324,y=0.518,zoneID=3521}},ends={{npcID=18017,x=0.324,y=0.518,zoneID=3521}},coords={x=0.324,y=0.518,source="quest_giver",zoneID=3521},questType="standard"},
[9847] = {id=9847,name="A Spirit Ally?",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="We must find out how much power this Feralfen snake spirit possesses and whether it can be bent to our will. Imagine what I could do with the powers of an Outland spirit at my command! Take this totem with you and make your way to the foot of the stairs leading to the Boha'mu Ruins. Plant the totem in the ground and it should do the rest. The spirit should not be able to tell who has used the totem until it has manifested.",starts={{npcID=18017,x=0.324,y=0.518,zoneID=3521}},ends={{npcID=18017,x=0.324,y=0.518,zoneID=3521}},coords={x=0.324,y=0.518,source="quest_giver",zoneID=3521},questType="standard"},
[9848] = {id=9848,name="Secrets of the Daggerfen",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="Bugs, bugs, bugs! The marsh is full of them and my companions here seem obsessed with them. Well, I've had it with the bugs! Something far more intriguing has captured my interest. To the west, there is a village of Lost Ones who call themselves the Daggerfen. The whole tribe consists of highly specialized assassins. I've noticed them mixing and using a particularly potent kind of poison. I'm dying to know more about the poison, but that's going to require a copy of the recipe and a sample vial.",starts={{npcID=18019,x=0.412,y=0.286,zoneID=3521}},ends={{npcID=18019,x=0.412,y=0.286,zoneID=3521}},coords={x=0.412,y=0.286,source="quest_giver",zoneID=3521},questType="standard"},
[9849] = {id=9849,name="Shattering the Veil",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Gordawg breaks off a piece of ebon rock from his back.> You are granted a piece of the fury of the earth. Take the boulder of Gordawg and hurl it at the poison rock. Shatter their shells to discover the truth. Destroy the minions of the usurper and return to Gordawg with the name. You find the shattered elements at the edge of the world. Southwest.",starts={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},ends={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},coords={x=0.612,y=0.222,source="quest_giver",zoneID=3518},questType="standard"},
[9850] = {id=9850,name="Clefthoof Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="You've proved to me that you can find and take down a regular clefthoof, but far more dangerous are the clefthoof bulls . Bag yourself twelve of those. Then you can talk to me of your hunting prowess. Look for them all along the middle region of Nagrand to the west and south.",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[9851] = {id=9851,name="Clefthoof Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Banthar is the fiercest and most elusive of all the clefthoof in Outland. She's also the hairiest. It is said that she roams with her clefthoof herd in the Spirit Fields near Oshu'gun. You want to truly prove your hunting mastery? Bring me her horn!",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[9852] = {id=9852,name="The Ultimate Bloodsport",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="The queen of all that dwell in Nagrand is known as Tusker. She's a giant elekk the likes of which you won't see anywhere else! You're right to be fearful of that name. Bach'lor, Gutripper, and Banthar are nothing when compared to her. It is said that she can be found on a huge bluff far to the southwest overlooking Oshu'gun. Bring me her massive heart if you dare. Do you want to leave a letter with me so that I can have it delivered to your next of kin in the likely event that you don't return?",starts={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.714,y=0.408,source="quest_giver",zoneID=3518},questType="standard"},
[9853] = {id=9853,name="Gurok the Usurper",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Gurok must be summoned. You summon Gurok and you destroy. You must go to Warmaul Hill to the northwest and find where ogre worships Gurok. You put ogre skull from Warmaul ogres on Gurok's earthen brand. Only then will Gurok come. Seven skulls. If you live, bring Gordawg back Gurok earthen head. Gordawg crushes head. Gordawg bites down hard, shaking the earth beneath your feet.>",starts={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},ends={{npcID=18099,x=0.612,y=0.222,zoneID=3518}},coords={x=0.612,y=0.222,source="quest_giver",zoneID=3518},questType="standard"},
[9854] = {id=9854,name="Windroc Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Do you live for the hunt as I do, ? Do you seek the quietude that comes as you stalk your prey? Would you know what it is to honor the last heartbeats of your fallen quarry? I will help you to achieve this. Nagrand is a lush land, full of life in the midst of this broken world. Bring down a handful of the windrocs and then we will speak more. You can find them in many places nearby in all directions around our camp.",starts={{npcID=18200,x=0.716,y=0.406,zoneID=3518}},ends={{npcID=18200,x=0.716,y=0.406,zoneID=3518}},coords={x=0.716,y=0.406,source="quest_giver",zoneID=3518},questType="standard"},
[9855] = {id=9855,name="Windroc Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="You must always push yourself if you are to one day stalk the mightiest of prey! While you are not yet ready, I will point you in the right direction. There is another breed of windroc even deadlier. Seek out the ravenous windroc to test your mettle against. You will find them in the heart of Nagrand to the west and southwest.",starts={{npcID=18200,x=0.716,y=0.406,zoneID=3518}},ends={{npcID=18200,x=0.716,y=0.406,zoneID=3518}},coords={x=0.716,y=0.406,source="quest_giver",zoneID=3518},questType="standard"},
[9856] = {id=9856,name="Windroc Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="You are ready, . Ready to face the mother of all windrocs, Gutripper! Honor demands that after hunting so many of her children that you give her the chance to defeat you! Seek her out amongst the greater windroc far to the west. Should you survive, bring her eye to me.",starts={{npcID=18200,x=0.716,y=0.406,zoneID=3518}},ends={{npcID=18200,x=0.716,y=0.406,zoneID=3518}},coords={x=0.716,y=0.406,source="quest_giver",zoneID=3518},questType="standard"},
[9857] = {id=9857,name="Talbuk Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="I don't think that I'm up to the hunt today. Do you think that you might take my place? I told Hemet that I was going to see about bagging us some of those talbuk that seem to be all over the place. The stags are especially nice to hunt. You can find them congregated around the nearby trees. Think that you could take care of that for me?",starts={{npcID=18218,x=0.714,y=0.406,zoneID=3518}},ends={{npcID=18218,x=0.714,y=0.406,zoneID=3518}},coords={x=0.714,y=0.406,source="quest_giver",zoneID=3518},questType="standard"},
[9858] = {id=9858,name="Talbuk Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="This darned scratch is getting the worst of me it would seem. So, are you up to filling... ... in for me again? This time you're going to bag yourself some thorngrazers. They're tougher and wilier than the stags, so keep your wits about you. Look for them... ... sheltered under the trees in the middle of Nagrand to the west and south. Go on, get out there and... ... show Hemet what you're made of. I'll be fine.",starts={{npcID=18218,x=0.714,y=0.406,zoneID=3518}},ends={{npcID=18218,x=0.714,y=0.406,zoneID=3518}},coords={x=0.714,y=0.406,source="quest_giver",zoneID=3518},questType="standard"},
[9859] = {id=9859,name="Talbuk Mastery",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Don't worry about... ... me. I'll be fine. It's just a... ... scratch. Just the same, I think you'll... ... have to fill in for me one more... ... time. You must seek out the great Bach'lor, king of... ... the stags. Bring me one of his hooves... , ... as confirmation. Look for him... ... leading his herd in the far west of Nagrand .",starts={{npcID=18218,x=0.714,y=0.406,zoneID=3518}},ends={{npcID=18218,x=0.714,y=0.406,zoneID=3518}},coords={x=0.714,y=0.406,source="quest_giver",zoneID=3518},questType="standard"},
[9861] = {id=9861,name="The Howling Wind",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="This amorphous mass of elemental air is speaking to you in a language that you cannot understand. You believe the language to be the tongue of the elements: Kalimag. Perhaps someone at the Throne of the Elements could shed some insight on this unusual find.",ends={{npcID=18074,x=0.604,y=0.224,zoneID=3518}},questType="standard"},
[9862] = {id=9862,name="Murkblood Corrupters",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Murkblood are capturing and torturing the spirits of air! Murkblood are my kin: A tribe of the Broken who serve the vile Musel'ek, beast lord of Coilfang. The air spirit states that the Murkblood putrefiers are capturing other spirits of air and using them to sow chaos into the ranks of the elements. It would seem that the Murkblood have recently sacked an orc village to the southwest known as Sunspring and are using powerful elemental magic to disturb the lake. Find the putrefiers and destroy them.",starts={{npcID=18074,x=0.604,y=0.224,zoneID=3518}},ends={{npcID=18074,x=0.604,y=0.224,zoneID=3518}},coords={x=0.604,y=0.224,source="quest_giver",zoneID=3518},questType="standard"},
[9863] = {id=9863,name="Vile Idolatry",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="With our leadership in ruin, we are left open to attacks from all sides. The foul Murkblood tribe could not have picked a better time to attack us! In recent days, we have been subject to no less than 5 assaults from the Broken. They have even taken over our only other territorial holding in the area: Sunspring Post. We must strike and show them that we are not powerless! Strike down the vile idolaters and bring me their twisted idols of worship so that they may ride the lightning.",starts={{npcID=18066,x=0.548,y=0.394,zoneID=3518}},ends={{npcID=18066,x=0.548,y=0.394,zoneID=3518}},coords={x=0.548,y=0.394,source="quest_giver",zoneID=3518},questType="standard"},
[9864] = {id=9864,name="The Missing War Party",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="After the last Murkblood raid, a group of younglings decided to act. We tried to stop them but the rage had taken hold. It has now been one week since we last saw our beloved younglings. Please, , you must find them! They have just barely reached adolescence. How can they expect to defeat such savages? They took the road leading west out of town. Follow that road around and look for signs of our younglings. And , avoid Halaa if you value your life. It is a war-zone.",starts={{npcID=18067,x=0.548,y=0.398,zoneID=3518}},ends={{npcID=18229,x=0.324,y=0.36,zoneID=3518}},coords={x=0.548,y=0.398,source="quest_giver",zoneID=3518},questType="standard"},
[9865] = {id=9865,name="Once Were Warriors",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="I do not know you, stranger, but I ask for your help. I feel shame for this, but I am only one orc. Emotions have surfaced that I have never felt. I... I seek vengeance. Blood for blood. Do your people ever feel this? I wish to pick up my axe and split my enemies in two. To swing the weapon until my arms fall lifelessly at my sides, exhausted. Sunspring Post is directly south of this procession. It is there that you will find our enemies... Kill them... Kill them all...",starts={{npcID=18229,x=0.324,y=0.36,zoneID=3518}},ends={{npcID=18229,x=0.324,y=0.36,zoneID=3518}},coords={x=0.324,y=0.36,source="quest_giver",zoneID=3518},questType="standard"},
[9866] = {id=9866,name="He Will Walk The Earth...",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Will you do me one last honor, ? I do not wish to return to Garadar. I believe that my destiny lies elsewhere - that I will serve a greater purpose someday. Please, return to Farseer Corhuk and tell him that I will not be returning. That I cannot return. I must walk the earth... He will understand.",starts={{npcID=18229,x=0.324,y=0.36,zoneID=3518}},ends={{npcID=18067,x=0.548,y=0.398,zoneID=3518}},coords={x=0.324,y=0.36,source="quest_giver",zoneID=3518},questType="standard"},
[9867] = {id=9867,name="Murkblood Leaders...",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="We have lost many friends in recent weeks. For decades we have dealt with the ogres of Nagrand but now a new threat has arisen. The Broken tribe of Murkblood attacked our fishing village to the southwest, Sunspring Post, and managed to kill or evict all of the orcs that inhabited the town. While the others feel that the best course of action is to kill indiscriminately, I know that we must destroy their leadership. I do not know who their leader is but I suspect that you will know when you find him.",starts={{npcID=18068,x=0.546,y=0.398,zoneID=3518}},ends={{npcID=18068,x=0.546,y=0.398,zoneID=3518}},coords={x=0.546,y=0.398,source="quest_giver",zoneID=3518},questType="standard"},
[9868] = {id=9868,name="The Totem of Kar'dash",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Thank you, stranger. They would have surely killed me had it not been for you. I was kidnapped by these Murkbloods 3 nights ago during a nighttime raid on Garadar. What I have since uncovered may very well shake the foundation of the Outland: these savages seek to recover the totem of Kar'dash! We cannot allow the totem to fall into the hands of the Murkbloods! You must help me escape. And stranger, if I do not make it back to Garadar, you must tell Garrosh what happened here...",starts={{npcID=18210,x=0.314,y=0.44,zoneID=3518}},ends={{npcID=18063,x=0.554,y=0.376,zoneID=3518}},coords={x=0.314,y=0.44,source="quest_giver",zoneID=3518},questType="standard"},
[9869] = {id=9869,name="The Throne of the Elements",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="Greetings, . I am Ioki, elementalist of the Earthen Ring. I have come to Telaar to inform the Kurenai of the state of the elements. Could I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand , beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Telaar safely? She will surely reward you for this small deed.",starts={{npcID=18233,x=0.554,y=0.688,zoneID=3518}},ends={{npcID=18072,x=0.606,y=0.222,zoneID=3518}},coords={x=0.554,y=0.688,source="quest_giver",zoneID=3518},questType="standard"},
[9870] = {id=9870,name="The Throne of the Elements",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Greetings, . I am Yal'hah, elementalist of the Earthen Ring. I have come to Garadar to inform the Mag'har of the state of the elements. Could I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand , beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Garadar safely? She will surely reward you for this small deed.",starts={{npcID=18234,x=0.556,y=0.378,zoneID=3518}},ends={{npcID=18072,x=0.606,y=0.222,zoneID=3518}},coords={x=0.556,y=0.378,source="quest_giver",zoneID=3518},questType="standard"},
[9871] = {id=9871,name="Murkblood Invaders",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="The parchment holds a crudely painted map of Nagrand . There is a big red 'X' where Telaar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Arechron in Telaar.",ends={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},questType="standard"},
[9872] = {id=9872,name="Murkblood Invaders",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="The parchment holds a crudely painted map of Nagrand . There is a big red 'X' where Garadar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Garrosh in Garadar.",ends={{npcID=18063,x=0.554,y=0.376,zoneID=3518}},questType="standard"},
[9873] = {id=9873,name="Ortor My Old Friend...",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="These invasion plans were written by someone I once knew. Ortor of Murkblood , once a noble Broken, versed in the way of the elements, now a muck addled yes-man of Musel'ek the bog lord. The plans state that they have taken over an orc village northwest of here known as Sunspring. Travel to Sunspring Post and rid the world of Ortor of Murkblood . What you do, you do for the good of us all...",starts={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},ends={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},coords={x=0.554,y=0.688,source="quest_giver",zoneID=3518},questType="standard"},
[9874] = {id=9874,name="Stopping the Spread",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="I have just gotten word of a catastrophe of epic proportions, . The foul Murkblood have sacked the orc village of Sunspring Post, northwest of here, and murdered its residents. To make matters worse, they have begun dumping the bodies into Sunspring Lake. Should those bodies rot, our primary source of water in the region will be compromised. It's a gruesome task that I give you next but it must be done. Take this enchanted torch and return to Sunspring. Burn all of the rotting orc corpses...",starts={{npcID=18222,x=0.544,y=0.72,zoneID=3518}},ends={{npcID=18222,x=0.544,y=0.72,zoneID=3518}},coords={x=0.544,y=0.72,source="quest_giver",zoneID=3518},questType="standard"},
[9875] = {id=9875,name="Uncatalogued Species",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Lauranna must've missed this particular plant. You're certain you've discovered a species not yet catalogued by Lauranna's work. You'd best show it to her to see what she makes of it.",ends={{npcID=17909,x=0.802,y=0.642,zoneID=3521}},questType="standard"},
[9878] = {id=9878,name="Solving the Problem",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="The appearance of the Murkblood in Nagrand has had a profound negative impact on our environment. The elementals are all in flux which has, in turn, greatly disturbed the wildlife. Worse yet, the razing of Sunspring Post has reignited the hatred that the orcs held for our people. While the Kurenai are a different tribe than the Murkblood, all an orc sees is Broken. We must make an effort to solve this dilemma. Travel to Sunspring Post, northwest of here, and resolve the Murkblood problem.",starts={{npcID=18224,x=0.544,y=0.722,zoneID=3518}},ends={{npcID=18224,x=0.544,y=0.722,zoneID=3518}},coords={x=0.544,y=0.722,source="quest_giver",zoneID=3518},questType="standard"},
[9879] = {id=9879,name="The Totem of Kar'dash",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="I would have been killed had you not come along, stranger. They have already murdered so many Kurenai in their search for a lost relic. What they seek is the totem of Kar'dash. Why they think that we would know anything about this totem, I cannot understand. Is a totem not an orcish implement by nature? This information must be taken back to Arechron . Perhaps he knows why Murkblood are kidnapping Kurenai and torturing them for information regarding an orcish device. Let's go before more come.",starts={{npcID=18209,x=0.33,y=0.422,zoneID=3518}},ends={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},coords={x=0.33,y=0.422,source="quest_giver",zoneID=3518},questType="standard"},
[9882] = {id=9882,name="Stealing from Thieves",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Nexus Prince Haramad has ordered us to not begin work inside of Oshu'gun as it might anger a certain powerful naaru. Sort of puts a damper on our operation. I think I might've found a loophole, however. You see, we're not the only ethereals drawn to this colossal diamond. A thief called Gava'xi has led a band of rogue ethereals into Oshu'gun and they've begun to dislodge large fragments from it. Your job, , is to go there and retrieve what is rightfully ours.",starts={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},ends={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},coords={x=0.314,y=0.576,source="quest_giver",zoneID=3518},questType="standard"},
[9883] = {id=9883,name="More Crystal Fragments",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,starts={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},ends={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},coords={x=0.314,y=0.576,source="quest_giver",zoneID=3518},questType="standard"},
[9884] = {id=9884,name="Membership Benefits",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,mapID=107,starts={{npcID=18265,x=0.314,y=0.576,mapID=107}},ends={{npcID=18265,x=0.314,y=0.576,mapID=107}},coords={x=0.314,y=0.576,source="quest_giver",mapID=107},questType="standard"},
[9885] = {id=9885,name="Membership Benefits",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,mapID=107,starts={{npcID=18265,x=0.314,y=0.576,mapID=107}},ends={{npcID=18265,x=0.314,y=0.576,mapID=107}},coords={x=0.314,y=0.576,source="quest_giver",mapID=107},questType="standard"},
[9886] = {id=9886,name="Membership Benefits",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,mapID=107,starts={{npcID=18265,x=0.314,y=0.576,mapID=107}},ends={{npcID=18265,x=0.314,y=0.576,mapID=107}},coords={x=0.314,y=0.576,source="quest_giver",mapID=107},questType="standard"},
[9887] = {id=9887,name="Membership Benefits",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,mapID=107,starts={{npcID=18265,x=0.314,y=0.576,mapID=107}},ends={{npcID=18265,x=0.314,y=0.576,mapID=107}},coords={x=0.314,y=0.576,source="quest_giver",mapID=107},questType="standard"},
[9888] = {id=9888,name="The Impotent Leader",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="I have escaped certain death, surviving a cowardly nighttime attack by Boulderfist ogres upon my village. But I ask you, stranger: For what? He has refused to give us assistance. Ogres are rampaging through my town and he sits here, weeping into a fire. What has become of us? What will become of us? I've sent a scout, Kilrath , to the village, now the Bleeding Hollow Ruins. Will you find him and give him your assistance? He hides on the border of Nagrand and Terokkar.",starts={{npcID=18106,x=0.556,y=0.376,zoneID=3518}},ends={{npcID=18273,x=0.196,y=0.608,zoneID=3519}},coords={x=0.556,y=0.376,source="quest_giver",zoneID=3518},questType="standard"},
[9889] = {id=9889,name="Don't Kill the Fat One",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="I have been watching these beasts for days. The fat one says that he is waiting for something. What he is waiting for, however, is a mystery. I have a plan but it is going to involve some violence on your part. You will need to kill several of his subordinates and then beat him within an inch of his life. Do this and I am certain he will tell us everything that we need to know.",starts={{npcID=18273,x=0.196,y=0.608,zoneID=3519}},ends={{npcID=18262,x=0.2,y=0.634,zoneID=3519}},coords={x=0.196,y=0.608,source="quest_giver",zoneID=3519},questType="standard"},
[9890] = {id=9890,name="Success!",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="For many years, Boulderfist ruled all ogres in the Outland. The ogres were united under Krol and content with the lands that they were given. In the past few months, we have lost many ogres to a new clan known as Warmaul. Warmaul has taken most of our land in Nagrand and killed many of our people. We had no choice but to take this town. We are being exterminated... Krol has gone missing and Boulderfist is in turmoil. Lantresor of the Blade rules in his absence.",starts={{npcID=18262,x=0.2,y=0.634,zoneID=3519}},ends={{npcID=18273,x=0.196,y=0.608,zoneID=3519}},coords={x=0.2,y=0.634,source="quest_giver",zoneID=3519},questType="standard"},
[9891] = {id=9891,name="Because Kilrath is a Coward",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Take what you have learned and tell Jorin at Garadar. I can assure you that he won't be happy to know that our village was destroyed and many of our people killed because the ogres needed more space. May the ancestors watch over you... I will be hiding in the bushes if you need me for anything else.",starts={{npcID=18273,x=0.196,y=0.608,zoneID=3519}},ends={{npcID=18106,x=0.556,y=0.376,zoneID=3518}},coords={x=0.196,y=0.608,source="quest_giver",zoneID=3519},questType="standard"},
[9892] = {id=9892,name="More Obsidian Warbeads",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,starts={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},ends={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},coords={x=0.314,y=0.576,source="quest_giver",zoneID=3518},questType="standard"},
[9893] = {id=9893,name="Obsidian Warbeads",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="All this waiting around for Oshu'gun to be ready for digging is eating into our profits, . Fortunately, I've devised an alternate source of income. The ogres of Nagrand wear warbeads made of obsidian, a mineral that commands a hefty price in many other worlds. Zerid already has had to take care a few of the brutes as a matter of security. Think of the warbeads as an added bonus. Or better yet, don't think about it too much and just bring them to me.",starts={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},ends={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},coords={x=0.314,y=0.576,source="quest_giver",zoneID=3518},questType="standard"},
[9894] = {id=9894,name="Safeguarding the Watchers",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="In your travels, you might have encountered some of the expedition's watchers. They do the majority of the field work: documenting the unique inhabitants of the marsh, collecting samples, and making contact with sentient species. The safety of the watchers is paramount, . We've had to recall the watchers we sent to explore Funggor Cavern to the south, because of marshbeast attacks. Warden Hamoot believes that killing their leader, Lord Klaq , will bring a swift end to the attacks.",starts={{npcID=18070,x=0.804,y=0.646,zoneID=3521}},ends={{npcID=18070,x=0.804,y=0.646,zoneID=3521}},coords={x=0.804,y=0.646,source="quest_giver",zoneID=3521},questType="standard"},
[9895] = {id=9895,name="The Dying Balance",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Have you observed your surroundings closely, ? This is an ailing landscape, struggling to keep itself in balance and losing the fight. If you know where to look, you can see the symptoms. Members of some species rapidly outgrow their peers and become more aggressive. A good example of this uncontrolled growth is the marshtrekker Boglash . If you wish to see it for yourself, look no further than the waterways south of the refuge. Be prepared to defend yourself. The creature knows no mercy.",starts={{npcID=17834,x=0.786,y=0.63,zoneID=3521}},ends={{npcID=17834,x=0.786,y=0.63,zoneID=3521}},coords={x=0.786,y=0.63,source="quest_giver",zoneID=3521},questType="standard"},
[9896] = {id=9896,name="Blacksting's Bane",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="By Khaz'goroth's flaming navel, it's hot here! I can't blame the first party for leaving, but everyone knows 'twasn't the heat that drove them away. No, it was Blacksting, although they won't admit it. They were camped just to the south of the glowing draenei towers to the west, just north of the Feralfen Village, when the giant wasp appears out of nowhere and attacks! I can't wait to see the looks on their faces when I bring the creature's stinger back to Ironforge and show it to them!",starts={{npcID=18295,x=0.684,y=0.494,zoneID=3521}},ends={{npcID=18295,x=0.684,y=0.494,zoneID=3521}},coords={x=0.684,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9898] = {id=9898,name="The Respect of Another",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Magasha is the fiercest troll in the Marsh, but she only respects mighty hunters. I tried to prove myself to her, but the one beast that could impress her is beyond my skill. Maybe you could help me out? It's the giant bog wasp known as Blacksting that roams the area south of the glowing draenei towers to the west. If you bring me its stinger maybe she'll give me a chance to join her hunters. I know it's a little sneaky, but I promise to learn under her and do ya both proud.",starts={{npcID=18012,x=0.85,y=0.54,zoneID=3521}},ends={{npcID=18012,x=0.85,y=0.54,zoneID=3521}},coords={x=0.85,y=0.54,source="quest_giver",zoneID=3521},questType="standard"},
[9899] = {id=9899,name="A Job Undone",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Someone needs to find a way to make Reavij come to his senses! He's ignoring his duty and instead, he's devoting all his energy to getting my attention. I've tried ignoring him and telling him to stop. Nothing seems to work. Until he gets over this, I'm left cleaning up after him. He was supposed to have dealt with Sporewing , but I'll bet the monster is alive and well. If you have time, would you mind going to the western part of the Dead Mire and killing the bat? I'll deal with Reavij in the meantime.",starts={{npcID=18016,x=0.844,y=0.544,zoneID=3521}},ends={{npcID=18016,x=0.844,y=0.544,zoneID=3521}},coords={x=0.844,y=0.544,source="quest_giver",zoneID=3521},questType="standard"},
[9900] = {id=9900,name="Gava'xi",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="The presence of rogue ethereals in this area might amuse Gezhe, who sees nothing but opportunity wherever we go, but it's a true threat to the security of our operations. Their leader, Gava'xi , is a dangerous criminal and I've made it my top priority to see to it that he is neutralized. If you're looking to make yourself useful, go and take care of Gava'xi . I will see to it that you're rewarded properly.",starts={{npcID=18276,x=0.308,y=0.58,zoneID=3518}},ends={{npcID=18276,x=0.308,y=0.58,zoneID=3518}},coords={x=0.308,y=0.58,source="quest_giver",zoneID=3518},questType="standard"},
[9901] = {id=9901,name="Unfinished Business",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="The first expedition the league sent reported encountering a gigantic spore bat they'd taken to calling Sporewing . They had to leave in a hurry, so they didn't have the chance to kill him while they were here, so I figured I'd finish the job for them. What's left of their report suggests that the creature can be found in the southwestern parts of the Dead Mire. I think Vindicator Idaar mentioned that it's to the northeast of Telredor.",starts={{npcID=18295,x=0.684,y=0.494,zoneID=3521}},ends={{npcID=18295,x=0.684,y=0.494,zoneID=3521}},coords={x=0.684,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[9902] = {id=9902,name="The Terror of Marshlight Lake",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="Traveling through naga-infested lands has shown me the cruel truth about how my less fortunate brethren are treated. At Marshlight Lake, to the southwest, I observed a particularly malicious taskmaster playing a deadly game. He orders his slaves out to the islands in Marshlight Lake when he knows that Terrorclaw , a giant bogstrok, is ready to feed. I needn't describe what results. We are too few to take on the naga directly, but we can deprive them of their amusement by killing their pet.",starts={{npcID=18009,x=0.408,y=0.286,zoneID=3521}},ends={{npcID=18009,x=0.408,y=0.286,zoneID=3521}},coords={x=0.408,y=0.286,source="quest_giver",zoneID=3521},questType="standard"},
[9903] = {id=9903,name="The Biggest of Them All",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="You've dealt with most of the little hydra, but I doubt Mragesh was impressed by your display. He's a cunning, ferocious beast and he's dogged many an angler in his time. I intend to be the last one he'll ever bother. He's bound to be hiding deep in the waters of Serpent Lake, to the northeast. He's a has-been; he just doesn't know it yet.",starts={{npcID=18018,x=0.322,y=0.496,zoneID=3521}},ends={{npcID=18018,x=0.322,y=0.496,zoneID=3521}},coords={x=0.322,y=0.496,source="quest_giver",zoneID=3521},questType="standard"},
[9904] = {id=9904,name="Pursuing Terrorclaw",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="I've caught every kind of fish that lives in the marsh, but there's one that eludes me. Sure, I've caught eels and mudfin frenzies. But the last time I was out on one of the islands in Marshlight Lake, I hooked a gigantic bogstrok that snapped my line and got away. Terrorclaw , he's called, and I won't rest until he's dead. He's too big for any fisherman to catch, so I suppose we'll just have to kill him the old-fashioned way.",starts={{npcID=18018,x=0.322,y=0.496,zoneID=3521}},ends={{npcID=18018,x=0.322,y=0.496,zoneID=3521}},coords={x=0.322,y=0.496,source="quest_giver",zoneID=3521},questType="standard"},
[9905] = {id=9905,name="Maktu's Revenge",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="Last time Maktu was out hunting hydras for hides at Serpent Lake, he was attacked by the biggest hydra he's ever seen. Maktu reached for his spear, but it was too late. He had just enough time to escape becoming hydra food. Who knows? Maybe next time, Maktu not be so lucky. Maktu wants to be there so there won't be a next time. Will you help Maktu get his revenge on Mragesh ?",starts={{npcID=18010,x=0.416,y=0.274,zoneID=3521}},ends={{npcID=18010,x=0.416,y=0.274,zoneID=3521}},coords={x=0.416,y=0.274,source="quest_giver",zoneID=3521},questType="standard"},
[9906] = {id=9906,name="Message in a Battle",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Ogres are moved by one thing: Might. If we expose ourselves to them as being weak, they will take advantage of that weakness and wipe us out. Garrosh might be ready to lie down and let the ogre dogs take our lands but I am not! I need you to deliver a message to the Boulderfist, . The only type of message that they are capable of understanding: Brutality. Travel to the Burning Blade Ruins, southeast of here and show them the might of the Mag'har. And , check in with the others before leaving.",starts={{npcID=18106,x=0.556,y=0.376,zoneID=3518}},ends={{npcID=18106,x=0.556,y=0.376,zoneID=3518}},coords={x=0.556,y=0.376,source="quest_giver",zoneID=3518},questType="standard"},
[9907] = {id=9907,name="An Audacious Advance",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Directly west of here you will find the Halaani Basin. Within the basin are the twin clefts of Nagrand : Northwind and Southwind. Boulderfist shock troops use the clefts to hide their ogre mounds. I need you to track down those troops and kill all that you encounter in the name of Mag'har.",starts={{npcID=18106,x=0.556,y=0.376,zoneID=3518}},ends={{npcID=18106,x=0.556,y=0.376,zoneID=3518}},coords={x=0.556,y=0.376,source="quest_giver",zoneID=3518},questType="standard"},
[9910] = {id=9910,name="Standards and Practices",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="If you're venturing into the Burning Blade Ruins, I have a task for you. Take these Mag'har battle standards and place them at three distinct locations in the ogre compound. An area of high visibility is recommended. Look for the gigantic flaming pyres on the upper levels. Place a standard near the first, second, and third Burning Blade pyres. The standard will leave a lasting impression upon any ogres who may have missed the battle.",starts={{npcID=18300,x=0.556,y=0.376,zoneID=3518}},ends={{npcID=18300,x=0.556,y=0.376,zoneID=3518}},coords={x=0.556,y=0.376,source="quest_giver",zoneID=3518},questType="standard"},
[9911] = {id=9911,name="The Count of the Marshes",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="This bloody mandible comes from an unbelievably large creature. The nether ray that it belonged to has to be the largest ever seen in Zangarmarsh . Judging from the condition of the mandible, the count must've abandoned a diet of carrion in favor of living flesh. Surely the Cenarion Expedition would be interested in such a specimen. Watcher Leesa'oh has a small camp to the west of Quagg Ridge.",ends={{npcID=17831,x=0.232,y=0.662,zoneID=3521}},questType="standard"},
[9912] = {id=9912,name="The Cenarion Expedition",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition. Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body. The expedition's leader, Ysiel Windsinger , has asked us to direct volunteers to her outpost. Report to her at the Cenarion Refuge in eastern Zangarmarsh . Take the main path to the west and it will lead you directly there.",starts={{npcID=16885,x=0.16,y=0.522,zoneID=3483}},ends={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},coords={x=0.16,y=0.522,source="quest_giver",zoneID=3483},questType="standard"},
[9913] = {id=9913,name="The Consortium Needs You!",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="My organization, the Consortium, is looking for a few resourceful individuals just like yourself. You'll be hard pressed to find ethereals more honest, hard-working or pleasant to be around than us. All we require is loyalty, dedication and a reasonable amount of moral flexibility. If you're interested, speak to Gezhe , our ground operations leader. You will find him at Aeris Landing, north of Oshu'gun.",starts={{npcID=18335,x=0.518,y=0.346,zoneID=3518}},ends={{npcID=18265,x=0.314,y=0.576,zoneID=3518}},coords={x=0.518,y=0.346,source="quest_giver",zoneID=3518},questType="standard"},
[9914] = {id=9914,name="A Head Full of Ivory",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Ivory is a much sought after prize. I have many customers lined up in far off places to purchase it. I could be convinced to let you in on a cut of the profits. The wild elekk roaming Nagrand have the high quality of tusks that I'm after. Steer clear of the bull elekk; their ivory isn't in the condition that I desire. Oh and don't worry, it's not poaching; I have an understanding with both the orcs and the draenei. Do you and I have an understanding?",starts={{npcID=18333,x=0.316,y=0.568,zoneID=3518}},ends={{npcID=18333,x=0.316,y=0.568,zoneID=3518}},coords={x=0.316,y=0.568,source="quest_giver",zoneID=3518},questType="standard"},
[9915] = {id=9915,name="More Heads Full of Ivory",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,starts={{npcID=18333,x=0.316,y=0.568,zoneID=3518}},ends={{npcID=18333,x=0.316,y=0.568,zoneID=3518}},coords={x=0.316,y=0.568,source="quest_giver",zoneID=3518},questType="standard"},
[9916] = {id=9916,name="Bleeding Hollow Supply Crates",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="The Boulderfist have moved the supplies they stole from our village to the twin clefts of Nagrand , found west of here in the Halaani Basin. While you are in the area, keep your eye out for the supply crates. If we can get those back, it would ease much of the burden that has fallen upon the matrons of Garadar.",starts={{npcID=18300,x=0.556,y=0.376,zoneID=3518}},ends={{npcID=18300,x=0.556,y=0.376,zoneID=3518}},coords={x=0.556,y=0.376,source="quest_giver",zoneID=3518},questType="standard"},
[9917] = {id=9917,name="Do My Eyes Deceive Me",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="Do my eyes deceive me or is there an ogre hunting party over yonder? What could ogres be doing this far from their mound? I don't like this one bit, stranger. First Murkbloods and now ogres. We just don't have the manpower to handle all of these threats to our land. Could you investigate the ogre presence to the east for us? Their forward camp is about 200 paces east of here. You'll know you're at the right place if you see the Boulderfist hunters. Kill them to find the plans!",starts={{npcID=18353,x=0.55,y=0.706,zoneID=3518}},ends={{npcID=18353,x=0.55,y=0.706,zoneID=3518}},coords={x=0.55,y=0.706,source="quest_giver",zoneID=3518},questType="standard"},
[9918] = {id=9918,name="Not On My Watch!",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="The battle plans were written up by an ogre lieutenant. His name is either Dump or Lump. It could also be Billy. Anyhow, I think you should go back out there and have a word with Billy or Lump or Dumpy or whatever! Try to approach him diplomatically. If that doesn't work, try using some muscle.",starts={{npcID=18353,x=0.55,y=0.706,zoneID=3518}},ends={{npcID=18353,x=0.55,y=0.706,zoneID=3518}},coords={x=0.55,y=0.706,source="quest_giver",zoneID=3518},questType="standard"},
[9919] = {id=9919,name="Sporeggar",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="You're a kind , . Not like some of the others I've met. You should meet the rest of my people; they'll be very grateful for your help. Take these spore sacs to my leader, Msshi'fn . You will find him in Sporeggar, north of here.",starts={{npcID=17923,x=0.19,y=0.626,zoneID=3521}},ends={{npcID=17924,x=0.196,y=0.52,zoneID=3521}},coords={x=0.19,y=0.626,source="quest_giver",zoneID=3521},questType="standard"},
[9920] = {id=9920,name="Mo'mor the Breaker",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="You must seek out Mo'mor immediately! You will find him in the center of Telaar, by the fountain. Tell him exactly what the ogre told you.",starts={{npcID=18353,x=0.55,y=0.706,zoneID=3518}},ends={{npcID=18223,x=0.546,y=0.722,zoneID=3518}},coords={x=0.55,y=0.706,source="quest_giver",zoneID=3518},questType="standard"},
[9921] = {id=9921,name="The Ruins of Burning Blade",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="These ogre hunting parties are a precursor to invasion. We must strike at them before they have a chance to amass an army big enough to take over our town. You're going to need to get your hands dirty, . The largest collection of Boulderfist in this region can be found at the Burning Blade Ruins, almost directly east of Telaar, near the border of Terokkar. Go there and show the Boulderfist that Telaar will not bend to their will!",starts={{npcID=18223,x=0.546,y=0.722,zoneID=3518}},ends={{npcID=18223,x=0.546,y=0.722,zoneID=3518}},coords={x=0.546,y=0.722,source="quest_giver",zoneID=3518},questType="standard"},
[9922] = {id=9922,name="The Twin Clefts of Nagrand",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="You made a strong showing, . Are you ready for more? I have received reports of a large contingent of Boulderfist ogres hidden in the twin clefts of Nagrand , northwest of here in the Halaani Basin. Venture forth to the clefts and deal with the remaining Boulderfist ogres.",starts={{npcID=18223,x=0.546,y=0.722,zoneID=3518}},ends={{npcID=18223,x=0.546,y=0.722,zoneID=3518}},coords={x=0.546,y=0.722,source="quest_giver",zoneID=3518},questType="standard"},
[9923] = {id=9923,name="HELP!",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="HELP! They're gonna eat me! I just know it! Find the key, I know it has to be on one of these ogres. If you get me out of here, my father will reward you handsomely! He's the leader of Telaar, Arechron .",starts={{npcID=18369,x=0.726,y=0.706,zoneID=3518}},ends={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},coords={x=0.726,y=0.706,source="quest_giver",zoneID=3518},questType="standard"},
[9924] = {id=9924,name="Corki's Gone Missing Again!",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="Arechron sighs.> This is so embarrassing. Do you remember my boy, Corki ? You rescued him from the Burning Blade Ruins recently. Well, his curiosity has gotten the best of him once more. He told me that he was going to investigate the Boulderfist menace for 'uncle' Mo'mor and ran off to the ogre mounds in the Halaani Basin, north of here. Do you think you could track him down? I would be eternally grateful.",starts={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},ends={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},coords={x=0.554,y=0.688,source="quest_giver",zoneID=3518},questType="standard"},
[9925] = {id=9925,name="Matters of Security",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Gezhe chose to base our operations as close to Oshu'gun as possible, without any regard for the safety of our crew. Why? Because he projected a ten percent increase in productivity by setting up shop here instead of in the mountains to the south. Never mind the crazed voidspawn wandering all of ten feet away from us. That would be the security officer's problem, not Gezhe's. Kill some voidspawn for me and I'll pay you a tenth of our security budget. Don't get excited, it's not much of a budget.",starts={{npcID=18276,x=0.308,y=0.58,zoneID=3518}},ends={{npcID=18276,x=0.308,y=0.58,zoneID=3518}},coords={x=0.308,y=0.58,source="quest_giver",zoneID=3518},questType="standard"},
[9927] = {id=9927,name="Ruthless Cunning",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="These are Warmaul ogre banners that I recently acquired. I want you to travel to Kil'sorrow Fortress, directly south of here, and kill as many of the Kil'sorrow filth as you can find. Drive a Warmaul ogre banner through the heart of each fallen Kil'sorrow soldier. Return to me when you have completed this task and the other that this plan requires.",starts={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},ends={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},coords={x=0.738,y=0.626,source="quest_giver",zoneID=3518},questType="standard"},
[9928] = {id=9928,name="Armaments for Deception",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="You will need to steal Kil'sorrow armaments from Kil'sorrow Fortress if my plan is to work. Search the fortress for crates of Kil'sorrow armaments . Bring whatever you can find to me. Kil'sorrow Fortress is located directly south and a little to the west of the Burning Blade Ruins.",starts={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},ends={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},coords={x=0.738,y=0.626,source="quest_giver",zoneID=3518},questType="standard"},
[9931] = {id=9931,name="Returning the Favor",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Now you must plant the seed of war in the fat, useless heads of the Warmaul. To the northwest, near the mountains, you will find the Laughing Skull Ruins. Do you recognize those banners? They are Kil'sorrow banners . I want you to take a stack of Kil'sorrow banners and plant them on the corpses of Warmaul ogres. Remember, northwest is where you will find the ogres.",starts={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},ends={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},coords={x=0.738,y=0.626,source="quest_giver",zoneID=3518},questType="standard"},
[9932] = {id=9932,name="Body of Evidence",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Your rampage through Kil'sorrow Fortress has provided us with a special opportunity. We have enough bodies to make it appear as if a great battle has taken place. Travel to the Laughing Skull Ruins and find the Laughing Skull Courtyard. There should be a blazing pyre in the courtyard. Make sure the area is secure and then use this blanket to send up smoke signals. When my ogres see the smoke, they will sneak in and plant the bodies of slain Kil'sorrow soldiers. That should be the final straw!",starts={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},ends={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},coords={x=0.738,y=0.626,source="quest_giver",zoneID=3518},questType="standard"},
[9933] = {id=9933,name="Message to Telaar",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="Take it. It is my offering to your people. You have single-handedly saved my clan from extermination. You may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.",starts={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},ends={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},coords={x=0.738,y=0.626,source="quest_giver",zoneID=3518},questType="standard"},
[9934] = {id=9934,name="Message to Garadar",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Take it. It is my offering to your people. You have single-handedly saved my clan from extermination. You may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.",starts={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},ends={{npcID=18063,x=0.554,y=0.376,zoneID=3518}},coords={x=0.738,y=0.626,source="quest_giver",zoneID=3518},questType="standard"},
[9935] = {id=9935,name="WANTED: Giselda the Crone",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Wanted: Dead or Alive Giselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary. Known to congregate at Kil'sorrow Fortress in southeastern Nagrand , near the border of Terokkar. Large gold reward to be dispensed by Warden Bullrok at Garadar to anyone able to bring Giselda to justice.",starts={{npcID=182392,x=0.557,y=0.38,zoneID=3518}},ends={{npcID=18407,x=0.558,y=0.378,zoneID=3518}},coords={x=0.557,y=0.38,source="quest_giver",zoneID=3518},questType="standard"},
[9936] = {id=9936,name="WANTED: Giselda the Crone",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="Wanted: Dead or Alive Giselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary. Known to congregate at Kil'sorrow Fortress in southeastern Nagrand , near the border of Terokkar. Large gold reward to be dispensed by Warden Moi'bff Jill at Telaar to anyone able to bring Giselda to justice.",starts={{npcID=182393,x=0.547,y=0.708,zoneID=3518}},ends={{npcID=18408,x=0.548,y=0.708,zoneID=3518}},coords={x=0.547,y=0.708,source="quest_giver",zoneID=3518},questType="standard"},
[9937] = {id=9937,name="WANTED: Durn the Hungerer",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="You have destroyed two of the biggest threats in Nagrand , . Are you ready to take on the scourge of the Spirit Fields? Durn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, far southwest of here, near Oshu'gun, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.",starts={{npcID=18407,x=0.558,y=0.378,zoneID=3518}},ends={{npcID=18407,x=0.558,y=0.378,zoneID=3518}},coords={x=0.558,y=0.378,source="quest_giver",zoneID=3518},questType="standard"},
[9938] = {id=9938,name="WANTED: Durn the Hungerer",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="You have destroyed two of the biggest threats in Nagrand , . Are you ready to take on the scourge of the Spirit Fields? Durn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, west of here, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.",starts={{npcID=18408,x=0.548,y=0.708,zoneID=3518}},ends={{npcID=18408,x=0.548,y=0.708,zoneID=3518}},coords={x=0.548,y=0.708,source="quest_giver",zoneID=3518},questType="standard"},
[9939] = {id=9939,name="WANTED: Zorbo the Advisor",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Wanted: Dead or Alive Zorbo the Advisor , wanted for numerous planned attacks on Garadar. Along with his reavers and shaman, Zorbo has slain countless orcs. Consider Zorbo as armed, dangerous, and merciless. Zorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand . Reward for Zorbo the Advisor 's death or capture to be dispensed by Warden Bullrok at Garadar.",starts={{npcID=182392,x=0.557,y=0.38,zoneID=3518}},ends={{npcID=18407,x=0.558,y=0.378,zoneID=3518}},coords={x=0.557,y=0.38,source="quest_giver",zoneID=3518},questType="standard"},
[9940] = {id=9940,name="WANTED: Zorbo the Advisor",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="Wanted: Dead or Alive Zorbo the Advisor , wanted for numerous planned attacks on Telaar. Along with his reavers and shaman, Zorbo has slain countless Broken. Consider Zorbo as armed, dangerous, and merciless. Zorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand . Reward for Zorbo the Advisor 's death or capture to be dispensed by Warden Moi'bff Jill at Telaar.",starts={{npcID=182393,x=0.547,y=0.708,zoneID=3518}},ends={{npcID=18408,x=0.548,y=0.708,zoneID=3518}},coords={x=0.547,y=0.708,source="quest_giver",zoneID=3518},questType="standard"},
[9944] = {id=9944,name="Missing Mag'hari Procession",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Greatmother says that we must press on and serve our people. She says that we must serve as an example for Garrosh - to show that life goes on. I have so many matters to attend to here, especially with Greatmother having taken ill. Would you honor the Mag'har by helping one of their matrons? Several days ago we sent a funeral procession to the Ancestral Grounds and they have yet to return. Will you go search for them? They took the western road out of Garadar. Follow it around and avoid Halaa.",starts={{npcID=18302,x=0.566,y=0.342,zoneID=3518}},ends={{npcID=18414,x=0.322,y=0.362,zoneID=3518}},coords={x=0.566,y=0.342,source="quest_giver",zoneID=3518},questType="standard"},
[9945] = {id=9945,name="War on the Warmaul",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="We were en route to the Ancestral Grounds when we were ambushed by Warmaul. They came from all sides, killing several of the procession guards and many of the others. They even desecrated the remains of the elder in the wagon. And for what? So they could humiliate us and display their power. Not even Boulderfist would have sunk so low. I am a spiritual orc, , but even I have limitations. Find the attackers at Warmaul Hill to the northwest and destroy them!",starts={{npcID=18414,x=0.322,y=0.362,zoneID=3518}},ends={{npcID=18414,x=0.322,y=0.362,zoneID=3518}},coords={x=0.322,y=0.362,source="quest_giver",zoneID=3518},questType="standard"},
[9946] = {id=9946,name="Cho'war the Pillager",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Have you ever seen an ogre king, ? Few have and lived to tell the tale. Unfortunately, that is exactly what we are dealing with here. The leader of these barbarians is an ogre named Cho'war. Rumor has it that Cho'war was the ogre responsible for forcing the gronn out of the cave. Cho'war then declared himself king and dissolved the ogre clans that served under the gronn. Thus, Warmaul was born. Find Cho'war deep in the caves of Warmaul Hill. Slay him and bring me his head.",starts={{npcID=18414,x=0.322,y=0.362,zoneID=3518}},ends={{npcID=18414,x=0.322,y=0.362,zoneID=3518}},coords={x=0.322,y=0.362,source="quest_giver",zoneID=3518},questType="standard"},
[9948] = {id=9948,name="Finding the Survivors",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="If I know anything about ogres, it's that they like their food fresh. This means that the Mag'har that they captured are more than likely being kept alive until they are ready to serve. It's a sickening thought, I know, but one that we must use to our advantage. Venture to Warmaul Hill and search for Mag'har prisoners . If you find prisoners, then you will find keys to their cages on the nearby Warmaul ogres. Kill ogres for their keys and release the prisoners.",starts={{npcID=18415,x=0.322,y=0.362,zoneID=3518}},ends={{npcID=18415,x=0.322,y=0.362,zoneID=3518}},coords={x=0.322,y=0.362,source="quest_giver",zoneID=3518},questType="standard"},
[9951] = {id=9951,name="It's Watching You!",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Quick, hide! The eyes of Naphthal'ar are upon you... upon us all! I dare not go to the top of the tower to speak with it, but you... you look as if you might know the right words to say. Just be careful, it doesn't like jokes and will not suffer fools easily. If you can, convince it to come down for tea. But, by all means, get it to stop staring at me!",starts={{npcID=18424,x=0.434,y=0.224,zoneID=3519}},ends={{npcID=18424,x=0.434,y=0.224,zoneID=3519}},coords={x=0.434,y=0.224,source="quest_giver",zoneID=3519},questType="standard"},
[9954] = {id=9954,name="Corki's Ransom",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="Arechron shows you a grime covered letter.> I just received this letter. It's from a clan of ogres known as Warmaul that rule the northwestern lands of Nagrand . It says that they have Corki and if we don't cooperate, they're going to eat him. Admittedly, Corki is a moron, but he's still my blood. Will you rescue him, ? I presume that he's locked up in a cage somewhere on Warmaul Hill. That should be your first stop.",starts={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},ends={{npcID=18445,x=0.294,y=0.26,zoneID=3518}},coords={x=0.554,y=0.688,source="quest_giver",zoneID=3518},questType="standard"},
[9955] = {id=9955,name="Cho'war the Pillager",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="They call him Cho'war the Pillager, . He's the ogre that forced out the gronn that used to rule over these ogres. You better believe he's powerful! The chef said that Cho'war lives in the big cave - wherever that may be... Get that key and get me out of here! If we live through this, my father will no doubt give you the big reward! As soon as I'm free, seek him out.",starts={{npcID=18445,x=0.294,y=0.26,zoneID=3518}},ends={{npcID=18183,x=0.554,y=0.688,zoneID=3518}},coords={x=0.294,y=0.26,source="quest_giver",zoneID=3518},questType="standard"},
[9956] = {id=9956,name="The Ravaged Caravan",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="I was part of a caravan taking supplies to the Orebor Harborage in Zangarmarsh. As we were nearing the border of the marsh, we were jumped by a vicious squad of Warmaul ogres. They killed the others and took me prisoner, along with all of our supplies. Thankfully, they neglected to place a backing on my cage. When they fell asleep, I made my escape. It's too late for my comrades but we could really use the supplies they stole. Warmaul Hill is in the northwestern mountains of Nagrand .",starts={{npcID=18416,x=0.548,y=0.706,zoneID=3518}},ends={{npcID=18416,x=0.548,y=0.706,zoneID=3518}},coords={x=0.548,y=0.706,source="quest_giver",zoneID=3518},questType="standard"},
[9957] = {id=9957,name="What's Wrong at Cenarion Thicket?",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="We haven't heard from the druids at the Cenarion Thicket of Terokkar Forest in quite some time. , I'd like for you to go down there and check in with them to see what's happening. There are several ways to get there, but the fastest is to head south along the path, and then take the road that branches east from Shattrath City once you're in the forest.",starts={{npcID=17834,x=0.786,y=0.63,zoneID=3521}},ends={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},coords={x=0.786,y=0.63,source="quest_giver",zoneID=3521},questType="standard"},
[9960] = {id=9960,name="What's Wrong at Cenarion Thicket?",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="Hey there, . We haven't heard from the druids of the Cenarion Thicket in quite some time. I want you to go over there and check to see what's happening. You can find it by heading northwest through the forest.",starts={{npcID=18447,x=0.5,y=0.458,zoneID=3519}},ends={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},coords={x=0.5,y=0.458,source="quest_giver",zoneID=3519},questType="standard"},
[9961] = {id=9961,name="What's Wrong at Cenarion Thicket?",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description=", I have urgent business for you. We haven't heard from the druids of the Cenarion Thicket in quite some time. This is unusual as we usually hear from them at least once every few days. I want you to go up there and make sure that they're alright. You can find the thicket by heading northwest through the forest.",starts={{npcID=18459,x=0.57,y=0.536,zoneID=3519}},ends={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},coords={x=0.57,y=0.536,source="quest_giver",zoneID=3519},questType="standard"},
[9962] = {id=9962,name="The Ring of Blood: Brokentoe",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="So are you ready for your first battle? If you are, let me know and I'll get things started. All you have to do is go wait in the Ring of Blood for your opponent to arrive. This fight is against Brokentoe, a ferocious clefthoof. Good luck! I hope you brought friends. And remember, the fight's over when either you or your opponent are lying face down on the arena floor.",starts={{npcID=18471,x=0.428,y=0.206,zoneID=3518}},ends={{npcID=22893,x=0.428,y=0.206,zoneID=3518}},coords={x=0.428,y=0.206,source="quest_giver",zoneID=3518},questType="group"},
[9967] = {id=9967,name="The Ring of Blood: The Blue Brothers",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="This next battle involves a duo - twin brothers to be precise. They call themselves the \"Blue Brothers.\" It's not too late to chicken out, . I'd certainly understand. But if you're ready for some action, step in the Ring of Blood and wait for the Murkblood twins to arrive. Last one standing is the winner!",starts={{npcID=18471,x=0.428,y=0.206,zoneID=3518}},ends={{npcID=22893,x=0.428,y=0.206,zoneID=3518}},coords={x=0.428,y=0.206,source="quest_giver",zoneID=3518},questType="group"},
[9968] = {id=9968,name="Strange Energy",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Something strange has changed the teromoths of the thicket. Where once there was a diversity of life in there, now only the teromoths remain. And while before they were at peace, now they are agitated and will not hesitate to attack you should you get close. I need to compare the vicious ones to the normal. Collect for me a number of samples from both. You'll find the unaffected teromoths both to the south and the north. I'm certain this is related to whatever killed all of the druids.",starts={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},ends={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},coords={x=0.442,y=0.262,source="quest_giver",zoneID=3519},questType="standard"},
[9970] = {id=9970,name="The Ring of Blood: Rokdar the Sundered Lord",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="This fight is gonna be painful, . Do you have any friends that are brave enough to help you out? The ogres managed to get a giant from Blade's Edge named Rokdar! Trust me, you're gonna need friends, he seems unbeatable! He's hard as a rock - literally! If you still want to fight him, step into the Ring of Blood and he will come.",starts={{npcID=18471,x=0.428,y=0.206,zoneID=3518}},ends={{npcID=22893,x=0.428,y=0.206,zoneID=3518}},coords={x=0.428,y=0.206,source="quest_giver",zoneID=3518},questType="group"},
[9971] = {id=9971,name="Clues in the Thicket",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="I have no idea what killed all of the druids here. I've been away for a couple of days on a survey of the Bone Wastes to the south. Please, you must help me to uncover what's behind this horrible tragedy. Go into the thicket and look for a clue that might reveal something to us. When I was in there briefly, I could have sworn I saw a dead Broken and a strange object next to him. And don't worry about Treelos - he might have been driven insane by what happened, but I think he's mostly harmless.",starts={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},ends={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},coords={x=0.442,y=0.262,source="quest_giver",zoneID=3519},questType="standard"},
[9972] = {id=9972,name="The Ring of Blood: Skra'gath",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="You're murderin' 'em out there, kid! They got a ringer for the next match. They say he's a void lord or something... No way do they want you up against their champion. Did you here that palooka, Mogor, yapping at you? The bets are through the roof! Get in that ring and take this one out fast!",starts={{npcID=18471,x=0.428,y=0.206,zoneID=3518}},ends={{npcID=22893,x=0.428,y=0.206,zoneID=3518}},coords={x=0.428,y=0.206,source="quest_giver",zoneID=3518},questType="group"},
[9973] = {id=9973,name="The Ring of Blood: The Warmaul Champion",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="They had to ship the champion in from the Blade's Edge gladiator pits. He was training on mountain giants - three at a time. If you win this one, you become the new champion. What do you think your odds are, kid? Do you have a shot? Just give me the word and I'll bet the house on you. Now get in there and win!",starts={{npcID=18471,x=0.428,y=0.206,zoneID=3518}},ends={{npcID=22893,x=0.428,y=0.206,zoneID=3518}},coords={x=0.428,y=0.206,source="quest_giver",zoneID=3518},questType="group"},
[9977] = {id=9977,name="The Ring of Blood: The Final Challenge",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Gurgthock is counting his massive pile of gold.> You've made me a lot of money, kid. If you can defeat Mogor, I promise to make it worth your while. All that pain you suffered in the Ring of Blood is gonna end up paying off. Now get in there and show these ogres what you're made of!",starts={{npcID=18471,x=0.428,y=0.206,zoneID=3518}},ends={{npcID=22893,x=0.428,y=0.206,zoneID=3518}},coords={x=0.428,y=0.206,source="quest_giver",zoneID=3518},questType="group"},
[9978] = {id=9978,name="By Any Means Necessary",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="I don't know what to make of all of this, but I do know how we can find more clues. Empoor is a Broken merchant that traffics in all sorts of goods and information. If you were to persuade him to talk, I'm sure he might have something interesting to say. He travels the road here between Tuurem and Shattrath. Watch out, though -- he travels with a bodyguard.",starts={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},ends={{npcID=18482,x=0.436,y=0.262,zoneID=3519},{npcID=18482,x=0.838,y=0.542,zoneID=3703}},coords={x=0.442,y=0.262,source="quest_giver",zoneID=3519},questType="standard"},
[9979] = {id=9979,name="Wind Trader Lathrai",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="I was asked to pick up and deliver some boxes of goods from an ethereal in Shattrath City . Last I saw him, he was standing outside of the World's End Tavern in Lower City. His name is Wind Trader Lathrai , and that's all that I know! Want more answers, go talk with him!",starts={{npcID=18482,x=0.436,y=0.262,zoneID=3519},{npcID=18482,x=0.838,y=0.542,zoneID=3703}},ends={{npcID=18484,x=0.722,y=0.31,zoneID=3703}},coords={x=0.436,y=0.262,source="quest_giver",zoneID=3519},questType="standard"},
[9982] = {id=9982,name="He Called Himself Altruis...",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand . He claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons? Before he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.",starts={{npcID=18416,x=0.548,y=0.706,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.548,y=0.706,source="quest_giver",zoneID=3518},questType="standard"},
[9983] = {id=9983,name="He Called Himself Altruis...",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand . He claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons? Before he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.",starts={{npcID=18301,x=0.552,y=0.36,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.552,y=0.36,source="quest_giver",zoneID=3518},questType="standard"},
[9986] = {id=9986,name="Stymying the Arakkoa",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers. My scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz , Ayit , and Urdak , in Veil Reskk, Veil Shienor, and Veil Skith and kill them.",starts={{npcID=18389,x=0.578,y=0.542,zoneID=3519}},ends={{npcID=18389,x=0.578,y=0.542,zoneID=3519}},coords={x=0.578,y=0.542,source="quest_giver",zoneID=3519},questType="standard"},
[9987] = {id=9987,name="Stymying the Arakkoa",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers. My scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz , Ayit , and Urdak , in Veil Reskk, Veil Shienor, and Veil Skith and kill them.",starts={{npcID=18386,x=0.488,y=0.446,zoneID=3519}},ends={{npcID=18386,x=0.488,y=0.446,zoneID=3519}},coords={x=0.488,y=0.446,source="quest_giver",zoneID=3519},questType="standard"},
[9990] = {id=9990,name="Investigate Tuurem",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="You know, come to think of it, I do recall selling several boxes of strange and exotic engineering parts to Empoor about a month ago. I'm not sure what they'd be used for, but I know that they were delivered to Tuurem. Perhaps one or more of those boxes is still there?",starts={{npcID=18484,x=0.722,y=0.31,zoneID=3703}},ends={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},coords={x=0.722,y=0.31,source="quest_giver",zoneID=3703},questType="standard"},
[9991] = {id=9991,name="Survey the Land",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="To be my eyes will require some diligence on your part. Nethrandamus will take you through the Legion camps, but you must catalog everything that you see. Even the smallest detail that you may think to be inconsequential could be useful for our purposes. Primarily, I want you to note what structures are in the camps and what comprises the camps' defenses. Nethrandamus is ready when you are, . Do not be afraid, he will keep you safe from harm.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[9992] = {id=9992,name="Olemba Seeds",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="Aren't the trees in the forest beautiful? I've often wondered if they would survive on Azeroth. I'm hesitant to send back seedlings, though. It's a rough trip and they're much harder to transport than something like a sack of seeds. The seeds are stored in tough cones that fall from the tree's branches once they've reached maturity. If you come upon some of those cones in your travels, would you mind bringing some of the seeds back to me?",starts={{npcID=18390,x=0.574,y=0.554,zoneID=3519}},ends={{npcID=18390,x=0.574,y=0.554,zoneID=3519}},coords={x=0.574,y=0.554,source="quest_giver",zoneID=3519},questType="standard"},
[9993] = {id=9993,name="Olemba Seed Oil",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="The oily seeds from the forest's olemba trees could prove very valuable. I'd like to gather a larger quantity of them, press them for their oil, and then see what I can do with it. Just think, there's a whole forest full of trees out there, producing a lot of seeds that go to waste. I don't care if it turns out to be cooking oil, lamp oil, or weapon oil, I won't let it go to waste! Bring me any of the seeds that you happen to gather from the olemba cones. They're all over the place.",starts={{npcID=18385,x=0.5,y=0.448,zoneID=3519}},ends={{npcID=18385,x=0.5,y=0.448,zoneID=3519}},coords={x=0.5,y=0.448,source="quest_giver",zoneID=3519},questType="standard"},
[9994] = {id=9994,name="What Are These Things?",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="I don't know about you, but I have no idea what all of those things are. I do know one thing though - they look dangerous! , I think you should take this box of parts to Jenai Starwhisper at the Allerian Stronghold to the southeast. She may have some idea of what these are.",starts={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},ends={{npcID=18459,x=0.57,y=0.536,zoneID=3519}},coords={x=0.442,y=0.262,source="quest_giver",zoneID=3519},questType="standard"},
[9995] = {id=9995,name="What Are These Things?",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="I don't know about you, but I have no idea what all of those things are. I do know one thing though - they look dangerous! , I think you should take this box of parts to Tooki at Stonebreaker Hold to the southeast. He may have some idea of what these are.",starts={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},ends={{npcID=18447,x=0.5,y=0.458,zoneID=3519}},coords={x=0.442,y=0.262,source="quest_giver",zoneID=3519},questType="standard"},
[9996] = {id=9996,name="Attack on Firewing Point",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="We know that the blood elves of Firewing Point are working for Kael'thas and Illidan. And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon. Whatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers. The Firewing blood elves need to be taken out! Head up to Firewing Point to the north and see to it.",starts={{npcID=21006,x=0.696,y=0.44,zoneID=3519}},ends={{npcID=21006,x=0.696,y=0.44,zoneID=3519}},coords={x=0.696,y=0.44,source="quest_giver",zoneID=3519},questType="standard"},
[9997] = {id=9997,name="Attack on Firewing Point",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="We know that the blood elves of Firewing Point are working for Kael'thas and Illidan. And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon. Whatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers. The Firewing blood elves need to be taken out! Head over to Firewing Point to the northeast and see to it.",starts={{npcID=21007,x=0.632,y=0.424,zoneID=3519}},ends={{npcID=21007,x=0.632,y=0.424,zoneID=3519}},coords={x=0.632,y=0.424,source="quest_giver",zoneID=3519},questType="standard"},
[9998] = {id=9998,name="Unruly Neighbors",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="The recent arrival of the fel orcs at the ruins to the east both puzzles and troubles Thander. They wasted no time in starting to construct fortifications and repair the buildings. The construction goes on day and night, . I've dispatched one of my most reliable agents to keep watch, but we can ill afford to delay action. Move against their workers, then seek out Theloria Shadecloak at the Allerian Post to the north of the Bonechewer Ruins. She'll give you further instructions.",starts={{npcID=18387,x=0.582,y=0.548,zoneID=3519}},ends={{npcID=18565,x=0.696,y=0.442,zoneID=3519}},coords={x=0.582,y=0.548,source="quest_giver",zoneID=3519},questType="standard"},
[10000] = {id=10000,name="An Unwelcome Presence",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="Our forces at Thrallmar thought they had the fel orcs contained in the Hellfire Citadel area, but the recent arrivals at the ruins to the east say otherwise. We can't permit them to gain a foothold here. Rokag has dispatched Shadowstalker Kaide to the ruins to keep an eye on them, but we have to do something to keep them from digging in. Go to the ruins, decimate their peons, and then look for Kaide in the trees to the north. He'll tell you where to go from there.",starts={{npcID=18383,x=0.488,y=0.456,zoneID=3519}},ends={{npcID=18566,x=0.632,y=0.426,zoneID=3519}},coords={x=0.488,y=0.456,source="quest_giver",zoneID=3519},questType="standard"},
[10001] = {id=10001,name="The Master Planner",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="All forge camps have a master planner. The master planner dictates what types of structures are present at a forge camp and how each structure is situated. Moreover, this information is kept on a set of blueprints that the planner carries around on their person. We need the master planner's blueprints . Armed with such exacting information, we could persuade an acquaintance of mine to lend some assistance. Find the mo'arg master planner and take his blueprints. He will be stationed behind the forges.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[10002] = {id=10002,name="The Firewing Liaison",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying? My curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost. Kill her before she leaves the fel orc camp again.",starts={{npcID=18565,x=0.696,y=0.442,zoneID=3519}},ends={{npcID=18565,x=0.696,y=0.442,zoneID=3519}},coords={x=0.696,y=0.442,source="quest_giver",zoneID=3519},questType="standard"},
[10003] = {id=10003,name="The Firewing Liaison",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying? My curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost. Kill her before she leaves the fel orc camp again.",starts={{npcID=18566,x=0.632,y=0.426,zoneID=3519}},ends={{npcID=18566,x=0.632,y=0.426,zoneID=3519}},coords={x=0.632,y=0.426,source="quest_giver",zoneID=3519},questType="standard"},
[10005] = {id=10005,name="Letting Earthbinder Tavgren Know",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description=", after you're done celebrating here, I think that you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren . I'm certain that he'll want to know what really happened out there.",starts={{npcID=18459,x=0.57,y=0.536,zoneID=3519}},ends={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},coords={x=0.57,y=0.536,source="quest_giver",zoneID=3519},questType="standard"},
[10006] = {id=10006,name="Letting Earthbinder Tavgren Know",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description=", I think that after you're done celebrating here, you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren . I'm certain that he'll want to know what really happened out there.",starts={{npcID=18447,x=0.5,y=0.458,zoneID=3519}},ends={{npcID=18446,x=0.442,y=0.262,zoneID=3519}},coords={x=0.5,y=0.458,source="quest_giver",zoneID=3519},questType="standard"},
[10007] = {id=10007,name="Thinning the Ranks",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="Knowing Thander and Bertelm, they won't tolerate such a large buildup of hostile forces on our doorstep. Asking them to dispatch members of the garrison to participate in an attack on the camp isn't an option either. It would just leave us too vulnerable to attack. It falls to us to do what we can to diminish the threat the fel orc buildup poses. Kill what you can of their forces and I will look for ways to stall any reinforcements.",starts={{npcID=18565,x=0.696,y=0.442,zoneID=3519}},ends={{npcID=18565,x=0.696,y=0.442,zoneID=3519}},coords={x=0.696,y=0.442,source="quest_giver",zoneID=3519},questType="standard"},
[10008] = {id=10008,name="What Happens in Terokkar Stays in Terokkar",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="If word reaches Thrallmar that they've failed to contain the fel orcs, we're going to be receiving a lot of company down here. Frankly, I'm not sure I want all that attention, so we're going to keep this little problem under wraps, got it? If we can inflict enough casualties on the fel orcs, chances are their presence will never come to the attention of anyone outside Stonebreaker. So, let's end it now. Wade in there, swing your weapon, wave your hands, or whatever it is you do - just kill fel orcs.",starts={{npcID=18566,x=0.632,y=0.426,zoneID=3519}},ends={{npcID=18566,x=0.632,y=0.426,zoneID=3519}},coords={x=0.632,y=0.426,source="quest_giver",zoneID=3519},questType="standard"},
[10009] = {id=10009,name="Crackin' Some Skulls",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Sal'salabim laughs.> This Sal'salabim design. Sal'salabim points to the architecture and formations on the blueprints.> Look at towers. Demon hunter no can see, yes? Poor, poor Altruis. He cry if he had eyes, yes? Yes, Sal'salabim help but first you help Sal'salabim . Sal'salabim gives you a ledger.> These creatures owe Sal'salabim golds. Many golds. Go collect for Sal'salabim and come back. They no give you Sal'salabim gold easy. Have to fight, but you strong. You defeat Sal'salabim !",starts={{npcID=18584,x=0.772,y=0.348,zoneID=3703}},ends={{npcID=18584,x=0.772,y=0.348,zoneID=3703}},coords={x=0.772,y=0.348,source="quest_giver",zoneID=3703},questType="standard"},
[10010] = {id=10010,name="It's Just That Easy?",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Sal'salabim points to the blueprint.> You see where fel cannons are? Sal'salabim draws an arrow denoting a change of direction.> You turn fel cannon around and use on structures. Wait! Don't be mad! One thing you not know. Overseers have key to turn cannons. You need key first! One from each overseer! Not so easy, eh? Take information back to Altruis.",starts={{npcID=18584,x=0.772,y=0.348,zoneID=3703}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.772,y=0.348,source="quest_giver",zoneID=3703},questType="standard"},
[10011] = {id=10011,name="Forge Camp: Annihilated",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Gather your courage, . You will need it if you are to face an overseer. Once you are ready, find and kill the overseers at each camp. Take their keys and use them to turn and fire the fel cannons upon the camps. Return to me once the camps are destroyed.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[10012] = {id=10012,name="Fel Orc Plans",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point. Why would the two forces be working together? Bertelm might have some insight into this odd alliance. You decide to make your way back to the Allerian Stronghold and show him the map.",starts={{npcID=182549,x=0.679,y=0.535,zoneID=3519}},ends={{npcID=18387,x=0.582,y=0.548,zoneID=3519}},coords={x=0.679,y=0.535,source="quest_giver",zoneID=3519},questType="standard"},
[10013] = {id=10013,name="An Unseen Hand",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point. Why would the two forces be working together? Rokag might have some insight into this odd alliance. You decide to make your way back to Stonebreaker Hold and show him the map.",starts={{npcID=182549,x=0.679,y=0.535,zoneID=3519}},ends={{npcID=18386,x=0.488,y=0.446,zoneID=3519}},coords={x=0.679,y=0.535,source="quest_giver",zoneID=3519},questType="standard"},
[10016] = {id=10016,name="Timber Worg Tails",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="Have you come across the timber worgs in your travels? I've had the opportunity to observe them while mapping some of the northern reaches of the forest. I wouldn't recommend getting close to them unless you're prepared for combat. They have no fear of us and won't hesitate to defend their territory. It's fitting that such a creature would have a magnificent tail. I've been trying to collect enough of them to trim a new cloak, but the worgs have a habit of evading my snares. Will you help?",starts={{npcID=18387,x=0.582,y=0.548,zoneID=3519}},ends={{npcID=18387,x=0.582,y=0.548,zoneID=3519}},coords={x=0.582,y=0.548,source="quest_giver",zoneID=3519},questType="standard"},
[10017] = {id=10017,name="Strained Supplies",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="More and more refugees come through the gates of Shattrath City each day. Some have sustained such injuries, it's a real wonder they made it here. I can deal with most of the conventional injuries; my training as an Aldor healer has prepared me for that. Poison wounds are more problematic as my anti-venom supplies have begun to run low. Bring me venom sacs from the local dreadfang spiders so I can produce more antidotes. You'll find a pocket of the spiders in the southeastern region of Terokkar.",starts={{npcID=18597,x=0.642,y=0.154,zoneID=3703}},ends={{npcID=18597,x=0.642,y=0.154,zoneID=3703}},coords={x=0.642,y=0.154,source="quest_giver",zoneID=3703},questType="standard"},
[10018] = {id=10018,name="Vestments of the Wolf Spirit",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3483,description="Generations ago, when orc clans still called Terokkar Forest home, the wolf spirit played an important role in their lives. When the orcs departed, they had no longer had any need for the spirit and they left it behind. In time, the spirit grew lonely and it too left the forest. I believe I can bring the wolf spirit back to his ancestral home, just as we orcs have returned. The ritual will require me to create vestments from the pelts of the wolves of the forest to guide the spirit back to its home.",starts={{npcID=18384,x=0.5,y=0.464,zoneID=3519}},ends={{npcID=18384,x=0.5,y=0.464,zoneID=3519}},coords={x=0.5,y=0.464,source="quest_giver",zoneID=3519},questType="standard"},
[10019] = {id=10019,name="More Venom Sacs",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18597,x=0.642,y=0.154,zoneID=3703}},ends={{npcID=18597,x=0.642,y=0.154,zoneID=3703}},coords={x=0.642,y=0.154,source="quest_giver",zoneID=3703},questType="standard"},
[10020] = {id=10020,name="A Cure for Zahlia",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="The woman to my right suffered a severe injury to the head. She survived, but lost her eyesight. A traditional cure used among my people requires the blood of a very old basilisk. Unfortunately, due to poaching from various groups, Terokkar basilisks don't tend to live very long. There is one basilisk whose name I've known since I was a youngling. It is known only as \"Stonegazer\" and it's rumored to live east of here, near the land's edge. Bring me its blood so that Zahlia may see once again.",starts={{npcID=18597,x=0.642,y=0.154,zoneID=3703}},ends={{npcID=18597,x=0.642,y=0.154,zoneID=3703}},coords={x=0.642,y=0.154,source="quest_giver",zoneID=3703},questType="standard"},
[10021] = {id=10021,name="Restoring the Light",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Much of this region was inhabited by draenei long ago. We Aldor were charged with the safeguarding of our holy sites and altars. Many of them have since been destroyed or taken over by our enemies. To the east of here there is an arakkoa outpost. It was purposefully built on the location of three of our sacred altars. The arakkoa use their foul magic to warp and defile the innate power of our shrines. Take this to the arakkoa outpost and use it to cleanse the three altars.",starts={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},ends={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},coords={x=0.242,y=0.298,source="quest_giver",zoneID=3703},questType="standard"},
[10022] = {id=10022,name="The Elusive Ironjaw",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="Now that I have the fur I'll need for the trim, I've been thinking that the pelt of a particular wolf would make a good hood for my cloak. Imagine seeing your enemy clad in the pelt of the most cunning predator in the forest! I've tried trapping old Ironjaw without success. I've tried cornering him, outsmarting him, and baiting him. None of it has worked. He stalks the northeastern reaches of the forest, and I'd gladly reward you if you could succeed where I have failed.",starts={{npcID=18387,x=0.582,y=0.548,zoneID=3519}},ends={{npcID=18387,x=0.582,y=0.548,zoneID=3519}},coords={x=0.582,y=0.548,source="quest_giver",zoneID=3519},questType="standard"},
[10023] = {id=10023,name="Patriarch Ironjaw",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="You've done well in gathering the first pelts. The final piece of the vestments requires a pelt unlike any other. There is one particular wolf, an old and cunning one, that has earned his place as the patriarch of the forest wolves. He is known among them as Ironjaw, the mighty hunter. In my visions, I have seen him wandering the northeastern region of the forest. Including his pelt in the vestments will surely light the wolf spirit's path. Do not mourn Ironjaw. He will be well honored.",starts={{npcID=18384,x=0.5,y=0.464,zoneID=3519}},ends={{npcID=18384,x=0.5,y=0.464,zoneID=3519}},coords={x=0.5,y=0.464,source="quest_giver",zoneID=3519},questType="standard"},
[10024] = {id=10024,name="Voren'thal's Visions",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Our leader, Voren'thal the Seer, was once a close advisor to Kael'thas. His prophetic visions warned him that Kael's path would lead to the destruction of our race. The visions are usually vague and unfocused, but our alchemists have devised an elixir to help him focus his clairvoyance. Unfortunately, this elixir calls for a rare ingredient: basilisk eyes. My usual source, this pathetic ethereal, has failed me. Seek the dampscale basilisks in the rocky regions of Terokkar and bring me their eyes.",starts={{npcID=18596,x=0.548,y=0.224,zoneID=3703}},ends={{npcID=18596,x=0.548,y=0.224,zoneID=3703}},coords={x=0.548,y=0.224,source="quest_giver",zoneID=3703},questType="standard"},
[10025] = {id=10025,name="More Basilisk Eyes",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18596,x=0.548,y=0.224,zoneID=3703}},ends={{npcID=18596,x=0.548,y=0.224,zoneID=3703}},coords={x=0.548,y=0.224,source="quest_giver",zoneID=3703},questType="standard"},
[10026] = {id=10026,name="Magical Disturbances",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="It's embarrassing to admit this, but something has happened to me here in Terokkar Forest that hasn't occurred since my apprentice days. Occasionally, my spells will fizzle when I know I've done everything correctly. I almost drove myself crazy the first time it happened. I think I've found the cause. The forest is full of creatures called warp stalkers , demonic creatures with an affinity for magic and a habit of disturbing magical flows. The best way to deal with them is simply to kill them.",starts={{npcID=18252,x=0.584,y=0.536,zoneID=3519}},ends={{npcID=18252,x=0.584,y=0.536,zoneID=3519}},coords={x=0.584,y=0.536,source="quest_giver",zoneID=3519},questType="standard"},
[10027] = {id=10027,name="Magical Disturbances",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="There's nothing more annoying than preparing to cast a spell, only to have it interrupted by some unseen force. After the fourth time, I knew it couldn't be coincidence and I sent Keb'ezil out to investigate. I guarantee you'll never encounter an imp that talks back more than Keb. Anyway, he managed to find the source of the problem, a pesky creature known as a warp stalker . They have a habit of disturbing the magical energy wherever they blink into existence. I've had enough of their interference.",starts={{npcID=18383,x=0.488,y=0.456,zoneID=3519}},ends={{npcID=18383,x=0.488,y=0.456,zoneID=3519}},coords={x=0.488,y=0.456,source="quest_giver",zoneID=3519},questType="standard"},
[10028] = {id=10028,name="Vessels of Power",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="Amid the ruins of Tuurem are a number of vessels containing raw, magical energy. We are fortunate that the Broken who have overrun the city are ignorant to the resource in their midst, but we cannot assume they will remain so forever. With those vessels and their power in hand, the scattered survivors of my people can resist the lure of demonic magic. Every quel'dorei we can save from our prince's folly is one more that can help us regain our lost glory. Bring me these vessels, .",starts={{npcID=18390,x=0.574,y=0.554,zoneID=3519}},ends={{npcID=18390,x=0.574,y=0.554,zoneID=3519}},coords={x=0.574,y=0.554,source="quest_giver",zoneID=3519},questType="standard"},
[10030] = {id=10030,name="Recover the Bones",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="The bones of the dead draenei litter the Bone Wastes from the explosion of Auchindoun. Their spirits are restless, and cannot move on to the next life. , you must help me to recover their bones and take them to their final resting place! Only then will they be at peace; only then will they know comfort. Gather up the restless bones with care and deliver them to Ramdor the Mad at Auchindoun in the center of the Bone Wastes. Despite his name, he will know how to care for them.",starts={{npcID=18675,x=0.37,y=0.496,zoneID=3519}},ends={{npcID=19417,x=0.352,y=0.662,zoneID=3519}},coords={x=0.37,y=0.496,source="quest_giver",zoneID=3519},questType="standard"},
[10031] = {id=10031,name="Helping the Lost Find Their Way",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Many spirits of the draenei were corrupted by the explosion of Auchindoun. Now they wander the wastes in torment. , I beseech you to put them to rest. Destroy the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun's walls. What? You think leaving them to wander in blind agony would be better? Afterward, return to Soolaveen at the Refugee Caravan and tell him of that which you have done.",starts={{npcID=19417,x=0.352,y=0.662,zoneID=3519}},ends={{npcID=18675,x=0.37,y=0.496,zoneID=3519}},coords={x=0.352,y=0.662,source="quest_giver",zoneID=3519},questType="standard"},
[10033] = {id=10033,name="WANTED: Bonelashers Dead!",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="A bounty is declared on the bonelashers of the Bone Wastes. As known carriers of the plague, they are to be destroyed forthwith! While they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north. Report to Taela Everstride afterward to collect your reward.",starts={{npcID=182587,x=0.576,y=0.547,zoneID=3519}},ends={{npcID=18704,x=0.58,y=0.534,zoneID=3519}},coords={x=0.576,y=0.547,source="quest_giver",zoneID=3519},questType="standard"},
[10034] = {id=10034,name="WANTED: Bonelashers Dead!",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="The bonelashers of the Bone Wastes bit Mawg and made him sick. Now he wants all of them destroyed! While they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north. Return to Mawg Grimshot after you've done the deed and he'll give you a good reward.",starts={{npcID=182588,x=0.498,y=0.452,zoneID=3519}},ends={{npcID=18705,x=0.492,y=0.458,zoneID=3519}},coords={x=0.498,y=0.452,source="quest_giver",zoneID=3519},questType="standard"},
[10035] = {id=10035,name="Torgos!",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="There's a creature in the Bone Wastes so fearsome that only the dauntless dare to stalk him. I speak of Torgos, king of the bonelashers, who circles over Veil Rhaze on the western edge of the wastes. Too bad that there's an arakkoan scarecrow there, known as Torgos's Bane, which keeps him at bay. I'd bet if you laid his mate Trachela's carcass at the foot of that scarecrow he'd come down anyway. She can be found at Carrion Hill in the northern wastes. Bring me one of Torgos's tail feathers.",starts={{npcID=18704,x=0.58,y=0.534,zoneID=3519}},ends={{npcID=18704,x=0.58,y=0.534,zoneID=3519}},coords={x=0.58,y=0.534,source="quest_giver",zoneID=3519},questType="standard"},
[10036] = {id=10036,name="Torgos!",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="I want Torgos, king of the bonelashers, dead! Not long ago, while I was out hunting at Veil Rhaze on the western edge of the wastes, he fell upon me. He took my eye, and now I would have his life! Bring me one of his tail feathers as proof and I'll give you a worthy reward. You'll need his mate Trachela's carcass though to call him down as he's deathly afraid of the old arakkoan scarecrow known as Torgos's Bane. Find her at Carrion Hill in the northern wastes.",starts={{npcID=18705,x=0.492,y=0.458,zoneID=3519}},ends={{npcID=18705,x=0.492,y=0.458,zoneID=3519}},coords={x=0.492,y=0.458,source="quest_giver",zoneID=3519},questType="standard"},
[10037] = {id=10037,name="Rather Be Fishin'",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Speaking of lakes, there's a lake with real good fishin' up to the northeast. I used to go up there with my friends, but my mom won't let me go anymore. She says it's too dangerous, but I haven't seen anything up there but a few little spiders. Like spiders can do anything to you... My favorites were always the eels that live up there. If you're going to be up by the lake, would you think about bringing back some of the eels? They're feisty but once you subdue 'em, you can bring 'em back no problem.",starts={{npcID=18653,x=0.64,y=0.156,zoneID=3703}},ends={{npcID=18653,x=0.64,y=0.156,zoneID=3703}},coords={x=0.64,y=0.156,source="quest_giver",zoneID=3703},questType="standard"},
[10038] = {id=10038,name="Speak with Private Weeks",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="A report's just come in from one of our scouts near Grangol'var Village. He says that a shadowy band has moved into the ruins there. , I want you to speak with Private Weeks and see how you can assist him to figure out what this unknown group is up to. Just head west past Stonebreaker Hold. His last report puts his position near the north entrance to the village.",starts={{npcID=18713,x=0.574,y=0.556,zoneID=3519}},ends={{npcID=18715,x=0.404,y=0.36,zoneID=3519}},coords={x=0.574,y=0.556,source="quest_giver",zoneID=3519},questType="standard"},
[10039] = {id=10039,name="Speak with Scout Neftis",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="I am informed that one of our scouts near Grangol'var Village is currently observing a shadowy band that has recently moved in there. , I want you to speak with Scout Neftis and see how you can assist her in figuring out what this unknown group is up to. Just head south out of here, and then due west, skirting the north of the Bone Wastes. Her last report puts her position near the southern entrance to the village.",starts={{npcID=18712,x=0.488,y=0.446,zoneID=3519}},ends={{npcID=18714,x=0.39,y=0.438,zoneID=3519}},coords={x=0.488,y=0.446,source="quest_giver",zoneID=3519},questType="standard"},
[10040] = {id=10040,name="Who Are They?",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="I don't know who they are, but I know they're hostile! I'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor. Just watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.",starts={{npcID=18715,x=0.404,y=0.36,zoneID=3519}},ends={{npcID=18715,x=0.404,y=0.36,zoneID=3519}},coords={x=0.404,y=0.36,source="quest_giver",zoneID=3519},questType="standard"},
[10041] = {id=10041,name="Who Are They?",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="I don't know who they are, but I know they're hostile! I'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor. Just watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.",starts={{npcID=18714,x=0.39,y=0.438,zoneID=3519}},ends={{npcID=18714,x=0.39,y=0.438,zoneID=3519}},coords={x=0.39,y=0.438,source="quest_giver",zoneID=3519},questType="standard"},
[10042] = {id=10042,name="Kill the Shadow Council!",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="What! Those guys are Shadow Council?! , you have to go back in there and waste them! I want you to take out their leader and as many of their executioners and summoners as you can. After you're done with that, report back to Lieutenant Gravelhammer at the Allerian Stronghold. Good luck, !",starts={{npcID=18715,x=0.404,y=0.36,zoneID=3519}},ends={{npcID=18713,x=0.574,y=0.556,zoneID=3519}},coords={x=0.404,y=0.36,source="quest_giver",zoneID=3519},questType="standard"},
[10043] = {id=10043,name="Kill the Shadow Council!",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="What! Those guys are Shadow Council?! , you have to go back in there and waste them! I want you to take out their leader and as many of their executioners and summoners as you can. After you're done with that, report back to Advisor Faila at Stonebreaker Hold. Good luck, !",starts={{npcID=18714,x=0.39,y=0.438,zoneID=3519}},ends={{npcID=18712,x=0.488,y=0.446,zoneID=3519}},coords={x=0.39,y=0.438,source="quest_giver",zoneID=3519},questType="standard"},
[10044] = {id=10044,name="A Visit With the Greatmother",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="The Greatmother has asked that I seek you out and deliver a message. She wishes to speak with you at once. My will has been sapped but make no mistake, , if you anger the Greatmother, I will come down upon you with all the force that I can muster. She is in the main hall. Garrosh points at the large building to the north.> Listen to what she has to say and do as she tells you.",starts={{npcID=18063,x=0.554,y=0.376,zoneID=3518}},ends={{npcID=18141,x=0.566,y=0.342,zoneID=3518}},coords={x=0.554,y=0.376,source="quest_giver",zoneID=3518},questType="standard"},
[10045] = {id=10045,name="Material Components",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Mother Kashur wishes to speak with you, . Before this becomes possible, you must collect the herbs required to create a potion that will expand your mind, allowing you to commune with the spirits. You must gather Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade's Edge mountains. I have written down instructions on this parchment as to the cultivation of these herbs. Return to me when you have gathered the materials.",starts={{npcID=18141,x=0.566,y=0.342,zoneID=3518}},ends={{npcID=18141,x=0.566,y=0.342,zoneID=3518}},coords={x=0.566,y=0.342,source="quest_giver",zoneID=3518},questType="standard"},
[10047] = {id=10047,name="The Path of Glory",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The 'Path of Glory,' they called it. A road leading from the heart of their gruesome fortress to the Dark Portal, paved with the bones of my people. It wasn't enough for them to hunt us down like animals, destroy our cities, and torture those who survived. No, they had to use our bones as paving stones, denying my brethren a proper burial under the Light. Those tortured souls still wander these lands, crying out for release. I ask you, , help me in this undertaking.",starts={{npcID=16839,x=0.566,y=0.664,zoneID=3483}},ends={{npcID=16839,x=0.566,y=0.664,zoneID=3483}},coords={x=0.566,y=0.664,source="quest_giver",zoneID=3483},questType="standard"},
[10050] = {id=10050,name="Unyielding Souls",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Near the end of our invasion, the Armory to the south fell under attack by the Horde's insidious Death Knights. Those vile shades cursed the Armory's defenders - and trapped their souls between the realms of the living and the dead. Those noble souls must be set free! I beg you, , end my comrades' torment, for I have not the heart to slay them myself.",starts={{npcID=16827,x=0.508,y=0.602,zoneID=3483}},ends={{npcID=16827,x=0.508,y=0.602,zoneID=3483}},coords={x=0.508,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[10051] = {id=10051,name="Escape from Firewing Point!",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="Thank goodness for you! , I need you to help me escape. I have information vital to the security of the Allerian Stronghold and probably all of Outland! I came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly. If you help me get to safety, I can assure you that you will be handsomely rewarded!",starts={{npcID=18760,x=0.738,y=0.352,zoneID=3519}},ends={{npcID=18745,x=0.572,y=0.558,zoneID=3519}},coords={x=0.738,y=0.352,source="quest_giver",zoneID=3519},questType="standard"},
[10052] = {id=10052,name="Escape from Firewing Point!",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="Thank goodness for you! , I need you to help me escape. I have information vital to the security of Stonebreaker Hold and probably all of Outland! I came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly. If you help me get to safety, I can assure you that you will be handsomely rewarded!",starts={{npcID=18760,x=0.738,y=0.352,zoneID=3519}},ends={{npcID=18712,x=0.488,y=0.446,zoneID=3519}},coords={x=0.738,y=0.352,source="quest_giver",zoneID=3519},questType="standard"},
[10055] = {id=10055,name="Waste Not, Want Not",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Reinforcements are great, but I don't see 'em haulin' any wagons loaded with ingots or timber. Take a look around, friend. Trees are in short supply, and the mines are overrun with Legion scum. I'm in a bad way fer supplies, and I'm makin' what substitutions I can, but it's time to start reusing what we can. The southern edge of the Path o' Glory is strewn with the ruins of siege machinery. Some pieces of 'em are still usable. Feeling up to a bit o' a salvage operation?",starts={{npcID=21209,x=0.512,y=0.602,zoneID=3483}},ends={{npcID=21209,x=0.512,y=0.602,zoneID=3483}},coords={x=0.512,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[10057] = {id=10057,name="Looking to the Leadership",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The disturbances at Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins. Perhaps we've been approaching this the wrong way. I've always assumed that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders? Arch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.",starts={{npcID=16827,x=0.508,y=0.602,zoneID=3483}},ends={{npcID=16827,x=0.508,y=0.602,zoneID=3483}},coords={x=0.508,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[10058] = {id=10058,name="An Old Gift",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Don't you know better than to bother a man in his cups? Oh, what's the use? I suppose newcomers are a good sign. What would Turalyon think? I remember the eve of our departure, when I gave Mysteries of the Light to him. During the campaign and the ensuing years, he never forgot to read his daily passage to the men. When he left us again, he gave the book back to me. Like a fool, I believed it safe in my quarters to the south of the armory.",starts={{npcID=16825,x=0.542,y=0.634,zoneID=3483}},ends={{npcID=16825,x=0.542,y=0.634,zoneID=3483}},coords={x=0.542,y=0.634,source="quest_giver",zoneID=3483},questType="standard"},
[10063] = {id=10063,name="Explorers' League, Is That Something for Gnomes?",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Babysitting! Would you believe it? They pulled me out of a promising dig and sent me along with Captain Odesyus' expedition to babysit that little gnome! I'd never heard o' a gnome wanting to become a prospector before, so I asked. Seems we are takin' gnomes now, and this particular one has a fascination with murlocs! Well, he's gone off and set up shop in an old turtle shell on the northern shore of the island. Go and have a look if you don't believe me!",starts={{npcID=18804,x=0.562,y=0.542,zoneID=3525}},ends={{npcID=17421,x=0.42,y=0.212,zoneID=3525}},coords={x=0.562,y=0.542,source="quest_giver",zoneID=3525},questType="standard"},
[10064] = {id=10064,name="Talk to the Hand",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="The Hand of Argus has established a forward base at Vindicator's Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we'd have no way to keep an eye on events near the Vector Coil. Report to Scout Jorli at Vindicator's Rest to the northwest and offer her your assistance, .",starts={{npcID=17423,x=0.526,y=0.532,zoneID=3525}},ends={{npcID=17927,x=0.302,y=0.46,zoneID=3525}},coords={x=0.526,y=0.532,source="quest_giver",zoneID=3525},questType="standard"},
[10065] = {id=10065,name="Cutting a Path",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="During our mission to reconnoiter the Sunhawks and their portal, I sustained a serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to figure out a way to evacuate me to Blood Watch. The problem is that we'd have to abandon our position here in order to guarantee a safe return. As soon as we leave this consecrated ground, we'll be set upon by ravagers. If you can clear some of the enraged ravagers , it might allow us to make the trip back safely.",starts={{npcID=17927,x=0.302,y=0.46,zoneID=3525}},ends={{npcID=17927,x=0.302,y=0.46,zoneID=3525}},coords={x=0.302,y=0.46,source="quest_giver",zoneID=3525},questType="standard"},
[10066] = {id=10066,name="Oh, the Tangled Webs They Weave",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="We don't dare abandon our post, or wander too far from Vindicator's Rest, . The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals. The mutated tanglers appear to have gained a certain degree of sentience. They've learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior. We'll never be able to move against the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its source, .",starts={{npcID=17986,x=0.306,y=0.466,zoneID=3525},{npcID=18020,x=0.518,y=0.518,zoneID=3525},{npcID=18024,x=0.554,y=0.524,zoneID=3525}},ends={{npcID=17986,x=0.306,y=0.466,zoneID=3525}},coords={x=0.306,y=0.466,source="quest_giver",zoneID=3525},questType="standard"},
[10067] = {id=10067,name="Fouled Water Spirits",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,description="Most of the creatures touched by the crystals' energy have been corrupted in the same ways: strange marks on their flesh, increased aggression, and small crystal shards in their bodies. However, the fouled water spirits north of here appear to be turning entirely to crystal. I've never seen anything react to the crystals this way before, when we explored the foul pool, they were particularly dangerous. We must get rid of them before the Sunhawks can exploit them as a new source of energy.",starts={{npcID=17986,x=0.306,y=0.466,zoneID=3525},{npcID=18020,x=0.518,y=0.518,zoneID=3525},{npcID=18024,x=0.554,y=0.524,zoneID=3525}},ends={{npcID=17986,x=0.306,y=0.466,zoneID=3525}},coords={x=0.306,y=0.466,source="quest_giver",zoneID=3525},questType="standard"},
[10074] = {id=10074,name="Oshu'gun Crystal Powder",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="This base was the primary draenei research facility for the study of naaru crystals. What we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.",starts={{npcID=18816,x=0.412,y=0.442,zoneID=3518}},ends={{npcID=18816,x=0.412,y=0.442,zoneID=3518}},coords={x=0.412,y=0.442,source="quest_giver",zoneID=3518},questType="pvp"},
[10075] = {id=10075,name="Oshu'gun Crystal Powder",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,starts={{npcID=18816,x=0.412,y=0.442,zoneID=3518}},ends={{npcID=18816,x=0.412,y=0.442,zoneID=3518}},coords={x=0.412,y=0.442,source="quest_giver",zoneID=3518},questType="pvp"},
[10076] = {id=10076,name="Oshu'gun Crystal Powder",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="This base was the primary draenei research facility for the study of naaru crystals. What we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.",starts={{npcID=18817,x=0.412,y=0.442,zoneID=3518}},ends={{npcID=18817,x=0.412,y=0.442,zoneID=3518}},coords={x=0.412,y=0.442,source="quest_giver",zoneID=3518},questType="pvp"},
[10077] = {id=10077,name="Oshu'gun Crystal Powder",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,starts={{npcID=18817,x=0.412,y=0.442,zoneID=3518}},ends={{npcID=18817,x=0.412,y=0.442,zoneID=3518}},coords={x=0.412,y=0.442,source="quest_giver",zoneID=3518},questType="pvp"},
[10078] = {id=10078,name="Laying Waste to the Unwanted",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Now that we've gotten our salvage operation off the ground, it's time to begin the second phase of the plan. Across the Path of Glory, the Horde still has their old blade throwers trained on us. Don't let their age fool you, , they're still very dangerous. Much as we're working to reclaim what we can, we can't assume the Horde is going to dismantle their weaponry. Take this torch and burn the remaining siege equipment. I'll take no chances with Honor Hold's safety.",starts={{npcID=21209,x=0.512,y=0.602,zoneID=3483}},ends={{npcID=21209,x=0.512,y=0.602,zoneID=3483}},coords={x=0.512,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[10079] = {id=10079,name="When This Mine's a-Rockin'",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The mine's been overrun by a plague of gan'arg misfits! Not only did they run all my workers out of the tunnels, but they're pounding away in there night and day! To make things worse, now I've got Danath on me back! He says he's going to take away me ale ration if I don't get this taken care of soon! None of the miners'll go in there, and the guards are busy drinking themselves silly. I'm begging you, , help me here. Danath can take me dignity, but he'll never take me ale!",starts={{npcID=16837,x=0.52,y=0.624,zoneID=3483}},ends={{npcID=16837,x=0.52,y=0.624,zoneID=3483}},coords={x=0.52,y=0.624,source="quest_giver",zoneID=3483},questType="standard"},
[10081] = {id=10081,name="To Meet Mother Kashur",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Do not be alarmed by what you might see once the effect has taken hold! These spirits are all around us - always. The potion allows your mind to be able to understand and ultimately see the spirits. You will need to be under its influence if you are to speak with Mother Kashur . You will find her a great ways to the southwest, at the Ancestral Grounds.",starts={{npcID=18141,x=0.566,y=0.342,zoneID=3518}},ends={{npcID=18687,x=0.26,y=0.606,zoneID=3518}},coords={x=0.566,y=0.342,source="quest_giver",zoneID=3518},questType="standard"},
[10082] = {id=10082,name="The Agitated Ancestors",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Do you see them walking around us? The Ancestral Grounds are normally quiet and undisturbed. As of late, the ancestral spirits have risen and are extremely agitated. Something is causing a great disturbance to the spirits. We must discover what that something could be, but first, we must put the immediate threat to rest. These ghosts that you see walking about are not truly the ancestors but a representation of their state of being. You must destroy the agitated orc spirits . Do this and return to me.",starts={{npcID=18687,x=0.26,y=0.606,zoneID=3518}},ends={{npcID=18687,x=0.26,y=0.606,zoneID=3518}},coords={x=0.26,y=0.606,source="quest_giver",zoneID=3518},questType="standard"},
[10085] = {id=10085,name="A Visit With The Ancestors",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="I need for you to journey to the villages of the ancestors, . Seek each one out and see if the ancestors remain. Visit Sunspring Post to the north, visit the Laughing Skull Ruins far to the north against the mountains, visit Garadar to the northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and the Terokkar Forest, to the east. Return to me once you have observed the ancestors in their homes.",starts={{npcID=18687,x=0.26,y=0.606,zoneID=3518}},ends={{npcID=18687,x=0.26,y=0.606,zoneID=3518}},coords={x=0.26,y=0.606,source="quest_giver",zoneID=3518},questType="standard"},
[10086] = {id=10086,name="I Work... For the Horde!",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Would you believe it? These orcs hired me to help them shore up damaged fortifications and build explosives. What a dream job! It's too bad we're so short on materials, but a clever goblin like myself learns how to make do! Can you help me? I need salvaged wood and metal from the ruined battlements along the Path of Glory. Go down there and salvage, and watch out for those red-skinned orcs! When you're done, come back for big rewards!",starts={{npcID=21283,x=0.552,y=0.386,zoneID=3483}},ends={{npcID=21283,x=0.552,y=0.386,zoneID=3483}},coords={x=0.552,y=0.386,source="quest_giver",zoneID=3483},questType="standard"},
[10087] = {id=10087,name="Burn It Up... For the Horde!",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="I'm a lucky, lucky goblin. I get to make explosives and killing machines, knowing they'll be used immediately on important missions! Speaking of missions, I just got one from Thrallmar command: burn the Alliance cannons on the far side of the Path of Glory... the ones pointing dangerously close to Horde fortifications. Take this torch and make your way to each cannon. Fire the torch and watch the sparks fly!",starts={{npcID=21283,x=0.552,y=0.386,zoneID=3483}},ends={{npcID=21283,x=0.552,y=0.386,zoneID=3483}},coords={x=0.552,y=0.386,source="quest_giver",zoneID=3483},questType="standard"},
[10093] = {id=10093,name="The Temple of Telhamat",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Fortunately, the Path of Glory is not the only trace of my people in these lands. To the west, a few of our holy sites survive, although some have been overrun. While Velen prepared for the journey that would lead him to Azeroth, those of us who would remain behind sought to reestablish a presence at our holy places. In the western part of the Hellfire Peninsula , you will find a small group of draenei at the Temple of Telhamat, led by Amaan the Wise . I am certain he'd be interested in meeting you.",starts={{npcID=16839,x=0.566,y=0.664,zoneID=3483}},ends={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},coords={x=0.566,y=0.664,source="quest_giver",zoneID=3483},questType="standard"},
[10096] = {id=10096,name="Saving the Sporeloks",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="Ikeyen's been telling me stories about what happened to him down in those caves and I think it's just awful! You know, maybe we should do something to help out those poor sporeloks. Ikeyen says that they live there in the Funggor Cavern, but that the marsh beasts have recently invaded. Why don't you go down there and see if you can clear some of those marsh beasts out? It's just to the southwest.",starts={{npcID=17909,x=0.802,y=0.642,zoneID=3521}},ends={{npcID=17909,x=0.802,y=0.642,zoneID=3521}},coords={x=0.802,y=0.642,source="quest_giver",zoneID=3521},questType="standard"},
[10099] = {id=10099,name="The Mastermind",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Those infernal gan'arg keep scurrying into the mine! For each one you kill, two or three more seem to take its place! There's got to be someone down there in the deepest reaches of the mine directing the incursion. You seemed to do well against them last time, and Light knows you're the only one brave enough to venture back into the mine. Find out who's responsible for this disturbance and make him pay!",starts={{npcID=16837,x=0.52,y=0.624,zoneID=3483}},ends={{npcID=16837,x=0.52,y=0.624,zoneID=3483}},coords={x=0.52,y=0.624,source="quest_giver",zoneID=3483},questType="standard"},
[10101] = {id=10101,name="When Spirits Speak",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Oshu'gun - the diamond mountain - was once sacred to my people. It was there that the clans would gather every year to celebrate the springtime festival. It was there that our shaman communed with the honored ancestors. It was the center of our culture - until the shadows overtook us. When the clans became a horde, the spirits of Oshu'gun fell silent. The ancestors turned their backs on us. Yet something now draws them from their rest. Venture to Oshu'gun and discover what could trouble the spirits so.",starts={{npcID=18687,x=0.26,y=0.606,zoneID=3518}},ends={{npcID=17545,x=0.354,y=0.776,zoneID=3518}},coords={x=0.26,y=0.606,source="quest_giver",zoneID=3518},questType="standard"},
[10102] = {id=10102,name="A Secret Revealed",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3703,description="As my energies bled away over the centuries, a void slowly grew in my place - devouring the souls of those nearby. Helplessly, I watched as generations of orc souls were drawn into the vortex. Recently, my enemies harnessed the vortex and used it to draw countless void minions into their Burning Legion. Now, the key to ending this cycle and freeing the orc spirits lies with another naaru - A'dal . I have sensed his essence within the ancient city of Shattrath in the Terokkar Forest.",starts={{npcID=17545,x=0.354,y=0.776,zoneID=3518}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.354,y=0.776,source="quest_giver",zoneID=3518},questType="standard"},
[10103] = {id=10103,name="Report to Zurai",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="With the arrival of Field Commander Romus and his forces, the Alliance and their draenei friends have grown bold. They're militarizing every old draenei ruin from here to Shattrath. In response, the trolls have established a new outpost in the eastern part of Zangarmarsh , just south of the Dead Mire. Swamprat Post, they're calling it. I'm glad they have a sense of humor about living in a place like that, because I wouldn't relish it. The post's commander has asked me to send anyone I can spare.",starts={{npcID=16789,x=0.284,y=0.602,zoneID=3483}},ends={{npcID=18011,x=0.852,y=0.546,zoneID=3521}},coords={x=0.284,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[10104] = {id=10104,name="Concerns About Tuurem",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="The rumors from Tuurem are unsettling. Some say the town's ruins are overrun with crazed Broken and Lost Ones, while opportunistic artifact hunters steal draenei relics. It's hard to know which are true and which aren't, but we have a responsibility to safeguard the ruins as best we can. Find Andarl at the Allerian Stronghold in Terokkar Forest . He is something of a student of magical relics. More than anyone else, he's likely to know what's going on there.",starts={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},ends={{npcID=18252,x=0.584,y=0.536,zoneID=3519}},coords={x=0.418,y=0.272,source="quest_giver",zoneID=3521},questType="standard"},
[10105] = {id=10105,name="News for Rakoria",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="Now that Swamprat Post is complete, our control of the roads in and out of the marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even so, at Stonebreaker Hold, Rakoria awaits word of our progress. She's sharp and capable, , but be careful around her. She's got a lot of goods she's eager to move along the roads, but don't assume she's got our best interests at heart. Rakoria goes where she believes there's profit to be found.",starts={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},ends={{npcID=18385,x=0.5,y=0.448,zoneID=3519}},coords={x=0.306,y=0.508,source="quest_giver",zoneID=3521},questType="standard"},
[10106] = {id=10106,name="Hellfire Fortifications",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The Hellfire Citadel wages constant battles with our forces. We are holding our own so far, but we can't yet launch a real offensive against them. To do that, we need forward staging areas. Our scouts identified three fortifications near Hellfire Citadel. We want you to help secure these forts. Capture each fort, and then report back to me. May fortune shine upon you in the conflicts ahead, , for you will no doubt clash with Horde forces eager to gain these same fortifications.",starts={{npcID=18266,x=0.564,y=0.628,zoneID=3483}},ends={{npcID=18266,x=0.564,y=0.628,zoneID=3483}},coords={x=0.564,y=0.628,source="quest_giver",zoneID=3483},questType="pvp"},
[10107] = {id=10107,name="Diplomatic Measures",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the southeast near the border of Terokkar. Good luck, ! Be warned, he is a blademaster...",starts={{npcID=18106,x=0.556,y=0.376,zoneID=3518}},ends={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},coords={x=0.556,y=0.376,source="quest_giver",zoneID=3518},questType="standard"},
[10108] = {id=10108,name="Diplomatic Measures",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="The huntress's agents send news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the east. Good luck, ! Be warned, he is a blademaster...",starts={{npcID=18223,x=0.546,y=0.722,zoneID=3518}},ends={{npcID=18261,x=0.738,y=0.626,zoneID=3518}},coords={x=0.546,y=0.722,source="quest_giver",zoneID=3518},questType="standard"},
[10109] = {id=10109,name="I Must Have Them!",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Do you see them?? By Gazlowe's horrific halitosis, I will have those eggs! Say, you look like you might be of some use. I'll tell you what, ; if you gather a few items for me to make my Jump-a-tron 4000 functional, I'll give you a key that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 you say? What can't you do is more like it... I'll need air elemental gas from the air elementals of Nagrand . They're all over the place so don't ask me where to find 'em!",starts={{npcID=19035,x=0.616,y=0.67,zoneID=3518}},ends={{npcID=19035,x=0.616,y=0.67,zoneID=3518}},coords={x=0.616,y=0.67,source="quest_giver",zoneID=3518},questType="standard"},
[10110] = {id=10110,name="Hellfire Fortifications",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="The fel orcs of Hellfire Citadel must be scoured from our birthland! To attack them, we must first secure forward staging points near the Citadel. Our outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them! We want you to stop the Alliance and capture these forts. Aid in the capture of each fort and then return to me. For the Horde!",starts={{npcID=18267,x=0.558,y=0.39,zoneID=3483}},ends={{npcID=18267,x=0.558,y=0.39,zoneID=3483}},coords={x=0.558,y=0.39,source="quest_giver",zoneID=3483},questType="pvp"},
[10111] = {id=10111,name="Bring Me The Egg!",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump.",starts={{npcID=19035,x=0.616,y=0.67,zoneID=3518}},ends={{npcID=19035,x=0.616,y=0.67,zoneID=3518}},coords={x=0.616,y=0.67,source="quest_giver",zoneID=3518},questType="standard"},
[10112] = {id=10112,name="A Personal Favor",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Hmmm? A box you say? Or was it several? Do you know what material the box was constructed from? And what was the name of this merchant? Empoor? Are you certain that he's one of the Broken? I don't do much business with their kind. Perhaps my memory would be jogged if you were to do me a favor? The Skithian arakkoa - primitive casters that they are - recently stole a huge shipment of my more exotic goods. I want it all back! You can find Veil Skith just to the south of Shattrath City.",starts={{npcID=18484,x=0.722,y=0.31,zoneID=3703}},ends={{npcID=18484,x=0.722,y=0.31,zoneID=3703}},coords={x=0.722,y=0.31,source="quest_giver",zoneID=3703},questType="standard"},
[10113] = {id=10113,name="The Nesingwary Safari",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="\"Go out and find us some supplies,\" he said. I was nearly killed about 15 times before I found this place! These Broken might not be the most hospitable bunch but at least they're not trying to tear my skin from my bones. Anyway, I'm not going back. My days of huntin' big game are over. If you end up heading northeast towards Zangarmarsh and run into the Nesingwary Safari, let them know that \"Shotgun\" quit. Hey, maybe you can take my place! Good luck, stranger.",starts={{npcID=19137,x=0.55,y=0.704,zoneID=3518}},ends={{npcID=18180,x=0.714,y=0.408,zoneID=3518}},coords={x=0.55,y=0.704,source="quest_giver",zoneID=3518},questType="standard"},
[10114] = {id=10114,name="The Nesingwary Safari",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="These orcs have never seen a tauren before - if you can believe such a thing. If it weren't for Captain Kroghan, they would have probably been serving me for their next meal right about now. But where are my manners? I am Ohlorn Farstrider , hunter extraordinaire! I am part of the Nesingwary expedition that came up here from Azeroth in search of big game. If you are interested in the hunt, perhaps you should visit my crew at the Nesingwary Safari, due east of here near the border of Zangarmarsh.",starts={{npcID=19133,x=0.554,y=0.374,zoneID=3518}},ends={{npcID=18200,x=0.716,y=0.406,zoneID=3518}},coords={x=0.554,y=0.374,source="quest_giver",zoneID=3518},questType="standard"},
[10115] = {id=10115,name="Daggerfen Deviance",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="The Kurenai and the draenei don't always see eye to eye, particularly on the issue of the Lost Ones. We are content to help the Lost Ones who seek us out, but we won't pursue them. Some draenei are intent on 'redeeming' them all. However, there are times when even the Lost Ones go too far, such as the Daggerfen. In their village to the west, they dabble in poisons and deceit, arts that come unnaturally to us. We must put an end to this before the vile Daggerfen can extend their influence.",starts={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},ends={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},coords={x=0.418,y=0.272,source="quest_giver",zoneID=3521},questType="standard"},
[10116] = {id=10116,name="WANTED: Chieftain Mummaki",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against the Orebor Harborage. The chieftain and his band of assassins are responsible for the deaths of numerous Kurenai and draenei and should only be approached by seasoned combatants. Travelers are advised to avoid the Daggerfen Village area to the west of the Orebor Harborage. To claim the bounty, present proof of the chieftain's demise to Ikuti .",starts={{npcID=183284,x=0.418,y=0.273,zoneID=3521}},ends={{npcID=18008,x=0.418,y=0.272,zoneID=3521}},coords={x=0.418,y=0.273,source="quest_giver",zoneID=3521},questType="standard"},
[10117] = {id=10117,name="WANTED: Chieftain Mummaki",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against Zabra'jin and its inhabitants. The chieftain and his band of assassins are responsible for the deaths of numerous scouts and messengers and should only be approached by seasoned combatants. Travelers are advised to avoid the Daggerfen Village area to the northwest of Zabra'jin. To claim the bounty, present proof of the chieftain's demise to Shadow Hunter Denjai .",starts={{npcID=182165,x=0.32,y=0.494,zoneID=3521}},ends={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},coords={x=0.32,y=0.494,source="quest_giver",zoneID=3521},questType="standard"},
[10118] = {id=10118,name="Message to the Daggerfen",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="Of all the Lost One tribes in Zangarmarsh , the Daggerfen are the most cunning and most aggressive. They are highly organized and make no secret of the fact that they desire control over the other Lost Ones in the marsh. Their attacks have already taken quite a toll on my scouts and messengers. I cannot afford to lose any more men. If we don't act soon, they'll have complete control over the roads and Zabra'jin will effectively be surrounded.",starts={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},ends={{npcID=18013,x=0.306,y=0.508,zoneID=3521}},coords={x=0.306,y=0.508,source="quest_giver",zoneID=3521},questType="standard"},
[10120] = {id=10120,name="Arrival in Outland",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Aided by the Alliance, my forces will hold the line here, but I need you to deliver my report to General Krakork in Thrallmar. With his help, we'll be able to drive these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather . She'll speed you on your way.",starts={{npcID=19253,x=0.874,y=0.498,zoneID=3483}},ends={{npcID=18930,x=0.874,y=0.482,zoneID=3483}},coords={x=0.874,y=0.498,source="quest_giver",zoneID=3483},questType="standard"},
[10121] = {id=10121,name="Eradicate the Burning Legion",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Though this land is full of strange new enemies, the Burning Legion is still the greatest threat to our Expedition. One of my most trusted warriors, Sergeant Shatterskull , has been studying the Legion's tactics - trying to discern the demons' true purpose in this land. Seek him out at the supply caravan just outside the southern wall. And - be wary of the Legion. Their evil cannot be underestimated.",starts={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=19256,x=0.58,y=0.412,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[10123] = {id=10123,name="Felspark Ravine",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground. They have stationed dreadlords in Felspark Ravine, east of here. They are responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.",starts={{npcID=19256,x=0.58,y=0.412,zoneID=3483}},ends={{npcID=19256,x=0.58,y=0.412,zoneID=3483}},coords={x=0.58,y=0.412,source="quest_giver",zoneID=3483},questType="standard"},
[10124] = {id=10124,name="Forward Base: Reaver's Fall",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Your battle prowess has been noted by high command, . They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in... Head east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Forward Commander To'arch . Now move out!",starts={{npcID=19256,x=0.58,y=0.412,zoneID=3483}},ends={{npcID=19273,x=0.658,y=0.436,zoneID=3483}},coords={x=0.58,y=0.412,source="quest_giver",zoneID=3483},questType="standard"},
[10129] = {id=10129,name="Mission: Gateways Murketh and Shaadraz",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="We've identified the two main transporters that the Burning Legion are using to bring in reinforcements: Gateway Murketh and Gateway Shaadraz. If you look east up the Path of Glory, you'll see them on either side of the road. I want you to bomb them both into oblivion! Here are the bombs you'll use, specially designed by a goblin in Area 52. Now, speak with Wing Commander Brack -- he'll put you on a wyvern.",starts={{npcID=19273,x=0.658,y=0.436,zoneID=3483}},ends={{npcID=19273,x=0.658,y=0.436,zoneID=3483}},coords={x=0.658,y=0.436,source="quest_giver",zoneID=3483},questType="standard"},
[10132] = {id=10132,name="Colossal Menace",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="You see that huge red crystal to the north? It fell from the sky not long ago, causing a massive earthquake. When we came out here to investigate the disturbance, we found all of these colossi wandering about that weren't previously here. There's definitely something strange about that crystal and the energies that it's emanating, but I don't have time for that. Those mountain giants are my immediate concern. I want you to head up to Fallen Sky Ridge and deal with them.",starts={{npcID=19293,x=0.156,y=0.52,zoneID=3483}},ends={{npcID=19293,x=0.156,y=0.52,zoneID=3483}},coords={x=0.156,y=0.52,source="quest_giver",zoneID=3483},questType="standard"},
[10134] = {id=10134,name="Crimson Crystal Clue",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="As the colossus falls under the weight of your attacks, you notice for the first time that it was holding a red crystal fragment. While it was small and unnoticeable in the mountain giant's hand, it's a fairly hefty piece for you to carry around. It also suspiciously looks like it's a piece of the giant crystal in the middle of the ridge. It's most definitely a clue as to the strangeness that is occurring here, and you're sure that the druids at the Cenarion Post to the south will want to see it.",ends={{npcID=19293,x=0.156,y=0.52,zoneID=3483}},questType="standard"},
[10136] = {id=10136,name="Cruel's Intentions",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Magister Bloodhawk finally deciphered the Legion missive you found earlier. It turned out to be attack plans sent by one of Highlord Kazzak's lieutenants - Arazzius the Cruel . Apparently, Arazzius commands the Legion ground forces in Hellfire. The time has come to terminate his command, . Terminate with extreme prejudice. Head west to the Pools of Aggonar and put an end to this so-called 'Legion lord'. Today, the Horde reclaims Hellfire Peninsula . Let the Legion be damned.",starts={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[10140] = {id=10140,name="Journey to Honor Hold",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="When you're ready, I'll arrange a flight straight to Honor Hold. From there, speak with Marshal Isildor and give him Duron's report . He'll be happy to see another recruit from the homelands, and I'm sure the information in that report is important stuff!",starts={{npcID=18931,x=0.874,y=0.524,zoneID=3483}},ends={{npcID=19308,x=0.546,y=0.626,zoneID=3483}},coords={x=0.874,y=0.524,source="quest_giver",zoneID=3483},questType="standard"},
[10141] = {id=10141,name="The Legion Reborn",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="While the Burning Legion invaded Azeroth, they were also at work here, in Outland. We have tracked their movements over the years, but this latest activity, - well, this is beyond anything we've seen. Seek out Sergeant Altumus near the eastern supply caravan. She has been monitoring the invaders and may have insights into their purpose. Be swift - and take care, - the Burning Legion is not to be underestimated.",starts={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},ends={{npcID=19309,x=0.616,y=0.608,zoneID=3483}},coords={x=0.566,y=0.666,source="quest_giver",zoneID=3483},questType="standard"},
[10142] = {id=10142,name="The Path of Anguish",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground. They have stationed dreadlords at the Path of Anguish, east of here. They are the ones responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.",starts={{npcID=19309,x=0.616,y=0.608,zoneID=3483}},ends={{npcID=19309,x=0.616,y=0.608,zoneID=3483}},coords={x=0.616,y=0.608,source="quest_giver",zoneID=3483},questType="standard"},
[10143] = {id=10143,name="Expedition Point",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Your battle prowess has been noted by high command, . They want to send you to the front lines to meet up with Rohamus's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in... Head east about 400 paces, across the Valley of Bones, until you run into a destroyed fel reaver. You'll see Expedition Point where a Legion base used to stand. Once there, you are to report to Forward Commander Kingston . Now move out!",starts={{npcID=19309,x=0.616,y=0.608,zoneID=3483}},ends={{npcID=19310,x=0.712,y=0.626,zoneID=3483}},coords={x=0.616,y=0.608,source="quest_giver",zoneID=3483},questType="standard"},
[10144] = {id=10144,name="Disrupt Their Reinforcements",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="You'll find the Legion front to our northeast, and spaced along it are portals used to gather reinforcements from throughout Outland. We, , are going to destroy those portals! Take this primer. Designed in Area 52, it uses the demons' own power as an explosive device! Defeat Legion forces around Portals Grimh and Kaalez to gather demonic rune stones , use the primer to detonate the stones inside the portals... then watch the fireworks!! Go, , and return to me when your mission is complete.",starts={{npcID=19310,x=0.712,y=0.626,zoneID=3483}},ends={{npcID=19310,x=0.712,y=0.626,zoneID=3483}},coords={x=0.712,y=0.626,source="quest_giver",zoneID=3483},questType="standard"},
[10146] = {id=10146,name="Mission: The Murketh and Shaadraz Gateways",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Just west of the Dark Portal are two huge transporters: Gateway Murketh and Gateway Shaadraz. If you look east up the Path of Glory, you'll see them on either side of the road. I want you to bomb them both into rubble! Here are the bombs you'll use, specially designed by a goblin in Area 52. Now, speak with Wing Commander Dabir'ee -- he'll put you on a gryphon and send you on your way.",starts={{npcID=19310,x=0.712,y=0.626,zoneID=3483}},ends={{npcID=19310,x=0.712,y=0.626,zoneID=3483}},coords={x=0.712,y=0.626,source="quest_giver",zoneID=3483},questType="standard"},
[10159] = {id=10159,name="Keep Thornfang Hill Clear!",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3521,description="We've been fighting an ongoing battle to keep the pass through Thornfang Hill to the west clear of ravagers. It would be bad if we were to become completely cut off from the refuge in Zangarmarsh. We don't want to displace the creatures, but there seems to be little choice as their attacks on travelers through the area have become more aggressive. Clear some of the ravagers out of there if you can.",starts={{npcID=16888,x=0.158,y=0.522,zoneID=3483}},ends={{npcID=16888,x=0.158,y=0.522,zoneID=3483}},coords={x=0.158,y=0.522,source="quest_giver",zoneID=3483},questType="standard"},
[10160] = {id=10160,name="Know your Enemy",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner - more cunning than the brutes we're familiar with. If these rumors are true then our forces, already stretched, may be taxed beyond their limit. I have entrusted my lieutenant, Amadi, with investigating this matter. If you would help us in this dark hour, seek her out. She is stationed at the broken tower just west of the Hold. And - be careful out there. You're heading into a dangerous new world.",starts={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},ends={{npcID=16820,x=0.51,y=0.602,zoneID=3483}},coords={x=0.566,y=0.666,source="quest_giver",zoneID=3483},questType="standard"},
[10161] = {id=10161,name="In Case of Emergency...",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="In the event of an emergency, it's always the pilot's job to keep a level head, especially when the only orders your co-pilot follows come from his stomach. The good news is that we won't need to wait days for replacement parts to be imported. The bad news is that the \"spare\" parts got scattered from here to the Valley of Bones to the east. The other bad news? The spare parts aren't so spare. They, uh, fell off during our rapid descent. Could you help me collect enough to get us off the ground again?",starts={{npcID=19367,x=0.49,y=0.748,zoneID=3483}},ends={{npcID=19367,x=0.49,y=0.748,zoneID=3483}},coords={x=0.49,y=0.748,source="quest_giver",zoneID=3483},questType="standard"},
[10162] = {id=10162,name="Mission: The Abyssal Shelf",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Now that you've got your wings, perhaps you'd be interested in running another bombing mission? This time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a wyvern and destroy the whole damned thing! Here are your bombs - now, talk to Wing Commander Brack when you're ready for takeoff.",starts={{npcID=19273,x=0.658,y=0.436,zoneID=3483}},ends={{npcID=19273,x=0.658,y=0.436,zoneID=3483}},coords={x=0.658,y=0.436,source="quest_giver",zoneID=3483},questType="standard"},
[10163] = {id=10163,name="Mission: The Abyssal Shelf",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Now that you've got your wings, perhaps you'd be interested in running another bombing mission? This time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a gryphon and destroy the whole damned thing! Here are your bombs - now, talk to Gryphoneer Windbellow when you're ready for takeoff.",starts={{npcID=20232,x=0.792,y=0.338,zoneID=3483}},ends={{npcID=20232,x=0.792,y=0.338,zoneID=3483}},coords={x=0.792,y=0.338,source="quest_giver",zoneID=3483},questType="standard"},
[10166] = {id=10166,name="Whitebark's Memory",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3430,description="This pendant brings back memories of a different time. A better time. Unfortunately, memories are the last thing I need right now. I want you to bury this by the runestone in the Scorched Grove. It was there that I first met the treant elder. Put my old friend's memory to rest.",starts={{npcID=15398,x=0.34,y=0.8,zoneID=3430}},ends={{npcID=19456,x=0.374,y=0.862,zoneID=3430}},coords={x=0.34,y=0.8,source="quest_giver",zoneID=3430},questType="standard"},
[10167] = {id=10167,name="Auchindoun...",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3790,description="Deep within the Auchenai Crypts is a tomb: A tomb unlike any that exists on this shattered realm. It was from this tomb, the first tomb, that the vast mausoleum of Auchindoun was born. You must venture to the Auchenai Crypts of Auchindoun and find this tomb. Slay the guardian of the crypt to release the captive spirit within. The spirit holds the key...",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[10168] = {id=10168,name="What the Soul Sees",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="For several centuries, the spirits of Auchindoun coalesced into my darkened essence. Many of the catastrophes that befell this crypt were a direct result of my weakened state. Regrettably, there is nothing that can be done to stop this cycle. It is a facet of the naaru condition - without the void, the Light cannot exist. Your only recourse is to destroy the ancient spirits of Nagrand before they transform into creatures of the void. Use the soul mirrors found throughout this crypt to free them...",ends={{npcID=18687,x=0.26,y=0.606,zoneID=3518}},questType="standard"},
[10170] = {id=10170,name="Return to the Greatmother",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Return to Greatmother Geyah at Garadar with news of your victory, . This will surely lift the spirits of the Mag'har. Perhaps even the young Hellscream will be lifted from his malaise.",starts={{npcID=18687,x=0.26,y=0.606,zoneID=3518}},ends={{npcID=18141,x=0.566,y=0.342,zoneID=3518}},coords={x=0.26,y=0.606,source="quest_giver",zoneID=3518},questType="standard"},
[10171] = {id=10171,name="The Inconsolable Chieftain",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="You have done so much for the Mag'har, . Your accomplishments are known to all, including Garrosh . Go to him now and tell him of your latest victory. Tell him that you do what you do for him and his people. Surely he will be lifted by your words.",starts={{npcID=18141,x=0.566,y=0.342,zoneID=3518}},ends={{npcID=18063,x=0.554,y=0.376,zoneID=3518}},coords={x=0.566,y=0.342,source="quest_giver",zoneID=3518},questType="standard"},
[10172] = {id=10172,name="There Is No Hope",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="You are an honorable , . You have done much for the Mag'har. No one could ever deny your service to my people. Alas, the time of the Mag'har is at an end. You have shown me, more than anything, that I am unfit to lead these people. My cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn the orcs. Please, , return to the Greatmother and tell her what I have told you. I am too ashamed to see her... to look into her eyes.",starts={{npcID=18063,x=0.554,y=0.376,zoneID=3518}},ends={{npcID=18141,x=0.566,y=0.342,zoneID=3518}},coords={x=0.554,y=0.376,source="quest_giver",zoneID=3518},questType="standard"},
[10173] = {id=10173,name="The Archmage's Staff",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Allow me to introduce myself, . I am Ravandwyr , apprentice to the Archmage Vargoth. My master is... indisposed, shall we say. I am here on a matter of great importance. The Arklon Ruins southeast of the city are a hotbed of Burning Legion activity. Their purpose in the ruins concerns neither me nor my master, but their leader, Ekkorash, possesses the archmage's staff. This conjuring powder will allow you to draw the demon out of hiding. Sprinkle it on the brazier at the center of the ruins.",starts={{npcID=19217,x=0.314,y=0.662,zoneID=3523}},ends={{npcID=19217,x=0.314,y=0.662,zoneID=3523}},coords={x=0.314,y=0.662,source="quest_giver",zoneID=3523},questType="standard"},
[10174] = {id=10174,name="Curse of the Violet Tower",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Now, you will be able to use the archmage's staff to contact him. He resides in the Violet Tower, on an 'island' to the southeast. The tower is both sanctuary and prison to him, cursed as it is. Kirin Tor can neither enter nor leave, keeping me apart from my master. The staff's magic can penetrate the tower's defenses, but only if invoked by one outside the Kirin Tor. Take the archmage's staff and use it to conjure his image. Tell him what has happened and that I have not completely failed him.",starts={{npcID=19217,x=0.314,y=0.662,zoneID=3523}},coords={x=0.314,y=0.662,source="quest_giver",zoneID=3523},questType="standard"},
[10176] = {id=10176,name="Ar'kelos the Guardian",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4395,description="Now that you've gathered all the items I'll need to break Kael'thas's curse, one thing remains to be done. When Kael'thas sealed the tower, he placed an arcane golem, known as Ar'kelos , at the bottom of the tower. You must defeat Ar'kelos in order allow me to work magic within the tower again. When you enter the Violet Tower, the curse will begin to affect you. Once you have defeated Ar'kelos , ascend the tower and assist me in making preparations for the ritual.",ends={{npcID=19481,x=0.582,y=0.864,zoneID=3523}},questType="standard"},
[10180] = {id=10180,name="Can't Stay Away",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3791,description="I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he's decided to venture out to Auchindoun again on his own. He was lucky enough to escape the Sethekk Halls once, but if they discover him, there won't be a second time. I admire his desire to free his sister, but he's not going to be able to do it without help. Find Isfar and have a word with him, . If you can't persuade him to come back, perhaps you could help him rescue Lakka?",starts={{npcID=19045,x=0.58,y=0.154,zoneID=3703}},coords={x=0.58,y=0.154,source="quest_giver",zoneID=3703},questType="standard"},
[10182] = {id=10182,name="Battle-Mage Dathric",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The sword is of exceptional quality, finely crafted and perfectly balanced for a battle-mage. The seal of the Kirin Tor and the name \"Dathric\" are engraved into the weapon's pommel. Turning the weapon over in your hands, you notice a sense of wrongness radiating from the metal, as if the item is torn between two worlds. Could this be the item anchoring Battle-Mage Dathric's spirit to this world? Perhaps returning it to its proper place can break the bond, freeing Dathric's spirit to rest at last.",ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},questType="standard"},
[10183] = {id=10183,name="Off To Area 52",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I'm out here studying the nether - the ethereal currents and all that. This is an ideal spot away from the lights and hubbub of town. Isn't this bridge great? If I could just keep this junk working. Hey, you know, if you're looking for work there's plenty at Area 52! It's just up the path and take a right at the fork in the road. Why don't you deliver my latest research notes to Rocket-Chief Fuselage ? I'm sure that he'd have plenty for you to do, what with the X-52 rocket ship, and all!",starts={{npcID=19569,x=0.218,y=0.556,zoneID=3523}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.218,y=0.556,source="quest_giver",zoneID=3523},questType="standard"},
[10184] = {id=10184,name="Malevolent Remnants",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Most of the spirits in the village are little more than pale remnants of Kirin Tor mages. They retain no knowledge of their former selves and wander the ruins in blind anger. It wasn't always like this, though. In the immediate aftermath of the attack, the spirits were restless, but not spiteful. With the passage of time they have only grown more aggressive. I dare not venture into the southern part of the village, for they will not spare even me. Quiet them and let us hope it will purge their anger.",starts={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10185] = {id=10185,name="A Fate Worse Than Death",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="After the blood elves leveled Kirin'Var Village, they started the construction of a large building to the northwest. Without the expertise of the archmage, we can't say for certain what's going on there. One thing is clear, though. The blood elf activities have unleashed a tide of ravenous mana elementals on the village. They seem drawn to the ruins of Wizard Row, wreaking further destruction. We cannot permit this to continue.",starts={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10186] = {id=10186,name="You're Hired!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Let me be the first to welcome you aboard, Junior Technician 3rd Grade ! We're building my masterpiece out here - the X-52 Nether-Rocket! But first we need to get all of the parts and fuel for it. That's where you come in. To start, I need crystals - LOTS of crystals - for the rocket's Etherlithium Engine Matrix. The draenei had crystals coming out of their ears! So head north to the Ruins of Enkaat and get them for me! Nevermind all of the draenei ghosts.",starts={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.326,y=0.644,source="quest_giver",zoneID=3523},questType="standard"},
[10188] = {id=10188,name="The Sigil of Krasus",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Before we departed Azeroth all those years ago, the Kirin Tor entrusted our expedition with a powerful artifact, the Sigil of Krasus . It was a great boon to us in our battle against the orcs and it could play a key role in helping me break the enchantment that imprisons me. However, when Kael'thas divested me of my possessions, he gave the sigil to Spellbinder Maryana, who remained behind with the garrison. If he truly realized what he had in his possession, he wouldn't have given it away so easily.",questType="standard"},
[10189] = {id=10189,name="Manaforge B'naar",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You may have noticed one of Kael's manaforges on your way here. You know, the large purple buildings sucking energy from the sky? We were sent here by the Sha'tar to investigate them. You can help our information gathering efforts by obtaining a personnel roster. Giving us an idea of who's there and what they do will prove to be invaluable information. We believe Captain Arathyn, leading a ballista team just outside of Manaforge B'naar, is in possession of one such roster. Obtain it for us.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10190] = {id=10190,name="Recharging the Batteries",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I have the very important task of collecting the machinery inside these ruins, but I'm having a problem keeping all of my bots charged up. The phase hunters - those wyrm-looking things - have lots of energy! You can find them all over the edges of this island, floating in from the nether. Fill the battery on this recharging blaster by using it on a phase hunter when they're very weak, and then finish it off to soak up the last of its energy.",starts={{npcID=19578,x=0.314,y=0.566,zoneID=3523}},ends={{npcID=19578,x=0.314,y=0.566,zoneID=3523}},coords={x=0.314,y=0.566,source="quest_giver",zoneID=3523},questType="standard"},
[10191] = {id=10191,name="Mark V is Alive!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Greetings, . I am charged up and fully functional. There are fragile draenei machines in these ruins, which I must retrieve. I am equipped with delicate servos in my wrist actuators, and the latest in combustion-pneumatic bump soakers. Handling them with care will not be an issue. However, the ghosts that haunt these ruins will likely attack, so I will need you and your friends along for protection.",starts={{npcID=19589,x=0.314,y=0.566,zoneID=3523}},ends={{npcID=19578,x=0.314,y=0.566,zoneID=3523}},coords={x=0.314,y=0.566,source="quest_giver",zoneID=3523},questType="group"},
[10192] = {id=10192,name="Krasus's Compendium",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The Kirin Tor sent one other of Krasus's possessions with our expedition. It was his spellbook, called Krasus's Compendium. Containing all the spells he mastered, it lent us a much-needed advantage in the war. Before Kael'thas and his forces laid siege to Kirin'Var, the compendium had been stolen from me by a rebellious apprentice intent on studying necromancy. The apprentice and his followers divided and studied the text in secret, locking themselves inside their houses in the southern part of town.",questType="standard"},
[10193] = {id=10193,name="High Value Targets",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Based on the roster information, we know that the brains of the manaforge operations are the warp-masters and warp-engineers. It is they who oversee the retrieval of a so called \"warp-energy\" by the manaforge and its delivery to a remote destination via a system of underground pipes. The only other specialists in the area are geologists. Everyone else is either part of the military or a magister crony; both easily replaced. Get in there and kill Kael's specialists; that's what'll hurt him the most.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10194] = {id=10194,name="Stealth Flight",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="While you were gone, my men uncovered another one of these manaforges. It is east of here and is known as Manaforge Coruu. Two of my best spies have arranged a secret landing spot outside of the manaforge. You are to help them infiltrate Kael's forces and obtain whatever information you can. Speak to Veronia just outside the city walls; she's arranged for a windrider that will take you to Manaforge Coruu. Once there, speak to Caledis Brightdawn; he will brief you on your mission.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=20162,x=0.338,y=0.642,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10197] = {id=10197,name="A Convincing Disguise",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Infiltrating the ranks of Kael's army will not be an easy task. With my knowledge of illusionary magic I could pass you off as one of Kael's followers, but there are certain details in their uniforms I could not replicate. Bring me a set of their robes, a pair of their gloves and a Sunfury guardsman medallion . This will make the results of my magic much more convincing.",starts={{npcID=19840,x=0.482,y=0.866,zoneID=3523}},ends={{npcID=19840,x=0.482,y=0.866,zoneID=3523}},coords={x=0.482,y=0.866,source="quest_giver",zoneID=3523},questType="standard"},
[10198] = {id=10198,name="Information Gathering",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I've prepared a uniform with the pieces you obtained. It is magically enhanced to complete the illusion. We spotted Commander Dawnforge going in to meet Arcanist Ardonis a few minutes ago. He had a full retinue of guards with him, so whatever they're discussing is bound to be incredibly important; see if you can catch any of it. Oh, I almost forgot. You'll want to stay away from the arcane golems patrolling the manaforge. They will see right through the illusion.",starts={{npcID=19840,x=0.482,y=0.866,zoneID=3523}},ends={{npcID=19840,x=0.482,y=0.866,zoneID=3523}},coords={x=0.482,y=0.866,source="quest_giver",zoneID=3523},questType="standard"},
[10199] = {id=10199,name="That Little Extra Kick",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="So, I'm just missing the one ingredient that'll give my concoction that little extra kick that it needs. The sting of the nether rays, roaming around near the shaleskin flayers, delivers quite a punch. Bring me some of their stingers and I'll extract the venom right out of them! I'm certain the results will be explosive!",starts={{npcID=19617,x=0.322,y=0.638,zoneID=3523}},ends={{npcID=19617,x=0.322,y=0.638,zoneID=3523}},coords={x=0.322,y=0.638,source="quest_giver",zoneID=3523},questType="standard"},
[10200] = {id=10200,name="Return to Thalodien",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="It would be best if this information got back to Thalodien as soon as possible. I'll stay here and cover our tracks. It wouldn't do us much good to have Kael'thas find out what we were snooping around here. Secret information is always better if your enemy doesn't know you have it.",starts={{npcID=19840,x=0.482,y=0.866,zoneID=3523}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.482,y=0.866,source="quest_giver",zoneID=3523},questType="standard"},
[10201] = {id=10201,name="And Now, the Moment of Truth",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="The oil is finally ready for its first test. It seems heavy enough to serve as a high quality weapon oil. The only way to find out is to have a professional try it out. See Grek over there by the wanted posters? Sure, he's no poet, but the orc knows his way around a weapon! Take a sample of the oil to him and ask him to use it on his weapon. After he's had a chance to test it out, let me know what he thinks of it.",starts={{npcID=18385,x=0.5,y=0.448,zoneID=3519}},ends={{npcID=18385,x=0.5,y=0.448,zoneID=3519}},coords={x=0.5,y=0.448,source="quest_giver",zoneID=3519},questType="standard"},
[10202] = {id=10202,name="A Defector",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We've recently been contacted by a Sunfury magister who wishes to join our ranks and swears he has information we're in need of. We've checked our informants to make sure he's not a double agent and he checks out. He's stationed in Manaforge Ara which makes communication difficult. Talk to him and see what he knows. If he's half as useful as he claims to be, we'll be able to put him to good use.",starts={{npcID=19469,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=20920,x=0.262,y=0.416,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10203] = {id=10203,name="Invaluable Asset Zapping",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="See the fissure running through Area 52? We did that! It's yielding up all sorts of goodies for the X-52 Nether-Rocket, but we're running short on equipment. We had an operation at the Arklon Ruins to the southeast until the Burning Legion moved in. I need you to take this Ultra Deconsolodation Zapper to the ruins. Use it to beam our gear back to Lead Sapper Blastfizzle down in the fissure. Junior Technician 3rd Grade , this is your chance for that promotion. Don't blow it!",starts={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},ends={{npcID=19634,x=0.34,y=0.68,zoneID=3523}},coords={x=0.326,y=0.644,source="quest_giver",zoneID=3523},questType="standard"},
[10204] = {id=10204,name="Bloodgem Crystals",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Kael's magisters have refined their usage of mana crystals to the point where they can siphon large amounts of energy in a matter of seconds. They do this by attuning smaller bloodgem crystal shards to larger, fully charged ones. Go to Manaforge B'naar and obtain one of these shards from a Sunfury magister and use it to siphon energy from one of the larger crystals. Return to me so that I may study the effects of the aura. Do not worry; any side effects should be temporary.",starts={{npcID=19469,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19469,x=0.32,y=0.64,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10205] = {id=10205,name="Warp-Raider Nesaad",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Warp-Raider Nesaad must be dealt with! I have no idea how he survived my attack, but he cannot be allowed to continue his operation out there. Go back and take out Nesaad. He keeps a small ethereal camp near the southwestern corner of the Heap. Don't fail like I did, .",starts={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},ends={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},coords={x=0.324,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10206] = {id=10206,name="Pick Your Part",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Those ethereal clowns are as opportunistic as us, I'll give them that. But no one, and I mean NO ONE, moves in on a B.O.O.M. claim! The Heap to the south is ours! If we're to finish the X-52 Nether-Rocket, we're going to need all of the new tech that we can get our hands on. And since the ethereals are stealing from us, I think it's only fair that we repay them in kind. Why don't you head down there and see if you can acquire some of their technology out from under their noses!",starts={{npcID=19645,x=0.328,y=0.646,zoneID=3523}},ends={{npcID=19645,x=0.328,y=0.646,zoneID=3523}},coords={x=0.328,y=0.646,source="quest_giver",zoneID=3523},questType="standard"},
[10208] = {id=10208,name="Disrupt Their Reinforcements",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Directly east of here is the Legion Front. Spaced across the front are infernal portals and gateways, used to bring reinforcements to Hellfire Peninsula and throughout Outland. We're going to destroy those portals! Take these primers. Designed in Area 52, they use the demons' own power as an explosive! Defeat Legion forces around Portals Xilus and Kruul to gather demonic rune stones , use the primer to detonate four stones inside the portals, and watch! Return to me when your mission is complete.",starts={{npcID=19273,x=0.658,y=0.436,zoneID=3483}},ends={{npcID=19273,x=0.658,y=0.436,zoneID=3483}},coords={x=0.658,y=0.436,source="quest_giver",zoneID=3483},questType="standard"},
[10209] = {id=10209,name="Summoner Kanthin's Prize",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The next thing we must do is reclaim my familiar, Glacius, from the blood elf summoner who holds it captive. Summoner Kanthin was one of the most senior magisters in the force Kael'thas sent to decimate Kirin'Var. It's only natural that he would claim my familiar as a kind of trophy. I'm certain that Kanthin, fool that he is, has tried to compel Glacius to serve him. My scrying has revealed that Kanthin is now stationed at 'Manaforge Duro,' if that terminology has any meaning for you.",questType="standard"},
[10210] = {id=10210,name="A'dal",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Welcome to Shattrath City, . This might be the one place in all of Outland where you'll find any semblance of safety. A group of naaru known as the Sha'tar drove the demons away from here. If you've never met a naaru, you ought to see A'dal inside the Terrace of Light. The leader of the Sha'tar is an awe-inspiring sight if I ever saw one. Sure is a change of pace from anything else in this bleak land.",starts={{npcID=19684,x=0.598,y=0.412,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.598,y=0.412,source="quest_giver",zoneID=3703},questType="standard"},
[10211] = {id=10211,name="City of Light",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Do not burden A'dal with petty inquisitions, . That just might be the most powerful being you ever come face to face with. You do not look familiar. I suppose you want to learn about the city? You'll have to excuse me if I don't give you a tour myself, but I'm a bit busy discussing strategy with A'dal. Perhaps you'll find a summoned servant acceptable in my stead? Excellent!",starts={{npcID=18166,x=0.546,y=0.44,zoneID=3703}},ends={{npcID=18166,x=0.546,y=0.44,zoneID=3703}},coords={x=0.546,y=0.44,source="quest_giver",zoneID=3703},questType="standard"},
[10213] = {id=10213,name="Investigate the Crash",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="When I was wounded in the wastes I saw a goblin zeppelin crash. It went down to the northwest, beyond the Expedition Armory. The zeppelin was on fire. Shrieking, burning goblins were falling like bombs from the sky. Of course I was in a lot of pain and I had lost a lot of blood. I may have imagined the whole thing. If you can find any survivors, we can offer them sanctuary here at Spinebreaker Post.",starts={{npcID=16858,x=0.61,y=0.816,zoneID=3483}},ends={{npcID=19367,x=0.49,y=0.748,zoneID=3483}},coords={x=0.61,y=0.816,source="quest_giver",zoneID=3483},questType="standard"},
[10220] = {id=10220,name="Make Them Listen",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="I was sent here to make contact with the Unyielding spirits. These once proud Alliance soldiers were defeated long ago, and now their cursed spirits haunt the ruins to the west. If they would only join us we would gain a powerful ally. Imagine, a legion of undying warriors to use against our enemies. But these undead are mad with hatred and will not listen to me. Perhaps they can be forced to join us.",starts={{npcID=19682,x=0.616,y=0.816,zoneID=3483}},ends={{npcID=19682,x=0.616,y=0.816,zoneID=3483}},coords={x=0.616,y=0.816,source="quest_giver",zoneID=3483},questType="standard"},
[10221] = {id=10221,name="Dr. Boom!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description=", my former protege, Sparky Uberthruster, wouldn't wear his helmet while down here and one day transformed into the infamous Dr. Boom ! And he stole off to the northeast with most of our sapping equipment! He and his Boom Bots have been a menace to Area 52 ever since. I need you to go to his Camp of Boom just outside of town and put an end to him! Use these Boom's Doom bombs to take him out. And make sure not to get too close to him or his Boom Bots!",starts={{npcID=19634,x=0.34,y=0.68,zoneID=3523}},ends={{npcID=19634,x=0.34,y=0.68,zoneID=3523}},coords={x=0.34,y=0.68,source="quest_giver",zoneID=3523},questType="standard"},
[10222] = {id=10222,name="The Sunfury Garrison",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="After Prince Kael'thas's forces destroyed the village and imprisoned the archmage in the Violet Tower, they withdrew to Sunfury Hold to the northeast. The very men who destroyed our village and slew our fellows toast their 'amazing victory' while we are helpless to avenge the fallen. We must not allow these crimes to go unanswered! Be the instrument of our vengeance, . Go to Sunfury Hold and claim the lives of those responsible for this crime.",starts={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10223] = {id=10223,name="Down With Daellis",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I'll never forget the blood elf who led the attack. He wore a tabard with a device I've never seen before, over top of crimson armor. He was ferocious and merciless, leading from the front where most other blood elf officers would never be seen. He was responsible for the deaths of many Kirin Tor mages that day, but he didn't linger long at Sunfury Hold. Kael'thas has ordered him to Manaforge Duro to aid in their attempt to control the area. Find him, , and silence his bow for good.",starts={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10224] = {id=10224,name="Essence for the Engines",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="As the X-52's chief of engineering, I have to see to it that the nether-rocket's main engines are in tip-top shape. Unfortunately, I haven't built them yet. , I'm in dire straits here! I have almost all of the parts. All that I'm missing is the engine core. Luckily for us, I think we can make use of the essence from the local mana wraiths to jump-start the engines. They can be found near most of the glowing trenches in the northern part of the island. Except for here in Area 52, of course.",starts={{npcID=19709,x=0.324,y=0.666,zoneID=3523}},ends={{npcID=19709,x=0.324,y=0.666,zoneID=3523}},coords={x=0.324,y=0.666,source="quest_giver",zoneID=3523},questType="standard"},
[10225] = {id=10225,name="Report to Engineering",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="! I need you to take all of these etherlithium crystals over to Chief Engineer Trep , my, uh, chief of engineering. He should know what to do with them. And if he doesn't, you see to it that he finds out!",starts={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},ends={{npcID=19709,x=0.324,y=0.666,zoneID=3523}},coords={x=0.326,y=0.644,source="quest_giver",zoneID=3523},questType="standard"},
[10226] = {id=10226,name="Elemental Power Extraction",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Darn it, that didn't do it! Ok, I've got another idea! I had Xyrol whip up an elemental power extractor . I'm not certain exactly what this power will do, but I know that I can use it. The sundered rumblers and warp aberrations on the ledge of the Crumbling Wastes to the south have just what I need for the engines! The extractor will change the form of their power into something solid that you'll be able to gather up after you've defeated them.",starts={{npcID=19709,x=0.324,y=0.666,zoneID=3523}},ends={{npcID=19709,x=0.324,y=0.666,zoneID=3523}},coords={x=0.324,y=0.666,source="quest_giver",zoneID=3523},questType="standard"},
[10227] = {id=10227,name="I See Dead Draenei",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="I see dead draenei. They're all around us. Bah, nobody believes me because I'm a child. Not even my own mommy believes me. Ha'lei points to Ramdor.> He believes me, though... He sees them too. Boy does he get angry about it! It's kind of funny. I see ghosts and people just smile and pat me on the head, trying to placate me. Ramdor sees ghosts and people label him as crazy. I sure hope I never grow up! You should probably talk to Ramdor before you go inside. He was once a death priest.",starts={{npcID=19697,x=0.35,y=0.652,zoneID=3519}},ends={{npcID=19417,x=0.352,y=0.662,zoneID=3519}},coords={x=0.35,y=0.652,source="quest_giver",zoneID=3519},questType="dungeon"},
[10228] = {id=10228,name="Ezekiel",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="I believe that the dead, which we have been caring for these last 500 odd years, should be left alone. Maladaar has other plans. He has retreated to the Crypt of Remembrance to start his experiments... Necromancy. I hope you weren't thinking about going in there... Not before helping me out so that these damned spirits will finally leave me alone. I know where they keep their treasures, . Got your attention, eh? Bring me the book of the dead, held by the Aldor, Ezekiel of Shattrath.",starts={{npcID=19417,x=0.352,y=0.662,zoneID=3519}},ends={{npcID=19715,x=0.508,y=0.34,zoneID=3703}},coords={x=0.352,y=0.662,source="quest_giver",zoneID=3519},questType="dungeon"},
[10229] = {id=10229,name="Decipher the Tome",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="This tome appears to be some sort of history written in a secret Alliance cipher. Althen, the historian in Spinebreaker Post, has studied the Unyielding for some time; he may be able to crack the Alliance code and decipher the book.",ends={{npcID=19736,x=0.616,y=0.816,zoneID=3483}},questType="standard"},
[10230] = {id=10230,name="The Battle Horn",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Perhaps we have taken the wrong approach to the Unyielding? The tome tells me the Expedition Armory was destroyed by orcs and death knights long ago. The Unyielding remain here as vengeful spirits trapped in an eternal battle against the fel orc clans. They think only of revenge. We must arrange for them to defeat their most hated enemies. Enter the Expedition Armory once again and find Lieutenant Commander Thalvos. He carries a battle horn that can summon the Unyielding. Bring it to me.",starts={{npcID=19736,x=0.616,y=0.816,zoneID=3483}},ends={{npcID=19736,x=0.616,y=0.816,zoneID=3483}},coords={x=0.616,y=0.816,source="quest_giver",zoneID=3483},questType="standard"},
[10231] = {id=10231,name="What Book? I Don't See Any Book.",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Ramdor? Hrm, let me think... Ramdor... Oh yes, the death priest. What does he want with the book? Well it doesn't matter. Yes I lied to you and no I don't have the book. Not anymore, anyway. It was stolen. Probably by one of those filthy refugees. Besides, Auchindoun is now defunct. We have no use for the book. If you find it, you can keep it. Like I said, I saw some of those ruffians snooping around the terrace last week. Start your search with them. They're probably playing dice in the slums.",starts={{npcID=19715,x=0.508,y=0.34,zoneID=3703}},ends={{npcID=19720,x=0.436,y=0.294,zoneID=3703}},coords={x=0.508,y=0.34,source="quest_giver",zoneID=3703},questType="dungeon"},
[10232] = {id=10232,name="In A Scrap With The Legion",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The Burning Legion has moved in on our claim at the Scrap Field down the path and across the bridge to the east. This could be a huge problem for us! With the Legion at the Arklon Ruins, and now there, it's starting to look bad for us - and the rocket project - here at Area 52. , I need you to go out there and deal with those demons! I'd do it, but I'm a lover, not a fighter. Yep, this is going to be trouble, I can feel it!",starts={{npcID=19645,x=0.328,y=0.646,zoneID=3523}},ends={{npcID=19645,x=0.328,y=0.646,zoneID=3523}},coords={x=0.328,y=0.646,source="quest_giver",zoneID=3523},questType="standard"},
[10233] = {id=10233,name="Torching Sunfury Hold",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Ridding Sunfury Hold of its garrison is not sufficient to keep the blood elves from reoccupying it. Kael'thas's followers are zealous and tenacious. Leaving them anything to use at Sunfury is effectively an invitation to return. No, it must all be destroyed. See to it that their tents and artillery burn to ashes! Steal torches from the Sunfury flamekeepers to accomplish your task, .",starts={{npcID=19489,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19489,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10234] = {id=10234,name="One Demon's Trash...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You look like a capable young ! I was wondering if you could lend me a hand? To the east is the Scrap Field, which the Burning Legion has moved into. It's full of huge fel reaver parts . There're also a whole bunch of smaller parts in there that they don't seem to care about. I want you to get in there and get me a lot of those smaller fel reaver parts !",starts={{npcID=19728,x=0.466,y=0.564,zoneID=3523}},ends={{npcID=19728,x=0.466,y=0.564,zoneID=3523}},coords={x=0.466,y=0.564,source="quest_giver",zoneID=3523},questType="standard"},
[10235] = {id=10235,name="Declawing Doomclaw",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You know what might just discourage them? Take out their leader! It seems to work everywhere else from what I've heard. And when they see a , such as yourself take out their leader... why, I bet they'll tuck tail and run for the hills! Get back in there and take out the big one they call Doomclaw. I hear he keeps himself in the eastern part of the Scrap Field underneath the pipe. Bring me his claw, too! Maybe we can make use of it.",starts={{npcID=19728,x=0.466,y=0.564,zoneID=3523}},ends={{npcID=19728,x=0.466,y=0.564,zoneID=3523}},coords={x=0.466,y=0.564,source="quest_giver",zoneID=3523},questType="standard"},
[10236] = {id=10236,name="Outland Sucks!",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="I can't believe I left Booty Bay to come to Outland. My cousin Screed Luckheed promised me I would make a fortune, but instead he flew off in his zeppelin and left me here to try to scrape a living out of this mine. How am I supposed to make a living here with helboars and demons and fel orcs attacking all the time? My shredder here was broken yesterday and the parts I need to fix it were stolen by fel orcs. They took the parts into the fissure to the southwest and may have dropped them there.",starts={{npcID=16915,x=0.512,y=0.306,zoneID=3483}},ends={{npcID=16915,x=0.512,y=0.306,zoneID=3483}},coords={x=0.512,y=0.306,source="quest_giver",zoneID=3483},questType="standard"},
[10237] = {id=10237,name="Warn Area 52!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description=", you have to get word back to Area 52 immediately! Hurry! Tell the rocket-chief that the Burning Legion is after us now!",starts={{npcID=19728,x=0.466,y=0.564,zoneID=3523}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.466,y=0.564,source="quest_giver",zoneID=3523},questType="standard"},
[10239] = {id=10239,name="Potential Energy Source",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We are not the only ones battling the influx of the mana beings. The blood elves, too, are troubled by them, but I'm not sure why. Whatever they're involved in over there, they don't seem to be stopping. Instead, I've seen them employ a variety of methods to kill the creatures. The most effective involves magical defenses fueled by some sort of concentrated energy. Capture some of these energy sources and bring them to me. Don't hesitate to stymie the elves if an opportunity presents itself.",starts={{npcID=19489,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19489,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10240] = {id=10240,name="Building a Perimeter",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We are prepared to try to construct a perimeter around the village using the energy source taken from the blood elves. I can't guarantee that it will work, but we have to attempt it. Otherwise, the mana creatures will surely continue devouring the spirits of the fallen Kirin Tor. Use this device at the small runes around the perimeter of town to release the energy there. If I've woven the field correctly, we should start noticing a difference once you've used the device at each point.",starts={{npcID=19489,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19489,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10241] = {id=10241,name="Distraction at Manaforge B'naar",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We were sent here by the Sha'tar to investigate the manaforges that Kael'thas' army is operating here. Unfortunately, the Scryers threaten to renege on their information-gathering duties unless we support them with military action. We can't afford to compromise this mission over politics, so we've agreed to weaken the manaforge's defenses so that the Scryers can do their work. Prove your loyalty to the Aldor and slay the Sunfury magisters and bloodwarders that guard Manaforge B'naar.",starts={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10242] = {id=10242,name="Spinebreaker Post",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description=", my equipment here is, unfortunately, not configured for all the tests I'd like to perform. However, my colleague at Spinebreaker Post, Apothecary Albreck , possesses the required implements. I have acquired a sample of Bleeding Hollow blood -- gained from a past mission of Thrallmar's agents. Take the sample to Albreck and allow him to study it. To reach Spinebreaker Post, speak with Wing Commander Brack, near the wyverns to the south.",starts={{npcID=21257,x=0.662,y=0.42,zoneID=3483}},ends={{npcID=21279,x=0.612,y=0.816,zoneID=3483}},coords={x=0.662,y=0.42,source="quest_giver",zoneID=3483},questType="standard"},
[10243] = {id=10243,name="Naaru Technology",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The Scryers obtained a personnel roster for Manaforge B'naar and are now having a field day picking out assassination targets. They've missed one small bit of information, scribbled on the side of the roster. It appeared to be a password or code like those used to access naaru-made technology like the Exodar or Tempest Keep. Go inside the manaforge and look for a control panel. Copy its readouts on this scroll as well as you can. We must confirm our suspicions about the origin of the technology.",starts={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=183770,x=0.232,y=0.681,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10245] = {id=10245,name="B'naar Console Transcription",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You try to transcribe the shapes as you see them flash across your eyes. The results are less than exact, but should serve as adequate evidence to prove or disprove the Aldor's suspicions.",starts={{npcID=183770,x=0.232,y=0.681,zoneID=3523}},ends={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},coords={x=0.232,y=0.681,source="quest_giver",zoneID=3523},questType="standard"},
[10246] = {id=10246,name="Attack on Manaforge Coruu",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Your success at Manaforge B'naar was quite noteworthy. I'm sure that Anchorite Karja will ask you for a repeat performance at Manaforge Coruu next. We've learned of a particularly important regiment of Sunfury arcanists and researchers being deployed there and I would like you to target them. Succeed and you will deliver a crushing blow against our enemy's forces.",starts={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10247] = {id=10247,name="Doctor Vomisa, Ph.T.",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="On the outskirts of town to the east are the Proving Grounds. Our top experimentalist, Doctor Vomisa, has been toying with a combination of fel reaver, ethereal, and of course, goblin technologies there. This is in no small part thanks to your gathering efforts Junior Technician 3rd Grade, ! Go to him; I know that he'll have a solution for saving Area 52. And since he's likely to use you as a test subject, if I were you, I'd bring some friends along just in case.",starts={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},ends={{npcID=19832,x=0.372,y=0.638,zoneID=3523}},coords={x=0.326,y=0.644,source="quest_giver",zoneID=3523},questType="group"},
[10248] = {id=10248,name="You, Robot",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Doctor Vomisa, Ph.T. at your service. Here, take this controller. I want you to activate it and give my newly-invented Scrap Reaver X6000 a spin. Just stay nearby! The controller is tied to my console here, and if you get too far away, the robot will cease to function. Try out everything... I'll be watching and calibrating its servos based upon your test run.",starts={{npcID=19832,x=0.372,y=0.638,zoneID=3523}},ends={{npcID=19832,x=0.372,y=0.638,zoneID=3523}},coords={x=0.372,y=0.638,source="quest_giver",zoneID=3523},questType="group"},
[10249] = {id=10249,name="Back to the Chief!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I'm certain that the rocket-chief is going to want to have a word or two with you! If I were you, I wouldn't hesitate to get back to Area 52 and speak with him!",starts={{npcID=19832,x=0.372,y=0.638,zoneID=3523}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.372,y=0.638,source="quest_giver",zoneID=3523},questType="standard"},
[10250] = {id=10250,name="Bloody Vengeance",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="East of here is an old destroyed Alliance siege tower. Now scavengers loot it for old nails and bits of scrap. Long ago, many Alliance warriors lost their lives at this tower and their banner was captured by Urtrak , a foul orc commander. Blow the Unyielding battle horn near the Alliance banner. This will get the attention of Urtrak . It may also summon forth warriors who fell in battle long ago.",starts={{npcID=19736,x=0.616,y=0.816,zoneID=3483}},ends={{npcID=19736,x=0.616,y=0.816,zoneID=3483}},coords={x=0.616,y=0.816,source="quest_giver",zoneID=3483},questType="standard"},
[10251] = {id=10251,name="The Master's Grand Design?",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="A couple of draenei paid us a visit last night. They'd somehow learned that we had the book in our possession and made a very generous offer to \"take it off our hands.\" We didn't ask them what they wanted with the book but the young one kept talking about \"the master's grand design,\" whatever that means. Look, I don't ask questions when money is in play. They gave us a lot of gold and we gave them the book. He said that they lived in Nagrand - in the old Abandoned Armory, north of Telaar.",starts={{npcID=19720,x=0.436,y=0.294,zoneID=3703}},ends={{npcID=19844,x=0.518,y=0.568,zoneID=3518}},coords={x=0.436,y=0.294,source="quest_giver",zoneID=3703},questType="dungeon"},
[10252] = {id=10252,name="Vision of the Dead",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3518,description="It has already begun. Levixus stands atop the ruins of Auchindoun and reads from the book of the dead. He calls the dead out by name and, through demonic ritual, binds the tortured souls to his will. He will raise all of Auchindoun if given the chance! But... you must first prepare. You cannot do battle with that which you cannot see. Bring me the items I require to brew the tincture. It will open your mind and allow you to see into the spirit world.",starts={{npcID=19844,x=0.518,y=0.568,zoneID=3518}},ends={{npcID=19844,x=0.518,y=0.568,zoneID=3518}},coords={x=0.518,y=0.568,source="quest_giver",zoneID=3518},questType="dungeon"},
[10253] = {id=10253,name="Levixus the Soul Caller",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Go now, . You will find Levixus on the uppermost ruins of Auchindoun. Enter there from the southern reaches of the Bone Wastes. He stands amidst a storm of souls... Destroy him and take the book of the dead . Once you have the cursed book in your possession, destroy it! Destroy it so that such an atrocity can never again be made possible.",starts={{npcID=19844,x=0.518,y=0.568,zoneID=3518}},ends={{npcID=19417,x=0.352,y=0.662,zoneID=3519}},coords={x=0.518,y=0.568,source="quest_giver",zoneID=3518},questType="dungeon"},
[10254] = {id=10254,name="Force Commander Danath",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Marshal Isildor spits in the dust.> Well, time to earn your pay. Report at once to Force Commander Trollbane within the keep. He and his advisors will no doubt be heartened to see you. Marshal Isildor salutes you stoically.> For the Alliance!",starts={{npcID=19308,x=0.546,y=0.626,zoneID=3483}},ends={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},coords={x=0.546,y=0.626,source="quest_giver",zoneID=3483},questType="standard"},
[10256] = {id=10256,name="Finding the Keymaster",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4395,description="In retrospect, I suppose I should've expected Kael'thas's magic to be this robust. He's always been a talented mage, but I've never seen anything like the power he wielded during the attack on the tower. The ward keeps me from being able to scry out the force holding it in place, but it doesn't preclude you from scrying. You'll require a focus, though. A crystal-bearing giant named Apex roams the plains to the west of Manaforge Duro. One of its crystals would make an excellent scrying focus.",starts={{npcID=19481,x=0.582,y=0.864,zoneID=3523}},ends={{npcID=19481,x=0.582,y=0.864,zoneID=3523}},coords={x=0.582,y=0.864,source="quest_giver",zoneID=3523},questType="group"},
[10257] = {id=10257,name="Capturing the Keystone",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3847,description="It doesn't surprise me that Kael'thas has put the key to this ward in the hands of someone like Commander Sarannis. Prince Kael'thas is a great many things, but he is no simpleton. In order to break this curse once and for all, you must enter Tempest Keep and claim the keystone . Only once the keystone has been destroyed will I regain my freedom.",starts={{npcID=19481,x=0.582,y=0.864,zoneID=3523}},ends={{npcID=19481,x=0.582,y=0.864,zoneID=3523}},coords={x=0.582,y=0.864,source="quest_giver",zoneID=3523},questType="dungeon"},
[10258] = {id=10258,name="Honor the Fallen",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Hogarth, the commander of the Armory, is in the eastern tower. You must report your victory over Urtrak to him. Perhaps he will be friendly? Of course he may try to consume your soul. One can never tell with spirits such as these. The Unyielding are still against us and will no doubt kill you if they can. Be careful .",starts={{npcID=19736,x=0.616,y=0.816,zoneID=3483}},ends={{npcID=19937,x=0.568,y=0.774,zoneID=3483}},coords={x=0.616,y=0.816,source="quest_giver",zoneID=3483},questType="standard"},
[10261] = {id=10261,name="WANTED: Annihilator Servo!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="WANTED: 1 Annihilator Servo to replace the failing one in my Long Neck Spectrum Analyzer. You and your friends might want to check with the blood elves at Manaforge B'naar to the west to see if they have any spares. They seem to have a few arcane annihilators roaming about. Please deliver the servo in pristine condition to Papa Wheeler at Area 52.",starts={{npcID=183811,x=0.321,y=0.647,zoneID=3523}},ends={{npcID=19645,x=0.328,y=0.646,zoneID=3523}},coords={x=0.321,y=0.647,source="quest_giver",zoneID=3523},questType="group"},
[10262] = {id=10262,name="A Heap of Ethereals",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="There is something else that I want your help with. A group of ethereals, known as the Zaxxis, have cut their relationship with the Consortium and gone into business for themselves. They've even cut deals with the Sunfury blood elves. This will not be tolerated! I infiltrated their group at the Heap to the south. But after I took out their leader, I had to escape here to Area 52. , go down there and bring back their insignias. Of course, not all wear them because they're cowards.",starts={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},ends={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},coords={x=0.324,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10263] = {id=10263,name="Assisting the Consortium",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things. Luck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured. There's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals. As a representative of the Aldor, I would like for you to help him in any way that you can.",starts={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10264] = {id=10264,name="Assisting the Consortium",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things. Luck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured. There's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals. As a representative of the Scryers, I would like for you to help him in any way that you can.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10265] = {id=10265,name="Consortium Crystal Collection",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Our leader, Nexus-Prince Haramad, has tasked me with the acquisition of a crystal artifact from the Arklon Ruins to the southeast. They're old draenei ruins. Unfortunately for both myself and the goblins here, the Burning Legion has decided to move in to perform their own excavation. If you're willing to help me, go to the ruins and take the crystal artifact from the dreadlord named Pentatharon.",starts={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},ends={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},coords={x=0.324,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10266] = {id=10266,name="Request for Assistance",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="While you were at the Arklon Ruins, I received a request for assistance from one of our representatives out in the field. It would appear that the Consortium is having some 'difficulties' in trying to recover property from the blood elves, which they refuse to pay for. Please head east out of Area 52 and cross the bridge to the next island over. You'll find my associate, Gahruj , at the Midrealm Post, just inside of Eco-Dome Midrealm.",starts={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},ends={{npcID=20066,x=0.466,y=0.568,zoneID=3523}},coords={x=0.324,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10267] = {id=10267,name="Rightful Repossession",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Our business relations with the blood elves appear to be at an end. A few weeks ago a large shipment of surveying equipment was delivered to them at Manaforge Duro. They have refused to pay for it. , I would ask that you pay the blood elves of Manaforge Duro to the east a visit. They appear to be having some trouble with an infestation of mana creatures there, so take advantage of their preoccupation. I care not what happens to them, but I would very much like to see the return of our property.",starts={{npcID=20066,x=0.466,y=0.568,zoneID=3523}},ends={{npcID=20066,x=0.466,y=0.568,zoneID=3523}},coords={x=0.466,y=0.568,source="quest_giver",zoneID=3523},questType="standard"},
[10268] = {id=10268,name="An Audience with the Prince",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Nexus-Prince Haramad has conveyed to me that he is interested in the immediate return of this property to him personally. I would greatly appreciate if you would deliver it in my stead. It is a great honor to gain an audience with the nexus-prince, and I am sure that he would be keenly interested in hearing the tales of your adventures here in the Netherstorm . Seek out his chamber atop the Stormspire to the north. He is often present as a holographic image, which you may address.",starts={{npcID=20066,x=0.466,y=0.568,zoneID=3523}},ends={{npcID=20084,x=0.458,y=0.36,zoneID=3523}},coords={x=0.466,y=0.568,source="quest_giver",zoneID=3523},questType="standard"},
[10269] = {id=10269,name="Triangulation Point One",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="There is another reason for the retrieval of the surveying equipment. There is a crystal from draenei legend of great importance to me. It is said that the crystal bestows god-like powers to its bearer! But it is in danger of being unearthed by others - namely the Burning Legion. , take the equipment and use it to find the first triangulation point. We know it to be somewhere to the east near Manaforge Ultris. Afterward, check-in with my agent, Dealer Hazzin , on the Manaforge Ultris island.",starts={{npcID=20084,x=0.458,y=0.36,zoneID=3523}},ends={{npcID=20092,x=0.584,y=0.314,zoneID=3523}},coords={x=0.458,y=0.36,source="quest_giver",zoneID=3523},questType="standard"},
[10270] = {id=10270,name="A Not-So-Modest Proposal",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="From the look on your face, I can tell you're a who appreciates a good profit. I've built a reputation as a dealer in exotic goods, and I'm about to launch a new venture. I need a reliable subcontractor to procure the goods from the Celestial Ridge. First, you'll need to re-energize a teleport pad. There is a spare power pack in Access Shaft Zeon, which is on the south side of Manaforge UItris. The Protectorate is operating in there, so you may be able to follow their tracers to your goal.",starts={{npcID=20071,x=0.582,y=0.316,zoneID=3523}},ends={{npcID=20518,x=0.712,y=0.39,zoneID=3523}},coords={x=0.582,y=0.316,source="quest_giver",zoneID=3523},questType="standard"},
[10271] = {id=10271,name="Getting Down to Business",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="As you've no doubt seen, the area is teeming with nether dragons in various stages of growth. All nether dragons, young and old, contain an essence that's highly desired by K -- err, by a client of mine. Most people aren't willing to risk their lives to gather it, so we've got the place to ourselves. You can start by gathering the essence from any of the creatures out here, but it's imperative that we start building a supply right away. Return to me once you have the first batch.",starts={{npcID=20518,x=0.712,y=0.39,zoneID=3523}},ends={{npcID=20154,x=0.708,y=0.388,zoneID=3523}},coords={x=0.712,y=0.39,source="quest_giver",zoneID=3523},questType="standard"},
[10272] = {id=10272,name="A Promising Start",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We've come here to investigate rumors of a strange breed of dragons, perhaps even descendents of Deathwing himself. These are clearly not ordinary black dragons, though. We'll know more once we've had a chance to examine their eggs. Their hatred for my flight runs deep, so I can't get close enough to gather the eggs. Will you agree to help?",starts={{npcID=20110,x=0.712,y=0.352,zoneID=3523}},ends={{npcID=20110,x=0.712,y=0.352,zoneID=3523}},coords={x=0.712,y=0.352,source="quest_giver",zoneID=3523},questType="standard"},
[10273] = {id=10273,name="Troublesome Distractions",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Your former employer, Wind Trader Marid , must've gotten wind that you're helping us now. Through my projection, I've seen his nether-stalkers entering the area, hoping to track us down. We've been able to evade them so far, but Marid must be dealt with before the problem grows more severe. If your impressions of Marid are correct, he'll do just about anything to secure the supply of his product. Return to him and tell him you're prepared to offer a deal. Lure him away and slay him.",starts={{npcID=20110,x=0.712,y=0.352,zoneID=3523}},ends={{npcID=20110,x=0.712,y=0.352,zoneID=3523}},coords={x=0.712,y=0.352,source="quest_giver",zoneID=3523},questType="standard"},
[10274] = {id=10274,name="Securing the Celestial Ridge",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The nether dragons have the same ferocious temperament as their black dragon forbears, but there is something entirely alien about them. They hatch and mature rapidly, harnessing the strange energies that forged their kind in the destruction of Draenor. There is so much more I need to know about them, but I believe the powers may be of use to my own flight. If we can displace the leader of these drakes, Veraku , with a show of dominance, we can cow the rest of them into submission.",starts={{npcID=20110,x=0.712,y=0.352,zoneID=3523}},ends={{npcID=20110,x=0.712,y=0.352,zoneID=3523}},coords={x=0.712,y=0.352,source="quest_giver",zoneID=3523},questType="group"},
[10275] = {id=10275,name="Triangulation Point Two",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I've recalibrated the triangulation device with the information that you provided from the first point. You'll use it in exactly the same manner to discover the second. All that I can tell you is that the second point is somewhere far to the west. Once you've located it, speak with Wind Trader Tuluman ; another of the nexus-prince's agents. He's posing as a weapon merchant at a small trading post next to the bridge, which leads to the island that Manaforge Ara is on.",starts={{npcID=20092,x=0.584,y=0.314,zoneID=3523}},ends={{npcID=20112,x=0.346,y=0.378,zoneID=3523}},coords={x=0.584,y=0.314,source="quest_giver",zoneID=3523},questType="standard"},
[10276] = {id=10276,name="Full Triangle",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="With the data from both the first and second points, I'm now certain that the crystal is at the top of the Ruins of Farahlon to the northeast. Unfortunately, the data indicates that the crystal is moving, which means that it has already been discovered, probably by the Burning Legion! Just in case, I recommend that you take some friends along. Slay the demon that has the crystal and return it to Nexus-Prince Haramad.",starts={{npcID=20112,x=0.346,y=0.378,zoneID=3523}},ends={{npcID=20084,x=0.458,y=0.36,zoneID=3523}},coords={x=0.346,y=0.378,source="quest_giver",zoneID=3523},questType="group"},
[10278] = {id=10278,name="The Warp Rifts",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Long have I wandered through Outland, searching for the truth of the void. Now I am old and weak. Perhaps you will help me? I must learn the secrets of the voidwalkers. You must find the Warp Fields to the west. West of the Expedition Armory there is a dark place on the edge of the abyss where time and space are weak. Use my unstable warp rift generator in the Warp Fields to create a warp rift. You must gather warp nether from the creatures that come through.",starts={{npcID=19683,x=0.618,y=0.814,zoneID=3483}},ends={{npcID=19683,x=0.618,y=0.814,zoneID=3483}},coords={x=0.618,y=0.814,source="quest_giver",zoneID=3483},questType="standard"},
[10280] = {id=10280,name="Special Delivery to Shattrath City",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="I am an ethereal of my word, . You have truly inspired me. I am now going to give you the ata'mal crystal to hand over to the naaru. As it was your heroics that made this possible, I wish for you to deliver it. You may use my personal teleporter to go directly to Shattrath City . Simply step through it and you will be transported there. Give the crystal to the naaru known as A'dal on the Terrace of Light. May the trade winds be at your back.",starts={{npcID=20084,x=0.458,y=0.36,zoneID=3523}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.458,y=0.36,source="quest_giver",zoneID=3523},questType="standard"},
[10281] = {id=10281,name="Formal Introductions",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Greetings, . Do not be alarmed. This is merely a projection of my current form. It's the only way my companion and I could keep watch without revealing ourselves. The ethereal who approached you, Marid, is little better than a swindler in the guise of a legitimate merchant. I'd like you to consider working with me instead. My purpose out here is to find out more about the unusual dragonkin on this ridge. Meet me at the north end of the ridge and we will discuss this further.",starts={{npcID=20154,x=0.708,y=0.388,zoneID=3523}},ends={{npcID=20110,x=0.712,y=0.352,zoneID=3523}},coords={x=0.708,y=0.388,source="quest_giver",zoneID=3523},questType="standard"},
[10286] = {id=10286,name="Arelion's Secret",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Arelion's journal does not deal with any sort of scholarly studies. It details his escapades with a young female blood elf! How could I've been such a fool? Unfortunately, the floozy's identity is not revealed in this journal. Aledis, a colleague of Arelion's, was his best friend and confidant. Go question him and find out who he was having this affair with. I saw Aledis leave Falcon Watch for Zangarmarsh. Follow the road headed north from town; it'll eventually lead west, toward Zangarmarsh.",starts={{npcID=16793,x=0.264,y=0.604,zoneID=3483}},ends={{npcID=20159,x=0.254,y=0.606,zoneID=3483}},coords={x=0.264,y=0.604,source="quest_giver",zoneID=3483},questType="standard"},
[10287] = {id=10287,name="The Mistress Revealed",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="I'm Arelion's friend, but I'm not going to take the beating of my life for him. His mistress is Viera Sunwhisper. Go tell that harpy of a wife of his. What's she going to do anyway?",starts={{npcID=20159,x=0.254,y=0.606,zoneID=3483}},ends={{npcID=16793,x=0.264,y=0.604,zoneID=3483}},coords={x=0.254,y=0.606,source="quest_giver",zoneID=3483},questType="standard"},
[10288] = {id=10288,name="Arrival in Outland",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="I want you to speak with Amish Wildhammer and catch the first flight to Honor Hold. When you arrive at Honor Hold, you'll be greeted by Marshal Isildor. I have prepared a report detailing our situation here. Give him the report, and tell him you're ready for duty. You have your orders, soldier, now move out! And though your blood must be burning to help us against the fiends below, waste no time here. Honor Hold needs you even more.",starts={{npcID=19229,x=0.874,y=0.506,zoneID=3483}},ends={{npcID=18931,x=0.874,y=0.524,zoneID=3483}},coords={x=0.874,y=0.506,source="quest_giver",zoneID=3483},questType="standard"},
[10289] = {id=10289,name="Journey to Thrallmar",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="When you're ready, I'll summon a wyvern to fly you to Thrallmar. Once you arrive, deliver Orion's report to General Krakork . Lok'tar ogar, - good luck.",starts={{npcID=18930,x=0.874,y=0.482,zoneID=3483}},ends={{npcID=19255,x=0.558,y=0.368,zoneID=3483}},coords={x=0.874,y=0.482,source="quest_giver",zoneID=3483},questType="standard"},
[10290] = {id=10290,name="In Search of Farahlite",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="To the northeast is an area called the Netherstone, a landmark not seen when this was a lush, green land. Newly-exposed crystal formations have shown us a mineral we've called farahlite in honor of this land's former identity. The tiny amount of farahlite we've mined has already proven popular with our clients. The highest grade of the mineral comes not from static deposits, but from the giants around the Netherstone. I can offer you a cut of the profits if you'll help supply the higher grade farahlite.",starts={{npcID=20067,x=0.44,y=0.36,zoneID=3523}},ends={{npcID=20067,x=0.44,y=0.36,zoneID=3523}},coords={x=0.44,y=0.36,source="quest_giver",zoneID=3523},questType="group"},
[10291] = {id=10291,name="Report to Nazgrel",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Though our warriors are without peer, our hold on this wasteland is still tenuous. Report to Nazgrel inside the barracks - he has need of agents... such as you. If we can't protect our holdings here, we'll be of no use to anyone. Now go!",starts={{npcID=19255,x=0.558,y=0.368,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.558,y=0.368,source="quest_giver",zoneID=3483},questType="standard"},
[10293] = {id=10293,name="Hitting the Motherlode",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Now that we've got a good baseline product, we're going to need something of higher quality. Certainly the farahlite we've gathered so far is nice, but I know there's better out there. We'll have to get a sample directly from Cragskaar, the patriarch of the Farahlon giants! You should be able to find it among the other giants in the Netherstone area. It's got huge pieces of farahlite jutting from its back and that's exactly what we need. Fell the giant and collect a farahlite core from it.",starts={{npcID=20067,x=0.44,y=0.36,zoneID=3523}},ends={{npcID=20067,x=0.44,y=0.36,zoneID=3523}},coords={x=0.44,y=0.36,source="quest_giver",zoneID=3523},questType="group"},
[10294] = {id=10294,name="Void Ridge",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="We have to improve my warp rift generator. You must take it to Void Ridge. Head east of here. You must avoid the foul fort of Zeth'Gor. To the east beyond Zeth'Gor is a small pass through the mountains. Through this pass you will find Void Ridge, a terrible place on the edge of the abyss. You must kill the walkers that you find there, and bring me shards of their souls. With their power we will improve upon the warp rift generator and open a portal to the beyond that cannot be closed.",starts={{npcID=19683,x=0.618,y=0.814,zoneID=3483}},ends={{npcID=19683,x=0.618,y=0.814,zoneID=3483}},coords={x=0.618,y=0.814,source="quest_giver",zoneID=3483},questType="standard"},
[10295] = {id=10295,name="From the Abyss",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="My warp rift generator is complete. You can now use it to summon a true prince of the void, a creature whose soul shard will tell us much of what lies beyond. Go south in Void Ridge and use my warp rift generator near the void stones. Look for a cluster of crystals near the edge of the abyss. A huge warp rift will form and Void Baron Galaxis will surely appear. Destroy this creature and bring me his soul shard.",starts={{npcID=19683,x=0.618,y=0.814,zoneID=3483}},ends={{npcID=19683,x=0.618,y=0.814,zoneID=3483}},coords={x=0.618,y=0.814,source="quest_giver",zoneID=3483},questType="standard"},
[10299] = {id=10299,name="Shutting Down Manaforge B'naar",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We cannot shut down the manaforges by force as we'd risk causing an explosion that would shake Outland to the core. According to your transcription, there is an emergency shutdown that permanently disables the technology - a safety mechanism common in naaru constructs. To perform this procedure you will have to obtain a crystal that will allow you to communicate with the console. This access crystal is in the possession of an overseer called Theredis according to our information.",starts={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10300] = {id=10300,name="Rebuilding the Staff",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Ravandwyr inspects the staff, noting that part of the headpiece seems to be missing.> Simply barbaric! Ekkorash must've taken the staff's crystalline headpiece for use in some other trinket, not realizing that it works in concert with the rest of the staff. As long as it remains broken, the staff's power is greatly diminished. With a suitable draenei crystal, I should be able to repair it. I've heard the goblins remarking about the crystals carried by the ghosts at the Enkaat Ruins to the north.",starts={{npcID=19217,x=0.314,y=0.662,zoneID=3523}},ends={{npcID=19217,x=0.314,y=0.662,zoneID=3523}},coords={x=0.314,y=0.662,source="quest_giver",zoneID=3523},questType="standard"},
[10301] = {id=10301,name="Unlocking the Compendium",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="While I'm glad to have most of Krasus's Compendium back, it's useless without the heliotrope oculus . You see, Krasus was well aware of the sheer power of the spells recorded in the book and took steps to safeguard them from prying eyes. Only a knowledgeable mage can use the oculus to unlock the compendium's secrets. During Kael'thas's attack, one of his lieutenants, Spellreaver Marathelle, looted it and took it to Sunfury Hold northeast of the tower. No doubt she thought it a pretty little bauble.",questType="standard"},
[10302] = {id=10302,name="Volatile Mutations",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="The irradiated power cores from the Exodar have been wreaking havoc on the environment here. The most obvious effect has been the appearance of the strange creatures that seem to have sprung up near them. There may be something we can do to help them, but now, their sheer numbers are becoming too much for us to handle. I'd like you to go out and cull their numbers somewhat, and perhaps I'll have another idea after giving it some thought.",starts={{npcID=16514,x=0.792,y=0.464,zoneID=3524},{npcID=16514,x=0.498,y=0.372,zoneID=6456}},ends={{npcID=16514,x=0.792,y=0.464,zoneID=3524},{npcID=16514,x=0.498,y=0.372,zoneID=6456}},coords={x=0.792,y=0.464,source="quest_giver",zoneID=3524},questType="standard"},
[10303] = {id=10303,name="The Blood Elves",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="You must eliminate... the blood elf... threat. Find out... what they're... up to! They're on the... ridge behind me.",starts={{npcID=16546,x=0.72,y=0.608,zoneID=3524},{npcID=16546,x=0.338,y=0.692,zoneID=6456}},ends={{npcID=16546,x=0.72,y=0.608,zoneID=3524},{npcID=16546,x=0.338,y=0.692,zoneID=6456}},coords={x=0.72,y=0.608,source="quest_giver",zoneID=3524},questType="standard"},
[10304] = {id=10304,name="Vindicator Aldar",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=6456,description="With your help, we were able to find a solution to our problems faster than I could have hoped. I don't have any other work for you to do. My apprentices and I can handle the rest. You should go speak with Vindicator Aldar on the other side of the ship.",starts={{npcID=16514,x=0.792,y=0.464,zoneID=3524},{npcID=16514,x=0.498,y=0.372,zoneID=6456}},ends={{npcID=16535,x=0.794,y=0.514,zoneID=3524},{npcID=16535,x=0.506,y=0.486,zoneID=6456}},coords={x=0.792,y=0.464,source="quest_giver",zoneID=3524},questType="standard"},
[10305] = {id=10305,name="Abjurist Belmara",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="This worn, sturdy tome is no spellbook, as you might expect a Kirin Tor mage to carry. The pages of the volume are covered with hand-copied stories, accompanied by colorful illustrations. The tome seems to be far older than its former owner and may have even been a family heirloom. A powerful tie to the book may have been the last thread tying Belmara's spirit to the ruins of Kirin'Var. Returning it to its proper place on the bookshelf in her quarters might help appease her restless spirit.",ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},questType="standard"},
[10306] = {id=10306,name="Conjurer Luminrath",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The cloak, undoubtedly of high elven craftsmanship, is richly tailored, even by the standards of the Kirin Tor. The symbols and characters sewn into the cloak's fabric hold no meaning for you, but clearly imbue the garment with magical properties. Perhaps this object binds the spirit of its former owner to this plane of existence. If so, returning it to the dresser in Conjurer Luminrath's quarters might break the spirit's link to this world, allowing it to rest.",ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},questType="standard"},
[10307] = {id=10307,name="Cohlien Frostweaver",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Looking at the hat, you find yourself asking if any Kirin Tor mage would own such headgear. Judging from the hat's wear, it seems the gnome wouldn't go anywhere without it. You try on the hat momentarily, discovering no magical properties beyond a faint urge to dance. The treasured possession might be the source of the dead mage's bond to the village. Placing the hat in the footlocker in Cohlien's quarters might free his spirit.",ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},questType="standard"},
[10308] = {id=10308,name="Another Heap of Ethereals",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,starts={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},ends={{npcID=19880,x=0.324,y=0.642,zoneID=3523}},coords={x=0.324,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10309] = {id=10309,name="It's a Fel Reaver, But with Heart",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You see that scrapped fel reaver over there to the south? Isn't it a thing of beauty? I want its heart! What? Yes, of course it has a heart... what doesn't? Go on over there, pry it open, bring back what I want and I'll give you a nice finder's fee in return. Oh, and I'd take a friend or two along if I were you. These Zaxxis ethereals are a pretty mean bunch! Take this fel zapper to jumpstart its heart when you're ready to begin.",starts={{npcID=19690,x=0.268,y=0.77,zoneID=3523}},ends={{npcID=19690,x=0.268,y=0.77,zoneID=3523}},coords={x=0.268,y=0.77,source="quest_giver",zoneID=3523},questType="group"},
[10310] = {id=10310,name="Sabotage the Warp-Gate!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="With the Burning Legion nearby at the fel reaver scrap field, we must do what we can to stop the flow of demons into the area. They have a warp-gate to the south in an area that they've cleverly named Invasion Point: Destroyer. I need you to go with me to the site and keep me safe while I sabotage it. Afterward, go to the Midrealm Post to the north inside Eco-Dome Midrealm and apprise Gahruj of our success. We're going to need a friend or two of yours along to help with this.",starts={{npcID=20281,x=0.48,y=0.634,zoneID=3523}},ends={{npcID=20066,x=0.466,y=0.568,zoneID=3523}},coords={x=0.48,y=0.634,source="quest_giver",zoneID=3523},questType="group"},
[10311] = {id=10311,name="Drijya Needs Your Help",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description=", it is good to see a helpful face around here. The Burning Legion at the nearby fel reaver heap has become more bold, and I am beginning to fear for our safety here. The demons are constantly receiving reinforcements from Invasion Point: Destroyer to the south. My compatriot, Drijya , has gone down there to scout and see if he can do something about the Burning Legion's warp-gate. Please find and assist him in any way that you can.",starts={{npcID=20066,x=0.466,y=0.568,zoneID=3523}},ends={{npcID=20281,x=0.48,y=0.634,zoneID=3523}},coords={x=0.466,y=0.568,source="quest_giver",zoneID=3523},questType="standard"},
[10312] = {id=10312,name="The Annals of Kirin'Var",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Silencing the spirits has not bled them of their aggression as we had hoped it would. The malevolent spirits you subdued have reemerged in the streets of the town. We must uncover what is causing this to happen. The destruction of Kirin'Var was just the beginning, or else the spirits would have been quieted by now. The town hall in the southern section of Kirin'Var maintained a logbook of all the residents. Last I heard, it was in the keeping of Battle-Mage Dathric. Perhaps his spirit still has it.",starts={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10313] = {id=10313,name="Measuring Warp Energies",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="If our instincts are right and these manaforges have been made using technology from Tempest Keep, then all of Outland could be in grave danger. Tempest Keep's energy-recharging mechanisms were never supposed to be used this close to the land. The warp energies are capable of destroying this very land, even when contained within Kael's pipelines. Take this orb to Manaforge B'naar; it is attuned to measure warp energies. Use it at the pipelines' ends, where they go into the earth.",starts={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10314] = {id=10314,name="A Lingering Suspicion",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The strange magical device resembles nothing you've ever seen before. It's certainly not of blood elf manufacture. As you sense spirits moving closer to the building, the orb glows with a greater intensity, which fades as the spirits leave. There's no question that it plays a role in the corruption of the ghosts. How it works remains a mystery. Perhaps Custodian Dieworth will have some insight if you can provide the remains of some of the spirits along with your observations.",starts={{npcID=184300,x=0.603,y=0.78,zoneID=3523}},ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},coords={x=0.603,y=0.78,source="quest_giver",zoneID=3523},questType="standard"},
[10315] = {id=10315,name="Neutralizing the Nethermancers",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The blood elves are fools! I'm glad that our trade relations with them have fallen apart. In all of my travels throughout the cosmos, I have never encountered beings so selfish. They continue to destroy the land around us with their manaforges, so let's see if we can put a dent in their operations across the bridge at Manaforge Ara. Their nethermancers channel energy to and from the blood gems to stabilize the flow of power. Go over there and wipe them out!",starts={{npcID=20341,x=0.346,y=0.378,zoneID=3523}},ends={{npcID=20341,x=0.346,y=0.378,zoneID=3523}},coords={x=0.346,y=0.378,source="quest_giver",zoneID=3523},questType="standard"},
[10316] = {id=10316,name="Searching for Evidence",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Whoever is behind the transformation of the spirits has been very deliberate in their actions, taking care to target the most powerful mages first, but why? The kind of magic required to influence the spirits of slain Kirin Tor mages must be very powerful. Why would a powerful mage go to all this trouble? I'm inclined to say this is another plot of Kael'thas's, designed to cause more misery here. If there are blood elves here, they're likely to be hiding in the houses across the covered bridge.",starts={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=184300,x=0.603,y=0.78,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10317] = {id=10317,name="Dealing with the Foreman",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The blood elves call the mine underneath Manaforge Ara the Trelleum Mine. Ever since they lost the one underneath Manaforge Ultris, this is where their sole supply of material for running the forges is coming from. Needless to say, it would be a boon for us to cripple their mining operation. Perhaps we'd even be able to move in and take it over for ourselves? Whatever the case, I want you to go in there and deal with Foreman Sundown . The mine is around the back of the island to the left.",starts={{npcID=20112,x=0.346,y=0.378,zoneID=3523}},ends={{npcID=20393,x=0.264,y=0.422,zoneID=3523}},coords={x=0.346,y=0.378,source="quest_giver",zoneID=3523},questType="standard"},
[10318] = {id=10318,name="Dealing with the Overmaster",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I used to be the foreman here. But now that I've been demoted, I've come to realize our pilgrimage from Quel'Thalas to Outland was all a lie. A lie perpetrated by Kael'thas to strengthen his forces here in the Netherstorm . I've tried to convince my brethren that we should leave, especially with the Burning Legion here, but they are all too stubborn. Do me a favor? Kill Overmaster Grindgarr . Then return to your ethereal and tell him that I am no longer his enemy.",starts={{npcID=20393,x=0.264,y=0.422,zoneID=3523}},ends={{npcID=20112,x=0.346,y=0.378,zoneID=3523}},coords={x=0.264,y=0.422,source="quest_giver",zoneID=3523},questType="standard"},
[10319] = {id=10319,name="Capturing the Phylactery",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I suppose an explanation is in order. You've met one of the archmage's apprentices, Ravandwyr, but there was also another named Naberius. He was an ardent student, but was drawn to necromancy. When Kael'thas appeared with his forces, Naberius seized the opportunity to betray the archmage, handing over the secrets to the tower's defense. Now, it seems, he has become a lich. If we are to stop him, we must capture his phylactery. Knowing him, he would've buried it somewhere out of sight in his domain.",starts={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10320] = {id=10320,name="Destroy Naberius!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Archmage Vargoth saw the danger in Naberius 's pursuit of necromancy, but I don't think he ever anticipated that his own apprentice would wreak this much destruction upon the Kirin Tor. You must defeat him, , or else he will continue enslaving the spirits of our fallen brothers, robbing them of their rightful rest and destroying what little remains of Kirin'Var. With his phylactery in hand, he can be confronted by two or three combatants, but who knows what his magic might do to more foes?",starts={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19488,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="group"},
[10321] = {id=10321,name="Shutting Down Manaforge Coruu",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Your success at B'naar has given us a great deal of hope, . We've shared our discoveries with the Scryers and in return they've given us more information on the remaining manaforges. Three other manaforges still stand, in full control of the Sunfury army. You will find Manaforge Coruu to the east. Overseer Seylanna holds the access crystal there. Obtain it and use it on the manaforge's control console to begin the emergency shutdown. We're all counting on you, .",starts={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10322] = {id=10322,name="Shutting Down Manaforge Duro",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We've received news from one of the two manaforges that remain operational. The Sunfury army is losing control of Manaforge Duro. Droves of errant mana creatures have been attracted to it by its increased energy production - the manaforge is in chaos. An explosion at Duro has the potential to cause a chain reaction that would endanger all of Outland. Overseer Athanel is in possession of the access crystal you need to safely disable the manaforge.",starts={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10323] = {id=10323,name="Shutting Down Manaforge Ara",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="One manaforge is all that keeps Tempest Keep functional. After we bring Manaforge Ara down, Kael will have to resort to depleting whatever energy he's got stored up. Travel to Manaforge Ara, in the northwest, and deliver the final blow that we need by shutting it down. The last access crystal is in the possession of Overseer Azarad. Be warned that we expect heavy opposition in the last of Kael's functional manaforges. You're likely to need the assistance of reliable friends.",starts={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="group"},
[10324] = {id=10324,name="The Great Moongraze Hunt",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3524,description="Well done, ! Well done! Now that you've cut your teeth with the moongraze stag, it's time you graduated to more formidable prey. Do not allow the casual disinterest of the moongraze bucks to fool you: when provoked, they are a fearsome foe. You'll find the bucks north of here. Good hunting.",starts={{npcID=17110,x=0.498,y=0.518,zoneID=3524}},ends={{npcID=17110,x=0.498,y=0.518,zoneID=3524}},coords={x=0.498,y=0.518,source="quest_giver",zoneID=3524},questType="standard"},
[10325] = {id=10325,name="Marks of Kil'jaeden",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="As you probably know, , the Aldor are keepers of the Light and servants of the naaru. Diametrically opposed to us are the agents of the Burning Legion - demons bent on the destruction of worlds and the corruption of the innocent. If you wish to prove yourself to the Aldor, bring me the insignias of low-ranking Legion and their Shadow Council followers. We know of a Shadow Council hideout in the Bone Wastes and there are many Legion outposts in Nagrand and the Blade's Edge Mountains.",starts={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},ends={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},coords={x=0.306,y=0.174,source="quest_giver",zoneID=3523},questType="standard"},
[10326] = {id=10326,name="More Marks of Kil'jaeden",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},ends={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},coords={x=0.306,y=0.174,source="quest_giver",zoneID=3523},questType="standard"},
[10327] = {id=10327,name="Single Mark of Kil'jaeden",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},ends={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},coords={x=0.306,y=0.174,source="quest_giver",zoneID=3523},questType="standard"},
[10328] = {id=10328,name="Sunfury Briefings",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Something about these manaforges has been bothering me, . Naaru technology is incredibly advanced; it should've taken Kael'thas years to even begin to understand it. Information-gathering on the subject has been difficult as Kael's army is well disciplined and destroys all evidence of written communication. We've been informed Manaforge Duro is under attack by mana creatures. It is possible that those defending it have not yet destroyed their briefings. Obtain them and bring them to me.",starts={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10329] = {id=10329,name="Shutting Down Manaforge B'naar",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I was having a friendly discussion with the Aldor while you were gone. Manaforges sure look like modified naaru technology from Tempest Keep. Apparently, most naaru constructs have certain safeguards that allow them to be permanently disabled in case of emergency. The procedure is usually initiated at a control console via an access crystal. Lo and behold, according to the roster you secured, such a crystal is in the possession of a fellow called Overseer Theredis. Obtain it and see what you can do.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10330] = {id=10330,name="Shutting Down Manaforge Coruu",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Thalodien told us of your success in disabling Manaforge B'naar. He expects a repeat performance here and asked us to keep an eye out for anyone using a crystal to access the console inside. Overseer Seylanna holds the access crystal, we're sure of it. Go back in there and finish the operation. No need to be stealthy anymore; get the crystal, begin the shutdown, kill the technicians trying to stop you and get out. Hurry, it won't be long before Kael's lapdogs sniff us out.",starts={{npcID=19840,x=0.482,y=0.866,zoneID=3523}},ends={{npcID=19840,x=0.482,y=0.866,zoneID=3523}},coords={x=0.482,y=0.866,source="quest_giver",zoneID=3523},questType="standard"},
[10331] = {id=10331,name="Indispensable Tools",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You haven't seen a heavy smithing hammer lying around by chance, have you? I brought it out here with me to finish the shoes for some of old man Amorlin's horses, but I can't find it. I've searched the barn no less than a half dozen times and I just can't seem to find it. Maybe one of the other apprentices retrieved it and took it back to the smithy? Would you be willing to go down there and take a look? The workshop is to the southeast of the tower in the Town Square.",starts={{npcID=20463,x=0.576,y=0.852,zoneID=3523}},ends={{npcID=20463,x=0.576,y=0.852,zoneID=3523}},coords={x=0.576,y=0.852,source="quest_giver",zoneID=3523},questType="standard"},
[10332] = {id=10332,name="Master Smith Rhonsus",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="At last, my journeyman project is complete! I can't wait to formally present it to Master Rhonsus . They attacked you? All of them? By the Light, they've gone mad! What are we to do, ? It grieves me to say so, but it may be necessary to kill Master Rhonsus . It would leave me as the only smith in Kirin'Var, but I believe my training is sufficient to serve the town's needs.",starts={{npcID=20463,x=0.576,y=0.852,zoneID=3523}},ends={{npcID=20463,x=0.576,y=0.852,zoneID=3523}},coords={x=0.576,y=0.852,source="quest_giver",zoneID=3523},questType="standard"},
[10333] = {id=10333,name="Help Mama Wheeler",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Say, , I was wondering if you could do me another favor. My partner out in the field could probably use a hand. I was wondering if you could go check in on her. I'm sure that Mama Wheeler will appreciate the help. Just don't mind her sharp tongue. She's trying to look out for our interests to the east. You'll find her just inside Eco-Dome Midrealm at the Midrealm Post.",starts={{npcID=19645,x=0.328,y=0.646,zoneID=3523}},ends={{npcID=19728,x=0.466,y=0.564,zoneID=3523}},coords={x=0.328,y=0.646,source="quest_giver",zoneID=3523},questType="standard"},
[10334] = {id=10334,name="Needs More Cowbell",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Where, oh where has my Bessy gone? After the attack, I searched the fields and the Chapel Yard for her, but she was nowhere to be seen! All I have left of her is this old cowbell. She usually comes running when she hears it, but these feeble old bones probably couldn't shake it hard enough. I'll loan you Bessy's bell if you're willing to go out to the fields and ring it as hard as you can. Perhaps all Bessy 's waiting for is a little more cowbell.",starts={{npcID=20464,x=0.576,y=0.85,zoneID=3523}},ends={{npcID=20415,x=0.59,y=0.788,zoneID=3523}},coords={x=0.576,y=0.85,source="quest_giver",zoneID=3523},questType="standard"},
[10335] = {id=10335,name="Surveying the Ruins",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I have to get over to the Ruins of Farahlon to start my excavations! The problem is that the place has been infested by demons! Maybe you could do some preliminary work for me? There are three locations within the ruins to the northeast where I want you to place surveying markers . Each is near a draenei banner. Return to me when you've managed to place all three markers.",starts={{npcID=20470,x=0.446,y=0.348,zoneID=3523}},ends={{npcID=20470,x=0.446,y=0.348,zoneID=3523}},coords={x=0.446,y=0.348,source="quest_giver",zoneID=3523},questType="standard"},
[10336] = {id=10336,name="The Minions of Culuthas",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="A few weeks ago, the Burning Legion moved into the Ruins of Farahlon, thwarting our plans to excavate the site for its artifacts. Then earlier today, I learned that one of their dreadlords, Culuthas, somehow killed off all of the other Burning Legion. He has since summoned in demons that serve him. , I want you to go up to those ruins to the northeast and rid them of their demon infestation.",starts={{npcID=20471,x=0.446,y=0.348,zoneID=3523}},ends={{npcID=20471,x=0.446,y=0.348,zoneID=3523}},coords={x=0.446,y=0.348,source="quest_giver",zoneID=3523},questType="standard"},
[10337] = {id=10337,name="When the Cows Come Home",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Realizing that Bessy is still staring at you, you gesture toward Thadell 's location. You find yourself promising to protect the cow on her way home. Upon finishing your sentence, you realize there's no possible way the cow could understand anything you've said. Shrugging your shoulders, you prepare to guard the bovine on her way back to Thadell .",starts={{npcID=20415,x=0.59,y=0.788,zoneID=3523}},ends={{npcID=20464,x=0.576,y=0.85,zoneID=3523}},coords={x=0.59,y=0.788,source="quest_giver",zoneID=3523},questType="group"},
[10338] = {id=10338,name="Shutting Down Manaforge Duro",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="So Manaforge Duro is under attack and Sunfury forces have lost control? What a dilemma! If Duro goes down, then Tempest Keep goes down. Only drawback is... if Tempest Keep is destroyed, the explosion will probably take what little remains of this forsaken land with it. Dead Kael'thas is good. Dead everyone else is... not that great, I suppose. It pains me to ask this of you, but go to Manaforge Duro and shut it down before it goes up in flames. The access crystal is held by Overseer Athanel.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10339] = {id=10339,name="The Ethereum",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Directly south of here you will find the Ethereum Staging Grounds. The Ethereum are there, preparing for something... Perhaps an assault on Ultris. We can't take any chances, though, . Break through their perimeter defenses and take out their training facility. Once you've destroyed their soldiers and Captain Zovax , locate Ethereum transponder Zeta and use it to establish contact with me to get your next set of orders.",starts={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},ends={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},coords={x=0.594,y=0.322,source="quest_giver",zoneID=3523},questType="standard"},
[10340] = {id=10340,name="Shatter Point",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description=", you've done a great job here at the front, and you showed a lot of talent with that armored gryphon... I think I have another mission in mind for you. This new mission launches from Shatter Point -- an attack base the Wildhammers set up on a floating piece of land near the Portal. It's a little unnerving there, but you have tough guts. You'll be fine. Talk to Wing Commander Dabir'ee and have him send you to Shatter Point. From there, report to the gryphon master Runetog Wildhammer .",starts={{npcID=19310,x=0.712,y=0.626,zoneID=3483}},ends={{npcID=20234,x=0.784,y=0.35,zoneID=3483}},coords={x=0.712,y=0.626,source="quest_giver",zoneID=3483},questType="standard"},
[10341] = {id=10341,name="Kick Them While They're Down",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The news you've discovered is fortunate, . Not only do you get to waltz into Manaforge Duro unfettered, this also presents a great opportunity to deal a blow to Kael's army. Use the mana creature assault to your advantage and pick off any Sunfury stragglers you run into. I do not take particular glee in the senseless slaughter of my own kin the way that Thalodien does, but the tactical advantage here is too high to pass up.",starts={{npcID=19469,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19469,x=0.32,y=0.64,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10342] = {id=10342,name="Securing the Shaleskin Shale",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I make a good living selling drinks to the boozehounds around here. But I want something more! The rocket-chief is always telling me how he can't perfect the rocket fuel needed to get the X-52 off of the ground. We can solve that little problem for him. For starters I need to extract the oil from the shale of the local shaleskin flayers! It'll form a concentrated, if explosive, base for the mix that I have in mind. Find the flayers, and their shale, all over the place near the purple rocks.",starts={{npcID=19617,x=0.322,y=0.638,zoneID=3523}},ends={{npcID=19617,x=0.322,y=0.638,zoneID=3523}},coords={x=0.322,y=0.638,source="quest_giver",zoneID=3523},questType="standard"},
[10343] = {id=10343,name="The Unending Invasion",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Kael'thas's assault on Kirin'Var began with thundering noise and a bright flash of light in the officer quarters to the northwest. The destruction there was the most severe and after the withdrawal of the blood elves, a strange thing began to happen. Beings of pure mana began streaming into the village from all over the area. For now, we're containing them as we can, but with more information about the weapon Kael'thas used, I hope to cut off the flow of mana creatures entirely.",starts={{npcID=19489,x=0.574,y=0.862,zoneID=3523}},ends={{npcID=19489,x=0.574,y=0.862,zoneID=3523}},coords={x=0.574,y=0.862,source="quest_giver",zoneID=3523},questType="standard"},
[10344] = {id=10344,name="Wing Commander Gryphongar",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Wing Commander Gryphongar runs this outfit of Wildhammers. If this is your first time to Shatter Point, then you should report to him. You'll find him inside what's left of that tower over yonder.",starts={{npcID=20234,x=0.784,y=0.35,zoneID=3483}},ends={{npcID=20232,x=0.792,y=0.338,zoneID=3483}},coords={x=0.784,y=0.35,source="quest_giver",zoneID=3483},questType="standard"},
[10345] = {id=10345,name="The Flesh Lies...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You see these corpses, ? Arconus is responsible for this slaughter. He's sucked them dry, leaving nothing more than a fleshy husk. But don't let the bodies fool you! Inside those corpses lie flesh beasts, waiting to pounce on the unsuspecting fool that gets too close. I've got my orders. I must remain here until backup arrives. That doesn't mean that you can't take my igniter and destroy the withered corpses that litter the mines. One way or another, the mission must be completed.",starts={{npcID=20551,x=0.594,y=0.45,zoneID=3523}},ends={{npcID=20551,x=0.594,y=0.45,zoneID=3523}},coords={x=0.594,y=0.45,source="quest_giver",zoneID=3523},questType="standard"},
[10346] = {id=10346,name="Return to the Abyssal Shelf",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description=", you've proven yourself as a capable gryphon rider, and we could use you on more sorties over the Abyssal Shelf. What say you, ? Do you want some more flight time?",starts={{npcID=20235,x=0.782,y=0.344,zoneID=3483}},ends={{npcID=20235,x=0.782,y=0.344,zoneID=3483}},coords={x=0.782,y=0.344,source="quest_giver",zoneID=3483},questType="standard"},
[10347] = {id=10347,name="Return to the Abyssal Shelf",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description=", are you ready for another sortie over the Abyssal Shelf? I fear that, if we do not maintain pressure on the Legion forces there and allow them to strengthen their hold, then we may suffer a large demon attack from the north. What say you, ? Do you want to take another windrider and hammer the Abyssal Shelf one more time?",starts={{npcID=19401,x=0.66,y=0.436,zoneID=3483}},ends={{npcID=19401,x=0.66,y=0.436,zoneID=3483}},coords={x=0.66,y=0.436,source="quest_giver",zoneID=3483},questType="standard"},
[10348] = {id=10348,name="New Opportunities",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I hear that a group of 'druids' from Azeroth has taken quite an interest in the effects of our eco-dome technology. The Cenarion Expedition's representatives are eager to get access to the plants growing within the domes, particularly one called the ivory bell , known for its healing properties. They're found in clumps of brush around larger plants in Eco-Dome Midrealm. I'll share the profits with you if you're willing to gather the herbs for my first delivery.",starts={{npcID=20810,x=0.464,y=0.564,zoneID=3523}},ends={{npcID=20810,x=0.464,y=0.564,zoneID=3523}},coords={x=0.464,y=0.564,source="quest_giver",zoneID=3523},questType="standard"},
[10349] = {id=10349,name="The Earthbinder",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="You should take the crystal lump over to the earthbinder. She's just like you... always needing to get to the bottom of a mystery and thinking all of the time. If you ask me, she thinks a little too much. Just give it to her and I'm sure that she'll get you into a heap of trouble figuring out what is going on up there on the ridge.",starts={{npcID=19293,x=0.156,y=0.52,zoneID=3483}},ends={{npcID=19294,x=0.158,y=0.516,zoneID=3483}},coords={x=0.156,y=0.52,source="quest_giver",zoneID=3483},questType="standard"},
[10350] = {id=10350,name="Behomat",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3557,description="While you have learned many hard lessons from me during our time together, it is time that I entrusted you to wiser hands. Behomat , who trained me when I was as green as grass, will be your new teacher. I have told him that you will be seeking him out, and he is expecting you. You will find him at the center of the Warriors' Terrace, at the highest point of the Traders Tier of the Exodar.",starts={{npcID=17480,x=0.498,y=0.504,zoneID=3524}},ends={{npcID=17120,x=0.554,y=0.82,zoneID=3557}},coords={x=0.498,y=0.504,source="quest_giver",zoneID=3524},questType="standard"},
[10351] = {id=10351,name="Natural Remedies",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="It must be that the evil emanations from that giant crystal are summoning the mountain giants and driving them insane. It's too big to move, and beyond our ability to destroy, but I know a way to quell its power. I've summoned a circle at the northwest corner of the crystal on the ridge. Take this seed to the circle and channel its powers to heal the land through the natural forces of rain, growth and insect repopulation. Beware, , I sense an external force at play here... this is not natural!",starts={{npcID=19294,x=0.158,y=0.516,zoneID=3483}},ends={{npcID=19294,x=0.158,y=0.516,zoneID=3483}},coords={x=0.158,y=0.516,source="quest_giver",zoneID=3483},questType="standard"},
[10353] = {id=10353,name="Arconus the Insatiable",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Araxes and I were deployed to Ultris 2 days ago. Our mission: Find and terminate the void lord Arconus. We tracked him to this mine and discovered that he'd been feeding off the energies of the creatures in the area. A fire-fight broke out which resulted in Araxes and I separating. Now I'm stuck here, badly injured. The mission is in shambles! If you can take out Arconus, high command would be grateful. Should you accept this mission, I will assist by providing a reflection of myself as a guardian.",starts={{npcID=20552,x=0.608,y=0.416,zoneID=3523}},ends={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},coords={x=0.608,y=0.416,source="quest_giver",zoneID=3523},questType="standard"},
[10355] = {id=10355,name="Withered Flesh",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="We must determine how far the damage has spread. The basidium you brought me comes from a bog giant. Their larger, hardier cousins, the bog lords, should prove more resistant to the degeneration that's struck the giants. It would be good to know how the changes in the Dead Mire have affected the other creatures out there, too. Return to the Dead Mire and see if you can get samples from the bog lords and the hydra in the area.",starts={{npcID=18007,x=0.686,y=0.488,zoneID=3521}},ends={{npcID=18007,x=0.686,y=0.488,zoneID=3521}},coords={x=0.686,y=0.488,source="quest_giver",zoneID=3521},questType="standard"},
[10365] = {id=10365,name="Shutting Down Manaforge Ara",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You've done much better than any of us anticipated. Manaforge Ara is the last of Kael's working manaforges. You'll find it northwest of here, though you're likely to have to do some circumnavigating to get to it. We want you to shut it down. The last access crystal is in the possession of Overseer Azarad. This is Kael's very last source of energy as far as we know, so expect heavy opposition. I'd bring a couple of friends along if I were you. Hmm... Azarad. What an odd name for a sin'dorei.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="group"},
[10367] = {id=10367,name="A Traitor Among Us",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="Anywhere you see a tribe of enslaved Broken you will also find a traitor. A despicable being who sold his brothers for promises of power. There is a hut at the top of the stairs in the center of the ruins. That's the turncoat's hut. He's not there right now, so you will be able to sneak in if you're patient. Inside you will find a coffer with a key inside of it. That key unlocks the chains that keep the Dreghood elders prisoner. Bring it to me. Beware, Arzeth the Merciless wanders nearby.",starts={{npcID=19361,x=0.162,y=0.65,zoneID=3483}},ends={{npcID=19361,x=0.162,y=0.65,zoneID=3483}},coords={x=0.162,y=0.65,source="quest_giver",zoneID=3483},questType="standard"},
[10368] = {id=10368,name="The Dreghood Elders",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="The Dreghood spirit is broken because our elders are imprisoned. Take this key and go downstairs to free them. They are Morod the Windstirrer , Akoru the Firecaller and Aylaan the Waterwaker . Once they are free, the spirits will return to the Dreghood tribe.",starts={{npcID=19361,x=0.162,y=0.65,zoneID=3483}},ends={{npcID=19361,x=0.162,y=0.65,zoneID=3483}},coords={x=0.162,y=0.65,source="quest_giver",zoneID=3483},questType="standard"},
[10369] = {id=10369,name="Arzeth's Demise",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="Yes, the elemental spirits have returned to us! We are not as strong as we once were, but a little magic can go a long way in the right hands. Arzeth has great powers bestowed upon him by his dark lord. Take this staff. It was once a great symbol of our tribe. Use it against Arzeth and his powers will be temporarily removed from him. Defeat him then, so that my people may finally be free!",starts={{npcID=19361,x=0.162,y=0.65,zoneID=3483}},ends={{npcID=19361,x=0.162,y=0.65,zoneID=3483}},coords={x=0.162,y=0.65,source="quest_giver",zoneID=3483},questType="standard"},
[10380] = {id=10380,name="A Dark Pact",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We've been so blind, , that the alliance of two of our most dangerous enemies went completely unnoticed. I wouldn't be surprised if the Scryers had something to do with hiding this information from us, but we must now face the reality. The Burning Legion and Kael'thas' Sunfury army serve under the same banner. These demons are the only reason Kael'thas was ever able to utilize the technology in Tempest Keep. Under Orelis's orders I must command you to destroy them.",starts={{npcID=20780,x=0.348,y=0.382,zoneID=3523}},ends={{npcID=20780,x=0.348,y=0.382,zoneID=3523}},coords={x=0.348,y=0.382,source="quest_giver",zoneID=3523},questType="standard"},
[10381] = {id=10381,name="Aldor No More",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="My mission here is finished. I did what Orelis ordered me to - I've never failed to. No more. I foresee a great carnage - a crusade, they'll call it - following the news of this alliance between Kael'thas and the Burning Legion. First they give our holiest city away to our enemies and then they ask us to die fighting their enemies. Go back to Orelis; tell him the naaru can fight their own fights from now on.",starts={{npcID=20780,x=0.348,y=0.382,zoneID=3523}},ends={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},coords={x=0.348,y=0.382,source="quest_giver",zoneID=3523},questType="standard"},
[10382] = {id=10382,name="Go to the Front",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Well, , I hope you're prepared for the next phase of our operation. The Legion never rests - and neither shall we! Take a gryphon and fly over to Honor Point - it's a small post near the Legion Front. Speak with Field Marshal Brock . He'll have instructions for you when you arrive. Oh, and tell that pasty-faced shield-kisser I said 'hello'.",starts={{npcID=20232,x=0.792,y=0.338,zoneID=3483}},ends={{npcID=20793,x=0.682,y=0.284,zoneID=3483}},coords={x=0.792,y=0.338,source="quest_giver",zoneID=3483},questType="standard"},
[10384] = {id=10384,name="Ethereum Data",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Look around you, fleshling. Very close to this transponder should be an Ethereum data cell . Locate that data cell, open it, and retrieve the contents. Bring it back to this transponder at once!",starts={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},ends={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},coords={x=0.568,y=0.386,source="quest_giver",zoneID=3523},questType="standard"},
[10385] = {id=10385,name="Potential for Brain Damage = High",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="They're using relays to transfer information around the staging grounds. There is only one way for you to see these relays and extract the information they hold. Unfortunately, doing so may cause you irreparable brain damage. If you're still interested, you'll need to slay Ethereum here at the staging grounds and take their essences. Once you have an essence, drink it down. It will temporarily allow you to see an Ethereum relay, giving you enough time to destroy a relay and extract its information.",starts={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},ends={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},coords={x=0.568,y=0.386,source="quest_giver",zoneID=3523},questType="standard"},
[10388] = {id=10388,name="Return to Thrallmar",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Hope you enjoyed your flight, friend. A messenger arrived while you were away - seems Nazgrel 's got a new use for you. You'd best head back to Thrallmar and check in with him. I have a feeling the Legion's just getting warmed up.",starts={{npcID=16576,x=0.65,y=0.442,zoneID=3483},{npcID=19273,x=0.658,y=0.436,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.65,y=0.442,source="quest_giver",zoneID=3483},questType="standard"},
[10389] = {id=10389,name="The Agony and the Darkness",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Greetings, . I've deciphered the Legion missive and uncovered the demons' strategic plans for this Peninsula. Apparently, there is a large group of hellish terrorfiends gathering near the Pools of Aggonar in the west. We cannot allow such a force to go unchallenged. You must go there and decimate their cursed numbers.",starts={{npcID=21175,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=21175,x=0.55,y=0.36,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[10390] = {id=10390,name="Forge Camp: Mageddon",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description=", we have reason to believe that the easternmost forge camp is not yet complete. The Legion's gan'arg servants are working 'round the clock to get the facility up and running. We can't allow that to happen. Head east to Forge Camp: Mageddon and slay 10 gan'arg. Bring me the head of their master - Razorsaw - and the Legion's fel reaver production will grind to a halt!",starts={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[10391] = {id=10391,name="Cannons of Rage",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="There is a second production facility, Forge Camp: Rage, that lies to the immediate northeast of Thrallmar. The demons have positioned a number of their fel cannons along the ridge - and they're aimed straight at us! You must enter the camp and destroy these fel cannons. , you must be sure to detonate them all - or nothing will stop the Legion from raining fiery hell down upon our heads!",starts={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[10392] = {id=10392,name="Doorway to the Abyss",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="You are an honor to us, . But now we must strike before the Legion recovers! To the north of Thrallmar lies Invasion Point: Annihilator. It houses a warp-portal through which the Legion draws its reinforcements. You must overload that portal - and blast it back to the abyss it came from. The portal's activation key will be held by the Point's commander - Warbringer Arix'Amal . Slay him. Take the key. Use it on the portal and do what must be done. May the warchief's blessings be with you.",starts={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[10393] = {id=10393,name="Vile Plans",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one in Thrallmar that can transcribe such vile script - the blood elf Magister Bloodhawk .",ends={{npcID=21175,x=0.55,y=0.36,zoneID=3483}},questType="standard"},
[10394] = {id=10394,name="Disruption - Forge Camp: Mageddon",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Pay close attention, . We've been surveying the Legion camps that lie along the ridge ahead. We have reason to believe that these so-called 'Forge Camps' are where the demons are constructing those blasted Fel Reavers. You can see the closest target, Forge Camp: Mageddon, to the west. Our intelligence suggests that it's still under construction. If you can slay the Gan'arg Servants and their master - Razorsaw - we can bring the Legion's Fel Reaver production to a grinding halt!",starts={{npcID=20793,x=0.682,y=0.284,zoneID=3483}},ends={{npcID=20793,x=0.682,y=0.284,zoneID=3483}},coords={x=0.682,y=0.284,source="quest_giver",zoneID=3483},questType="standard"},
[10395] = {id=10395,name="The Dark Missive",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one at Honor Hold who can decipher such archaic script - the draenei mystic, Kryv. Take the Burning Legion Missive to Warp-Scryer Kryv who resides within the War-Room at Honor Hold.",ends={{npcID=16839,x=0.566,y=0.664,zoneID=3483}},questType="standard"},
[10396] = {id=10396,name="Enemy of my Enemy...",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Now we focus on the second target - Forge Camp: Rage. It lies just west of Mageddon. Trouble is, the demons have a number of fel cannons aimed straight at the Horde's outpost of Thrallmar! Though I can scarcely believe it, we actually need the Horde to help us hold the line at the Dark Portal. We can't afford to let Thrallmar fall. You've got to destroy these cannons before the Legion pulverizes our allies!",starts={{npcID=20793,x=0.682,y=0.284,zoneID=3483}},ends={{npcID=20793,x=0.682,y=0.284,zoneID=3483}},coords={x=0.682,y=0.284,source="quest_giver",zoneID=3483},questType="standard"},
[10397] = {id=10397,name="Invasion Point: Annihilator",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Well, we've located the Legion's final base on the ridge - Invasion Point: Annihilator. It lies northwest of Forge Camp: Rage - and it houses a warp-portal through which the Legion has been drawing its reinforcements! You've got to close that portal to prevent any more demons from coming through. The Point's overlord, Warbringer Arix'Amal , holds the portal's activation key. Take it from him and shut that blasted gateway down!",starts={{npcID=20793,x=0.682,y=0.284,zoneID=3483}},ends={{npcID=20793,x=0.682,y=0.284,zoneID=3483}},coords={x=0.682,y=0.284,source="quest_giver",zoneID=3483},questType="standard"},
[10399] = {id=10399,name="The Heart of Darkness",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="It is just as I feared. Arix'Amal - the demon you killed earlier, was working for a secret Legionlord - Arazzius the Cruel. It appears this new villain has amassed a force of hellish terrorfiends near the Pools of Aggonar. You must journey there and slay the terrorfiends before they strike against us. But be wary, friend - the Pools of Aggonar lie within a tortured, poisonous valley. You can find the cursed pools to the northwest of here, beyond Hellfire Citadel. Light be with you, .",starts={{npcID=16839,x=0.566,y=0.664,zoneID=3483}},ends={{npcID=16839,x=0.566,y=0.664,zoneID=3483}},coords={x=0.566,y=0.664,source="quest_giver",zoneID=3483},questType="standard"},
[10400] = {id=10400,name="Overlord",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The honorable Warp-Scryer has told me of your perils, - and of the new foe you've discovered. If Kryv is to be believed, this ' Arazzius the Cruel ' is as powerful and evil as any foe the Sons of Lothar have ever faced. Will you stand for us now, ? Will you face this Legionlord and deliver the Light's justice upon him? If so, you will find him at the Pools of Aggonar. If not, his evil will most certainly find you.",starts={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},ends={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},coords={x=0.566,y=0.666,source="quest_giver",zoneID=3483},questType="standard"},
[10403] = {id=10403,name="Naladu",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="Perhaps not all hope is lost for the Dreghood. I am one of four elders that guided this tribe before we were enslaved by the Illidari. I thought the others were dead, but I've slowly learned that at least two others are alive - chained down and powerless just as I am. I've not yet been able to find Naladu and fear for the worst. There are more huts in the ruins upstairs; perhaps you could look for him. It would be a great boon for our tribe if all our elders were alive.",starts={{npcID=20677,x=0.13,y=0.61,zoneID=3483},{npcID=20678,x=0.156,y=0.586,zoneID=3483},{npcID=20679,x=0.13,y=0.584,zoneID=3483}},ends={{npcID=19361,x=0.162,y=0.65,zoneID=3483}},coords={x=0.13,y=0.61,source="quest_giver",zoneID=3483},questType="standard"},
[10405] = {id=10405,name="S-A-B-O-T-A-G-E",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We must destroy the machinery that is making these nexus-stalker aberrations possible. To strike at their proto-accelerator would be futile as it is an ethereal creation. We must instead destroy the manaforge energy tube that they are using as a conduit. I have all that I need to create a device to overload the conduit save for one item. I need a wrapping from an archon or overlord that might be transforming soon in order to calibrate the device.",starts={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},ends={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},coords={x=0.568,y=0.386,source="quest_giver",zoneID=3523},questType="standard"},
[10406] = {id=10406,name="Delivering the Message",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I'm sending one of my demolitionists out to place the disruption device. Just make sure no harm comes to him as he's placing the disruptor. Keep him protected! He will not fight back if enemies attack him, as he is only a holographic image, but the image can be destroyed! Return to me once the job is done.",starts={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},ends={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},coords={x=0.568,y=0.386,source="quest_giver",zoneID=3523},questType="standard"},
[10407] = {id=10407,name="Socrethar's Shadow",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The infamous eredar, Socrethar, leads the Burning Legion in Netherstorm . Mentioning his name is enough to make most draenei shudder. He gives orders from an island in the northwest that only his most trusted lieutenants can access. To get there you will need to obtain a teleportation stone, which won't be an easy task. The first half of the stone is in the possession of Forgemaster Morug at Forge Base: Oblivion. The second half is held by Silroth at Forge Base: Gehenna.",starts={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="group"},
[10408] = {id=10408,name="Nexus-King Salhadaar",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I have in my possession another disruptor--one capable of destroying the three conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar's protective force fields will be down. For this act, he will strike at you with a ferocity you have never before witnessed, . If you are willing to rid the world of Salhadaar, I will give you the disruptor.",starts={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},ends={{npcID=20482,x=0.568,y=0.386,zoneID=3523}},coords={x=0.568,y=0.386,source="quest_giver",zoneID=3523},questType="standard"},
[10409] = {id=10409,name="Deathblow to the Legion",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="When facing eredar of great power, large armies are useless for the most part. Their corruptive powers over mortal souls are such that only the strongest-willed can even stand face to face with them. Take this stone to the Invasion Point: Overlord, between Forge Base: Oblivion and Gehenna and bring your closest, strongest friends with you. Orelis and Karja will meet you at Socrethar 's Seat; I will send Adyen along with them. May the Light prevail today, . May Socrethar meet his end.",starts={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},ends={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},coords={x=0.242,y=0.298,source="quest_giver",zoneID=3703},questType="group"},
[10410] = {id=10410,name="Ishanah's Help",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="The time has come to face Socrethar, . Confronting an eredar leader isn't something that's taken lightly among us. A single mistake is likely to cost us our lives if we're ill-prepared. Take Socrethar's teleportation stone to High Priestess Ishanah at the Shrine of Unending Light in Shattrath City. She will determine how we need to handle the situation.",starts={{npcID=19467,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10411] = {id=10411,name="Electro-Shock Goodness!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Around the ruined manaforge you will find the run-off of Dimensius's handy work. Seeping sludge occupies the pools that surround Ultris. Directly below those pools, where the Ethereum Staging Grounds now stand, you will find even more run-off in the form of void waste. The best method of disposal is to use electro-shock to break slimes down to globules. Use this elixir to augment your attacks with electricity. The resultant discharge will break the slimes up into their raw form. Destroy the globules!",starts={{npcID=20449,x=0.592,y=0.324,zoneID=3523}},ends={{npcID=20449,x=0.592,y=0.324,zoneID=3523}},coords={x=0.592,y=0.324,source="quest_giver",zoneID=3523},questType="standard"},
[10412] = {id=10412,name="Firewing Signets",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="It is no secret that Kael'thas Sunstrider perceives us as a great threat. Let's face it - not many sin'dorei, fresh from Silvermoon, are willing to join the sort of company that Kael keeps. It's also no secret that this is not just a war of words. Scryers and the armies that serve Kael'thas attack each other on sight. The only way to prove you're with us, , is to do your share of fighting. Kael's lower ranking followers wear Firewing signets to indicate their rank. Bring them to me.",starts={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},ends={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},coords={x=0.454,y=0.814,source="quest_giver",zoneID=3703},questType="standard"},
[10413] = {id=10413,name="The Horrors of Pollution",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="You carefully fill a vial with the fallen void horror's ooze. Researcher Navuud at the Protectorate Watch Post would be quite interested in such a find! Take it to him at once!",ends={{npcID=20449,x=0.592,y=0.324,zoneID=3523}},questType="standard"},
[10414] = {id=10414,name="Single Firewing Signet",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},ends={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},coords={x=0.454,y=0.814,source="quest_giver",zoneID=3703},questType="standard"},
[10415] = {id=10415,name="More Firewing Signets",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},ends={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},coords={x=0.454,y=0.814,source="quest_giver",zoneID=3703},questType="standard"},
[10416] = {id=10416,name="Synthesis of Power",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Arcane tomes are not ordinary books that happen to deal with arcane matters. There is intrinsic power in them - a power I've learned to synthesize into a single arcane rune . Should you find an arcane tome in your travels I will give you one such rune. Only the most powerful wielders of magic carry the books I need. In Outland this usually means Kael's blood elves - but you'd be surprised by where such tomes often turn up.",starts={{npcID=18530,x=0.426,y=0.914,zoneID=3703}},ends={{npcID=18530,x=0.426,y=0.914,zoneID=3703}},coords={x=0.426,y=0.914,source="quest_giver",zoneID=3703},questType="standard"},
[10417] = {id=10417,name="Run a Diagnostic!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Wherever the Consortium establishes a presence, we bring our eco-dome technology. The fields allow us to work in a controlled and life-sustaining atmosphere since we often find ourselves in hostile environments. Netherstorm 's volatile conditions and creatures have begun to destroy the equipment that sustains our domes, especially the generator east of here. I've started a diagnostic there in hopes of understanding what can be done to combat the damage. Would you collect the results and bring them to me?",starts={{npcID=20810,x=0.464,y=0.564,zoneID=3523}},ends={{npcID=20810,x=0.464,y=0.564,zoneID=3523}},coords={x=0.464,y=0.564,source="quest_giver",zoneID=3523},questType="standard"},
[10418] = {id=10418,name="Deal With the Saboteurs",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="In searching the area for clues about the damage to our equipment, I've seen pieces of the shield generators at the bottom of the small lake to the north. I'm not sure why the crocolisks have taken an interest in the equipment, but we have to put a stop to this problem. The Consortium is quite clear on this matter. If it comes down to a choice between the equipment and crocolisks, the animals will have to go. I'll make it worth your while to deal with them.",starts={{npcID=20810,x=0.464,y=0.564,zoneID=3523}},ends={{npcID=20810,x=0.464,y=0.564,zoneID=3523}},coords={x=0.464,y=0.564,source="quest_giver",zoneID=3523},questType="standard"},
[10419] = {id=10419,name="Arcane Tomes",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18530,x=0.426,y=0.914,zoneID=3703}},ends={{npcID=18530,x=0.426,y=0.914,zoneID=3703}},coords={x=0.426,y=0.914,source="quest_giver",zoneID=3703},questType="standard"},
[10420] = {id=10420,name="A Cleansing Light",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="This temple is one of the holiest places in all of Outland. The power of the Light here is so strong, that even items with the strongest fel taint can be cleansed of a worldly item. Should you run into any fel armaments in your confrontations with demonic enemies, bring them to me and I will demonstrate the cleansing power of the Light.",starts={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},ends={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},coords={x=0.242,y=0.298,source="quest_giver",zoneID=3703},questType="standard"},
[10421] = {id=10421,name="Fel Armaments",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},ends={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},coords={x=0.242,y=0.298,source="quest_giver",zoneID=3703},questType="standard"},
[10422] = {id=10422,name="Captain Tyralius",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Captain Tyralius took a platoon of soldiers south towards the Ethereum Staging Grounds 10 days ago. We haven't heard from him or his crew since. Chances are good that they were ambushed and killed but I'm getting a curious reading from my instruments. I think it's a distress signal but these things have been wrong before. If Tyralius is still alive, they're keeping him in one of their prisons. You'll have to locate the prison and open it with a key, probably found on the warden.",starts={{npcID=20450,x=0.592,y=0.32,zoneID=3523}},ends={{npcID=20450,x=0.592,y=0.32,zoneID=3523}},coords={x=0.592,y=0.32,source="quest_giver",zoneID=3523},questType="standard"},
[10423] = {id=10423,name="To the Stormspire",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Master Engineer Ghabar will want to know about the results of the diagnostics. If anything, they caution us to keep a close eye on the workings of our dome generators. As the fields become more and more unstable, their effects will become harder to control. It could spell disaster for our expedition and anything else housed within the domes. You'll find Ghabar at the Stormspire. Just follow the road north from this eco-dome and across the bridge. It'll lead you to the elevator at the base of the spire.",starts={{npcID=20810,x=0.464,y=0.564,zoneID=3523}},ends={{npcID=20811,x=0.434,y=0.35,zoneID=3523}},coords={x=0.464,y=0.564,source="quest_giver",zoneID=3523},questType="standard"},
[10424] = {id=10424,name="Diagnosis: Critical",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="If Mehrdad's results are correct -- and I have no reason to believe they're faulty -- then the rest of the domes could be in trouble. I do think Mehrdad has failed to identify the underlying cause of the failures. From time to time, creatures damage the generators, but never this severely. To be on the safe side, I'd like for you to run a set of diagnostics at the Stormspire's main dome generator, located in Eco-Dome Sutheron at the very eastern edge of the dome.",starts={{npcID=20811,x=0.434,y=0.35,zoneID=3523}},ends={{npcID=20811,x=0.434,y=0.35,zoneID=3523}},coords={x=0.434,y=0.35,source="quest_giver",zoneID=3523},questType="standard"},
[10425] = {id=10425,name="Escape from the Staging Grounds",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Thank K'aresh! He would have torn me apart! I'm a Protectorate soldier, fleshling. My platoon was sent on a recon mission about 10 days ago. As we were moving across the upper ledges of this island, a group of Ethereum jumped us. At least I think it was Ethereum. They had the same energy color but their wrappings looked void. Only Tyralius was spared. I think they put him in a prison cell. I've got to get back to the Protectorate Watch Post! Can you escort me back?",starts={{npcID=20763,x=0.57,y=0.376,zoneID=3523}},ends={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},coords={x=0.57,y=0.376,source="quest_giver",zoneID=3523},questType="standard"},
[10426] = {id=10426,name="Flora of the Eco-Domes",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Just look around you, ! Isn't it amazing? Of course, this incredible resurgence of life is a byproduct of the ethereal domes, but imagine what it could do in the hands of the expedition. I'm preparing to negotiate with the ethereals for access to their technology, but I'd like to get a better idea of its effects on plant-based life. I've built a device to concentrate the dome's energies on the lashers in this area. Would you be so kind as to test it for me and share the results?",starts={{npcID=20871,x=0.422,y=0.326,zoneID=3523}},ends={{npcID=20871,x=0.422,y=0.326,zoneID=3523}},coords={x=0.422,y=0.326,source="quest_giver",zoneID=3523},questType="standard"},
[10427] = {id=10427,name="Creatures of the Eco-Domes",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Your work with the lashers turned up some astounding information, but I wonder if it holds true for animals as well. Gathering information on the talbuks that live underneath this dome is going to be trickier than studying the lashers, I'm afraid. Using this tagging device, you can put a weakened talbuk to sleep and apply a tag that I'll use to track the animal as it matures. The tagging mechanism won't work unless the talbuk has expended most of its energy.",starts={{npcID=20871,x=0.422,y=0.326,zoneID=3523}},ends={{npcID=20871,x=0.422,y=0.326,zoneID=3523}},coords={x=0.422,y=0.326,source="quest_giver",zoneID=3523},questType="standard"},
[10428] = {id=10428,name="The Missing Fisherman",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=457,description="In the fevered dreams of our injured guest, she spoke of a fisherman, Cowlen , who was in some distress at Silvermyst Isle, to the southwest, off the coast of Azuremyst. With all that has been happening, no one has had the opportunity to look into it, but I do feel a bit of worry. Perhaps there's something you can do, ?",starts={{npcID=17488,x=0.488,y=0.51,zoneID=3524}},ends={{npcID=17311,x=0.166,y=0.944,zoneID=3524},{npcID=17311,x=0.288,y=0.326,zoneID=457}},coords={x=0.488,y=0.51,source="quest_giver",zoneID=3524},questType="standard"},
[10429] = {id=10429,name="When Nature Goes Too Far",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The dome technology possesses such power! Certainly, there are bounds beyond which we dare not go, . Creatures allowed to grow too large or too fast could be just as bad as a barren landscape. I have heard rumors of just such a creature in the pool to the east. I've heard the ethereal merchants conspiring to catch the overgrown hydra for sport, but I have another purpose in mind for the giant. Bring me the creature's heart so I may study it.",starts={{npcID=20871,x=0.422,y=0.326,zoneID=3523}},ends={{npcID=20871,x=0.422,y=0.326,zoneID=3523}},coords={x=0.422,y=0.326,source="quest_giver",zoneID=3523},questType="standard"},
[10430] = {id=10430,name="Testing the Prototype",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,mapID=109,description="I've been working on a portable generator repair kit for use in some of the harsher climates that the Consortium operates in. Granted, it wasn't designed for Netherstorm , but we shouldn't have any problems with it. I had already scheduled a test with one of my best techs up at Eco-Dome Farfield beyond the Netherstone to the northeast. Take this prototype to Tashar . He'll know what to do with it. If it works, we can use it to reinforce the shield generators at the larger domes.",starts={{npcID=20811,x=0.434,y=0.35,mapID=109}},ends={{npcID=20913,x=0.446,y=0.144,mapID=109}},coords={x=0.434,y=0.35,source="quest_giver",mapID=109},questType="standard"},
[10431] = {id=10431,name="Outside Assistance",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The Sunfury briefings support the theory that Kael'thas has been receiving outside help in constructing and running these manaforges. Who this is remains a bit of a mystery, though we're likely to find out in Manaforge Ara. I've sent a group of my men to scout the surrounding area. Go to Tuluman's Landing, north of here, and speak to Kaylaan . See what he's discovered at Manaforge Ara. Find out who is assisting the Sunfury army and take care of them.",starts={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},ends={{npcID=20780,x=0.348,y=0.382,zoneID=3523}},coords={x=0.32,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10432] = {id=10432,name="Damning Evidence",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="As you may have noticed, there are servants of the Burning Legion all over Manaforge Ara. Kael'thas has entered an alliance with the Burning Legion. He must've caught wind of Illidan's descent into insanity and switched paymasters accordingly. If the Scryers get definite proof of this, it will give them a considerable political advantage. I know for a fact that the Legion forces at this manaforge have orders that bear Kael's seal. Get these orders and bring them to Thalodien.",starts={{npcID=20920,x=0.262,y=0.416,zoneID=3523}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.262,y=0.416,source="quest_giver",zoneID=3523},questType="standard"},
[10433] = {id=10433,name="Keeping Up Appearances",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=6721,description="The ethereals are clever and very observant, so it's no accident that I'm here posing as a simple furrier. In fact, I've been sent from Area 52 to appraise the technology the ethereals use to generate their eco-domes. I'd like to enlist your help, . We've been asked to use non-goblin agents whenever possible. What I want you to do is bring me a number of ripfang lynx pelts in the guise of a hunter. You can find the lynxes all over Eco-Dome Midrealm.",starts={{npcID=20921,x=0.464,y=0.56,zoneID=3523}},ends={{npcID=20921,x=0.464,y=0.56,zoneID=3523}},coords={x=0.464,y=0.56,source="quest_giver",zoneID=3523},questType="standard"},
[10434] = {id=10434,name="The Dynamic Duo",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Excellent job. I think they're buying it. Now, when I send you up to speak with my associates at the Stormspire, there won't be any suspicion at all. You'll want to look for Action Jaxon and Audi the Needle up there. They'll tell you everything you need to know. Tell 'em Shauly sent you.",starts={{npcID=20921,x=0.464,y=0.56,zoneID=3523}},ends={{npcID=20205,x=0.448,y=0.366,zoneID=3523}},coords={x=0.464,y=0.56,source="quest_giver",zoneID=3523},questType="standard"},
[10435] = {id=10435,name="Retrieving the Goods",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I'm sure Shauly told you a bit about our work here. When Jaxon and I are out in the field 'hunting,' we've been collecting pieces of the ethereal eco-dome generators and hiding them in the nests of our prey, the raptors in Eco-Dome Farfield. It's a remote area to the northeast of the Stormspire, close to the Netherstone. I don't anticipate you'll run into many ethereals there, but would you be willing to help us collect the dome generator pieces?",starts={{npcID=20205,x=0.448,y=0.366,zoneID=3523}},ends={{npcID=20205,x=0.448,y=0.366,zoneID=3523}},coords={x=0.448,y=0.366,source="quest_giver",zoneID=3523},questType="standard"},
[10436] = {id=10436,name="All Clear!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Before we can begin the test, we have to make certain the area is clear of anything that might interfere. In our case, that means these overgrown lizards. Tashar gestures toward the scythetooth raptors .> There's no telling what might happen if one of those decides to take a nice bite out of the generator while it's charging. I've seen a lot of strange things in all my years as a technician, including more than a few abominations that had their beginnings as humble animals.",starts={{npcID=20913,x=0.446,y=0.144,zoneID=3523}},ends={{npcID=20913,x=0.446,y=0.144,zoneID=3523}},coords={x=0.446,y=0.144,source="quest_giver",zoneID=3523},questType="standard"},
[10437] = {id=10437,name="Recipe for Destruction",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Atop Manaforge Ultris lies the tear in the nether that Void Lord Dimensius came through. That tear provides Dimensius with a link to the Void, rendering him immune to physical harm. If we can get a lock on the conduit that Dimensius is using to keep himself phased out of this plane of existence, we can destroy it and then destroy Dimensius. To do this, we're going to first need you to collect fragments of Dimensius from the void creatures that he sends out to do his dirty work.",starts={{npcID=20907,x=0.6,y=0.318,zoneID=3523}},ends={{npcID=20907,x=0.6,y=0.318,zoneID=3523}},coords={x=0.6,y=0.318,source="quest_giver",zoneID=3523},questType="standard"},
[10438] = {id=10438,name="On Nethery Wings",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Here it is, . Take this phase disruptor and mount up! The Protectorate nether drake will fly you close enough to Ultris so that you can drop the disruptor on top of the void conduit . Drop as many disruptor charges as possible to ensure complete annihilation! When you are ready, speak with the nether drake and he'll take you up. If you miss the mark you will have to get more bombs from me before you can go up again.",starts={{npcID=20907,x=0.6,y=0.318,zoneID=3523}},ends={{npcID=20907,x=0.6,y=0.318,zoneID=3523}},coords={x=0.6,y=0.318,source="quest_giver",zoneID=3523},questType="standard"},
[10439] = {id=10439,name="Dimensius the All-Devouring",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Your brave actions have forced Ameer to react! He has deployed Captain Saeed and the Avengers! Now all that is left to do is destroy Dimensius. When you are ready, I will call for Saeed. If he is not currently fighting another battle, he will be awaiting orders from you directly east of here. Let him know when you are ready to fight and he will put his troops in motion! I wish you luck, fleshling! We have hunted Dimensius for a thousand years!",starts={{npcID=20907,x=0.6,y=0.318,zoneID=3523}},ends={{npcID=20907,x=0.6,y=0.318,zoneID=3523}},coords={x=0.6,y=0.318,source="quest_giver",zoneID=3523},questType="standard"},
[10440] = {id=10440,name="Success!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The test was a resounding success! We can certainly use this device to start repairing the domes. Carry word of the test results to the Stormspire and let Ghabar know that I've also found a pattern in the damage to the shield generators. Key pieces of generator units have gone missing from a number of sites. This is no accident, , no technological failure. We're being stolen from.",starts={{npcID=20913,x=0.446,y=0.144,zoneID=3523}},ends={{npcID=20811,x=0.434,y=0.35,zoneID=3523}},coords={x=0.446,y=0.144,source="quest_giver",zoneID=3523},questType="standard"},
[10442] = {id=10442,name="Helping the Cenarion Post",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description=", there's some tauren by the name of Thiah Redmane that keeps pestering us for assistance. She's with the Cenarion Expedition, and they've setup a little post just to the west on the south side of the road leading to Zangarmarsh. If you hit Thornfang Hill, you've gone too far. Do you think you might head over there and see what she needs? I don't want to have to bother Ranger Captain Venn'ren with such trivialities.",starts={{npcID=16790,x=0.276,y=0.604,zoneID=3483}},ends={{npcID=16991,x=0.156,y=0.522,zoneID=3483}},coords={x=0.276,y=0.604,source="quest_giver",zoneID=3483},questType="standard"},
[10443] = {id=10443,name="Helping the Cenarion Post",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="The Cenarion Circle has sent an expedition to Outland and, as I understand it, they are here to study what has happened and to help reverse any damage that they can. They've setup a little post just to the west on the south side of the road leading to Zangarmarsh. If you hit Thornfang Hill, you've gone too far. Would you please go and see how you might help them? Speak with Thiah Redmane as she is the one that sent the request to us for assistance.",starts={{npcID=16796,x=0.234,y=0.366,zoneID=3483}},ends={{npcID=16991,x=0.156,y=0.522,zoneID=3483}},coords={x=0.234,y=0.366,source="quest_giver",zoneID=3483},questType="standard"},
[10444] = {id=10444,name="Report to the Allerian Post",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="This calls for immediate action! We have someone out in the field closer to Firewing Point that I want you to speak with. He'll have a better idea of what our next step should be. Report to Lieutenant Meridian out at the Allerian Post and apprise him of the situation. You'll find the post to the northeast on the southern bank of the river just south of Firewing Point. Godspeed, .",starts={{npcID=18459,x=0.57,y=0.536,zoneID=3519}},ends={{npcID=21006,x=0.696,y=0.44,zoneID=3519}},coords={x=0.57,y=0.536,source="quest_giver",zoneID=3519},questType="standard"},
[10446] = {id=10446,name="The Final Code",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="They're building a second mana bomb in the courtyard. My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point. , you have to go back in there and retrieve the final code from him. He keeps himself to the top of the highest spire. Take the final code to the mana bomb that they're working on in the central courtyard and set it off. Only then will we be certain that the Allerian Stronghold is safe.",starts={{npcID=21006,x=0.696,y=0.44,zoneID=3519}},ends={{npcID=18459,x=0.57,y=0.536,zoneID=3519}},coords={x=0.696,y=0.44,source="quest_giver",zoneID=3519},questType="standard"},
[10447] = {id=10447,name="The Final Code",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="They're building a second mana bomb in the courtyard. My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point. , you have to go back in there and retrieve the final code from him. He keeps himself to the top of the highest spire. Take the final code to the mana bomb that they're working on in the central courtyard and set it off. Only then will we be certain that Stonebreaker Hold is safe.",starts={{npcID=21007,x=0.632,y=0.424,zoneID=3519}},ends={{npcID=18447,x=0.5,y=0.458,zoneID=3519}},coords={x=0.632,y=0.424,source="quest_giver",zoneID=3519},questType="standard"},
[10448] = {id=10448,name="Report to Stonebreaker Camp",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="This calls for immediate action! We have someone out in the field closer to Firewing Point that I want you to speak with. She'll have a better idea of what our next step should be. Report to Sergeant Chawni out at Stonebreaker Camp and apprise her of the situation. Take the road north out of the hold. From the middle of Tuurem, follow the road to the east. You'll find the camp on the bank of the river that lies just southwest of Firewing Point. Good luck, .",starts={{npcID=18447,x=0.5,y=0.458,zoneID=3519}},ends={{npcID=21007,x=0.632,y=0.424,zoneID=3519}},coords={x=0.5,y=0.458,source="quest_giver",zoneID=3519},questType="standard"},
[10449] = {id=10449,name="Apothecary Zelana",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Apethecary Zelana has been studying the beasts of Hellfire Peninsula in the field. She wants a sample of the blood you gathered; with luck, she might discover what turned those Bonechewer freaks' skins red! Zelana is at Reaver's Fall, southeast of Thrallmar. Follow the road east and when you see a destroyed, green-glowing hunk of metal, you're there. She has a camp set up behind the wyverns.",starts={{npcID=21256,x=0.55,y=0.362,zoneID=3483}},ends={{npcID=21257,x=0.662,y=0.42,zoneID=3483}},coords={x=0.55,y=0.362,source="quest_giver",zoneID=3483},questType="standard"},
[10450] = {id=10450,name="Bonechewer Blood",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Bonechewers! They should all die! The sight of their red skin and depravity makes my blood boil! I have a mission for you, . Kill Bonechewer orcs and collect their vile blood. There is an apothecary who needs the blood for her tests, so we can discover how these orcs fell to the demon taint, a taint from which we so recently freed ourselves. Bonechewers scavenge near the ruined battlements along the Path of Glory, to the south. Return to me when your mission is complete.",starts={{npcID=21256,x=0.55,y=0.362,zoneID=3483}},ends={{npcID=21256,x=0.55,y=0.362,zoneID=3483}},coords={x=0.55,y=0.362,source="quest_giver",zoneID=3483},questType="standard"},
[10451] = {id=10451,name="Escape from Coilskar Cistern",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Thank the Earthmother! I parted ways with the others several days ago. I was intent on discovering the source of the disturbance that the spirits of water were feeling. My search led me to Coilskar where I discovered that the naga were befouling the water supply of Shadowmoon Valley . Unfortunately, I was discovered and taken prisoner. There's no telling what ghastly things they had in store for me. We must leave this place! Help me escape and then seek out Torlok at the Altar of Damnation.",starts={{npcID=21027,x=0.52,y=0.188,zoneID=3520}},ends={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},coords={x=0.52,y=0.188,source="quest_giver",zoneID=3520},questType="group"},
[10455] = {id=10455,name="The Encroaching Wilderness",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="We've been growing the Living Grove at an accelerated rate, but somehow the lynxes there have become lost to our control. Where once their population was stable, the grovestalker lynxes are now beginning to encroach upon Sylvanaar, and there have been a number of unpleasant incidents of late. I suspect that the arakkoa of Veil Lashh are somehow behind it, but the immediate issue is with the lynxes themselves. I would be most grateful if you would help us to deal with this situation.",starts={{npcID=21066,x=0.362,y=0.672,zoneID=3522}},ends={{npcID=21066,x=0.362,y=0.672,zoneID=3522}},coords={x=0.362,y=0.672,source="quest_giver",zoneID=3522},questType="standard"},
[10456] = {id=10456,name="Marauding Wolves",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="The filthy races of the Horde have taken over a settlement to the east. They've brought with them a large pack of the dire wolves that they prefer to use as mounts and sentries. These sentries have been marauding across the bridge that separates us. They've been stalking our fey drakes, which are critical to the pollination of the Living Grove. Use the east exit to traverse the bridge over Bloodmaul Ravine that leads to the Jagged Ridge to the east, and bring me their tails as proof!",starts={{npcID=21066,x=0.362,y=0.672,zoneID=3522}},ends={{npcID=21066,x=0.362,y=0.672,zoneID=3522}},coords={x=0.362,y=0.672,source="quest_giver",zoneID=3522},questType="standard"},
[10457] = {id=10457,name="Protecting Our Own",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Though you've done a great deal of good work in defense of our new home here, I still feel that the Living Grove needs more protection. Please, take this small tree bough that I have imbued with the force of nature. When used upon the seedlings that I have planted out in the grove, it will call down a storm to accelerate the growth of a treant defender. These treants are critical to the defense of the grove, especially if you choose not to make Sylvanaar your home for long.",starts={{npcID=21066,x=0.362,y=0.672,zoneID=3522}},ends={{npcID=21066,x=0.362,y=0.672,zoneID=3522}},coords={x=0.362,y=0.672,source="quest_giver",zoneID=3522},questType="standard"},
[10458] = {id=10458,name="Enraged Spirits of Fire and Earth",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="We must try and make amends. We must commune with the elements of this region and see if anything can be done! I grant you the totem of spirits , . If you slay an enraged elemental spirit in close proximity of the totem, it will consume the elemental's soul. You must use the totem to consume many souls before you may return to me. Do this for the spirits of fire and earth first. Return to me when the totem is full.",starts={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},ends={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},coords={x=0.422,y=0.45,source="quest_giver",zoneID=3520},questType="standard"},
[10476] = {id=10476,name="Fierce Enemies",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="If you seek to prove your loyalty to us, there is no better way than to fight against our enemies. Of these, there are none that can match the ogres in strength and fierceness. Bring me the warbeads they wear around their necks as proof of their demise and I'll let the others know of your prowess.",starts={{npcID=18408,x=0.548,y=0.708,zoneID=3518}},ends={{npcID=18408,x=0.548,y=0.708,zoneID=3518}},coords={x=0.548,y=0.708,source="quest_giver",zoneID=3518},questType="standard"},
[10477] = {id=10477,name="More Warbeads",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,starts={{npcID=18408,x=0.548,y=0.708,zoneID=3518}},ends={{npcID=18183,x=0.554,y=0.688,zoneID=3518},{npcID=18408,x=0.548,y=0.708,zoneID=3518}},coords={x=0.548,y=0.708,source="quest_giver",zoneID=3518},questType="standard"},
[10478] = {id=10478,name="More Warbeads!",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,starts={{npcID=18407,x=0.558,y=0.378,zoneID=3518}},ends={{npcID=18407,x=0.558,y=0.378,zoneID=3518}},coords={x=0.558,y=0.378,source="quest_giver",zoneID=3518},questType="standard"},
[10479] = {id=10479,name="Proving Your Strength",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Though we seek a peaceful life, our enemies are many. Of these, none match the ogres in sheer brute power. If you seek to prove your prowess to us, bring me the warbeads they wear around their necks. I will tell others of your accomplishments.",starts={{npcID=18407,x=0.558,y=0.378,zoneID=3518}},ends={{npcID=18407,x=0.558,y=0.378,zoneID=3518}},coords={x=0.558,y=0.378,source="quest_giver",zoneID=3518},questType="standard"},
[10480] = {id=10480,name="Enraged Spirits of Water",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The Illidari naga of the region have taken control of the only clean water supply that exists in Shadowmoon Valley . Directly north of here you will find the lair of the naga: Coilskar. Around Coilskar are pockets of agitated water that howl to the land in anguish. It is at those pockets that the enraged spirits of water now wander. Travel to Coilskar and use the totem of spirits to capture watery souls. You will find the largest concentration of these spirits near Coilskar Cistern.",starts={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},ends={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},coords={x=0.422,y=0.45,source="quest_giver",zoneID=3520},questType="standard"},
[10481] = {id=10481,name="Enraged Spirits of Air",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Venture southeast, hero. When you see fields of gigantic blue crystals jutting out from the land, you will have reached your destination. It is there, at the Netherwing Fields, that you will find the enraged spirits of air. They roam the cliffs and mountain bases that surround the fields. Destroy their tortured forms and capture their souls with the totem of spirits . Return to me when this is done.",starts={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},ends={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},coords={x=0.422,y=0.45,source="quest_giver",zoneID=3520},questType="standard"},
[10482] = {id=10482,name="Fel Orc Scavengers",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Scavengers, orcs of the Bonechewer clan, skulk about the ruined battlements overlooking the Path of Glory. We must assume that these fel orcs are gathering war machine parts for their masters within Hellfire Citadel--they must be stopped! Find Bonechewer orcs to the north, . Find them and slay them! But use caution, for although these orcs are the lesser of the fel clans, their strength is the match of any orc we've faced thus far.",starts={{npcID=16820,x=0.51,y=0.602,zoneID=3483}},ends={{npcID=16820,x=0.51,y=0.602,zoneID=3483}},coords={x=0.51,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[10483] = {id=10483,name="Ill Omens",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description=", in our battles with the Bleeding Hollow clan of fel orcs, we have found upon them foreboding trinkets. These orcs have collected the insignias of fallen Honor Hold soldiers and created cursed talismans from them. We fear the dark magic of the Bleeding Hollow orcs have transformed our insignias into evil charms with powers against us! Find such a talisman from the Bleeding Hollow orcs of Zeth'Gor, to the east, and bring it to Corporal Ironridge at Expedition Point, northeast of Zeth'Gor.",starts={{npcID=16820,x=0.51,y=0.602,zoneID=3483}},ends={{npcID=21133,x=0.708,y=0.634,zoneID=3483}},coords={x=0.51,y=0.602,source="quest_giver",zoneID=3483},questType="standard"},
[10484] = {id=10484,name="Cursed Talismans",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description=", we cannot allow the Bleeding Hollow orcs to possess their cursed talismans ! You must acquire them for us so they may be disposed of, and so the soldiers who owned them may be honored for their sacrifices. Go to Zeth'Gor, the cursed abode of the Bleeding Hollow, and perform your grim task... return to me when you have collected the talismans.",starts={{npcID=21133,x=0.708,y=0.634,zoneID=3483}},ends={{npcID=21133,x=0.708,y=0.634,zoneID=3483}},coords={x=0.708,y=0.634,source="quest_giver",zoneID=3483},questType="standard"},
[10485] = {id=10485,name="Warlord of the Bleeding Hollow",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="You have shown great strength and fortune, for you have delved into Zeth'Gor and lived! Now, let us hope your fortune holds, for I have a dire task to ask of you... Warlord Morkh sits within the barracks of Zeth'Gor, commanding his fel troops against us. His tactics are as clever as they are cruel, and I must admit that his successes against us have cut deep. And so, , I ask you to remove Morkh from his seat. Bring me his armor so that we might display it for our soldiers and bolster them.",starts={{npcID=21133,x=0.708,y=0.634,zoneID=3483}},ends={{npcID=21133,x=0.708,y=0.634,zoneID=3483}},coords={x=0.708,y=0.634,source="quest_giver",zoneID=3483},questType="standard"},
[10486] = {id=10486,name="The Encroaching Wilderness",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The Thunderlord were once a proud orc clan before they were transformed into fel orcs through the blood of Mannoroth. Recently we recovered this orc stronghold from the ogres that infest the ravine below. They had moved in when the Thunderlord clan abandoned it. We will keep this place and I will have your help doing so. In the Jagged Ridge to the south and the west, there are bloodletters that have become like a plague upon us. They eat and breed incessantly. Kill them and then return to me.",starts={{npcID=21117,x=0.522,y=0.576,zoneID=3522}},ends={{npcID=21117,x=0.522,y=0.576,zoneID=3522}},coords={x=0.522,y=0.576,source="quest_giver",zoneID=3522},questType="standard"},
[10487] = {id=10487,name="Dust from the Drakes",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The Alliance has recently moved in to the west, using their elven magics to grow a town and grove in a short matter of time. We must keep their defenses weak so that they do not also grow a spine. I have a plan that will do that and more. I want you to traverse the bridge to the southwest, which crosses over Bloodmaul Ravine and leads into the Living Grove. Attack their fey drake defenses in the Living Grove and bring back the magical dust that sometimes can be found upon their wings.",starts={{npcID=21117,x=0.522,y=0.576,zoneID=3522}},ends={{npcID=21117,x=0.522,y=0.576,zoneID=3522}},coords={x=0.522,y=0.576,source="quest_giver",zoneID=3522},questType="standard"},
[10488] = {id=10488,name="Protecting Our Own",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="With the magical dust you recovered, I have fashioned a magic ointment that will aid in our own defenses. Our dire wolves are the perfect combination of mount, sentry and friend, but the Alliance scum have been poaching them in the Jagged Ridge. , I want you to take this ointment and apply it to our dire wolf friends. The Alliance will get a rude surprise the next time that they send one of their hunting parties. Be aware though that some of the wolves may not like this, and will turn on you.",starts={{npcID=21117,x=0.522,y=0.576,zoneID=3522}},ends={{npcID=21117,x=0.522,y=0.576,zoneID=3522}},coords={x=0.522,y=0.576,source="quest_giver",zoneID=3522},questType="standard"},
[10489] = {id=10489,name="Felling an Ancient Tree",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="WANTED! Stronglimb Deeproot, ancient of war and chief defender of the Living Grove south of Sylvanaar. Find him by heading west across the bridge that traverses the Bloodmaul Ravine. Return his hewn trunk to Tor'chunk Twoclaws .",starts={{npcID=184660,x=0.519,y=0.578,zoneID=3522}},ends={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},coords={x=0.519,y=0.578,source="quest_giver",zoneID=3522},questType="standard"},
[10502] = {id=10502,name="The Bloodmaul Ogres",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="There is a threat to Sylvanaar far deadlier than the Horde at Thunderlord Stronghold. I'm speaking of the native ogres of these mountains. Just to the south and east, down in the ravine, lives the Bloodmaul clan. While they aren't the only group of ogres that threaten us here, they are the closest. I would have you head south through the Living Grove, and then go down the path to the east, which leads to their outpost. Slay as many of the Bloodmaul ogres at Bloodmaul Outpost as you can.",starts={{npcID=21158,x=0.362,y=0.662,zoneID=3522}},ends={{npcID=21158,x=0.362,y=0.662,zoneID=3522}},coords={x=0.362,y=0.662,source="quest_giver",zoneID=3522},questType="standard"},
[10503] = {id=10503,name="The Bladespire Threat",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="There is a threat to Thunderlord Stronghold worse than the Alliance at Sylvanaar. I speak of the ogres of these mountains. Just to the west, down in the ravine, lies the Bladespire clan. While they aren't the only ogres, they are the closest and they're the ones that we defeated to take this place. Head north through the Jagged Ridge, and then down the path, which leads to their hold. Slay as many of the Bladespire ogres and their raptors as you can at Bladespire Hold and the Bladespire Grounds.",starts={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10504] = {id=10504,name="The Bladespire Ogres",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="To the north of the Bloodmaul clan lies a threat more grave: Bladespire Hold. The Bladespire ogres are the strongest clan in the mountains, having the favor of the gronn known as Gruul the Dragonkiller, and his seven sons. Now that we've dealt with winnowing the Bloodmaul, it is time to turn our eye upon their rivals. From Bloodmaul Hold head north through the ravine until you come to Bladespire Hold and the Bladespire Grounds. Slay as many of the Bladespire ogres therein as you can.",starts={{npcID=21158,x=0.362,y=0.662,zoneID=3522}},ends={{npcID=21158,x=0.362,y=0.662,zoneID=3522}},coords={x=0.362,y=0.662,source="quest_giver",zoneID=3522},questType="standard"},
[10505] = {id=10505,name="The Bloodmaul Ogres",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="To the south of the Bladespire clan lies yet another threat: Bloodmaul Outpost. While the Bloodmaul ogres are not the strongest clan in the mountains, not having the favor of the gronn known as Gruul the Dragonkiller, they run a close second. Now that we've dealt with winnowing the Bladespire, it is time to turn our eye upon their rivals. From Bladespire Hold head south through the ravine until you come to Bloodmaul Outpost. Slay as many of the Bloodmaul ogres in the vicinity as you can.",starts={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10506] = {id=10506,name="A Dire Situation",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="With their wolf pack reduced, the Horde is looking for replacements. Unfortunately there's another source nearby. The Bloodmaul ogres in the ravine below to the east keep a strong pack as their own sentries. I hated sending you to kill the Thunderlord wolves, so why don't we do something different this time? I've derived a magic powder from the dust that naturally falls off the wings of our fey drakes. Sprinkle it on the Bloodmaul dire wolves to make them undesirable to the Horde.",starts={{npcID=21066,x=0.362,y=0.672,zoneID=3522}},ends={{npcID=21066,x=0.362,y=0.672,zoneID=3522}},coords={x=0.362,y=0.672,source="quest_giver",zoneID=3522},questType="standard"},
[10507] = {id=10507,name="Turning Point",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="This is the chance we've been waiting for, . Not only have we uncovered the evidence we need to show our people who Kael'thas is really working for, but we can prove our strength by defeating his new masters. My frail health prevents me from aiding you in person with this endeavor, but I will offer you an object that will allow me to project my powers across the continent.",starts={{npcID=18530,x=0.426,y=0.914,zoneID=3703}},ends={{npcID=18530,x=0.426,y=0.914,zoneID=3703}},coords={x=0.426,y=0.914,source="quest_giver",zoneID=3703},questType="group"},
[10508] = {id=10508,name="A Gift for Voren'thal",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I don't want to send you to Voren'thal empty-handed. It's not in my style to be underwhelming. To gain access to Socrethar's Seat in the north, we'll need to use his own teleporters - locked by Socrethar's teleportation stone. The first half of the stone is in the possession of Forgemaster Morug at Forge Base Oblivion. The second half is held by the demon Silroth at Forge Base: Gehenna. Obtain these and Voren'thal will be impressed beyond words.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="group"},
[10509] = {id=10509,name="Bound for Glory",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="Now I can properly send you back to Shattrath City . You've uncovered evidence of Kael'thas making pacts with the Burning Legion and you've got the key to the overlord's back door. Make sure Voren'thal doesn't topple over with excitement from the news - the old man's getting a bit fragile, if you know what I mean. You'll find him inside the Seer's Library at the Scryer's Tier.",starts={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},ends={{npcID=18530,x=0.426,y=0.914,zoneID=3703}},coords={x=0.32,y=0.64,source="quest_giver",zoneID=3523},questType="standard"},
[10510] = {id=10510,name="Into the Draenethyst Mine",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Well it's good to see someone who's willing to help out around here! Borgrim and I are part of the Explorers' League, and we're here to learn what we can of these mountains. We've heard all sorts of tales, and I can't wait to get settled in and started. One thing in particular has caught my attention. The night elves speak of a place down in the ravine to the east known as the Draenethyst Mine. It's at the south end of Bloodmaul Outpost. I'd like some of the crystals that grow naturally therein.",starts={{npcID=21197,x=0.374,y=0.65,zoneID=3522}},ends={{npcID=21197,x=0.374,y=0.65,zoneID=3522}},coords={x=0.374,y=0.65,source="quest_giver",zoneID=3522},questType="standard"},
[10511] = {id=10511,name="Strange Brew",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="If I'm going to start this vacation out right, then I'm going to need more brew. Unfortunately, the elves know nothing of the fine art of fermentation. I overheard that the Bloodmaul ogres down in the ravine have plenty. I'm willing to give it a try. Do me a favor? Head south through the Living Grove and then down the ramp to the east into Bloodmaul Outpost and procure me some? I hear they have big barrels of it laying around and that their brewmasters carry it around to all the other ogres.",starts={{npcID=21151,x=0.374,y=0.646,zoneID=3522}},ends={{npcID=21151,x=0.374,y=0.646,zoneID=3522}},coords={x=0.374,y=0.646,source="quest_giver",zoneID=3522},questType="standard"},
[10512] = {id=10512,name="Getting the Bladespire Tanked",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I'll not take another sip of that ill-smelling muck! But it does give me an idea. So here's the plan. We know that the Bloodmaul practically live off of this swill. But I wonder what their enemies, the Bladespire ogres, think of it? , I want you to take the rest of this rubbish and see if you can get the Bladespire ogres tanked. You can find them by heading north from Bloodmaul Outpost through the ravine.",starts={{npcID=21151,x=0.374,y=0.646,zoneID=3522}},ends={{npcID=21151,x=0.374,y=0.646,zoneID=3522}},coords={x=0.374,y=0.646,source="quest_giver",zoneID=3522},questType="standard"},
[10513] = {id=10513,name="Oronok Torn-heart",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I do not know how we can acquire the spell that the spirits mentioned, . Truth be told, I don't even know where we would start such a search. Hrm... It is a long shot but it might be our only chance. There is an orc that I have seen visit this area before. I spoke to him briefly once. He is a hermit that claims to live above Coilskar Cistern to the northeast. Seek out this orc, Oronok Torn-heart . As I said, it is a long shot.",starts={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},ends={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},coords={x=0.422,y=0.45,source="quest_giver",zoneID=3520},questType="standard"},
[10514] = {id=10514,name="I Was A Lot Of Things...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I've been a lot of things, stranger, but what I once was isn't what's important. What I am now is what matters and what I am now is a farmer. I use trained felboars to dig up tubers from the hardened earth of the Shattered Plains. Recently, though, flayers from a nest to the northeast have been attacking my animals, preventing me from gathering tubers. Would you go to the area north of here and gather tubers for me? Use this whistle while standing on a tuber mound and a boar will come dig one up!",starts={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},ends={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},coords={x=0.538,y=0.234,source="quest_giver",zoneID=3520},questType="standard"},
[10515] = {id=10515,name="A Lesson Learned",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="We need to show those flayers what happens when you mess with Oronok's business! I want you to go back to the Shattered Plains and destroy every flayer egg that you see. They'll be deep in flayer territory so keep your guard up.",starts={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},ends={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},coords={x=0.538,y=0.234,source="quest_giver",zoneID=3520},questType="standard"},
[10516] = {id=10516,name="The Trappings of a Vindicator",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I know it's strange, but I do want to stay in this cage. It gives me the perfect opportunity to do what I came here for; to gather information on the Bladespire. I can leave at any time, but I would like to have my sword and shield back. Two of their leaders have my trappings. Droggam has my sword and Mugdorg has my shield. If you have need, obtain and use the brew from Bloodmaul Outpost to the south to thin out their help and entice those two, but beware their sober guards who don't drink!",starts={{npcID=21277,x=0.44,y=0.518,zoneID=3522}},ends={{npcID=21277,x=0.44,y=0.518,zoneID=3522}},coords={x=0.44,y=0.518,source="quest_giver",zoneID=3522},questType="standard"},
[10517] = {id=10517,name="Gorr'Dim, Your Time Has Come...",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="The leader of Bladespire Hold is known as Gorr'Dim . Trust me... the name is appropriate. Still, I wouldn't underestimate him. He's crafty enough to have elevated his clan to be the favorite of Gruul the Dragonkiller and they now dominate these mountains. And Gorr'Dim keeps an entourage about him at all times, including defenders who are sworn not to drink the Bloodmaul brew. For the safety of Sylvanaar, I'm asking that you go back in there and deal with him.",starts={{npcID=21277,x=0.44,y=0.518,zoneID=3522}},ends={{npcID=21277,x=0.44,y=0.518,zoneID=3522}},coords={x=0.44,y=0.518,source="quest_giver",zoneID=3522},questType="standard"},
[10518] = {id=10518,name="Planting the Banner",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I want you to steal the Bladespire banner from one of their champions and take it south to Bloodmaul Outpost. Plant it atop their Northmaul Tower. This will infuriate the Bloodmaul and they will attack you relentlessly. But it will also keep their hatred focused on Bladespire Hold, and away from Sylvanaar. You will know you have accomplished the deed when you have defeated Gurn Grubnosh and taken his helm. Return it to Sylvanaar. , this isn't going to be easy. Take a friend or two with you.",starts={{npcID=21277,x=0.44,y=0.518,zoneID=3522}},ends={{npcID=21158,x=0.362,y=0.662,zoneID=3522}},coords={x=0.44,y=0.518,source="quest_giver",zoneID=3522},questType="standard"},
[10519] = {id=10519,name="The Cipher of Damnation - Truth and History",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I had to be sure, . And to be sure, I had to test you. Please excuse the little masquerade. I am as much a farmer as you are a felboar. Which is to say, not at all. If you are to recover the Cipher of Damnation, you will need to listen to what I have to tell you. When you are ready, let me know and I will tell you the story.",starts={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},ends={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},coords={x=0.538,y=0.234,source="quest_giver",zoneID=3520},questType="standard"},
[10521] = {id=10521,name="Grom'tor, Son of Oronok",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="My first born, Grom'tor, left to search Coilskar Point - directly southwest of here. He's the warrior in the family - ill-tempered and blood-thirsty... Traits he inherited from his mother. Search along the outskirts of Coilskar Point. If you see naga corpses, Grom'tor is sure to be close. When you find him, tell him this: \"We spill blood for just cause.\" It will let him know that you are a friend to Torn-heart and prevent your premature death.",starts={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},ends={{npcID=21291,x=0.446,y=0.236,zoneID=3520}},coords={x=0.538,y=0.234,source="quest_giver",zoneID=3520},questType="standard"},
[10522] = {id=10522,name="The Cipher of Damnation - Grom'tor's Charge",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="This naga filth is the sixth one I've interrogated today. He's got the fancy armor so I figured he knew something. Those other ones were useless. I only had to beat him once and he told me everything. The first part of the cipher is hidden in a naga chest at Coilskar Point or Coilskar Cistern, east of here. He says naga carry the keys. Kill 'em, take their keys and use them to open the Coilskar chests. Return to me when you find the cipher.",starts={{npcID=21291,x=0.446,y=0.236,zoneID=3520}},ends={{npcID=21291,x=0.446,y=0.236,zoneID=3520}},coords={x=0.446,y=0.236,source="quest_giver",zoneID=3520},questType="standard"},
[10523] = {id=10523,name="The Cipher of Damnation - The First Fragment Recovered",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Take this box to father. He awaits your return at the farm, northeast of here. Tell him that I will be home soon. As soon as I am done having my fun...",starts={{npcID=21291,x=0.446,y=0.236,zoneID=3520}},ends={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},coords={x=0.446,y=0.236,source="quest_giver",zoneID=3520},questType="standard"},
[10524] = {id=10524,name="Thunderlord Clan Artifacts",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The artifact bears markings that indicate its origins as being created by the Thunderlord clan orcs. These orcs used to live at Thunderlord Stronghold before they were changed into fel orcs. For a time the Bladespire ogres inhabited the stronghold until recently when the Horde pushed them out. You've heard of other artifacts that were lost. A drum, an arrow and a tablet come to mind as objects that you know are being sought after. Find them in Bladespire Hold and return them to Rokgar Bloodgrip.",ends={{npcID=21311,x=0.528,y=0.588,zoneID=3522}},questType="standard"},
[10525] = {id=10525,name="Vision Guide",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="fool. You almost destroyed the drum! I've worked too hard to get here, and my hands have been empty up until now. At least you were able to succeed where the others only met with failure, or worse. It is time to evoke a vision that will lead you to the last relic that I have been seeking. Take this fiery fragment of my soul. Use it to transform your body into flame and denature your spirit into a vision guide that will shoot forth to reveal the location of the final Thunderlord relic.",starts={{npcID=21311,x=0.528,y=0.588,zoneID=3522}},ends={{npcID=21311,x=0.528,y=0.588,zoneID=3522}},coords={x=0.528,y=0.588,source="quest_giver",zoneID=3522},questType="standard"},
[10526] = {id=10526,name="The Thunderspike",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="If the vision that I granted you is true, then you must travel down into the ravine and to the south end of Bloodmaul Ravine. There you will find the Draenethyst Mine. Journey to the back of the mine, and retrieve the Thunderspike . Ignore everything else! I have no interest in the crystals of the mine, nor the ogres therein. As soon as you have the spear return it to me here! And, , be very careful with it... I would hate to think what would happen to you should you break it.",starts={{npcID=21311,x=0.528,y=0.588,zoneID=3522}},ends={{npcID=21311,x=0.528,y=0.588,zoneID=3522}},coords={x=0.528,y=0.588,source="quest_giver",zoneID=3522},questType="standard"},
[10527] = {id=10527,name="Ar'tor, Son of Oronok",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="My youngest son, Ar'tor, left to search Illidari Point - far to the southwest, nestled between Legion Hold and Wildhammer Stronghold. While Ar'tor is a hunter of remarkable skill and an expert tracker, I fear that he may be in over his head this time. Illidari Point is the proving grounds for Illidan's demons. These are demons that left the Burning Legion to join the Betrayer! Travel to Illidari Point and find Ar'tor, .",starts={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},ends={{npcID=21292,x=0.296,y=0.504,zoneID=3520}},coords={x=0.538,y=0.234,source="quest_giver",zoneID=3520},questType="standard"},
[10528] = {id=10528,name="Demonic Crystal Prisons",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="From assessing the scene, you note that Ar'tor is being held in place by energy beams emanating from the crystals hovering around the rune. Try as you might, Ar'tor is unmovable. You note that the crystals have an empty slot at their base - perhaps for a key. It also seems as if succubi periodically perform some sort of ritual at the site. Search Illidari Point for their leader. Perhaps she holds the key to releasing Ar'tor.",starts={{npcID=21292,x=0.296,y=0.504,zoneID=3520}},ends={{npcID=21292,x=0.296,y=0.504,zoneID=3520}},coords={x=0.296,y=0.504,source="quest_giver",zoneID=3520},questType="standard"},
[10537] = {id=10537,name="Lohn'goron, Bow of the Torn-heart",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="It is a sign, . Even in death, I cannot be stopped. Recovering a part of the Cipher of Damnation is my destiny. With your help, that destiny will be fulfilled. Before we embark on that journey, I must have my longbow, Lohn'goron. It is a family heirloom that has been handed down from Torn-heart to Torn-heart for generations. My instinct tells me that a demon stole it from my corpse. Kill the demons here until you find my bow.",starts={{npcID=21318,x=0.296,y=0.504,zoneID=3520}},ends={{npcID=21318,x=0.296,y=0.504,zoneID=3520}},coords={x=0.296,y=0.504,source="quest_giver",zoneID=3520},questType="standard"},
[10538] = {id=10538,name="Boiling Blood",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="That last experiment was not a complete loss -- I did save a small bit of the blood you brought me. Now boiled down, it should be free of whatever curses the Bleeding Hollow witches placed on their people's blood. I need more for study. Go gather Bleeding Hollow blood from the orcs in Zeth'Gor. When you've gathered the blood, bring it to their cursed cauldron and boil it. Bring me the boiled blood .",starts={{npcID=21279,x=0.612,y=0.816,zoneID=3483}},ends={{npcID=21279,x=0.612,y=0.816,zoneID=3483}},coords={x=0.612,y=0.816,source="quest_giver",zoneID=3483},questType="standard"},
[10540] = {id=10540,name="The Cipher of Damnation - Ar'tor's Charge",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="At last, we are ready. I will bestow a piece of my spirit upon you, hero. It will guard you and help you in your battle against evil. You must then travel south of here towards the back of Illidari Point. Hidden in the ether is a vile creature known as Veneratus the Many. My spirit hunter will call him out when he is near. Destroy Veneratus and take from his corpse the second part of the Cipher of Damnation.",starts={{npcID=21318,x=0.296,y=0.504,zoneID=3520}},ends={{npcID=21318,x=0.296,y=0.504,zoneID=3520}},coords={x=0.296,y=0.504,source="quest_giver",zoneID=3520},questType="standard"},
[10541] = {id=10541,name="The Cipher of Damnation - The Second Fragment Recovered",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I thank you, hero. For without you, my spirit would forever remain in this cursed place. Take it and deliver it to my father at the farm, far to the northeast, above Coilskar Cistern... Inside are Lohn'goron and the second part of the cipher. He will be sad to hear news of my death. Promise me that you will assure him that I died a free soul. Tell him that I see the hunting grounds and they are glorious. Tell him that I wait for him there...",starts={{npcID=21318,x=0.296,y=0.504,zoneID=3520}},ends={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},coords={x=0.296,y=0.504,source="quest_giver",zoneID=3520},questType="standard"},
[10542] = {id=10542,name="They Stole Me Hookah and Me Brews!",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="T'chali used to be a pretty friendly troll. Me come down here to teach the Bloodmaul how to brew their beer. But once me do that, the Bloodmaul bury T'chali and leave him here to rot! The worst part of it was that they stole me hookah! So, you want to help T'chali? You bring me hookah back. T'chali think the ogres that stole it headed southwest over by the mine. And while you're in there, pick up some brews, too!",starts={{npcID=21349,x=0.45,y=0.722,zoneID=3522}},ends={{npcID=21349,x=0.45,y=0.722,zoneID=3522}},coords={x=0.45,y=0.722,source="quest_giver",zoneID=3522},questType="standard"},
[10543] = {id=10543,name="Grimnok and Korgaah, I Am For You!",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="T'chali has been waiting for his revenge! The day they bury T'chali and leave him to die, it was Grimnok Battleborn that led them. And the next day it was Korgaah that come south to raid and kick T'chali in the head. I want them dead! You will find Grimnok atop the Southmaul Tower in Bloodmaul Outpost. You will find Korgaah in the top of a building at the north end of Bladespire Hold. Korgaah has sober defenders, so use the brew to distract him away from them, because they won't drink.",starts={{npcID=21349,x=0.45,y=0.722,zoneID=3522}},ends={{npcID=21349,x=0.45,y=0.722,zoneID=3522}},coords={x=0.45,y=0.722,source="quest_giver",zoneID=3522},questType="standard"},
[10544] = {id=10544,name="A Curse Upon Both of Your Clans!",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="T'chali wants revenge on all of the ogres! T'chali was a powerful witch doctor in life. If you reach into me grave you will find a wicked strong fetish . Invoke the fetish's magic at the entrances to the buildings and towers of both Bladespire Hold and Bloodmaul Outpost. The voodoo you work will summon an evil spirit that you must defeat. This in turn will curse that building. Beware, if you attempt to curse a building that is already cursed, you will call down another cursed spirit!",starts={{npcID=21349,x=0.45,y=0.722,zoneID=3522}},ends={{npcID=21349,x=0.45,y=0.722,zoneID=3522}},coords={x=0.45,y=0.722,source="quest_giver",zoneID=3522},questType="standard"},
[10545] = {id=10545,name="Bladespire Kegger",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="As T'chali was saying, he helped out his Bloodmaul friends to make their brew. But what T'chali did not say was why. The Bloodmaul are in dire straits. The Bladespire clan be crushing them, and they needed a new weapon to help out with their fight. That's when T'chali came up with a great idea. Why not make the perfect brew, one that strengthens you and weakens your enemy? Only thing is, T'chali does not know if it works. So, you gonna take this brew up to Bladespire Hold and see if it works!",starts={{npcID=21349,x=0.45,y=0.722,zoneID=3522}},ends={{npcID=21349,x=0.45,y=0.722,zoneID=3522}},coords={x=0.45,y=0.722,source="quest_giver",zoneID=3522},questType="standard"},
[10546] = {id=10546,name="Borak, Son of Oronok",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="While Ar'tor was off hunting and Grom'tor was off fighting, Borak studied. Eventually he took up a vocation as a scholar and left for the wilds of Draenor. He returned home a few years ago a changed orc. His heightened sense of awareness and mental acuity had forged a silent assassin. Now a confident and powerful orc, he has taken to recovering the most guarded piece of the cipher. Find Borak hiding near Eclipse Point, far to the south. He watches from the shadows of the bridge.",starts={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},ends={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},coords={x=0.538,y=0.234,source="quest_giver",zoneID=3520},questType="standard"},
[10547] = {id=10547,name="Of Thistleheads and Eggs...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="I'd have given up had I not noticed... He's a Thistlehead. I couldn't place it at first but the signs are all there... Now if we could get our hands on some bloodthistle, we'd be in business. In my travels, I met a shady Broken in Shattrath named Tobias. Tobias made a business of trading bloodthistle to blood elves for rotten arakkoa eggs . Directly west of here are arakkoa ruins. Search them for an egg and head to the lower city of Shattrath. That's where you'll find Tobias.",starts={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},ends={{npcID=21411,x=0.638,y=0.698,zoneID=3703}},coords={x=0.474,y=0.572,source="quest_giver",zoneID=3520},questType="standard"},
[10550] = {id=10550,name="The Bundle of Bloodthistle",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I wasn't lying. That egg was incredible. Where did you get it from? Well, if you ever need more bloodthistle, you know where I am and what I need. Here's a bundle of the stuff. Take it back to your benefactor.",starts={{npcID=21411,x=0.638,y=0.698,zoneID=3703}},ends={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},coords={x=0.638,y=0.698,source="quest_giver",zoneID=3703},questType="standard"},
[10551] = {id=10551,name="Allegiance to the Aldor",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,mapID=111,starts={{npcID=18166,x=0.546,y=0.44,mapID=111}},ends={{npcID=18166,x=0.546,y=0.44,mapID=111}},coords={x=0.546,y=0.44,source="quest_giver",mapID=111},questType="standard"},
[10552] = {id=10552,name="Allegiance to the Scryers",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,mapID=111,starts={{npcID=18166,x=0.546,y=0.44,mapID=111}},ends={{npcID=18166,x=0.546,y=0.44,mapID=111}},coords={x=0.546,y=0.44,source="quest_giver",mapID=111},questType="standard"},
[10553] = {id=10553,name="Voren'thal the Seer",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Now that you've chosen a side, , you should meet the Scryers' leader. You will find Voren'thal the Seer inside the Seer's Library at the Scryer's Tier. See if you can be of assistance to him. He will be glad to hear you've decided to lend them a hand.",starts={{npcID=18166,x=0.546,y=0.44,zoneID=3703}},ends={{npcID=18530,x=0.426,y=0.914,zoneID=3703}},coords={x=0.546,y=0.44,source="quest_giver",zoneID=3703},questType="standard"},
[10554] = {id=10554,name="Ishanah",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Now that you've decided to side with the Aldor, you'd do well to introduce yourself to their leader. You will find High Priestess Ishanah inside the Shrine of Unending Light.",starts={{npcID=18166,x=0.546,y=0.44,zoneID=3703}},ends={{npcID=18538,x=0.242,y=0.298,zoneID=3703}},coords={x=0.546,y=0.44,source="quest_giver",zoneID=3703},questType="standard"},
[10555] = {id=10555,name="Malaise",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="The magic practiced by the Lashh'an arakkoa is unnatural. They rip out handfuls-clawfuls?-of their own feathers as reagents! That doesn't sound like good magic to me. I've come here to learn more about their spells. Unfortunately getting close is too much for me. You could succeed: cast one of their spells on yourself, then return to me. You'll have to find one of their spellbooks, high up in the trees of Veil Lashh. And unless you've grown feathers I can't see, you'll need to get some of those.",starts={{npcID=21469,x=0.37,y=0.656,zoneID=3522}},ends={{npcID=184825,x=0.343,y=0.773,zoneID=3522}},coords={x=0.37,y=0.656,source="quest_giver",zoneID=3522},questType="standard"},
[10556] = {id=10556,name="Scratches",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="The pictograms indicate using feathers to cast the spell at one of the circles of power in Veil Lashh. Confusing iconography seems to show an arakkoa being suffused with the spirit of a kaliri.",starts={{npcID=184825,x=0.343,y=0.773,zoneID=3522}},ends={{npcID=21469,x=0.37,y=0.656,zoneID=3522}},coords={x=0.343,y=0.773,source="quest_giver",zoneID=3522},questType="standard"},
[10557] = {id=10557,name="Test Flight: The Zephyrium Capacitorium",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I built an amazing device, the Zephyrium Capacitorium, and I'm sure it'll work perfectly, but... do you want to help me test it? There's plenty of hazard pay! Speak with my twin over there, Rally. Good luck, . Come back after your experiment. Or... if that's not possible due to sustained injuries, your next of kin can report to collect your pay.",starts={{npcID=21460,x=0.602,y=0.684,zoneID=3522}},ends={{npcID=21460,x=0.602,y=0.684,zoneID=3522}},coords={x=0.602,y=0.684,source="quest_giver",zoneID=3522},questType="standard"},
[10562] = {id=10562,name="Besieged!",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Don't let your guard down, . We're under constant assault from the Burning Legion. From their base of Legion Hold to the northwest, the demons rain down a ceaseless stream of infernals. As quickly as we can kill them, the new meteors impact and begin a new wave of attacks. My men are ragged and exhausted. I don't know how much longer they'll hold out. Please, , lend your help to our defenses. Take your place on the line and halt the advance of the infernals!",starts={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},ends={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=3520},questType="standard"},
[10563] = {id=10563,name="To Legion Hold",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="The fortress of Legion Hold is nigh impregnable, and to be completely honest, I can't spare the forces for an assault. Our hopes are riding on you, . What little information we've been able to gather indicates that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and learn about their plans. Your best hope is to intercept or overhear communication between their commanders. Good luck, .",starts={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},ends={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=3520},questType="standard"},
[10564] = {id=10564,name="Blast the Infernals!",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power. If you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.",starts={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},ends={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=3520},questType="standard"},
[10565] = {id=10565,name="The Stones of Vekh'nir",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The arakkoa of Vekh'nir have been a thorn in our sides for many years. Some strange religion guides them, a religion which has the arakkoa in a frenzy of activity. They carry these crystals with them now, which they have turned to some dark purpose. I know something of their rituals. They take the crystals to their spell circles to infuse them. We at the village would like to know more. Waylay a few of the arakkoa until you find a crystal, charge it, then return it to me.",starts={{npcID=21496,x=0.752,y=0.62,zoneID=3522}},ends={{npcID=21496,x=0.752,y=0.62,zoneID=3522}},coords={x=0.752,y=0.62,source="quest_giver",zoneID=3522},questType="standard"},
[10566] = {id=10566,name="Trial and Error",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="I've fashioned four wands that I believe will enhance the power of the arakkoa's crystals. Take these wands to Trogma's Claim, and try them on the ogre slaves. You'll need to find an infused crystal off of the arakkoa in the area. When you figure out which is best, come back to me.",starts={{npcID=21496,x=0.752,y=0.62,zoneID=3522}},ends={{npcID=21496,x=0.752,y=0.62,zoneID=3522}},coords={x=0.752,y=0.62,source="quest_giver",zoneID=3522},questType="standard"},
[10567] = {id=10567,name="Creating the Pendant",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="The arakkoa of Ruaan Weald elevate from their flock the Harbingers of the Raven, the heralds of their god. They believe that the Harbingers watch over them from the sky, where they receive the teachings of the Raven, and descend to pass this message along. The Harbingers hold a powerful sway over the souls of the arakkoa. They use magical pendants, which we need. Attract one of the Harbingers by slaying its flock and taking their claws. Place the claws upon the altar to get his attention.",starts={{npcID=21782,x=0.622,y=0.39,zoneID=3522}},ends={{npcID=21782,x=0.622,y=0.39,zoneID=3522}},coords={x=0.622,y=0.39,source="quest_giver",zoneID=3522},questType="standard"},
[10568] = {id=10568,name="Tablets of Baa'ri",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Years ago, the dreaded warlock known as Gul'dan raised the volcano in the middle of Shadowmoon. The draenei village of Baa'ri, to the southwest, was buried under the lava along with its inhabitants and artifacts of religious importance. The treacherous tribe of Broken known as the Ashtongue has been ordered by Illidan to excavate the area. We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor, now known as the Black Temple.",starts={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},ends={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},coords={x=0.624,y=0.284,source="quest_giver",zoneID=3520},questType="standard"},
[10569] = {id=10569,name="The Sketh'lon Wreckage",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Our scouts have brought back disturbing reports from the ruined arakkoa encampments in the area. The ghosts of powerful arakkoa magicians wield powers we never thought they possessed. They seem to be organizing, as though preparing for something, but our knowledge is limited. We cannot afford to remain ignorant! Travel north to the Sketh'lon Wreckage, to the northwest of the Deathforge and search for signs of their motives.",starts={{npcID=22042,x=0.386,y=0.542,zoneID=3520}},ends={{npcID=22042,x=0.386,y=0.542,zoneID=3520}},coords={x=0.386,y=0.542,source="quest_giver",zoneID=3520},questType="standard"},
[10570] = {id=10570,name="To Catch A Thistlehead",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="bundle of bloodthistle from you and places it to his nose.> Pungent... Now, take this bundle and place it at the other end of this bridge. When the envoy makes his daily rounds, he will be compelled to pick it up - without his bodyguard. You see, blood elves look down upon bloodthistle addicts. If any of his compatriots ever found out... All you need to do is lie in wait for him to dismiss his bodyguard. When he is alone, make your strike! Kill him and take the missive.",starts={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},ends={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},coords={x=0.474,y=0.572,source="quest_giver",zoneID=3520},questType="standard"},
[10571] = {id=10571,name="Oronu the Elder",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri. Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor. We must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet. Its power would provide great aid in our fight against Illidan. Akama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily. Obtain them and bring them to me.",starts={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},ends={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},coords={x=0.624,y=0.284,source="quest_giver",zoneID=3520},questType="standard"},
[10572] = {id=10572,name="Setting Up the Bomb",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="We cannot permit the Legion to carry out its plan to destroy Wildhammer Stronghold on their march to the Black Temple. There's only one way to stop them, . You must create an explosive large enough to destroy the Legion's entire stockpile of infernals at the hold. The Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the base of your device. Search the other wreckage near the fel reaver for armor plating we might be able to make a casing from.",starts={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},ends={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=3520},questType="standard"},
[10573] = {id=10573,name="The Deathforge",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="From your findings at Legion Hold, we know that the Legion's Shadow Council allies are producing infernals in the Deathforge. I've dispatched a small scouting party to keep watch over the area, but they're not able to accomplish everything we need. If the Deathforge is left alone to operate, they'll rebuild the infernal stockpile that you destroyed at Legion Hold. I want you to meet up with Stormer Ewan Wildwing , at the Deathforge Tower, to the northwest, overlooking the Deathforge itself.",starts={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},ends={{npcID=21471,x=0.404,y=0.412,zoneID=3520}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=3520},questType="standard"},
[10574] = {id=10574,name="The Ashtongue Corruptors",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors. These dreaded Broken were once powerful shaman who now defile the very elements they revered. Haalum, Corruptor of Air, can be found at Netherwing Pass. Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan. Lakaan, Corruptor of Water, is rumored to be near Coilskar Point. Find them and obtain the medallion fragments.",starts={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},ends={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},coords={x=0.624,y=0.284,source="quest_giver",zoneID=3520},questType="standard"},
[10575] = {id=10575,name="The Warden's Cage",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The fragments you obtained are only half of the medallion. The Ashtongue leader, Akama, must have kept the other half. I dread to ask this of you, as Akama is both evil and cunning. He and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage. I want you to find that dreaded prison, and find the whereabouts of Akama. His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.",starts={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},ends={{npcID=21826,x=0.572,y=0.496,zoneID=3520}},coords={x=0.624,y=0.284,source="quest_giver",zoneID=3520},questType="standard"},
[10576] = {id=10576,name="The Shadowmoon Shuffle",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="This is going to be tricky, but I think I can make it work. I can disguise you as one of these Illidari blood elves, . What I need first, though, are several pieces of their armor. It is imperative that the armor be clean. No blood stains! We want to avoid suspicion. Bring me the gear and I'll take care of the rest of the disguise. Once the disguise is assembled, you're going to deliver the message to the Grand Commander - in person.",starts={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},ends={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},coords={x=0.474,y=0.572,source="quest_giver",zoneID=3520},questType="standard"},
[10577] = {id=10577,name="What Illidan Wants, Illidan Gets...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Take this disguise and enter Eclipse Point. Once inside, use the disguise to cloak yourself. The Eclipsion blood elves will be unable to see through the disguise, thereby granting you safe passage to Grand Commander Ruusk. Once you find Ruusk, tell him where next to move the cipher. You're going to have to act your heart out, . Play it off as if you are his superior, delivering a message from his lord. That should do it! Oh - watch out for the dragonhawks as they see through the disguise.",starts={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},ends={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},coords={x=0.474,y=0.572,source="quest_giver",zoneID=3520},questType="standard"},
[10578] = {id=10578,name="The Cipher of Damnation - Borak's Charge",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="That Cipher fragment will never reach Zuluhed. You're going to ambush Ruul the Darkener and his transport before it has a chance to make the delivery. The Dragonmaw Fortress is directly east of here, across the Netherwing Fields. Somewhere between Dragonmaw Fortress and the Sanctum of the Stars is where you'll find Ruul. Strike hard and strike fast! And , from the sound of it, this Ruul is going to be tough. Keep your guard up. Return the Cipher to me should you succeed.",starts={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},ends={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},coords={x=0.474,y=0.572,source="quest_giver",zoneID=3520},questType="group"},
[10579] = {id=10579,name="The Cipher of Damnation - The Third Fragment Recovered",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Take this box to my father. He still resides at Oronok's Farm, far to the north, above Coilskar Cistern. When all three fragments are pieced together, the ancient words will be known once more. Good luck, . Tell my father that I will be home soon.",starts={{npcID=21293,x=0.474,y=0.572,zoneID=3520}},ends={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},coords={x=0.474,y=0.572,source="quest_giver",zoneID=3520},questType="standard"},
[10580] = {id=10580,name="Where Did Those Darn Gnomes Go?",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Despite the good that we've done here, I feel bad about one thing: driving Toshley and his gnome friends away. We had no choice; they were making a mess of our efforts in the grove with all of their technology and experimentation. I would appreciate it if you would find out what became of them. Last we heard, they headed east across the bridge. I'm certain that they must have turned south, away from Thunderlord Stronghold. Look for a clue as to their whereabouts in the southern Jagged Ridge.",starts={{npcID=21158,x=0.362,y=0.662,zoneID=3522}},ends={{npcID=21690,x=0.55,y=0.728,zoneID=3522}},coords={x=0.362,y=0.662,source="quest_giver",zoneID=3522},questType="standard"},
[10581] = {id=10581,name="Follow the Breadcrumbs",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="VERY WELL, I AM HEREBY WARNING YOU THAT YOU WILL FIND NOTHING UP ON THE RIDGE. DO NOT FOLLOW THE TRAIL OF SPARE PARTS THAT LEAD TO TOSHLEY 'S STATION! YOU WILL NOT FIND TOSHLEY , NOR ANY OTHER GNOME THERE.",starts={{npcID=21690,x=0.55,y=0.728,zoneID=3522}},ends={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},coords={x=0.55,y=0.728,source="quest_giver",zoneID=3522},questType="standard"},
[10582] = {id=10582,name="Minions of the Shadow Council",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="That puts our observations into perspective. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that. The Shadow Council has the Deathforge sealed tighter than a new keg o' thunderbrew. The first thing you'll need to do is crack some skulls so you can get in there and poke around. Start eliminating the Shadow Council guarding the entrance to the Deathforge!",starts={{npcID=21471,x=0.404,y=0.412,zoneID=3520}},ends={{npcID=21471,x=0.404,y=0.412,zoneID=3520}},coords={x=0.404,y=0.412,source="quest_giver",zoneID=3520},questType="standard"},
[10583] = {id=10583,name="The Fate of Flanis",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Wing Commander Nuainn originally sent three of us out here to keep watch over the Deathforge and to gather information. Flanis Swiftwing volunteered to try to infiltrate the Deathforge, but we haven't heard anything from him in days. I fear the worst, . Flanis is a skilled scout, but if he's gotten in over his head, we have no way of knowing. Search the Deathforge for him and recover any information or items he might have collected.",starts={{npcID=21471,x=0.404,y=0.412,zoneID=3520}},ends={{npcID=21471,x=0.404,y=0.412,zoneID=3520}},coords={x=0.404,y=0.412,source="quest_giver",zoneID=3520},questType="standard"},
[10584] = {id=10584,name="Picking Up Some Power Converters",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Those dumb ogres at the Bladespire Outpost to the north have been raiding our power converters! And you're going to get them back for me, sort of. No doubt, with their big, clumsy hands, the ogres have damaged the converters. So, what I want you to do is release the energy from them and then use this protovoltaic magneto collector on the resultant electromental to encase it. It'll likely be sore with you, so you'll need to 'kill' it while it's contained in the magneto sphere.",starts={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},ends={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},coords={x=0.604,y=0.69,source="quest_giver",zoneID=3522},questType="standard"},
[10585] = {id=10585,name="The Summoning Chamber",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="In order for the Shadow Council to construct infernals as quickly as they're being used, they must have an area dedicated to summoning the corrupted elementals that serve as the souls of the creatures. The summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.",starts={{npcID=21471,x=0.404,y=0.412,zoneID=3520}},ends={{npcID=21471,x=0.404,y=0.412,zoneID=3520}},coords={x=0.404,y=0.412,source="quest_giver",zoneID=3520},questType="standard"},
[10586] = {id=10586,name="Bring Down the Warbringer!",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="We've made a lot of progress against the Shadow Council's operations at the Deathforge, but if we're to truly be triumphant, we'll need to defeat the Legion's overseer there. I found a key among the items in Flanis's pack. I'm certain it will prove useful in tracking down this Warbringer Razuun you observed at Legion Hold. After you've hunted down and dealt with Warbringer Razuun , report directly to Wing Commander Nuainn . He'll want to know immediately!",starts={{npcID=21471,x=0.404,y=0.412,zoneID=3520}},ends={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},coords={x=0.404,y=0.412,source="quest_giver",zoneID=3520},questType="standard"},
[10587] = {id=10587,name="Karabor Training Grounds",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor. Normally this would represent a purely military threat, however we believe something else is amiss. Descriptions of their attire and fighting style are suspiciously close to that of Illidan himself. I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons. We will then determine whether my fears are unfounded or not.",starts={{npcID=21860,x=0.612,y=0.292,zoneID=3520}},ends={{npcID=21860,x=0.612,y=0.292,zoneID=3520}},coords={x=0.612,y=0.292,source="quest_giver",zoneID=3520},questType="standard"},
[10588] = {id=10588,name="The Cipher of Damnation",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="How many times has this spell been used in the history of our worlds? Undoubtedly, its power for destruction is unparalleled. What you must do now is take the cipher, now made whole, and read from it at the Altar of Damnation - where the memory of Gul'dan stands. What you will see once the words are uttered are the memories left imprinted upon the land. Stand your ground and await the coming of Cyrukh. You must be victorious, . This land cannot withstand another shattering.",starts={{npcID=21183,x=0.538,y=0.234,zoneID=3520}},ends={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},coords={x=0.538,y=0.234,source="quest_giver",zoneID=3520},questType="group"},
[10589] = {id=10589,name="Gaining Access",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's nestled in the northern mountains. The only way to reach it is by using a teleporter located at Legion Hold. Certain members of the Legion host carry devices allowing them to activate the teleporters. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed.",starts={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},ends={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=3520},questType="standard"},
[10594] = {id=10594,name="Gauging the Resonant Frequency",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Take these scanners to the Singing Ridge. By dropping them in a pattern on the ground, you will create overlapping fields that will read the amplitude of the crystals. Stand amidst them in such a way that you're in five oscillation fields and I'll have the information that I need! Your scanners will even work with those that others drop. Oh, and it's likely that a rift will be formed! I have no idea what, if anything, will come out of it, but be prepared for the worst.",starts={{npcID=21755,x=0.602,y=0.69,zoneID=3522}},ends={{npcID=21755,x=0.602,y=0.69,zoneID=3522}},coords={x=0.602,y=0.69,source="quest_giver",zoneID=3522},questType="standard"},
[10595] = {id=10595,name="Besieged!",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Our scouts are putting up a good fight, but the infernals keep coming! From their base of Legion Hold to the southwest, the demons bombard us with impunity! Even the elite Kor'kron guard cannot hold them off forever. I'm drafting every able-bodied to do their part in defense of Shadowmoon Village. This is no game, . The survival of the village is at stake. Do your duty to the Horde, and join the fray!",starts={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},ends={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},coords={x=0.304,y=0.324,source="quest_giver",zoneID=3520},questType="standard"},
[10596] = {id=10596,name="To Legion Hold",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The fortress of Legion Hold is your target. You'll have no reinforcements, so a frontal attack is out of the question. What little information we have shows that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and discover their plans. Your best hope is to intercept or overhear communication between their commanders.",starts={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},ends={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},coords={x=0.304,y=0.324,source="quest_giver",zoneID=3520},questType="standard"},
[10597] = {id=10597,name="Setting Up the Bomb",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="We can't allow the Legion to trample us on their march to Black Temple. Find a way to destroy the infernals they intend to use against us. That's not a request, ; it's an order. The Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the basis for a kind of fel bomb. Search the other wreckage near the fel reaver for a section of armor plating. You should be able to make a bomb powerful enough to take out those infernals and give the hold a nice shake!",starts={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},ends={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},coords={x=0.304,y=0.324,source="quest_giver",zoneID=3520},questType="standard"},
[10598] = {id=10598,name="Blast the Infernals!",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power. If you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.",starts={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},ends={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},coords={x=0.304,y=0.324,source="quest_giver",zoneID=3520},questType="standard"},
[10599] = {id=10599,name="The Deathforge",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="While you were taking care of the infernals at Legion Hold, I've been going over your reports. We've got no reason to believe the Legion lied about what's going on at the Deathforge. They're really cranking out infernals down there, so I've dispatched a scouting party to keep watch over it. If we don't shut down the Deathforge, they'll rebuild the infernal stockpile that you destroyed at Legion Hold. Report to Scout Zagran atop Slag Watch, to the southeast of here and overlooking the Deathforge.",starts={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},ends={{npcID=21475,x=0.386,y=0.382,zoneID=3520}},coords={x=0.304,y=0.324,source="quest_giver",zoneID=3520},questType="standard"},
[10600] = {id=10600,name="Minions of the Shadow Council",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="That fills in the gaps we've seen. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that. The Shadow Council has the forge pretty much locked down. Looks like you're going to need to fight your way in. Start eliminating the Shadow Council guarding the entrance to the Deathforge!",starts={{npcID=21475,x=0.386,y=0.382,zoneID=3520}},ends={{npcID=21475,x=0.386,y=0.382,zoneID=3520}},coords={x=0.386,y=0.382,source="quest_giver",zoneID=3520},questType="standard"},
[10601] = {id=10601,name="The Fate of Kagrosh",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The scouting party originally had three members. Unfortunately, Kagrosh decided he wanted to be a hero. He descended into the Deathforge and we haven't heard from him since. In all likelihood, the fool's gone and gotten himself killed. The Shadow Council members aren't idiots and Kagrosh wasn't exactly strong in the subtlety department, if you know what I mean. Keep an eye out for him in the Deathforge and recover any information or items he might have collected.",starts={{npcID=21475,x=0.386,y=0.382,zoneID=3520}},ends={{npcID=21475,x=0.386,y=0.382,zoneID=3520}},coords={x=0.386,y=0.382,source="quest_giver",zoneID=3520},questType="standard"},
[10602] = {id=10602,name="The Summoning Chamber",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="In order to churn out infernals as quickly as the Deathforge seems to, they must have an area dedicated to summoning the elementals that form the core of the infernals. The summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.",starts={{npcID=21475,x=0.386,y=0.382,zoneID=3520}},ends={{npcID=21475,x=0.386,y=0.382,zoneID=3520}},coords={x=0.386,y=0.382,source="quest_giver",zoneID=3520},questType="standard"},
[10603] = {id=10603,name="Bring Down the Warbringer!",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="We've made a lot of progress against the Shadow Council here at the Deathforge, but now it's time to finish the job. I found a key among the items in Kagrosh's pack. At least he accomplished something before they got to him. The key should help you to track down this Warbringer Razuun you observed at Legion Hold. After you've hunted down and dealt with Warbringer Razuun , report directly to Blood Guard Gulmok . We must not keep him waiting.",starts={{npcID=21475,x=0.386,y=0.382,zoneID=3520}},ends={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},coords={x=0.386,y=0.382,source="quest_giver",zoneID=3520},questType="standard"},
[10604] = {id=10604,name="Gaining Access",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's located in the mountains behind our village! The only way to reach it is by using a teleporter at Legion Hold. Certain Legion minions carry a device allowing them to use the teleporter. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed. Do not delay; the enemy is perilously close.",starts={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},ends={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},coords={x=0.304,y=0.324,source="quest_giver",zoneID=3520},questType="standard"},
[10606] = {id=10606,name="The Art of Fel Reaver Maintenance",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below. There are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Gutrick keeps locked in a chest at the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest!",starts={{npcID=21790,x=0.408,y=0.222,zoneID=3520}},ends={{npcID=21790,x=0.408,y=0.222,zoneID=3520}},coords={x=0.408,y=0.222,source="quest_giver",zoneID=3520},questType="standard"},
[10607] = {id=10607,name="Whispers of the Raven God",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="At Grishnath, totems left by the Oracles of the Raven enable the arakkoa to hear the Word of the Raven. Unfortunately, the language of the arakkoa is indecipherable to us. Using the Harbinger's pendant, we can understand it. You will be able to take the souls of the arakkoa to understand their language. While you are suffused with the arakkoa's spirit, you can visit the totems and understand their message. Discover this for us, .",starts={{npcID=21782,x=0.622,y=0.39,zoneID=3522}},ends={{npcID=21782,x=0.622,y=0.39,zoneID=3522}},coords={x=0.622,y=0.39,source="quest_giver",zoneID=3522},questType="standard"},
[10608] = {id=10608,name="Crystal Clear",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="The damned rock flayers are keeping me from my research down in the Singing Ridge! By digging at the crystals there, with every scratch they are ruining my chances of studying the harmonics of the singing crystals. You look like someone who can help me deal with this problem. Head south and clear those crystal flayers out.",starts={{npcID=21755,x=0.602,y=0.69,zoneID=3522}},ends={{npcID=21755,x=0.602,y=0.69,zoneID=3522}},coords={x=0.602,y=0.69,source="quest_giver",zoneID=3522},questType="standard"},
[10609] = {id=10609,name="What Came First, the Drake or the Egg?",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I'm researching the applications of drake essences to my work as a physician. I think they could be a panacea for a host of maladies! I need someone to go south to the Singing Ridge and get me some. Willing to take my temporal phase modulator and use it on the nether whelps that hatch from the nether drake eggs? Retrieve the essences from whatever they turn into. Which, I might add, I'm not certain of what that will be as we're using some pretty dicey, time and space modifying tech here.",starts={{npcID=21110,x=0.608,y=0.682,zoneID=3522}},ends={{npcID=21110,x=0.608,y=0.682,zoneID=3522}},coords={x=0.608,y=0.682,source="quest_giver",zoneID=3522},questType="standard"},
[10611] = {id=10611,name="The Art of Fel Reaver Maintenance",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below. There are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Maleficus keeps locked in a chest near the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest.",starts={{npcID=21789,x=0.274,y=0.212,zoneID=3520}},ends={{npcID=21789,x=0.274,y=0.212,zoneID=3520}},coords={x=0.274,y=0.212,source="quest_giver",zoneID=3520},questType="standard"},
[10612] = {id=10612,name="The Fel and the Furious",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Plexi leafs through the manual.> Well, this has everything we need, but there's just one problem. Fel Reavers aren't really built to respond to remote control. We can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion's lackeys, either. Keep an eye out, and whatever you do, don't forget to destroy as much as you can!",starts={{npcID=21790,x=0.408,y=0.222,zoneID=3520}},ends={{npcID=21790,x=0.408,y=0.222,zoneID=3520}},coords={x=0.408,y=0.222,source="quest_giver",zoneID=3520},questType="standard"},
[10613] = {id=10613,name="The Fel and the Furious",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Nakansi leafs through the manual.> All the information is here, but be warned. These things weren't built to be controlled remotely. We can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion scum, either. Try to keep yourself safe, but remember, the mission and the safety of Shadowmoon Village come first!",starts={{npcID=21789,x=0.274,y=0.212,zoneID=3520}},ends={{npcID=21789,x=0.274,y=0.212,zoneID=3520}},coords={x=0.274,y=0.212,source="quest_giver",zoneID=3520},questType="standard"},
[10614] = {id=10614,name="Whispers on the Wind",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="I have chased rumors of the Mok'Nathal across Outland with nothing to show for it. Finally, we may have found their home. But now that the moment is here, I am filled with unease. Unease that has kept me awake deep into the nights during my search. Will they accept me? I... know their leader's name: Leoroxx . Seek him out. You must be my eyes in this.",starts={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10615] = {id=10615,name="Ruuan Weald",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The information you have helped me reveal about the nature of the arakkoa here will be of great interest to another. We were visited by members of the Cenarion Expedition, who have also become concerned with the arakkoa's intentions here in the Blade's Edge Mountains . You should seek him out. His name is Timeon , and you will find him at Evergrove in Ruuan Weald. Follow the road west from here, then north when it forks in Razor Ridge. Finally, follow the road west when it splits in the Bladed Gulch.",starts={{npcID=21496,x=0.752,y=0.62,zoneID=3522}},ends={{npcID=21782,x=0.622,y=0.39,zoneID=3522}},coords={x=0.752,y=0.62,source="quest_giver",zoneID=3522},questType="standard"},
[10617] = {id=10617,name="Silkwing Cocoons",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The silk from the cocoons of the silkwings are used for all manner of things in the village. We can never get enough, and we never have enough. It is difficult to harvest the cocoons from the larva once they begin the process of metamorphosis. Our warriors are occupied with the assault on our village. If you could gather these for us, that would be helpful.",starts={{npcID=21895,x=0.758,y=0.614,zoneID=3522}},ends={{npcID=21895,x=0.758,y=0.614,zoneID=3522}},coords={x=0.758,y=0.614,source="quest_giver",zoneID=3522},questType="standard"},
[10618] = {id=10618,name="The Softest Wings",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Hunting silkwing larva is a difficult challenge for our young warriors, but luckily, even if they fail to harvest the cocoon from the larva, we can still use the wings of hatched silkwings. In fact, we use the wings for much more than the cocoons, and we can never have too many. If you'll be out there, it would be a great help if you could bring me some.",starts={{npcID=21896,x=0.758,y=0.614,zoneID=3522}},ends={{npcID=21896,x=0.758,y=0.614,zoneID=3522}},coords={x=0.758,y=0.614,source="quest_giver",zoneID=3522},questType="standard"},
[10619] = {id=10619,name="The Ashtongue Tribe",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The Ashtongue tribe is feared among all Broken. It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself. They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, southwest of here. Go there and put a dent in their numbers before they get a chance to mount an attack on us.",starts={{npcID=21822,x=0.612,y=0.292,zoneID=3520}},ends={{npcID=21822,x=0.612,y=0.292,zoneID=3520}},coords={x=0.612,y=0.292,source="quest_giver",zoneID=3520},questType="standard"},
[10620] = {id=10620,name="Ridgespine Menace",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="We hired on to help Toshley when he decided to move to Outland, and we've been on the move ever since. Now it looks like we've finally put down some roots. All of the crazy scientists have their projects going, and us Roughriders are here to protect them. What we need right now is for you to go north into Razor Ridge, or east to the Scalewing Shelf, and keep them clear by killing the stalkers. They're stealthy spiders that live amongst the rock outcroppings, and jump unsuspecting passersby.",starts={{npcID=21824,x=0.604,y=0.688,zoneID=3522}},ends={{npcID=21824,x=0.604,y=0.688,zoneID=3522}},coords={x=0.604,y=0.688,source="quest_giver",zoneID=3522},questType="standard"},
[10621] = {id=10621,name="Illidari-Bane Shard",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light. The weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Wildhammer Stronghold might be able to tell you more about it.",ends={{npcID=19370,x=0.368,y=0.548,zoneID=3520}},questType="standard"},
[10622] = {id=10622,name="Proof of Allegiance",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Akama has been tracking your progress quite closely, . The Ashtongue you've slain at the Ruins of Baa'ri are amongst the most evil Broken known among us... carefully hand-picked by Akama himself to maintain the facade we need to present to Illidan. The Deathsworn, however, know of Akama's true intentions. First things first. We need to know that you are not with Illidan. A Satyr known as Zandras watches over us from above the prison walls on his behalf. Slay him as proof of your allegiance.",starts={{npcID=21826,x=0.572,y=0.496,zoneID=3520}},ends={{npcID=21826,x=0.572,y=0.496,zoneID=3520}},coords={x=0.572,y=0.496,source="quest_giver",zoneID=3520},questType="standard"},
[10623] = {id=10623,name="Illidari-Bane Shard",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light. The weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Shadowmoon Village might be able to tell you more about it.",ends={{npcID=19333,x=0.298,y=0.312,zoneID=3520}},questType="standard"},
[10624] = {id=10624,name="A Haunted History",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Have you felt the cold chill? Perhaps what you thought was a hand on your shoulder? That was not your mind playing tricks on you, . The land is haunted. Ghosts litter the landscape, stuck here for all eternity. Would you like to see them? Are you sure about that? These types of things tend to change a person - and not for the better. Very well, I will need you to collect for me the ever-burning ash that is found near any of the fel lava pools of western Shadowmoon. Anywhere near green lava...",starts={{npcID=21772,x=0.298,y=0.276,zoneID=3520}},ends={{npcID=21772,x=0.298,y=0.276,zoneID=3520}},coords={x=0.298,y=0.276,source="quest_giver",zoneID=3520},questType="standard"},
[10625] = {id=10625,name="Spectrecles",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="I call them \" Spectrecles .\" Clever, no? When you equip these goggles, you will be able to see the spirits of Shadowmoon Valley . Before I let you have them, though, you must promise me that you will help us clear out the ghosts at the village. Take the goggles and destroy any and all spirits that you see wandering about Shadowmoon Village. Hopefully, destroying these spirits will force any that remain to move elsewhere.",starts={{npcID=21772,x=0.298,y=0.276,zoneID=3520}},ends={{npcID=21772,x=0.298,y=0.276,zoneID=3520}},coords={x=0.298,y=0.276,source="quest_giver",zoneID=3520},questType="standard"},
[10626] = {id=10626,name="Capture the Weapons",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="With a larger supply of this material, we might be able to forge a weapon for you to use. The two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. We have no way of knowing how many more the Legion intends to produce, but if we can capture these prototypes, there should be enough for our project. There's a certain amount of satisfaction in using the Legion's own 'secret weapons' against them, don't you think?",starts={{npcID=19370,x=0.368,y=0.548,zoneID=3520}},ends={{npcID=19370,x=0.368,y=0.548,zoneID=3520}},coords={x=0.368,y=0.548,source="quest_giver",zoneID=3520},questType="group"},
[10627] = {id=10627,name="Capture the Weapons",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="With a larger supply of this material, I can forge a weapon suitable for you. The two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. Capturing those two weapons should provide us with enough material to make your weapon, and then some. I can't wait to bring the battle to the enemy using these weapons. That'll teach the Legion to trifle with anti-demon magics.",starts={{npcID=19333,x=0.298,y=0.312,zoneID=3520}},ends={{npcID=19333,x=0.298,y=0.312,zoneID=3520}},coords={x=0.298,y=0.312,source="quest_giver",zoneID=3520},questType="group"},
[10628] = {id=10628,name="Akama",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="You've proven what side you're on. I will reveal to you our leader's hideout. Follow the halls beyond; there will be an underground passage hidden by stagnant water on your right. I must warn you, . You are not to speak to anyone of what you see there.",starts={{npcID=21826,x=0.572,y=0.496,zoneID=3520}},ends={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},coords={x=0.572,y=0.496,source="quest_giver",zoneID=3520},questType="standard"},
[10629] = {id=10629,name="Shizz Work",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="I finally got my shredder working but I seem to have lost the keys. I keep a pack of felhounds to protect my camp. They don't do a very good job and they like to bite me a lot. They also like shiny things. I think this one felhound I have may have eaten my shredder keys . I'll pay you if you'll take my felhound on a walk. Kill some helboars and let him eat. He'll do his business. When he's done, see if you can't find the keys in his \"leavings.\"",starts={{npcID=16915,x=0.512,y=0.306,zoneID=3483}},ends={{npcID=16915,x=0.512,y=0.306,zoneID=3483}},coords={x=0.512,y=0.306,source="quest_giver",zoneID=3483},questType="standard"},
[10630] = {id=10630,name="Beneath Thrallmar",level=10,requiredLevel=10,faction="both",expansion=1,zoneID=3483,description="I'm almost back in business. Problem is all these gan'arg are in my mine. I can't send my peons in and even once I fix this shredder I wouldn't want to risk it in combat. Deep down in the mine the gan'arg have a leader. If you kill him maybe the gan'arg will leave. Then I could make some money and buy my way out of here.",starts={{npcID=16915,x=0.512,y=0.306,zoneID=3483}},ends={{npcID=16915,x=0.512,y=0.306,zoneID=3483}},coords={x=0.512,y=0.306,source="quest_giver",zoneID=3483},questType="standard"},
[10632] = {id=10632,name="Cutting Your Teeth",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="It's nice that you've been helping out Toshley and his scientists. I, however, do not have the luxury of indulging in my 'personal' interests. If you want to make a difference around here, you'll do what I ask of you, and right now, I need weapons. Our guns are effective at range, but when the bugs get in close, we need to have powerful melee weapons as a backup. The teeth of the daggermaw lashtails in the northern part of the Razor Ridge make for great vibro-weapon blades. Scare me up some.",starts={{npcID=21118,x=0.604,y=0.692,zoneID=3522}},ends={{npcID=21118,x=0.604,y=0.692,zoneID=3522}},coords={x=0.604,y=0.692,source="quest_giver",zoneID=3522},questType="standard"},
[10633] = {id=10633,name="Teron Gorefiend - Lore and Legend",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor. The only thing we are certain of is that he has already died once. I have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the southeast, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.",starts={{npcID=21772,x=0.298,y=0.276,zoneID=3520}},ends={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},coords={x=0.298,y=0.276,source="quest_giver",zoneID=3520},questType="standard"},
[10634] = {id=10634,name="Divination: Gorefiend's Armor",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="In life, Gorefiend was a monster, but in death, Gorefiend was an unmitigated terror. To the southeast you will find Netherwing Ledge. What was once part of the mainland of Shadowmoon is now a floating island in the sky. Vhel'kur, spawn of Deathwing, once called it his home, but now knows it as his grave. He flies an endless circle above the island, seething at his defeat to Gorefiend. If you are to recover the Gorefiend's armor , it is Vhel'kur that you must defeat.",starts={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},ends={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},coords={x=0.582,y=0.708,source="quest_giver",zoneID=3520},questType="group"},
[10635] = {id=10635,name="Divination: Gorefiend's Cloak",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Many a cruel act he committed but none so cold as the slaughter of the clerics of Karabor. After Gul'dan's Horde defeated the draenei of Karabor, the surviving clerics of Karabor were marched out, told that they were to be taken to Hellfire Citadel as prisoners of war. Gorefiend, not yet a death knight, murdered each and every last one of them in cold blood. They now roam in front of the Black Temple with vengeance in their hearts. It is the clerics of Karabor that hold the cloak of Gorefiend.",starts={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},ends={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},coords={x=0.582,y=0.708,source="quest_giver",zoneID=3520},questType="standard"},
[10636] = {id=10636,name="Divination: Gorefiend's Truncheon",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="One by one they knelt before him, offering their lives as a show of allegiance. Gorefiend hoisted his sickle and cut clean their heads. Shortly after this slaughter, Gorefiend took his own life. But this was no act of contrition! No, Gorefiend sought immortality! From the corpses of the fallen death knights rose the Ghostriders of Karabor. They now ride the roads encircling the Hand of Guldan, awaiting the day that their master returns. It is they who hold the truncheon of Gorefiend. Retrieve it...",starts={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},ends={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},coords={x=0.582,y=0.708,source="quest_giver",zoneID=3520},questType="group"},
[10637] = {id=10637,name="A Necessary Distraction",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The weapons are authentic, as we feared. Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it. Do not be fooled by their name, , their power will be used against us as often as against any demon. Their warlocks summon and subdue demons to be used as part of the initiates' training. A pit lord named Azaloth has proven too strong to be used in training and is kept banished. Find a way to let him loose on his captors. That should buy us the time we need.",starts={{npcID=21860,x=0.612,y=0.292,zoneID=3520}},ends={{npcID=21860,x=0.612,y=0.292,zoneID=3520}},coords={x=0.612,y=0.292,source="quest_giver",zoneID=3520},questType="standard"},
[10639] = {id=10639,name="Teron Gorefiend, I am...",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="With Gorefiend's items restored, there is but one last piece to this puzzle: A host. ancient shadowmoon spirit 's lips curl up to form a wicked grin.> Surely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever. Teron Gorefiend will be free!",starts={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},ends={{npcID=21772,x=0.298,y=0.276,zoneID=3520}},coords={x=0.582,y=0.708,source="quest_giver",zoneID=3520},questType="standard"},
[10640] = {id=10640,name="Altruis",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3518,description="It is rare in this day and age to hear of those who follow the path of the demon hunter. It is rarer still to find someone who does and has no allegiance to Illidan. There are rumors of one such individual here in Outland. One name is said to be feared in the Legion fields of Nagrand more than any army of Aldor vindicators. That name is Altruis. Go to western Nagrand and find him. He might be willing to shed some light on these new demon hunter training grounds.",starts={{npcID=21860,x=0.612,y=0.292,zoneID=3520}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.612,y=0.292,source="quest_giver",zoneID=3520},questType="standard"},
[10641] = {id=10641,name="Against the Legion",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3522,description="The Burning Legion has proven its capacity to corrupt mortal souls time and again. If I'm to entrust you with the knowledge you seek, I must have proof of your allegiance. A demoness known as Sathal has eluded me for a long time as she's gifted with an incorporeal form. She watches over the wrath priestesses as they do her bidding at Forge Base: Gehenna. Slay one of her minions and spill her blood on the ground. This affront should cause Sathal to materialize temporarily. Slay her while you can.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[10642] = {id=10642,name="A Ghost in the Machine",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="I fear that these dwarves do not understand what they have built upon. This area was once the ancestral grounds for the Shadowmoon orcs. I speak of spirits, . For nearly twenty years they have laid dormant beneath the Wildhammer Stronghold, but recently, something has riled them up. Venture beyond the gates of Wildhammer and seek out the pools and rivers of fel lava found across this land. Near the lava will be ever-burning ash . Bring me this ash so that I may craft something that will help us.",starts={{npcID=21774,x=0.366,y=0.554,zoneID=3520}},ends={{npcID=21774,x=0.366,y=0.554,zoneID=3520}},coords={x=0.366,y=0.554,source="quest_giver",zoneID=3520},questType="standard"},
[10643] = {id=10643,name="Harbingers of Shadowmoon",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Let it be known that Zorus does have a sense of humor. Enough small talk. Don the Spectrecles so that you are able to see the Shadowmoon orc spirits that wander this stronghold. Do not be frightened as we are truly the invaders here. Alas, they must be destroyed, for their time has long since passed. Destroy the Shadowmoon harbingers infesting Wildhammer Stronghold and return to me.",starts={{npcID=21774,x=0.366,y=0.554,zoneID=3520}},ends={{npcID=21774,x=0.366,y=0.554,zoneID=3520}},coords={x=0.366,y=0.554,source="quest_giver",zoneID=3520},questType="standard"},
[10644] = {id=10644,name="Teron Gorefiend - Lore and Legend",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor. The only thing we are certain of is that he has already died once. I have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the east, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.",starts={{npcID=21774,x=0.366,y=0.554,zoneID=3520}},ends={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},coords={x=0.366,y=0.554,source="quest_giver",zoneID=3520},questType="standard"},
[10645] = {id=10645,name="Teron Gorefiend, I am...",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="With Gorefiend's items restored, there is but one last piece to this puzzle: A host. ancient shadowmoon spirit 's lips curl up to form a wicked grin.> Surely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever. Teron Gorefiend will be free!",starts={{npcID=21797,x=0.582,y=0.708,zoneID=3520}},ends={{npcID=21774,x=0.366,y=0.554,zoneID=3520}},coords={x=0.582,y=0.708,source="quest_giver",zoneID=3520},questType="standard"},
[10646] = {id=10646,name="Illidan's Pupil",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3518,description="You've proven your allegiance, . You must forgive my caution, but in this world things are not what they appear. I will tell you about Varedis when you're ready.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[10647] = {id=10647,name="WANTED: Uvuros, Scourge of Shadowmoon",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Wanted - DEAD: Uvuros, scourge of Shadowmoon Valley . By order of Overlord Or'barokh, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Sardon Truslice should you succeed. Uvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - east of Shadowmoon Village.",starts={{npcID=184945,x=0.305,y=0.308,zoneID=3520}},ends={{npcID=21771,x=0.304,y=0.308,zoneID=3520}},coords={x=0.305,y=0.308,source="quest_giver",zoneID=3520},questType="group"},
[10648] = {id=10648,name="WANTED: Uvuros, Scourge of Shadowmoon",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Wanted - DEAD: Uvuros, scourge of Shadowmoon Valley . By order of Thane Yoregar, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Beersnout should you succeed. Uvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - northeast of Wildhammer Stronghold.",starts={{npcID=184946,x=0.383,y=0.54,zoneID=3520}},ends={{npcID=21775,x=0.382,y=0.54,zoneID=3520}},coords={x=0.383,y=0.54,source="quest_giver",zoneID=3520},questType="group"},
[10649] = {id=10649,name="The Book of Fel Names",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3789,description="I sympathize with your intentions of stopping Varedis and his followers, but you won't stand a chance against him. That is, unless you find the artifact that gave him his power. The Book of Fel Names is rumored to be in the possession of Blackheart the Inciter inside the Shadow Labyrinth in Auchindoun. Obtaining it will be your only hope against Varedis.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="dungeon"},
[10650] = {id=10650,name="Return to the Aldor",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="This book... I could use it to increase my power tenfold... No! It would end up corrupting my very soul, this I am sure of. Return to those who sent you here, . You now have the means to stop Varedis. Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence. That will be the only way you can deprive him of his power.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=21860,x=0.612,y=0.292,zoneID=3520}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[10651] = {id=10651,name="Varedis Must Be Stopped",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="We must dispose of this foul artifact, but not before we use it to dispose of Varedis 's powers. We need to permanently shut down the Ruins of Karabor training grounds, which will mean killing not only Varedis but also the three night elf masters that assist him: Alandien , Theras and Netharel . Gather a suitable force and return to the Ruins of Karabor. Follow Altruis's instructions for defeating Varedis . For all of our sakes, I hope they work.",starts={{npcID=21860,x=0.612,y=0.292,zoneID=3520}},ends={{npcID=21860,x=0.612,y=0.292,zoneID=3520}},coords={x=0.612,y=0.292,source="quest_giver",zoneID=3520},questType="group"},
[10652] = {id=10652,name="Behind Enemy Lines",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="All arrangements have been made to take you to where our spies are hiding. Just come see me when you're ready and we'll get you on your way.",starts={{npcID=20162,x=0.338,y=0.642,zoneID=3523}},ends={{npcID=19840,x=0.482,y=0.866,zoneID=3523}},coords={x=0.338,y=0.642,source="quest_giver",zoneID=3523},questType="standard"},
[10653] = {id=10653,name="Marks of Sargeras",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="By now it should be clear to you why we oppose the Burning Legion and those who serve them. If you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers. The highest-ranking Legion can be found in Netherstorm and Shadowmoon Valley.",starts={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},ends={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},coords={x=0.306,y=0.174,source="quest_giver",zoneID=3523},questType="standard"},
[10654] = {id=10654,name="More Marks of Sargeras",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},ends={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},coords={x=0.306,y=0.174,source="quest_giver",zoneID=3523},questType="standard"},
[10655] = {id=10655,name="Single Mark of Sargeras",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},ends={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},coords={x=0.306,y=0.174,source="quest_giver",zoneID=3523},questType="standard"},
[10656] = {id=10656,name="Sunfury Signets",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="As you might know, the Scryers and the armies of Kael'thas are at war. Kael sees us as a threat to his influence over other blood elves and has tried to crush us time and again. If you wish to aid us in our battle against Kael'thas, there are plenty of targets for you to go after. Kael's highest ranking soldiers wear Sunfury signets to mark their ranks. You will find them all over Netherstorm and Shadowmoon Valley.",starts={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},ends={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},coords={x=0.454,y=0.814,source="quest_giver",zoneID=3703},questType="standard"},
[10657] = {id=10657,name="Ride the Lightning",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="We haven't kept the use of the Zephyrium Capacitorium under budget. But, it occurs to me that the serpents of the Scalewing Shelf to the east have a lightning breath and glands that we can make use of. I've repolarized the magneto collector to absorb lightning strikes and I want you to head up there, activate it on yourself, and get us some cheap fuel from those serpents.",starts={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},ends={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},coords={x=0.604,y=0.69,source="quest_giver",zoneID=3522},questType="standard"},
[10658] = {id=10658,name="More Sunfury Signets",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},ends={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},coords={x=0.454,y=0.814,source="quest_giver",zoneID=3703},questType="standard"},
[10659] = {id=10659,name="Single Sunfury Signet",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},ends={{npcID=18531,x=0.454,y=0.814,zoneID=3703}},coords={x=0.454,y=0.814,source="quest_giver",zoneID=3703},questType="standard"},
[10660] = {id=10660,name="What Strange Creatures...",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="I am interested in learning more about the strange reptiles that mill about the lava flows of Shadowmoon Valley . Never have I seen beasts able to withstand the searing heat of molten lava! Outside of Shadowmoon Village, where the ground has ruptured and lava flows through the cracks, you will find felfire diemetradons. Slay them and bring me their spleens. From their spleens I will be able to begin preliminary analysis of their resistance to heat. Begin your search to the southeast.",starts={{npcID=21770,x=0.3,y=0.282,zoneID=3520}},ends={{npcID=21770,x=0.3,y=0.282,zoneID=3520}},coords={x=0.3,y=0.282,source="quest_giver",zoneID=3520},questType="standard"},
[10661] = {id=10661,name="Spleendid!",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Have you ever heard of food that cooks itself and stays hot forever? Dare to dream, I say! But maybe it's not a dream at all! Outside the fortress, near the lava pools and streams, you can find beasts that thrive in the sizzling heat. They're called felfire diemetradons. The dwarves around here tell me that those diemetradons have the tastiest spleens ever and that the spleens practically come pre-cooked! Bring me those spleens and I'll give you some coin. Start your search directly east of here.",starts={{npcID=21777,x=0.366,y=0.552,zoneID=3520}},ends={{npcID=21777,x=0.366,y=0.552,zoneID=3520}},coords={x=0.366,y=0.552,source="quest_giver",zoneID=3520},questType="standard"},
[10662] = {id=10662,name="The Hermit Smith",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3519,description="This is beyond my ability, but that's not to say the weapon can't be recreated for your use. There was a talented smith who accompanied the Sons of Lothar to Draenor, David Wayne . He was a remarkable blacksmith, but chose to leave the expedition. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you with the weapon.",starts={{npcID=19370,x=0.368,y=0.548,zoneID=3520}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.368,y=0.548,source="quest_giver",zoneID=3520},questType="standard"},
[10663] = {id=10663,name="The Hermit Smith",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3519,description="This is beyond my ability, but that's not to say the weapon can't be recreated. It pains me to suggest this, but your only hope may be a human smith by the name of David Wayne . It's true he was once a member of the Alliance's expedition, but that was a long time ago and he has since left the Sons of Lothar. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you.",starts={{npcID=19333,x=0.298,y=0.312,zoneID=3520}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.298,y=0.312,source="quest_giver",zoneID=3520},questType="standard"},
[10664] = {id=10664,name="Additional Materials",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3519,description="The ingots that you brought contain most of the metal I'll need to forge the sword's blade, but I'll need a variety of things to create other parts of the weapon. Let's see, among the things I don't have here are an adamantite frame , some heavy knothide leather , and a demon warding totem . Skilled crafters should be able to produce the first two, but the third is only sold by the reagent vendor in Shattrath's Lower City, Fantei. You'll find him with the other tradesmen.",starts={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.774,y=0.386,source="quest_giver",zoneID=3519},questType="standard"},
[10665] = {id=10665,name="Fresh from the Mechanar",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3519,description="Working with the ingots you brought is going to require a lot of heat -- rather more than a conventional forge can supply. I'm going to need a supplemental heat source for the forge and there are very few things in Outland that can supply that kind of power. The Mechanar area of Tempest Keep turns out manacells containing an incredible amount of power. Find one of the overcharged manacells from the stacks around Mechano-Lord Capacitus and bring it back here.",starts={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.774,y=0.386,source="quest_giver",zoneID=3519},questType="dungeon"},
[10666] = {id=10666,name="The Lexicon Demonica",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3789,description="Recreating the enchantments on the blade requires several spells to be spoken in demonic. It's not something I was taught during my training as an apprentice, but there's no way around it. There's a book, called the Lexicon Demonica , that will provide most of the words I need, but it's in the hands of a powerful Shadow Council warlock. Deep in the halls of Auchindoun's Shadow Labyrinth, it is held by Grandmaster Vorpil. Do whatever you must to secure the book and bring it to me.",starts={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.774,y=0.386,source="quest_giver",zoneID=3519},questType="dungeon"},
[10667] = {id=10667,name="Underworld Loam",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3715,description="The frame that you brought me earlier will not be sufficient to hold molten metal without reinforcement. A rare kind of earth can be used to cool and imbue the frame, giving the adamantite an unnatural strength. Underworld loam, as the earth is known, is accorded great value among the naga. Few enough of them possess it, and in Outland, I know of only one naga who uses it -- Hydromancer Thespia, who resides in the Steamvault of Coilfang Reservoir.",starts={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.774,y=0.386,source="quest_giver",zoneID=3519},questType="dungeon"},
[10668] = {id=10668,name="Against the Illidari",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I still have respect for Illidan. Without him I would not have found my path. He is not who he once was, however. His soul has been corrupted by power, his mind has been twisted by defeat. He has become what I am sworn to destroy and his pet servants, the Illidari, are as much of an abomination as any demon of the Burning Legion. His grasp on Outland is slipping yet his reach is still vast. Prove you're not with him by slaying his lieutenant Lothros at Illidari Point in Shadowmoon Valley.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[10669] = {id=10669,name="Against All Odds",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3521,description="Some demons pledge allegiance to no one but themselves. A true enemy of demons finds and destroys his prey regardless of affiliation, however. The demon Xeleth - a Legion defector - was once worshipped as a god by primitive swamp creatures in Zangarmarsh. When Draenor was nearly destroyed, he retreated into a slumber deep beneath Marshlight Lake. Find the portal at the lake and plant this spear into the ground. Xeleth will awake - be ready to slay him and prove you're an enemy to all demons.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[10670] = {id=10670,name="Tear of the Earthmother",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3714,description="The sword's enchantments must be contained within a powerful focus, such as a gem. I know of a gem that we can use for this purpose, for there are few that can play host to such powerful magics without shattering. The gem we need is called the tear of the earthmother . It's a powerful artifact in the hands of the ogres who created it, and Warbringer O'mrogg, who currently holds the gem, has many powerful allies in Hellfire Citadel's Shattered Halls. Take care in retrieving the tear, .",starts={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.774,y=0.386,source="quest_giver",zoneID=3519},questType="dungeon"},
[10671] = {id=10671,name="More than a Pound of Flesh",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description=", I've got something else for you to do. One of the eggheads wants to study the fiendling flesh beasts that can be found at Razaan's Landing, north of the Razor Ridge. More to the point, they want to study the flesh of the flesh beasts that are there. But, of course, they aren't willing to get their hands dirty, and they only want the ether-energized flesh , which it's not likely that all of them have. I say, beggars can't be choosers, but what can you do?",starts={{npcID=21824,x=0.604,y=0.688,zoneID=3522}},ends={{npcID=21824,x=0.604,y=0.688,zoneID=3522}},coords={x=0.604,y=0.688,source="quest_giver",zoneID=3522},questType="standard"},
[10672] = {id=10672,name="Frankly, It Makes No Sense...",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="We must study these creatures further. Far to the east - near the huge lava flow beneath the ruins of Baa'ri - you will find arcano control units. These controllers were crafted by a genius named Gnomus for the sole purpose of exploring lava via mechanical scorpion. He has long since lost his mind and is now only interested in eating the hottest food known to gnome-kind. I want you to use the control and tag the diemetradons of the lava flow for further study.",starts={{npcID=21770,x=0.3,y=0.282,zoneID=3520}},ends={{npcID=21770,x=0.3,y=0.282,zoneID=3520}},coords={x=0.3,y=0.282,source="quest_giver",zoneID=3520},questType="standard"},
[10673] = {id=10673,name="Felspine the Greater",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Gnomus knows about the massive diemetradon and plans to eat it! He must have been able to see what I could see through the eyes of his arcano-scorp. Look, there's no time to explain. He's crazy and that craziness is going to cost us the closest thing we've got to a fireproof jumpsuit. Get back to the lava flow near Baa'ri and track down Felspine the Greater. Once you find it, kill it and bring me back its hide. Don't try and reason with me, . I'm well past that point.",starts={{npcID=21770,x=0.3,y=0.282,zoneID=3520}},ends={{npcID=21770,x=0.3,y=0.282,zoneID=3520}},coords={x=0.3,y=0.282,source="quest_giver",zoneID=3520},questType="standard"},
[10674] = {id=10674,name="Trapping the Light Fantastic",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="The Razaani ethereals have been playing with some interesting technology at Razaan's Landing to the north. I'm sure they won't mind if you use this trap to take a few samples of their little pink floating light orbs? They're probably only for decoration anyway. The trap has a special property to it that when opened should attract one of the floating balls towards it. Of course, it'll probably also alert the Razaani to your presence.",starts={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},ends={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},coords={x=0.604,y=0.69,source="quest_giver",zoneID=3522},questType="standard"},
[10675] = {id=10675,name="Show Them Gnome Mercy!",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Toshley 's face.> These orbs are made up of both nether energy and souls, some of them gnome souls! How dare they! Were they the ones killing our people that traveled north?! , you must put a stop to this, and the only way to do that is to finish off their leader, Nexus-Prince Razaan. You'll have to coax him out of hiding though. I'm guessing that you can do that by killing a lot of his Razaani ethereal. Bring me the collection of souls that he no doubt has.",starts={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},ends={{npcID=21691,x=0.604,y=0.69,zoneID=3522}},coords={x=0.604,y=0.69,source="quest_giver",zoneID=3522},questType="standard"},
[10676] = {id=10676,name="Bane of the Illidari",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3519,description="You've done well in getting everything we'll need to reforge the anti-demon blade. Your hard work and dedication is about to be repaid. The time has come to forge the sword.",starts={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.774,y=0.386,source="quest_giver",zoneID=3519},questType="standard"},
[10677] = {id=10677,name="The Second Course...",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="I remember seeing larger diemetradons east of the Hand of Gul'dan, near the lava flows around the Ruins of Baa'ri. What I want you to get for me now is one overdeveloped felfire gizzard from the beasts around that area. You might have to kill several to find a gizzard like the one I described. Keep at it! One of them is bound to have my next meal.",starts={{npcID=21777,x=0.366,y=0.552,zoneID=3520}},ends={{npcID=21777,x=0.366,y=0.552,zoneID=3520}},coords={x=0.366,y=0.552,source="quest_giver",zoneID=3520},questType="standard"},
[10678] = {id=10678,name="The Main Course!",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Long story short, I used to work with a blood elf named Tiorus. My partnership with Tiorus dissolved once I got into gourmet living. He decided to take it upon himself to continue our research using MY inventions. Anyhow, he had some of his Horde goons using my arcano-scorp probes at the Ruins of Baa'ri lava flow and discovered the mother of all diemetradons! I need you to get there before he does and kill the diemetradon, Felspine, and bring his hide back to me. Hurry up!",starts={{npcID=21777,x=0.366,y=0.552,zoneID=3520}},ends={{npcID=21777,x=0.366,y=0.552,zoneID=3520}},coords={x=0.366,y=0.552,source="quest_giver",zoneID=3520},questType="standard"},
[10679] = {id=10679,name="Quenching the Blade",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3519,description="The blade is nearly finished! You can almost feel the magic beginning to coalesce inside the steel, but one thing remains to be done. You must take the forged blade to the Scalding Pools near the top of the Hand of Gul'dan in Shadowmoon Valley and plunge it into the lava pools to quench the sword. When you have quenched the sword, return.",starts={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},ends={{npcID=21465,x=0.774,y=0.386,zoneID=3519}},coords={x=0.774,y=0.386,source="quest_giver",zoneID=3519},questType="standard"},
[10680] = {id=10680,name="The Hand of Gul'dan",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="The elements need your help, ! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring. Help this world heal, friend. Directly northeast of Wildhammer Stronghold you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok .",starts={{npcID=21937,x=0.364,y=0.568,zoneID=3520}},ends={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},coords={x=0.364,y=0.568,source="quest_giver",zoneID=3520},questType="standard"},
[10681] = {id=10681,name="The Hand of Gul'dan",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The elements need your help, ! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring. Help this world heal, friend. Southeast of Shadowmoon Village - in the heart of Shadowmoon Valley - you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok .",starts={{npcID=21938,x=0.284,y=0.264,zoneID=3520}},ends={{npcID=21024,x=0.422,y=0.45,zoneID=3520}},coords={x=0.284,y=0.264,source="quest_giver",zoneID=3520},questType="standard"},
[10682] = {id=10682,name="A Time for Negotiation...",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="When we arrived in the Ruuan Weald, the wyrm cultists were keeping themselves to Blackwing Coven, through the tunnel to the west. But now, they are encroaching upon us here. I need you to find the wyrmcultists' overseer. He's known to make a regular patrol between their various camps in the Ruuan Weald. Negotiate with him. Let him know that there's room for compromise, but that we will not condone or allow the wholesale slaughter of the wildlife, nor the felling of all of the trees.",starts={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},ends={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},coords={x=0.62,y=0.394,source="quest_giver",zoneID=3522},questType="standard"},
[10683] = {id=10683,name="Tablets of Baa'ri",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The Ashtongue Broken have been ordered by Illidan to excavate the Ruins of Baa'ri, to the far north. They're in search of draenei artifacts, no doubt - Baa'ri was home to many Baa'ri relics before Gul'dan buried the town under a volcanic explosion. We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor... a place you might know as the Black Temple.",starts={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},ends={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},coords={x=0.562,y=0.594,source="quest_giver",zoneID=3520},questType="standard"},
[10684] = {id=10684,name="Oronu the Elder",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri. Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor. We must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet. Its power would provide great aid in our fight against Illidan. Akama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily. Obtain them and bring them to me.",starts={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},ends={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},coords={x=0.562,y=0.594,source="quest_giver",zoneID=3520},questType="standard"},
[10685] = {id=10685,name="The Ashtongue Corruptors",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors. These dreaded Broken were once powerful shaman who now defile the very elements they revered. Haalum, Corruptor of Air, can be found at Netherwing Pass. Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan. Lakaan, Corruptor of Water, is rumored to be near Coilskar Point. Find them and obtain the medallion fragments.",starts={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},ends={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},coords={x=0.562,y=0.594,source="quest_giver",zoneID=3520},questType="standard"},
[10686] = {id=10686,name="The Warden's Cage",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The fragments you obtained are only half of the medallion. The Ashtongue leader, Akama, must have kept the other half. I dread to ask this of you, as Akama is both evil and cunning. He and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage. I want you to find that dreaded prison, and find the whereabouts of Akama. His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.",starts={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},ends={{npcID=21826,x=0.572,y=0.496,zoneID=3520}},coords={x=0.562,y=0.594,source="quest_giver",zoneID=3520},questType="standard"},
[10687] = {id=10687,name="Karabor Training Grounds",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor. Normally this would represent a purely military threat, however we believe something else is amiss. Descriptions of their attire and fighting style are suspiciously close to that of Illidan himself. I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons. We will then determine whether my fears are unfounded or not.",starts={{npcID=21954,x=0.558,y=0.582,zoneID=3520}},ends={{npcID=21954,x=0.558,y=0.582,zoneID=3520}},coords={x=0.558,y=0.582,source="quest_giver",zoneID=3520},questType="standard"},
[10688] = {id=10688,name="A Necessary Distraction",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The weapons are authentic, as we feared. Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it. Do not be fooled by their name, , their power will be used against us as often as against any demon. Their warlocks summon and subdue demons to be used as part of the initiates' training. A pit lord named Azaloth has proven too strong to be used in training and is kept banished. Find a way to let him loose on his captors. That should buy us the time we need.",starts={{npcID=21954,x=0.558,y=0.582,zoneID=3520}},ends={{npcID=21954,x=0.558,y=0.582,zoneID=3520}},coords={x=0.558,y=0.582,source="quest_giver",zoneID=3520},questType="standard"},
[10689] = {id=10689,name="Altruis",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3518,description="You don't see many demon hunters nowadays. They're viewed with suspicion by their own people and it's very rare to find one that doesn't have some sort of allegiance to Illidan. There are rumors of one such demon hunter out in Nagrand . His name is Altruis. He hates all demons with a passion and will help us if you can convince him that you share his goals. Go to western Nagrand and find him. He might be willing to shed some light on these new demon hunter training grounds.",starts={{npcID=21954,x=0.558,y=0.582,zoneID=3520}},ends={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},coords={x=0.558,y=0.582,source="quest_giver",zoneID=3520},questType="standard"},
[10690] = {id=10690,name="The Den Mother",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="WANTED! Rema , the den mother and primary defender of the Jagged Ridge south of Thunderlord Stronghold. Find her by heading east out of town and across the bridge that traverses the Bloodmaul Ravine. She keeps herself secluded in the tunnel at the southern edge of the ridge. Return with news of her demise to Commander Skyshadow of Sylvanaar.",starts={{npcID=185035,x=0.366,y=0.673,zoneID=3522}},ends={{npcID=21158,x=0.362,y=0.662,zoneID=3522}},coords={x=0.366,y=0.673,source="quest_giver",zoneID=3522},questType="standard"},
[10691] = {id=10691,name="Return to the Scryers",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="This book... I could use it to increase my power tenfold... No! It would end up corrupting my very soul, this I am sure of. Return to those who sent you here, . You now have the means to stop Varedis. Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence. That will be the only way you can deprive him of his power.",starts={{npcID=18417,x=0.274,y=0.43,zoneID=3518}},ends={{npcID=21954,x=0.558,y=0.582,zoneID=3520}},coords={x=0.274,y=0.43,source="quest_giver",zoneID=3518},questType="standard"},
[10692] = {id=10692,name="Varedis Must Be Stopped",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Of course we must destroy this book, but not before we use it to destroy Varedis . If we're to shut down this academy of Illidan imitators, we'll have to deal not just with Varedis but also the three night elf masters that assist him: Alandien , Theras and Netharel . Gather a suitable force and return to the Ruins of Karabor. Follow Altruis's instructions for defeating Varedis . Hopefully his plan will work - otherwise... it'll have been a pleasure working with you.",starts={{npcID=21954,x=0.558,y=0.582,zoneID=3520}},ends={{npcID=21954,x=0.558,y=0.582,zoneID=3520}},coords={x=0.558,y=0.582,source="quest_giver",zoneID=3520},questType="group"},
[10701] = {id=10701,name="Breaking Down Netherock",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="To whomever cares about the timely construction of the X-52 Nether-Rocket -- The king of the local mountain giants, Netherock , has been terrorizing the Crumbling Wastes. He's been interfering with operations all along the south ledge of the island! Take your friends and deal with him! Then, return to me here in Area 52. Rocket-Chief Fuselage",starts={{npcID=183811,x=0.321,y=0.647,zoneID=3523}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.321,y=0.647,source="quest_giver",zoneID=3523},questType="group"},
[10702] = {id=10702,name="A Grunt's Work...",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="All Horde forces in this region have been dispatched to handle the attacks from the Burning Legion. This means that we are short-handed for grunt work. Our supply caravans are in constant danger from the wildlife of the region. We can't veer 15 feet off the road without running into a chimaera, felboar , or abnormally large scorpion. Get out there and clear Shadowmoon Valley of its sadistic wildlife! Just kill 'em all!",starts={{npcID=21769,x=0.284,y=0.264,zoneID=3520}},ends={{npcID=21769,x=0.284,y=0.264,zoneID=3520}},coords={x=0.284,y=0.264,source="quest_giver",zoneID=3520},questType="standard"},
[10703] = {id=10703,name="Put On Yer Kneepads...",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="It's time to get down in the muck and get dirty. What were you expectin'? You gotta learn to walk before you can crawl, right? Er, reverse that... Anyway, we got all hands on deck fer killin' the garbage being thrown at us by the Burning Legion. That leaves you with the honor of cleaning up the crazed wildlife of Shadowmoon Valley . Grab a sword, staff, whatever it is that makes you happy, and kill as much of the wildlife as you can see. That'll clear a way out for our supply caravans!",starts={{npcID=21773,x=0.362,y=0.568,zoneID=3520}},ends={{npcID=21773,x=0.362,y=0.568,zoneID=3520}},coords={x=0.362,y=0.568,source="quest_giver",zoneID=3520},questType="standard"},
[10704] = {id=10704,name="How to Break Into the Arcatraz",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3849,description="A message was embedded in the ata'mal crystal that you recovered. Nexus-Prince Haramad has given us information vital to our campaign against Tempest Keep. He tells us that there are two pieces, shards to a key, which, when combined, will unlock the keep's Arcatraz satellite. One half is possessed by an ancient in the Botanica known as Warp Splinter. The other is held by Pathaleon the Calculator inside the Mechanar. Bring both shards to me and I will combine them into the Arcatraz key.",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[10705] = {id=10705,name="Seer Udalo",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3848,description="I hope you're not shocked when I reveal to you that the pieces of the Medallion of Karabor you obtained from my minions are mere replicas. Akama shows you an identical medallion in his open palm.> My Deathsworn and I have kept the secret from Illidan for as long as possible. We are however, still missing the final piece. Udalo came to me in dreams to announce he had found it. Unfortunately he is held by Kael'thas inside the Arcatraz in Tempest Keep. Find him and see what he knows.",starts={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},coords={x=0.58,y=0.482,source="quest_giver",zoneID=3520},questType="dungeon"},
[10706] = {id=10706,name="A Mysterious Portent",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Before he died, Udalo appears to have written a single word on the floor beneath him. The writing is barely legible but you recognize the word Atam'al. Perhaps Akama will understand the meaning of his brethren's message.",ends={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},questType="standard"},
[10707] = {id=10707,name="The Ata'mal Terrace",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="It has been known to us that the fel orcs, under Illidan's command, have guarded an Ata'mal crystal known as the Heart of Fury at the Ata'mal Terrace. They cloud its presence with dark magic, to keep it from the Sha'tar. Fight your way to the Ata'mal Terrace outside the Black Temple and turn your eyes to the sky. Shadowlord Deathwail will circle the terrace, beyond your reach. You will have to slay him and his warlocks before you can obtain the crystal. It won't be easy, . I wish you luck.",starts={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},ends={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},coords={x=0.58,y=0.482,source="quest_giver",zoneID=3520},questType="group"},
[10708] = {id=10708,name="Akama's Promise",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=3520,description="I am not as strong as I once was, . Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this. Take this as my promise to you that when the time comes and you face Illidan, I will be on your side. Take it to the one being we know we can trust with its power. Take the medallion to A'dal in Shattrath City.",questType="standard"},
[10709] = {id=10709,name="Reunion",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="So you come from the world beyond the Portal? And you know of Rexxar . Oh yes, I am quite familiar with him. You see, he is my son. But he made his choice a lifetime ago. He is not one of us, and he is not welcome here. We have enough troubles with the Bloodmaul ogres. Know this: being born a half-breed does not make you Mok'Nathal.",starts={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.752,y=0.608,source="quest_giver",zoneID=3522},questType="standard"},
[10710] = {id=10710,name="Test Flight: The Singing Ridge",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I've been fiddling with the Zephyrium Capicitorium and I'm ready to perform another test! Do you want to help? This next flight should be short, but fast! Um... and although I'm sure there's no danger... I have this, uh, waiver that I'd like you to sign. It's just a formality, I assure you! Best of luck! Talk to Rally to launch yourself, and come back to me after the experiment is over!",starts={{npcID=21460,x=0.602,y=0.684,zoneID=3522}},ends={{npcID=21460,x=0.602,y=0.684,zoneID=3522}},coords={x=0.602,y=0.684,source="quest_giver",zoneID=3522},questType="standard"},
[10711] = {id=10711,name="Test Flight: Razaan's Landing",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description=", I raised the efficiency of the Zephyrium Capacitorium by 30 percent. That will launch a test subject of your weight and wind drag ratio to new heights! Want to test my theory? This experiment ought to send you near Razaan's Landing. Speak with Rally... he'll get you prepared for launch.",starts={{npcID=21460,x=0.602,y=0.684,zoneID=3522}},ends={{npcID=21460,x=0.602,y=0.684,zoneID=3522}},coords={x=0.602,y=0.684,source="quest_giver",zoneID=3522},questType="standard"},
[10712] = {id=10712,name="Test Flight: Ruuan Weald",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Hey, . I'm glad I caught you! I have a very important mission! Here is a nether-weather vane . I need you to take some in flight readings for me and deliver them to my cousin in Ruuan Weald. Speak with Rally and take a Zephyrium Capacitorium flight to Ruuan Weald. While you're flying, spin the vane! After you land, bring the spinning vane to O'Mally Zabnabber. Good luck, . And don't delay!",starts={{npcID=21460,x=0.602,y=0.684,zoneID=3522}},ends={{npcID=22020,x=0.626,y=0.402,zoneID=3522}},coords={x=0.602,y=0.684,source="quest_giver",zoneID=3522},questType="standard"},
[10713] = {id=10713,name="...and a Time for Action",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="We will not stand idly by while they decimate the Ruuan Weald around us. Our first priority must be to the trees. , I want you to go back out into the Weald and deliver a very different message for us. I want you to slay every one of their hewers that you come into contact with! If they will not listen to reason, perhaps they will listen to a more assertive method of persuasion!",starts={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},ends={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},coords={x=0.62,y=0.394,source="quest_giver",zoneID=3522},questType="standard"},
[10714] = {id=10714,name="On Spirit's Wings",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="If the Mok'Nathal are tormented by the Bloodmaul ogres, then I will stop them and their followers. Ogres are simple creatures, and there is little profit they could gain from harassing the Mok'Nathal. There must be something more to this. , take Spirit, my hawk, and spy upon the conversations of the Bloodmaul's leaders. He may go undetected where we cannot.",starts={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10715] = {id=10715,name="Into the Churning Gulch",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="So, your Rexxar would have me fashion a poison for him? I'll give him what he desires, but there will be a price. Even for friends, there must be a price. Free things destroy friendships. First, you must venture a short distance to the southwest to the Churning Gulch. Therein mill some of the most poisonous creatures in all of Outland, or anywhere. I speak of the crust bursters, and this poison will require gathering their glands for me.",starts={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.532,y=0.41,source="quest_giver",zoneID=3522},questType="standard"},
[10717] = {id=10717,name="Poaching from Poachers",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Pardon me, but I couldn't help but overhear your conversation with Chawn. I'd like to help. I'm studying the Blackwing Coven, and helping the druids in their dealings with them. I am very interested in acquiring a few of their dragon whelps; it would help us to gauge exactly what we're up against by understanding that which they revere. But first, we're going to need to acquire some nets. I noticed that the wyrmcult poachers out in the Ruuan Weald have an abundance of them.",starts={{npcID=21983,x=0.618,y=0.394,zoneID=3522}},ends={{npcID=21983,x=0.618,y=0.394,zoneID=3522}},coords={x=0.618,y=0.394,source="quest_giver",zoneID=3522},questType="standard"},
[10718] = {id=10718,name="The Spirits Have Voices",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description=", now that you can see me, there is something you must tell Rexxar . I know that he seeks his people, and I know where they are. The Mok'Nathal, as they are known, have a village to the east beyond the Razor Ridge. Go, give Rexxar this news. His people are in danger, and I know that he will want to come to their aid.",starts={{npcID=21950,x=0.526,y=0.588,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.526,y=0.588,source="quest_giver",zoneID=3522},questType="standard"},
[10719] = {id=10719,name="Did You Get The Note?",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="The cultist dropped this note, which apparently was to be delivered to Overseer Nuaar. It is signed by someone named Kolphis Darkscale. It is likely that Tree Warden Chawn will be interested in looking at this.",ends={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},questType="standard"},
[10720] = {id=10720,name="The Smallest Creatures",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The ogres, simple as they are, would notice you dispersing this poison throughout their camp. Thus, I will teach you how to enlist the help of one of nature's smallest creatures to do this task. By playing a simple rhythm on this drum, you can coax a marmot to follow your commands. There is a den of marmots near the Bloodmaul camp, to the north, down in the Daggermaw Canyon past the Circle of Blood. Once you have a marmot's aid, use it to disperse the poison to the Bloodmaul's kegs.",starts={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10721] = {id=10721,name="A Boaring Time for Grulloc",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description=", I have a pet boar named Huffer. He wants to help you to have some fun with one of the nearby sons of Gruul. Grulloc inhabits a place known as the Cursed Hollow. When you get there, let Huffer loose. The gronn will have a fine time chasing him around, and you will retrieve the bag that he guards and deliver it to Baron Sablemane . To get to the Cursed Hollow, head down the northern ramp and east through Dragons' End. The hollow is on the eastern edge.",starts={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10722] = {id=10722,name="Meeting at the Blackwing Coven",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="I know what must be done! , you must pose as Overseer Nuaar and attend that meeting! The wyrmcultists at the coven all have a standard outfit that they wear, so go collect scraps from them, and when you have enough, put together a disguise. Pose as Overseer Nuuar and speak with Kolphis Darkscale to see what he has to say, and then return to Tree Warden Chawn . You'll find the coven by heading through the Wyrmskull Tunnel and following the path past the Raven's Wood and Grishnath to its end.",starts={{npcID=22386,x=0.502,y=0.36,zoneID=3522}},ends={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},coords={x=0.502,y=0.36,source="quest_giver",zoneID=3522},questType="standard"},
[10723] = {id=10723,name="Gorgrom the Dragon-Eater",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The gronn we seek is Gorgrom the Dragon-Eater. With Sablemane's trap , you will make short work of the gronn. You will find him accepting sacrifices from the ogres of Boulder'mok. Follow the road north from the Circle of Blood, then west at Ruuan Weald. Go northwest through the tunnel. First, kill the ogres for their heads. We will send a message. Set the trap at his altar. When he is dead, plant the grisly totems near him - none can mistake that message. Take the bear.",starts={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10724] = {id=10724,name="Prisoner of the Bladespire",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Shortly after my arrival in the mountains, I came under attack by a group of Bladespire ogres. Though I fought free of them, and slew many, they took my wyvern, Leokk, captive. Spirit has found him, locked in a cage in the heart of the Bladespire encampment outside of Gruul's lair. One of the ogres must carry his key. Find it and Spirit can use it to unlock Leokk's cage. You will find the encampment at the north end of the Daggermaw Canyon down below.",starts={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10742] = {id=10742,name="Showdown",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Now it comes to this. We will bring Goc forth from his lair, and we will destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer. Go to Goc 's altar outside Gruul's Lair, then blow my horn. I will come, and we will face the son of Gruul together.",starts={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10744] = {id=10744,name="News of Victory",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="You must bring word of our success to Kurdran Wildhammer immediately! His men, under Wing Commander Nuainn, have fought nonstop to keep Wildhammer Stronghold safe and your return will surely bolster their spirits. With the threat from the Legion out of the way, Kurdran can finally turn his attention to dealing with the forces of Illidan. Our place here is far from secure, but we've won a major victory this day.",starts={{npcID=21790,x=0.408,y=0.222,zoneID=3520}},ends={{npcID=21330,x=0.358,y=0.576,zoneID=3520}},coords={x=0.408,y=0.222,source="quest_giver",zoneID=3520},questType="standard"},
[10745] = {id=10745,name="News of Victory",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="You must bring word of our success to Overlord Or'barokh immediately! Now that we've crushed the Legion and obliterated their presence in Shadowmoon Valley , the overlord can turn his attention to our other foes. Although the Kor'kron guard will never admit it, they'll be glad we're no longer fighting on two fronts.",starts={{npcID=21789,x=0.274,y=0.212,zoneID=3520}},ends={{npcID=21769,x=0.284,y=0.264,zoneID=3520}},coords={x=0.274,y=0.212,source="quest_giver",zoneID=3520},questType="standard"},
[10747] = {id=10747,name="Whelps of the Wyrmcult",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="I need to examine the whelps that they are raising at the Blackwing Coven. There should be an abundance of them flying around inside their cavernous base, as well as a number of eggs, which if you get close to them will likely hatch. Please, , take the net and capture a handful of them alive for me. Find them by heading west across the Wyrmskull Bridge and heading through the Wyrmskull Tunnel. Follow the path to its end past Grishnath and the Raven's Wood.",starts={{npcID=21983,x=0.618,y=0.394,zoneID=3522}},ends={{npcID=21983,x=0.618,y=0.394,zoneID=3522}},coords={x=0.618,y=0.394,source="quest_giver",zoneID=3522},questType="standard"},
[10748] = {id=10748,name="Maxnar Must Die!",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="They've left us no choice, . It's time to put an end to the threat from the Blackwing Coven by taking out their leader, Maxnar the Ashmaw . I don't know if you caught a glimpse of him while you were in there, but he's one of the dragonkin, half-man, half-dragon. And he's tough, so don't underestimate him! Finish it quickly and with any luck you'll secure the safety of Evergrove and the Ruuan Weald.",starts={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},ends={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},coords={x=0.62,y=0.394,source="quest_giver",zoneID=3522},questType="standard"},
[10749] = {id=10749,name="Baron Sablemane's Poison",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Here, take this to your master. I'm sure that whatever the reason, Rexxar will put it to good use. Oh, and do be certain to remind him that he owes me. He knows what I want, and I'm certain that however he intends to obtain it for me, I'll be seeing you again sooner than you think. Now, do be a good little and run this up to Rexxar .",starts={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.532,y=0.41,source="quest_giver",zoneID=3522},questType="standard"},
[10750] = {id=10750,name="The Path of Conquest",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Word has come from my wind riders, . The Eclipsion blood elves are planning something big. They have begun forming their armies at the Path of Conquest, far to the southeast - adjacent to Eclipse Point. I want you to travel to the Path of Conquest and assess the situation. Once you have done so, use this flare gun to signal a wind rider. One will swoop down from the sky to meet you. Inform them of what you have discovered and they will give you your next set of orders.",starts={{npcID=21769,x=0.284,y=0.264,zoneID=3520}},ends={{npcID=21998,x=0.52,y=0.652,zoneID=3520}},coords={x=0.284,y=0.264,source="quest_giver",zoneID=3520},questType="group"},
[10751] = {id=10751,name="Breaching the Path",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="We're going to need more time, . I'm going to fly further ahead with some of the other wind riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us! Call for a wind rider with the Kor'kron flare gun once you have thinned their numbers.",starts={{npcID=21998,x=0.52,y=0.652,zoneID=3520}},ends={{npcID=21998,x=0.52,y=0.652,zoneID=3520}},coords={x=0.52,y=0.652,source="quest_giver",zoneID=3520},questType="group"},
[10753] = {id=10753,name="Culling the Wild",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="The number of atrocities committed by the Burning Legion is countless. Even as we speak, they send their legion forces against the creatures of this land. Helpless to defend against their power, they fall one by one. , help me stop these crimes of nature destroy all which they corrupt. Over the hill, east of here, you will see the corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel Corrupters , and as many Felsworn as you can.",starts={{npcID=22133,x=0.626,y=0.382,zoneID=3522}},ends={{npcID=22133,x=0.626,y=0.382,zoneID=3522}},coords={x=0.626,y=0.382,source="quest_giver",zoneID=3522},questType="standard"},
[10759] = {id=10759,name="Find the Deserter",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="I get the feeling that all the pieces are here, but I just can't put them together in a way that makes sense. I think our best lead is to attempt to locate this deserter. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning. Start your search for him along the road in Magma Fields to the northwest. It seems a likely place for him to take refuge.",starts={{npcID=22042,x=0.386,y=0.542,zoneID=3520}},ends={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},coords={x=0.386,y=0.542,source="quest_giver",zoneID=3520},questType="standard"},
[10760] = {id=10760,name="The Sketh'lon Wreckage",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The Sketh'lon Wreckage, just to the east, is an eerie place. The peons are convinced that it's cursed. There are few trees here, so the peons have no choice but to venture into the arakkoa ruins to chop wood. The arakkoa spirits prey on the work groups, draining their life and using it to fuel their foul magics. We must find out what is driving the dark conclave and stop them before their influence expands. Search the Sketh'lon Wreckage for evidence of their plans.",starts={{npcID=22043,x=0.31,y=0.298,zoneID=3520}},ends={{npcID=22043,x=0.31,y=0.298,zoneID=3520}},coords={x=0.31,y=0.298,source="quest_giver",zoneID=3520},questType="standard"},
[10761] = {id=10761,name="Find the Deserter",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="There's nothing here that would explain why the spirits of these arakkoa have remained in this world or how they came into thirst for the blood of orcs. I think our best lead is to try to find the deserter mentioned in the journal. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning. Start your search for him on the road through the Magma Fields to the southeast.",starts={{npcID=22043,x=0.31,y=0.298,zoneID=3520}},ends={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},coords={x=0.31,y=0.298,source="quest_giver",zoneID=3520},questType="standard"},
[10765] = {id=10765,name="When Worlds Collide...",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. You've probably already noticed the smaller giants on the path as well. Something is just not right about all of this, grunt. I want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.",starts={{npcID=21998,x=0.52,y=0.652,zoneID=3520}},ends={{npcID=21998,x=0.52,y=0.652,zoneID=3520}},coords={x=0.52,y=0.652,source="quest_giver",zoneID=3520},questType="group"},
[10766] = {id=10766,name="Invasion Point: Cataclysm",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Wildhammer Stronghold won't be safe until the Legion's presence is erased from Shadowmoon Valley . I've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Plexi will meet you at your destination.",starts={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},ends={{npcID=21790,x=0.408,y=0.222,zoneID=3520}},coords={x=0.394,y=0.536,source="quest_giver",zoneID=3520},questType="standard"},
[10767] = {id=10767,name="Invasion Point: Cataclysm",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Shadowmoon Village won't be safe until the Legion's presence is erased from the valley. I've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Nakansi will meet you at your destination.",starts={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},ends={{npcID=21789,x=0.274,y=0.212,zoneID=3520}},coords={x=0.304,y=0.324,source="quest_giver",zoneID=3520},questType="standard"},
[10768] = {id=10768,name="Tabards of the Illidari",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The wind riders must return to Shadowmoon Village to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear. When you have collected enough tabards, call for a wind rider using the Kor'kron flare gun. Prepare yourself for a bit of espionage, !",starts={{npcID=21998,x=0.52,y=0.652,zoneID=3520}},ends={{npcID=21998,x=0.52,y=0.652,zoneID=3520}},coords={x=0.52,y=0.652,source="quest_giver",zoneID=3520},questType="group"},
[10769] = {id=10769,name="Dissension Amongst the Ranks...",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Researcher Tiorus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth. Take the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!",starts={{npcID=21998,x=0.52,y=0.652,zoneID=3520}},ends={{npcID=21769,x=0.284,y=0.264,zoneID=3520}},coords={x=0.52,y=0.652,source="quest_giver",zoneID=3520},questType="group"},
[10770] = {id=10770,name="Little Embers",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Northeast of here, on the plateau above us lies the burnt ashes of my ancient home. A great wood flourished there before the Burning Legion sent their imps to burn us away. So many died that even centuries later my tired old heart hungers for revenge. There are too many of them for us to ever reclaim the land, but you could make them afraid. Surely you will help me?",starts={{npcID=22053,x=0.612,y=0.384,zoneID=3522}},ends={{npcID=22053,x=0.612,y=0.384,zoneID=3522}},coords={x=0.612,y=0.384,source="quest_giver",zoneID=3522},questType="standard"},
[10771] = {id=10771,name="From the Ashes",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="If you follow the road east and up the side of the mountain, then turn north, you will come to my long lost home. Once there was a wood there. Its name is forgotten. Long ago the Burning Legion summoned scorched imps and other creatures of flame. My home was destroyed and my people fled. Now only I remain. I have saved some ironroot seeds that could be planted in fertile volcanic soil . Their magic is strong. Do this for me and I will share with you the treasures of a forgotten age.",starts={{npcID=22053,x=0.612,y=0.384,zoneID=3522}},ends={{npcID=22053,x=0.612,y=0.384,zoneID=3522}},coords={x=0.612,y=0.384,source="quest_giver",zoneID=3522},questType="standard"},
[10772] = {id=10772,name="The Path of Conquest",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="My gryphon riders have come back with a bit of news! The Eclipsion blood elves are planning something big. They've begun forming their armies at the Path of Conquest, located east of here - adjacent to Eclipse Point. I want you to travel to the Path of Conquest and assess the situation. Once you've done so, use this flare gun to signal a gryphon rider. One will swoop down from the sky to meet you. Tell 'em what you've discovered and they'll give you the next set of orders.",starts={{npcID=21773,x=0.362,y=0.568,zoneID=3520}},coords={x=0.362,y=0.568,source="quest_giver",zoneID=3520},questType="group"},
[10773] = {id=10773,name="Breaching the Path",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="We're going to need more time, . I'm going to fly further ahead with some of the other gryphon riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us! Call for a gryphon rider with the Wildhammer flare gun once you have thinned their numbers.",questType="group"},
[10774] = {id=10774,name="Blood Elf + Giant = ???",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. What are giants even doing here? Something is just not right about all of this, grunt. I want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.",questType="group"},
[10775] = {id=10775,name="Tabards of the Illidari",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="The gryphon riders must return to Wildhammer Stronghold to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear. When you have collected enough tabards, call for a gryphon rider using the Wildhammer flare gun. Prepare yourself for a bit of espionage, !",questType="group"},
[10776] = {id=10776,name="Dissension Amongst the Ranks...",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Gnomus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth. Take the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!",ends={{npcID=21773,x=0.362,y=0.568,zoneID=3520}},questType="group"},
[10777] = {id=10777,name="Asghar's Totem",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="What you read in the commander's journal is true. While the orcish Horde massed under Gul'dan, my people sought to defend ourselves from the threat by striking against him. Gul'dan learned of their intentions and cast a mighty spell that destroyed our camps and twisted the spirits of my brothers. They must be stopped before they unleash a greater evil. In the Sketh'lon Wreckage to the north, seek out Asghar and bring me the totem he carries. With it, we can begin to thwart the dark conclave's plans.",starts={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},ends={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},coords={x=0.354,y=0.418,source="quest_giver",zoneID=3520},questType="standard"},
[10778] = {id=10778,name="The Rod of Lianthe",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The totem alone is not strong enough to counteract the sinister magics of the dark conclave. We can combine it with other objects of power, forming a staff to focus the energies. We cannot rescue my brethren from the depths of their depravity, but we can stop them. One of the items I need for the staff is the Rod of Lianthe , held by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the top tier of the ruins and will be heavily guarded. Use caution, .",starts={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},ends={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},coords={x=0.354,y=0.418,source="quest_giver",zoneID=3520},questType="standard"},
[10780] = {id=10780,name="Sketh'lon Feathers",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="There is one last element missing from the staff. We must direct the staff's power toward the Dark Conclave spirits. We can do that by gathering feathers scattered on the ground at the Sketh'lon Base Camp and using them in the staff. The base camp is to the south, east of Wildhammer Stronghold. Gul'dan's magic utterly destroyed my brethren, leaving only their spirits, but it did not stop there. The magic fed on the spell the arakkoa were preparing, forging a sinister force that engulfed the spirits.",starts={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},ends={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},coords={x=0.354,y=0.418,source="quest_giver",zoneID=3520},questType="standard"},
[10781] = {id=10781,name="Battle of the Crimson Watch",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="They are probably searching for you on the Path of Conquest as we speak. You must make your escape, ! Leave me, I'm done for... They... I think I hear them coming. It's now or never! Get out! If you choose to stay, you will have to fight! If you fight and somehow manage to survive, take what you have learned here and deliver that knowledge to A'dal in Shattrath City.",starts={{npcID=185126,x=0.515,y=0.727,zoneID=3520}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.515,y=0.727,source="quest_giver",zoneID=3520},questType="group"},
[10782] = {id=10782,name="Imbuing the Headpiece",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The staff is nearly finished! All that remains is to imbue the headpiece with power flowing from the echoes of Gul'dan in this accursed place. To the east, near the Fel Pits and south of the Deathforge, is the Altar of Damnation. There, fragments of Gul'dan's past are trapped. When you carry the unfinished headpiece of the staff into the area around the altar, don't be surprised if some of the entities react to it. You will be carrying a dangerous object with strong connections to the cataclysm.",starts={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},ends={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},coords={x=0.354,y=0.418,source="quest_giver",zoneID=3520},questType="standard"},
[10783] = {id=10783,name="Baron Sablemane",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Here is my plan. We will poison the ogres and then destroy their gronn master. During my travels in these mountains, I met a man named Baron Sablemane . He is a master of the alchemical arts, and may be convinced to assist us. You will find him at the Circle of Blood, down in the canyon to the north of here. Whatever price he requires, I will leave it to your discretion to accept.",starts={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10784] = {id=10784,name="Crush the Bloodmaul Camp",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description=", you've done us more than proud in the fight against the ogres so far. And while I have every confidence in what Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before returning. That way we'll be doubly certain of the outcome. To get there, head north down the ramp out of Thunderlord. Then, at the base of the ramp, head west across Dragons' End and north through the Churning Gulch and Daggermaw Canyon.",starts={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10785] = {id=10785,name="It's a Trap!",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="There's is no cause of fury greater in this world than that of Gruul and his sons. They slaughtered my people - my children - and now I will have revenge. I have fashioned a trap from dragon fire, and if you're clever enough, you can use it to kill even a gronn. Just hurry, take the trap to Rexxar . My thirst for revenge must be quenched.",starts={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},ends={{npcID=21984,x=0.518,y=0.584,zoneID=3522}},coords={x=0.532,y=0.41,source="quest_giver",zoneID=3522},questType="standard"},
[10786] = {id=10786,name="Slaughter at Boulder'mok",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="I know that Rexxar has plans for you to head to Boulder'mok. I have something that I want you to do while you are there. We must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing! Boulder'mok lies far to the northwest. Travel north to Ruuan Weald, and from there head west through the tunnel and past the Raven's Wood. , I want you to kill the Bladespire ogres of Boulder'mok. Wipe them out!",starts={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},ends={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},coords={x=0.518,y=0.584,source="quest_giver",zoneID=3522},questType="standard"},
[10791] = {id=10791,name="Welcoming the Wolf Spirit",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="I've nearly completed the vestments that I'll wear during the ceremony. As I add the finishing touches, I'd like you to set this incense by the candles near the runestone to my left. I believe it will help us to attract the wolf spirit's attention, since it was made in the days of the orcish clans. I can almost imagine my ancestors using it in a ceremony paying tribute to the wolf spirit after a successful hunt. Once you've placed the incense, I'll begin the ceremony.",starts={{npcID=18384,x=0.5,y=0.464,zoneID=3519}},ends={{npcID=18384,x=0.5,y=0.464,zoneID=3519}},coords={x=0.5,y=0.464,source="quest_giver",zoneID=3519},questType="standard"},
[10792] = {id=10792,name="Zeth'Gor Must Burn!",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="The Bleeding Hollow clan have betrayed their noble heritage! We, the orcs who fought and died to save ourselves from the fel taint of Mannoroth, look upon our vile cousins and see only weakness and ignobility... and for that, they must burn! Enter Zeth'Gor, their bastion to the east, and burn their buildings. Kill peons for their torches, ignite them at their forge, and hurl the burning torches at their hovels, their stable and their barracks. Burn them all, and then return to me! For the Horde!",starts={{npcID=22107,x=0.612,y=0.812,zoneID=3483}},ends={{npcID=22107,x=0.612,y=0.812,zoneID=3483}},coords={x=0.612,y=0.812,source="quest_giver",zoneID=3483},questType="standard"},
[10793] = {id=10793,name="The Journal of Val'zareq: Portends of War",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar. This general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.",ends={{npcID=185126,x=0.515,y=0.727,zoneID=3520}},questType="group"},
[10795] = {id=10795,name="A Date with Dorgok",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Good, I've seen you around and I've been meaning to speak to you about a matter of some importance. There are reports coming in that for some reason the Bloodmaul ogres are planning an offensive against Sylvanaar and Ruuan Weald. We don't know who or what is pushing them to do this, but I intend to nip their plan in the bud! Bloodmaul Camp is where the attacks are to be staged from. Head northwest down the ramp out of the Ruuan Weald and you will find it. I want you to kill their leader, Dorgok !",starts={{npcID=22149,x=0.62,y=0.38,zoneID=3522}},ends={{npcID=22149,x=0.62,y=0.38,zoneID=3522}},coords={x=0.62,y=0.38,source="quest_giver",zoneID=3522},questType="standard"},
[10796] = {id=10796,name="Crush the Bloodmaul Camp!",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I've heard that you've done us more than proud in the fight against the ogres thus far. Now, I would ask that you face them again. I want you to crush the ogres at Bloodmaul Camp! To get down there, head northwest down the ramp out of the Ruuan Weald. You'll find them at the base of the ramp. Good luck, !",starts={{npcID=22150,x=0.62,y=0.38,zoneID=3522}},ends={{npcID=22150,x=0.62,y=0.38,zoneID=3522}},coords={x=0.62,y=0.38,source="quest_giver",zoneID=3522},questType="standard"},
[10797] = {id=10797,name="Favor of the Gronn",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="A token in the form of a small statuette falls from Dorgok's dead clutch. It bears a striking resemblance to one of the gronn. Surely, Commander Haephus Stonewall at Evergrove in the Ruuan Weald, up the ramp to the east, would be interested in this!",ends={{npcID=22149,x=0.62,y=0.38,zoneID=3522}},questType="standard"},
[10798] = {id=10798,name="Pay the Baron a Visit",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="This is bad news. Gorgrom the Dragon-Eater is behind the recent Bloodmaul plans against Sylvanaar! Why he's manipulating them, and not just using the Bladespire, I don't know. But if we're to deal with a gronn, we're going to need help. I know a man who is wise in the ways of all sorts of exotic magics. Baron Sablemane is his name, and you can find him at the Circle of Blood, back down the ramp to the northwest, and then southwest through the canyon. Ask him to fashion us a trap for the gronn.",starts={{npcID=22149,x=0.62,y=0.38,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.62,y=0.38,source="quest_giver",zoneID=3522},questType="standard"},
[10799] = {id=10799,name="Into the Churning Gulch",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Very well, I'll create this trap, but first I want something in return. There happens to be a nearby gronn that is in possession of an item that I want, but you can't face him, not yet anyway. So, you and I are going to fashion a sleeping powder from the poison of the nearby crust bursters. You'll find them in the Churning Gulch to the southwest. Bring me a number of their glands, and be quick about it!",starts={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.532,y=0.41,source="quest_giver",zoneID=3522},questType="standard"},
[10800] = {id=10800,name="Goodnight, Gronn",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I've outdone myself again. I've fashioned a sleeping powder for you to use on Grulloc, the gronn I spoke of who is guarding what I want. Grulloc keeps himself at the Cursed Hollow, an area at the eastern edge of Dragons' End on the other side of the Circle of Blood. If I were you, I wouldn't tarry long once you have his sack. The effects of the dust won't last long.",starts={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.532,y=0.41,source="quest_giver",zoneID=3522},questType="standard"},
[10801] = {id=10801,name="It's a Trap!",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="There's nothing more that I hate in this world than the sons of Gruul and their father! They slaughtered my people, and my children, and now I will have a taste of revenge! I have fashioned a trap from some dragon fire, and if you're clever enough, you might just be able to use it to kill a gronn. I'm sure that you have a particular gronn in mind; it matters not to me which one you kill. Just hurry, take the trap to your Commander Stonewall. My thirst for revenge must be quenched!",starts={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},ends={{npcID=22149,x=0.62,y=0.38,zoneID=3522}},coords={x=0.532,y=0.41,source="quest_giver",zoneID=3522},questType="standard"},
[10802] = {id=10802,name="Gorgrom the Dragon-Eater",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="We must show the ogres that we are not to be trifled with. We must send a message. Travel to Boulder'mok and kill the ogres there. Make sure you keep their heads. Then go to Gorgrom's altar and place the trap there for him. Gorgrom will appear, and you must lure him into the trap. When he is dead, mount your grisly totems near his corpse, so that the ogres may look at their fallen master and their fallen brothers, and know the price for seeking to destroy us.",starts={{npcID=22149,x=0.62,y=0.38,zoneID=3522}},ends={{npcID=22149,x=0.62,y=0.38,zoneID=3522}},coords={x=0.62,y=0.38,source="quest_giver",zoneID=3522},questType="standard"},
[10803] = {id=10803,name="Slaughter at Boulder'mok",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="I know that we have plans for you to head to Boulder'mok. I have something that I want you to do while you are there. We must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing! Boulder'mok lies to the west. Travel southwest, cross the bridge and head through the tunnel. On the west side of the Raven's Wood you will find them. , I want you to wipe out the Bladespire ogres of Boulder'mok.",starts={{npcID=22150,x=0.62,y=0.38,zoneID=3522}},ends={{npcID=22150,x=0.62,y=0.38,zoneID=3522}},coords={x=0.62,y=0.38,source="quest_giver",zoneID=3522},questType="standard"},
[10804] = {id=10804,name="Kindness",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Something has them spooked, . Mordenai points to the nether drakes flying overhead.> They won't even come down to feed. I have seen several fall to the earth, dead from exhaustion before their bodies hit the ground. We must save them! The Rocknail flayers that are found near the crystals are their natural prey. Kill flayers and take their carcasses. Place a carcass in the field and stand extremely still. As long as you do not make any aggressive motions, they will not attack you.",starts={{npcID=22113,x=0.594,y=0.586,zoneID=3520}},ends={{npcID=22113,x=0.594,y=0.586,zoneID=3520}},coords={x=0.594,y=0.586,source="quest_giver",zoneID=3520},questType="standard"},
[10805] = {id=10805,name="Massacre at Gruul's Lair",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="You've proven yourself resourceful, and now I think I'm going to put you to personal use in my own fight against Gruul and his sons. The Bladespire clan are the favored of the gronn, and while you may have thinned out their numbers elsewhere, you haven't yet dealt with their strongest. Gruul protects the exterior of his lair with only the toughest of ogres, and it is those that you must kill. Head north through the Daggermaw Canyon and you will find Gruul's Lair at the end.",starts={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.532,y=0.41,source="quest_giver",zoneID=3522},questType="standard"},
[10806] = {id=10806,name="Showdown",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="The time has come for us to face Goc , the master of the Bladespire ogres. It is also time that I take a hand in events, to see the last of the gronn's life. Take my signet ring. When you come to the Altar of Goc , use it, and I will come to join you. Together we will destroy Goc .",starts={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.532,y=0.41,source="quest_giver",zoneID=3522},questType="standard"},
[10807] = {id=10807,name="The Ashtongue Broken",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The Ashtongue tribe is feared among all Broken. It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself. They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, to the north. Go there and put a dent in their numbers before they get a chance to mount an attack on us.",starts={{npcID=21953,x=0.548,y=0.582,zoneID=3520}},ends={{npcID=21953,x=0.548,y=0.582,zoneID=3520}},coords={x=0.548,y=0.582,source="quest_giver",zoneID=3520},questType="standard"},
[10808] = {id=10808,name="Thwart the Dark Conclave",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The spirits of the dark conclave seek to summon an ancient and powerful evil through a ritual conducted at the lava pits to the south of the Sketh'lon Base Camp. Gul'dan's magic mingled with their own, empowering them to aid this creature in manifesting in our world! We must not allow this to happen, . The death and destruction it would bring are unimaginable! Carry the staff with you to the site of the summoning and use its magics to stop the dark conclave once and for all!",starts={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},ends={{npcID=22024,x=0.354,y=0.418,zoneID=3520}},coords={x=0.354,y=0.418,source="quest_giver",zoneID=3520},questType="standard"},
[10809] = {id=10809,name="WANTED: Worg Master Kruush",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="The poster reads: \"Worg Master Kruush leads the worg riders of the Bleeding Hollow clan. A price has been placed on his head, for his riders exact heavy tolls on supply trains to Spinebreaker Post.\" \"Scouts report him within Zeth'Gor, and the hero able to bring the severed head of this villain to me will earn the thanks of the Horde, and a large bounty.\" \"- Captain Darkhowl \"",starts={{npcID=185166,x=0.612,y=0.806,zoneID=3483}},ends={{npcID=22107,x=0.612,y=0.812,zoneID=3483}},coords={x=0.612,y=0.806,source="quest_giver",zoneID=3483},questType="standard"},
[10810] = {id=10810,name="Damaged Mask",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="As you examine the damaged mask , you hear strange sounds coming from within. If the mask wasn't damaged you might be able to hear the sounds more clearly. O'Mally Zapnabber in Ruuan Weald might be able to fix the mask.",ends={{npcID=22020,x=0.626,y=0.402,zoneID=3522}},questType="standard"},
[10811] = {id=10811,name="Seek Out Neltharaku",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Their patron soars high above, . Perhaps the kindness that you showed his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you may be able to solve the plight of the Netherwing drakes. Mordenai points to the sky.> Fly high, friend...",starts={{npcID=22113,x=0.594,y=0.586,zoneID=3520}},ends={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},coords={x=0.594,y=0.586,source="quest_giver",zoneID=3520},questType="standard"},
[10812] = {id=10812,name="Mystery Mask",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Ok, it should work now. What is it, you ask? Why, it's a communication device - it allows those blockheads to communicate with each other. You know, the Burning Legion! I would suggest that you hand this mask to Wildlord Antelarion . He's over there pacing around. Always moving, he is. Well get moving, he's been trying to get his hands on one of these for sometime now.",starts={{npcID=22020,x=0.626,y=0.402,zoneID=3522}},ends={{npcID=22127,x=0.616,y=0.384,zoneID=3522}},coords={x=0.626,y=0.402,source="quest_giver",zoneID=3522},questType="standard"},
[10813] = {id=10813,name="The Eyes of Grillok",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description=", you have braved the lair of the Bleeding Hollow orcs, dreaded Zeth'Gor, and survived! Perhaps you have the strength to aid me, for I aim to gaze into the mind of its darkest witch, Grillok! Take this shard. Use it to ensorcel an Eye of Grillok and bind it to yourself. Return here and approach my cauldron... and it will pull the eye from you. Go, . And use care -- An Eye of Grillok will betray you to our enemies if given the slightest opening!",starts={{npcID=22231,x=0.616,y=0.818,zoneID=3483}},ends={{npcID=22231,x=0.616,y=0.818,zoneID=3483}},coords={x=0.616,y=0.818,source="quest_giver",zoneID=3483},questType="standard"},
[10814] = {id=10814,name="Neltharaku's Tale",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I have information that you may find useful. Please listen to what I have to tell you, .",starts={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},ends={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},coords={x=0.618,y=0.6,source="quest_giver",zoneID=3520},questType="standard"},
[10816] = {id=10816,name="Reclaiming Holy Grounds",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="You did well against the Broken in Baa'ri, . Let's see how well you do against Illidan's most feared army. The fel orcs of the Shadowmoon Clan occupy the Ata'mal Terrace, once a very holy site where ata'mal crystals were used in spiritual ceremonies. We had reason to believe they were hiding an actual ata'mal crystal in the vicinity, but our scrying has revealed nothing. Nevertheless, the fel orcs are on draenei holy ground and their presence must be dealt with.",starts={{npcID=21822,x=0.612,y=0.292,zoneID=3520}},ends={{npcID=21822,x=0.612,y=0.292,zoneID=3520}},coords={x=0.612,y=0.292,source="quest_giver",zoneID=3520},questType="standard"},
[10817] = {id=10817,name="The Great Retribution",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="You did well against the Ashtongue Broken, . I have another challenge for you, should you be up to it. Not too long ago, the Sanctum of the Stars suffered a tremendous attack by Illidan's fel orcs. We've determined it was perpetrated by the Shadowmoon orcs who occupy the Ata'mal Terrace. Show them that the Scryers are not to be trifled with.",starts={{npcID=21953,x=0.548,y=0.582,zoneID=3520}},ends={{npcID=21953,x=0.548,y=0.582,zoneID=3520}},coords={x=0.548,y=0.582,source="quest_giver",zoneID=3520},questType="standard"},
[10818] = {id=10818,name="Baron Sablemane Has Requested Your Presence",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description=", while you were out being one hell of a , Baron Sablemane sent his pet dragon up here with a message. He's asked for you personally. From what I understand, he wants you to head up his own fight against the gronn. I guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.",starts={{npcID=22149,x=0.62,y=0.38,zoneID=3522}},ends={{npcID=22103,x=0.532,y=0.41,zoneID=3522}},coords={x=0.62,y=0.38,source="quest_giver",zoneID=3522},questType="standard"},
[10819] = {id=10819,name="Felsworn Gas Mask",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=7705,description="I have a very special mission for you, . I need you to infiltrate Forge Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas mask and locate the Legion communicator . Once you have located the communication device speak with whomever is on the other side of the device. If all works out you can trick the demon into something devious! Try telling the demon that Camp Anger has revolted. Good luck to you .",starts={{npcID=22127,x=0.616,y=0.384,zoneID=3522}},ends={{npcID=185165,x=0.733,y=0.401,zoneID=3522},{npcID=185165,x=0.417,y=0.73,zoneID=7705}},coords={x=0.616,y=0.384,source="quest_giver",zoneID=3522},questType="standard"},
[10820] = {id=10820,name="Deceive thy Enemy",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=7705,description="For every moment I hear silence, you draw closer to your death! SPEAK! What? The camp has revolted? This cannot possibly be true! My minions would not dare undermine my authority. Well then, every last one of them will pay for this treachery, they will pay dearly. Silence them all and be done with it! Report back to me once you have carried out my order or you shall be dealt with.",starts={{npcID=185165,x=0.733,y=0.401,zoneID=3522},{npcID=185165,x=0.417,y=0.73,zoneID=7705}},ends={{npcID=185165,x=0.733,y=0.401,zoneID=3522},{npcID=185165,x=0.417,y=0.73,zoneID=7705}},coords={x=0.733,y=0.401,source="quest_giver",zoneID=3522},questType="standard"},
[10821] = {id=10821,name="You're Fired!",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3523,description="Doomcryer did nothing to stop the revolt? How dare she! She has been trying to undermine my authority for some time. However, this time will be her last. You must summon her and deal with her personally. Her anger guards hold the keys that summon her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. The obelisks have a short duration, so make sure they are all activated at the same time. Remember, the anger guards carry more keys.",starts={{npcID=185165,x=0.733,y=0.401,zoneID=3522},{npcID=185165,x=0.417,y=0.73,zoneID=7705}},ends={{npcID=22127,x=0.616,y=0.384,zoneID=3522}},coords={x=0.733,y=0.401,source="quest_giver",zoneID=3522},questType="standard"},
[10822] = {id=10822,name="Single Sunfury Signet",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,starts={{npcID=22211,x=0.562,y=0.586,zoneID=3520}},ends={{npcID=22211,x=0.562,y=0.586,zoneID=3520}},coords={x=0.562,y=0.586,source="quest_giver",zoneID=3520},questType="standard"},
[10823] = {id=10823,name="More Sunfury Signets",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,starts={{npcID=22211,x=0.562,y=0.586,zoneID=3520}},ends={{npcID=22211,x=0.562,y=0.586,zoneID=3520}},coords={x=0.562,y=0.586,source="quest_giver",zoneID=3520},questType="standard"},
[10824] = {id=10824,name="Sunfury Signets",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The survival of the Scryers hinges on outrecruiting Kael'thas. Every pilgrim from Quel'Thalas that joins his side brings him closer to victory. The opposite is true for us. Soon, however, we will run out of recruits and it will come down to what side can kill the other quicker. Prove your worth to the Scryers by bringing me Sunfury signets worn by high-ranking blood elves allied with Kael'thas and Illidan. You'll find them at Eclipse Point to the west and the Ruins of Karabor, to the northeast.",starts={{npcID=22211,x=0.562,y=0.586,zoneID=3520}},ends={{npcID=22211,x=0.562,y=0.586,zoneID=3520}},coords={x=0.562,y=0.586,source="quest_giver",zoneID=3520},questType="standard"},
[10825] = {id=10825,name="The Truth Unorbed",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="This strange, magical orb drops from beneath the contour feathers of the arakkoa. Suffused with an eerie, purple glow, the orb pulses to an unheard beat. Holding it makes you mildly uncomfortable, and so you quickly place it within your pack. Perhaps Tree Warden Chawn at Ruuan Weald to the west, through the tunnel and across the Wyrmskull Bridge, would be interested in examining it?",ends={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},questType="standard"},
[10826] = {id=10826,name="Marks of Sargeras",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="By now it should be clear to you why we oppose the Burning Legion and those who serve them. If you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers. Here in Shadowmoon you will find a strong Legion presence to the far west in Legion Hold and the Deathforge.",starts={{npcID=22214,x=0.622,y=0.298,zoneID=3520}},ends={{npcID=22214,x=0.622,y=0.298,zoneID=3520}},coords={x=0.622,y=0.298,source="quest_giver",zoneID=3520},questType="standard"},
[10827] = {id=10827,name="More Marks of Sargeras",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,starts={{npcID=22214,x=0.622,y=0.298,zoneID=3520}},ends={{npcID=22214,x=0.622,y=0.298,zoneID=3520}},coords={x=0.622,y=0.298,source="quest_giver",zoneID=3520},questType="standard"},
[10828] = {id=10828,name="Single Mark of Sargeras",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,starts={{npcID=22214,x=0.622,y=0.298,zoneID=3520}},ends={{npcID=22214,x=0.622,y=0.298,zoneID=3520}},coords={x=0.622,y=0.298,source="quest_giver",zoneID=3520},questType="standard"},
[10829] = {id=10829,name="Treebole Must Know",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="This is troubling! The arakkoa are causing the ancients and protectors to become possessed by evil spirits! But, there is one ancient that could not possibly have been affected. His name is Treebole , and you must go to him at once if we're to save the trees of the Raven's Wood! Go back to the Raven's Wood. You will find him at the fork in the path just past Grishnath.",starts={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},ends={{npcID=22215,x=0.366,y=0.232,zoneID=3522}},coords={x=0.62,y=0.394,source="quest_giver",zoneID=3522},questType="standard"},
[10830] = {id=10830,name="Exorcising the Trees",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="The Grishna have caused the leafbeards and stonebarks to be inhabited by evil koi-koi spirits . We must save the trees or soon all of the Raven's Wood will be lost forever! Combine the magic of a Grishnath orb, found throughout Grishnath, with a dire pinfeather from a dire raven. Use the resultant exorcism feather to draw out and slay the koi-koi spirit as quickly as possible. The stonebarks are too powerful for this ritual, but if enough leafbeards are saved, they will be freed as well.",starts={{npcID=22215,x=0.366,y=0.232,zoneID=3522}},ends={{npcID=22215,x=0.366,y=0.232,zoneID=3522}},coords={x=0.366,y=0.232,source="quest_giver",zoneID=3522},questType="standard"},
[10834] = {id=10834,name="Grillok \"Darkeye\"",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it. His lost eye burns deep in some hellish pit, now a demon's trinket... and the patch that covers his betrayal holds its own dark secrets. Bring me Grillok's eyepatch , , and I will reward you greatly for your service...",starts={{npcID=22231,x=0.616,y=0.818,zoneID=3483}},ends={{npcID=22231,x=0.616,y=0.818,zoneID=3483}},coords={x=0.616,y=0.818,source="quest_giver",zoneID=3483},questType="standard"},
[10835] = {id=10835,name="Apothecary Antonivich",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description=", I have prepared a preliminary report of my findings regarding the Bleeding Hollow orcs. My colleague in Thrallmar, Apothecary Antonivich , will be happy to receive them. He too studies the phenomenon of fel orcs... in hopes of preventing such a tragedy from again befalling our orcish allies. Take him this report, and I will continue my study of the blood you brought me. If fortune is with us, we will isolate the cause of the fel orc affliction.",starts={{npcID=21279,x=0.612,y=0.816,zoneID=3483}},ends={{npcID=16588,x=0.522,y=0.364,zoneID=3483}},coords={x=0.612,y=0.816,source="quest_giver",zoneID=3483},questType="standard"},
[10836] = {id=10836,name="Infiltrating Dragonmaw Fortress",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I require time so that I may devise a plan to save my children and mate. You will buy me this time, mortal. Venture into Dragonmaw Fortress, located on the eastern edge of the Netherwing Fields, and lay waste to all Dragonmaw orcs that you find. The ensuing chaos and confusion should have a considerable impact on their plans. Be warned, some of my kin are too far gone - their minds corrupted by the Dragonmaw. For them, the only resolution is death. You have my permission to end their lives as well.",starts={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},ends={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},coords={x=0.618,y=0.6,source="quest_giver",zoneID=3520},questType="standard"},
[10837] = {id=10837,name="To Netherwing Ledge!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I believe that I can imbue nethervine crystals with my own essence. The power contained within these imbued crystals should be sufficient to free enslaved drakes of their masters' grasps. Travel to Netherwing Ledge, an island located off the broken shelf of Shadowmoon Valley , to the southeast. It is on Netherwing Ledge that you will find nethervine crystals . Return to me when you have collected enough crystals to fill your packs. And , Beware the Dragonmaw that now inhabit the island.",starts={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},ends={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},coords={x=0.618,y=0.6,source="quest_giver",zoneID=3520},questType="standard"},
[10838] = {id=10838,name="The Demoniac Scryer",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="The Demoniac Scryer is now ready. Take it behind Hellfire Citadel, to Hellfire Basin, and summon it upon the ground. It will then begin to attune itself to Hellfire Citadel. After its attunement, speak to the Scryer and transcribe what it tells you. Bring that transcription to me... Go, , but only when you are ready. There is no doubt that Hellfire Citadel will detect the Scryer and send wardens to destroy it!",starts={{npcID=16588,x=0.522,y=0.364,zoneID=3483}},ends={{npcID=16588,x=0.522,y=0.364,zoneID=3483}},coords={x=0.522,y=0.364,source="quest_giver",zoneID=3483},questType="standard"},
[10840] = {id=10840,name="The Tomb of Lights",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="To the east, buried under the charred sand, is the Tomb of Lights, a lost resting place of the dead. Before our caravan was ambushed I was going to journey to the tomb and cleanse it of evil spirits. Little did I know it was already infested with another kind of evil. Even now the ethereals plunder the bodies of the fallen for trinkets and keepsakes that were given to the dead centuries ago. There is little I can do while our caravan struggles to survive.",starts={{npcID=22278,x=0.374,y=0.508,zoneID=3519}},ends={{npcID=22278,x=0.374,y=0.508,zoneID=3519}},coords={x=0.374,y=0.508,source="quest_giver",zoneID=3519},questType="standard"},
[10842] = {id=10842,name="Vengeful Souls",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="The Tomb of Lights has become corrupted by the Shadow Council and the draenei dead have become cursed spirits, angry and confused with a burning hatred for the living. Enter the tomb and seek out these tragic victims. Give them the rest that they deserve.",starts={{npcID=22278,x=0.374,y=0.508,zoneID=3519}},ends={{npcID=22278,x=0.374,y=0.508,zoneID=3519}},coords={x=0.374,y=0.508,source="quest_giver",zoneID=3519},questType="standard"},
[10843] = {id=10843,name="Since Time Forgotten...",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Since time forgotten we have fought with the Bladespire ogres. We have managed to push them back so that now they only hold a tenuous grip at Bladespire Outpost. It's back the way that you came, on the southwestern edge of the Razor Ridge. Prove your worth to me by killing their leader, Gnosh Brognat . Let us see what stuff you are made of when fighting the ogres.",starts={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},ends={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},coords={x=0.752,y=0.608,source="quest_giver",zoneID=3522},questType="standard"},
[10845] = {id=10845,name="Slay the Brood Mother",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="My hunters have just returned from a scouting mission to the Singing Ridge. It seems that the nether drakes, which infest the crystals there, have increased greatly in number, and threaten to spill out into our laps. Since you have proven yourself a competent slayer, let us see if your skills are the match of an adult drake. Find the Singing Ridge by heading south through the Scalewing Shelf. Enter and slay their brood mother, Dreadwing .",starts={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},ends={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},coords={x=0.752,y=0.608,source="quest_giver",zoneID=3522},questType="standard"},
[10846] = {id=10846,name="Understanding the Mok'Nathal",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Leoroxx looks you in the eye with the kind of stare that chills your soul.> You come to the Mok'Nathal, but you do not understand us. You do not understand our struggle to survive. If you would understand us, then you will have to endure a taste of that struggle. To the south are the Vekh 'nir arakkoa. They have enslaved a group of ogres in the caverns known as Trogma's Claim and their leader, Vekh is in there. Slay him!",starts={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},ends={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},coords={x=0.752,y=0.608,source="quest_giver",zoneID=3522},questType="standard"},
[10847] = {id=10847,name="The Eyes of Skettis",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Doom harkens from the cliffs of Skettis. My people, the arakkoa, face a fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. Through A'dal I have learned of the Light and of redemption. Terokk watches his colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me look through the eyes of Skettis.",starts={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},ends={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},coords={x=0.526,y=0.208,source="quest_giver",zoneID=3703},questType="standard"},
[10848] = {id=10848,name="Veil Rhaze: Unliving Evil",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Veil Rhaze was a particularly wicked colony of Skettis. Despite the village's eradication by the Auchindoun disaster, Terokk's influence remained in the maligned spirits there. Travel west to Veil Rhaze and slay those murderous wretches. You'll find them to the west of the Shadow Tomb, on the border of Bone Wastes and Terokkar Forest . This will be our first blow against Terokk and the guardians of Skettis.",starts={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},ends={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},coords={x=0.374,y=0.514,source="quest_giver",zoneID=3519},questType="standard"},
[10849] = {id=10849,name="Seek Out Kirrik",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Other arakkoa took part in the betrayal of Terokk. Kirrik recognized Terokk as a charlatan, not a prophet. The only prophecy Terokk envisioned was the doom borne of his own bidding. It was Kirrik who led us bravely from Skettis. After our pilgrimage to Shattrath, Kirrik traveled to the colonies in search of others. This missive tells of what the Eyes have seen. Kirrik must be told! Follow the road south out of Shattrath to the Bone Wastes and look for the caravan.",starts={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},ends={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},coords={x=0.526,y=0.208,source="quest_giver",zoneID=3703},questType="standard"},
[10850] = {id=10850,name="Nether Gas In a Fel Fire Engine",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3522,starts={{npcID=22293,x=0.38,y=0.256,zoneID=3523}},ends={{npcID=22293,x=0.38,y=0.256,zoneID=3523}},coords={x=0.38,y=0.256,source="quest_giver",zoneID=3523},questType="standard"},
[10851] = {id=10851,name="The Totems of My Enemy",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="There is the right way to honor one's ancestors, and there is the wrong way. The Bladespire ogres carry totems with them, but they do not use them to show their respect. Instead, they seek to use them to manipulate and control. We should steal their totems because they are unworthy! We will then put them to better use. Go to the Bladespire Outpost to the west, just southwest of the Razor Ridge. Slay the Bladespire mystics and crushers, and take their totems from them!",starts={{npcID=22312,x=0.748,y=0.604,zoneID=3522}},ends={{npcID=22312,x=0.748,y=0.604,zoneID=3522}},coords={x=0.748,y=0.604,source="quest_giver",zoneID=3522},questType="standard"},
[10852] = {id=10852,name="Missing Friends",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="We broke down here because some guys came in the night and made a lot of noise. It was scary. I don't know when we are going to get moving again. Some of my friends are missing though. I don't know where they are. I think those scary bird men took them away to the northwest. They probably are all locked up in cages and stuff. If you find them that would be great. I'm kind of worried about them.",starts={{npcID=22365,x=0.376,y=0.514,zoneID=3519}},ends={{npcID=22365,x=0.376,y=0.514,zoneID=3519}},coords={x=0.376,y=0.514,source="quest_giver",zoneID=3519},questType="standard"},
[10853] = {id=10853,name="Spirit Calling",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The spirits of the nether drakes in the Singing Ridge are in need of liberation. The nether drakes were not always nether drakes. They used to be black drakes. But then, with the destruction of this world, a wave of nether energy washed over everything and had the side-effect of changing the drakeling eggs. Now they are all twisted versions of their former selves. We must help them to find peace. Do this by slaying a drake near to the spirit calling totem, and then take its spirit from it.",starts={{npcID=22312,x=0.748,y=0.604,zoneID=3522}},ends={{npcID=22312,x=0.748,y=0.604,zoneID=3522}},coords={x=0.748,y=0.604,source="quest_giver",zoneID=3522},questType="standard"},
[10854] = {id=10854,name="The Force of Neltharaku",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Take this enchanted nethervine crystal and make your way back to Dragonmaw Fortress. Once there, seek out the enslaved drakes and invoke the magic of the nethervine crystal. My own energies will pour forth, causing the drakes to break free from the bond of their captors. When you see that the drake has broken free, help it defeat its captor! It will most assuredly be weak from the imprisonment. Release all that you can find and return to me, .",starts={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},ends={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},coords={x=0.618,y=0.6,source="quest_giver",zoneID=3520},questType="standard"},
[10855] = {id=10855,name="Fel Reavers, No Thanks!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3522,description="Ah, yes - the fel reaver! Certainly the Legion's most terrible mechanical creation. There are no less than three of these abominations aimed at the Stormspire. Fortunately for us, they are not active yet. This affords us the possibility of dealing with them through sabotage instead of brute force. Obtain condensed nether gas from the gan'arg at Forge Base: Oblivion and fill a nearby fel reaver's fuel tank with it. I've a feeling its engine won't handle it too well.",starts={{npcID=20471,x=0.446,y=0.348,zoneID=3523}},ends={{npcID=20471,x=0.446,y=0.348,zoneID=3523}},coords={x=0.446,y=0.348,source="quest_giver",zoneID=3523},questType="standard"},
[10856] = {id=10856,name="The Best Defense",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Brave acts of industrial sabotage will only get us so far, . Just as Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion's teleportation devices are located. I want you to go in there and put a dent in their numbers. They must have a full regiment of wrathbringers by now and we just can't allow that.",starts={{npcID=20471,x=0.446,y=0.348,zoneID=3523}},ends={{npcID=20471,x=0.446,y=0.348,zoneID=3523}},coords={x=0.446,y=0.348,source="quest_giver",zoneID=3523},questType="standard"},
[10857] = {id=10857,name="Teleport This!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="As fun as killing demons might be, it does us little good when the Legion can keep using its teleporters to replace anything we kill. Unfortunately, I don't have any high-powered explosives handy... but the mo'arg that maintain the teleporters do. Take this rod... I've tuned its powers to interfere with mo'arg brain frequencies. Return to Forge Base: Gehenna and use it on any mo'arg you see. You won't have long, but you'll be able to use their demolition charges on the nearby teleporters.",starts={{npcID=20471,x=0.446,y=0.348,zoneID=3523}},ends={{npcID=20471,x=0.446,y=0.348,zoneID=3523}},coords={x=0.446,y=0.348,source="quest_giver",zoneID=3523},questType="standard"},
[10858] = {id=10858,name="Karynaku",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="It shames me to ask for your assistance once more, , but you are my flight's only hope. Without my mate, the netherwing brood may die out completely. Make your way to the top of Dragonmaw Fortress and find Karynaku . We will be flying overhead. Should a break appear in their defenses, the might of the netherwing will swoop down to assist you.",starts={{npcID=21657,x=0.618,y=0.6,zoneID=3520}},ends={{npcID=22112,x=0.698,y=0.614,zoneID=3520}},coords={x=0.618,y=0.6,source="quest_giver",zoneID=3520},questType="group"},
[10859] = {id=10859,name="Gather the Orbs",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="The Razaani ethereals have strange devices that emit small, pink floating light orbs. They remind me of souls. They are not to be confused with the large yellow balls that break free of the ethereal when they die, these are something else entirely. I'd like for you to head north to Razaan's Landing and drop some totems, which will attract the pink light orbs. Bring them back to me so that I might determine exactly what they are.",starts={{npcID=22312,x=0.748,y=0.604,zoneID=3522}},ends={{npcID=22312,x=0.748,y=0.604,zoneID=3522}},coords={x=0.748,y=0.604,source="quest_giver",zoneID=3522},questType="standard"},
[10860] = {id=10860,name="Mok'Nathal Treats",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Hungry, ? The Great Spirit helps those that help themselves. If you want to earn a meal, I suggest that you listen up, because Braagor there isn't going to give you anything for free, nor as tasty! The raptors and scalewings of Razor Ridge and the Scalewing Shelf have everything that's needed for two of the most delicious dishes you'll ever taste. Bring me their raptor ribs and serpent flesh , and I'll make some of each for you. I may even teach you how to cook them up for yourself, if you hurry.",starts={{npcID=21088,x=0.76,y=0.602,zoneID=3522}},ends={{npcID=21088,x=0.76,y=0.602,zoneID=3522}},coords={x=0.76,y=0.602,source="quest_giver",zoneID=3522},questType="standard"},
[10861] = {id=10861,name="Veil Lithic: Preemptive Strike",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="In the wretched colony to the southwest known as Veil Lithic, Terokk's minions are attempting to befoul their avian brethren before they hatch. The dark sorcerers of Lithic encase eggs in a shadowy curse. When the hatchlings emerge, they mindlessly serve Terrok. Travel to Veil Lithic and prematurely break the eggs before the curse has time to seep in. Even if you are too late, you can put down the tainted ones. Remember, the Light shines brightest in the darkness.",starts={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},ends={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},coords={x=0.374,y=0.514,source="quest_giver",zoneID=3519},questType="standard"},
[10862] = {id=10862,name="Surrender to the Horde",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3703,description="The cowardly arakkoa attack us daily. They ambush our hunters and sometimes even raid inside our walls. We kill them when we can, but their magic is strong and they often escape our warbands. I have learned that some arakkoa claim to be friendly with the Horde. They live in Shattrath City to the northwest. Rilak the Redeemed is their leader. Search for him in the Lower City, and when you find him, demand his surrender.",starts={{npcID=18386,x=0.488,y=0.446,zoneID=3519}},ends={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},coords={x=0.488,y=0.446,source="quest_giver",zoneID=3519},questType="standard"},
[10863] = {id=10863,name="Secrets of the Arakkoa",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3703,description="Out here on the frontier we have to deal with the arakkoa every day. They strike at us when they please, raiding our supply lines and killing our scouts. Yet we know very little about these enigmatic creatures. I have received news that northwest of here in Shattrath City there are arakkoa who are not hostile. They might be willing to share the secrets of their race. Rilak the Redeemed is their leader. He resides in the northern part of the Lower City.",starts={{npcID=15991,x=0.576,y=0.56,zoneID=3519}},ends={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},coords={x=0.576,y=0.56,source="quest_giver",zoneID=3519},questType="standard"},
[10864] = {id=10864,name="A Burden of Souls",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="I have a device, the Demoniac Scryer, that can analyze fel magic. I would have you use the Scryer, but first... you must appease it. The Scryer, you see, has trapped within it a creature of vast intelligence and its needs are, shall we say, quite eccentric. To appease the Scryer, you must kill orcs. Specifically, they must be Shattered Hand orcs -- the Scryer demands their souls. Return to me when the souls are reaped. You will find the orcs north, and south, and surrounding... Hellfire Citadel.",starts={{npcID=16588,x=0.522,y=0.364,zoneID=3483}},ends={{npcID=16588,x=0.522,y=0.364,zoneID=3483}},coords={x=0.522,y=0.364,source="quest_giver",zoneID=3483},questType="standard"},
[10865] = {id=10865,name="Inform Leoroxx!",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Quickly, you must inform Leoroxx of what is transpiring up at Razaan's Landing! Those orbs were comprised of souls, some of them Mok'Nathal!",starts={{npcID=22312,x=0.748,y=0.604,zoneID=3522}},ends={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},coords={x=0.748,y=0.604,source="quest_giver",zoneID=3522},questType="standard"},
[10866] = {id=10866,name="Zuluhed the Whacked",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will. And this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key! Know this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?",starts={{npcID=22112,x=0.698,y=0.614,zoneID=3520}},ends={{npcID=22112,x=0.698,y=0.614,zoneID=3520}},coords={x=0.698,y=0.614,source="quest_giver",zoneID=3520},questType="group"},
[10867] = {id=10867,name="There Can Be Only One Response",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="There can be only one response to this... this, DEFILEMENT of the souls of our ancestors! , if you would aid us to restore the souls of our honored dead to their rightful place, go back to Razaan's Landing. Go back up there and kill the razaani until their leader, Nexus-Prince Razaan shows his cowardly face. Kill him and get those souls back, and then give them over to Spiritcaller Dohgar !",starts={{npcID=22004,x=0.752,y=0.608,zoneID=3522}},ends={{npcID=22312,x=0.748,y=0.604,zoneID=3522}},coords={x=0.752,y=0.608,source="quest_giver",zoneID=3522},questType="standard"},
[10868] = {id=10868,name="Arakkoa War Path",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3519,description="The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could charge out to meet them in numbers. They use their summoning circles to rescue their warriors from certain death, but they cannot run from us if we attack their homes. Veil Reskk and Veil Shienor lie to the north and northeast. Find these arakkoa nests and kill as many as you can.",starts={{npcID=18712,x=0.488,y=0.446,zoneID=3519}},ends={{npcID=18712,x=0.488,y=0.446,zoneID=3519}},coords={x=0.488,y=0.446,source="quest_giver",zoneID=3519},questType="standard"},
[10869] = {id=10869,name="Thin the Flock",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3519,description="The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could marshal our soldiers. Veil Reskk and Veil Shienor lie to the north and northwest. Find these arakkoa nests and kill as many as you can. They may not fear us, but at least we can thin their numbers.",starts={{npcID=18713,x=0.574,y=0.556,zoneID=3519}},ends={{npcID=18713,x=0.574,y=0.556,zoneID=3519}},coords={x=0.574,y=0.556,source="quest_giver",zoneID=3519},questType="standard"},
[10870] = {id=10870,name="Ally of the Netherwing",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Allow me to return you to Mordenai . I am certain that he wishes to see you once more.",starts={{npcID=22112,x=0.698,y=0.614,zoneID=3520}},ends={{npcID=22113,x=0.594,y=0.586,zoneID=3520}},coords={x=0.698,y=0.614,source="quest_giver",zoneID=3520},questType="standard"},
[10873] = {id=10873,name="Taken in the Night",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Our small outpost is under constant attack. Several nights ago, we were raided by the spiders of Netherweb Ridge, on the southeastern edge of the Bone Wastes. They poisoned many of our people, wrapped them in webs and carried them away. Some of our warriors took up arms and with little preparation pursued the spiders. We have not seen the captives or our hunting parties since. We hope that some may still be alive, perhaps imprisoned by the spiders. Our numbers are few. Will you search for our people?",starts={{npcID=22364,x=0.314,y=0.756,zoneID=3519}},ends={{npcID=22364,x=0.314,y=0.756,zoneID=3519}},coords={x=0.314,y=0.756,source="quest_giver",zoneID=3519},questType="standard"},
[10874] = {id=10874,name="Veil Shalas: Signal Fires",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Terokk's perch, Skettis, looms above the Bone Wastes to the east. At the base of Skettis lies Veil Shalas, the most formidable of Terokk's colonies. It is through the stronghold of Veil Shalas that Terokk's forward sages wage war against the Light. The evil-doers of Shalas communicate with their master using a complex system of magical signal fires. Travel to the east, , and extinguish the fires. Once Veil Shalas is silenced, we can begin to plot the fall of Skettis. But I get ahead of myself.",starts={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},ends={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},coords={x=0.374,y=0.514,source="quest_giver",zoneID=3519},questType="standard"},
[10875] = {id=10875,name="Report to Nazgrel",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description=", during your foray with the Demoniac Scryer, I sent word of your exploits against the fel orcs. Nazgrel , our illustrious leader in Thrallmar, wishes to speak with you. I believe he has a bloody mission in mind...",starts={{npcID=16588,x=0.522,y=0.364,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.522,y=0.364,source="quest_giver",zoneID=3483},questType="standard"},
[10876] = {id=10876,name="The Foot of the Citadel",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3483,description="Force-Commander Gorax is training Shattered Hand captains at the base of Hellfire Citadel, honing them to a bloody razor's edge. You must kill him, , for his loss would be a mighty blow to the fel orcs. However, that is not all you must do. Take this banner. Place it atop Gorax's corpse. Gorax's commander, the Hand of Kargath, must answer your challenge if he has even a drop of true orc blood within him! His head, the head of the hand of Kargath , is what I seek.",starts={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},coords={x=0.55,y=0.36,source="quest_giver",zoneID=3483},questType="standard"},
[10877] = {id=10877,name="The Dread Relic",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Long ago a caravan went to Auchindoun with a mission to take a Dread Relic from the ancient tombs beneath the necropolis. They fled, but the relic was their undoing. The relic is evil and it summons evil when touched. Their caravan was destroyed somewhere to the east. This dark artifact is the key to a terrible plan to defeat Teribus the Cursed, a creature that flies over the Bone Wastes. Help me if you wish, but your life and even your soul will be at risk.",starts={{npcID=22456,x=0.31,y=0.764,zoneID=3519}},ends={{npcID=22456,x=0.31,y=0.764,zoneID=3519}},coords={x=0.31,y=0.764,source="quest_giver",zoneID=3519},questType="standard"},
[10878] = {id=10878,name="Before Darkness Falls",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="After our caravan fell prey to an attack by Shadow Council cabal cultists, scouts were sent to Shattrath to call for help. The guards think we're safe for now, but they underestimate these madmen. I, for one, am not looking forward to having my throat slit by some cabal initiate in the middle of the night. Do us all a favor and take the fight to them, before they come to us. You will find our attackers south of here, at Auchindoun's northern entrance.",starts={{npcID=22370,x=0.372,y=0.506,zoneID=3519}},ends={{npcID=22370,x=0.372,y=0.506,zoneID=3519}},coords={x=0.372,y=0.506,source="quest_giver",zoneID=3519},questType="standard"},
[10879] = {id=10879,name="The Skettis Offensive",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Skettis has waged war on us! Have you gathered enough strength to help with Shattrath's defense? Hold off the attackers!",starts={{npcID=22373,x=0.52,y=0.206,zoneID=3703}},ends={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},coords={x=0.52,y=0.206,source="quest_giver",zoneID=3703},questType="standard"},
[10880] = {id=10880,name="Cabal Orders",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="This message bears a dark seal and though the language seems somewhat familiar, it appears to be encoded. Perhaps someone at the Refugee Caravan will know something about it.",ends={{npcID=22370,x=0.372,y=0.506,zoneID=3519}},questType="standard"},
[10881] = {id=10881,name="The Shadow Tomb",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Many believe it was the Shadow Council that caused the explosion that tore Auchindoun apart. It is rumored they awoke a great evil inside. If that is true, then that evil must have turned against them. According to these orders, part of the Shadow Council is fleeing Auchindoun. They are using the Shadow Tomb to store powerful artifacts from Auchindoun. Three of these are sacred, for they belonged to the powerful patriarchs Arunen, K'alen and Atalor. I must ask you to retrieve them.",starts={{npcID=22370,x=0.372,y=0.506,zoneID=3519}},ends={{npcID=22370,x=0.372,y=0.506,zoneID=3519}},coords={x=0.372,y=0.506,source="quest_giver",zoneID=3519},questType="standard"},
[10883] = {id=10883,name="The Tempest Key",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3703,description="You have proven yourself capable of great feats, . Your discovery of the Cipher of Damnation and Kael'Thas' involvement is most important to our cause. Should Kael use the cipher, what little is left of this world may collapse. A'dal is convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. Those that prove their strength will be granted favor by the naaru. A'dal awaits...",starts={{npcID=18166,x=0.546,y=0.44,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.546,y=0.44,source="quest_giver",zoneID=3703},questType="standard"},
[10884] = {id=10884,name="Trial of the Naaru: Mercy",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3714,description="Four trials you must pass before you are deemed worthy by the naaru. Within the Shattered Halls of Hellfire Citadel are three of your people. They are held there by the merciless one, Kargath Bladefist. He seeks to execute them as a sign of his virility and power. You must save these prisoners before such an atrocity can come to pass. As proof of deed, bring me the unused axe of the executioner . It must not have a drop of blood on its blade!",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[10885] = {id=10885,name="Trial of the Naaru: Strength",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3789,description="Four trials you must pass before you are deemed worthy by the naaru. The trial of strength is divided in two. You must destroy the leader of the Coilfang Steamvaults, Warlord Kalithresh, and bring me his trident. Slay the extra-planar being known as Murmur, in the Shadow Labyrinth of Auchindoun, and bring me his essence. Do this and you will have passed the trial of strength.",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[10886] = {id=10886,name="Trial of the Naaru: Tenacity",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3848,description="Four trials you must pass before you are deemed worthy by the naaru. In our travels we have encountered many dangerous beings. Some of these beings we incarcerated and placed in what is now known as the Arcatraz of Tempest Keep. There is one prisoner, however, that is a victim of circumstance. A stowaway who was in the wrong naaru vessel at the wrong time. Venture to the Arcatraz and rescue the gnome, Millhouse Manastorm. Ensure his survival.",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[10887] = {id=10887,name="Escaping the Tomb",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="I appreciate your help, . I was certain I was going to be killed. Let's get out of here with a hurry. It won't be long before more cultists come after us.",starts={{npcID=22377,x=0.306,y=0.49,zoneID=3519}},ends={{npcID=22370,x=0.372,y=0.506,zoneID=3519}},coords={x=0.306,y=0.49,source="quest_giver",zoneID=3519},questType="standard"},
[10888] = {id=10888,name="Trial of the Naaru: Magtheridon",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3836,description="Four trials you must pass before you are deemed worthy by the naaru. Only one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon , deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!",ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},questType="raid"},
[10889] = {id=10889,name="Return to Shattrath",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Your actions, while brave, will surely rouse a vindictive response from Terokk. Hurry to Shattrath. Send word to Rilak!",starts={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},ends={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},coords={x=0.374,y=0.514,source="quest_giver",zoneID=3519},questType="standard"},
[10893] = {id=10893,name="Longtail is the Lynchpin",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="With the Blackwing wyrmcultists massing in the tunnel, we're hard pressed to deal with the situation. Quite frankly, they have the numbers. And while we've been able to take care of any of their people that get too close, the fact remains that if they attack in earnest, we're going to be overrun. The situation calls for someone to get through to the other end of the tunnel, and take out their leader, Draaca Longtail . Up for some fun?",starts={{npcID=22386,x=0.502,y=0.36,zoneID=3522}},ends={{npcID=22386,x=0.502,y=0.36,zoneID=3522}},coords={x=0.502,y=0.36,source="quest_giver",zoneID=3522},questType="standard"},
[10894] = {id=10894,name="Wyrmskull Watcher",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Hmm, I'm not certain what we should do. I'm not much of a military planner. Watcher Moonshade will know what to do. He's heading up our defensive efforts at the Wyrmskull Tunnel to the west at the end of Wyrmskull Bridge. We have a force out there just in case the cultists try anything funny. Please, take the note to him with all due haste.",starts={{npcID=22007,x=0.62,y=0.394,zoneID=3522}},ends={{npcID=22386,x=0.502,y=0.36,zoneID=3522}},coords={x=0.62,y=0.394,source="quest_giver",zoneID=3522},questType="standard"},
[10895] = {id=10895,name="Zeth'Gor Must Burn!",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="It's time to strike Zeth'Gor from the air! Our gryphon riders are ready for a sortie, . But they need someone on the ground to direct their fire. Are you ready for a covert mission? Take these smoke beacons into Zeth'Gor, the Bleeding Hollow stronghold to the west. They have four guard towers: one near their northern wall, one near their southern wall, one near their forge and another nestled in their foothills. Place a beacon underneath each of the towers and we'll fly in and bomb them!",starts={{npcID=19409,x=0.714,y=0.624,zoneID=3483}},ends={{npcID=19409,x=0.714,y=0.624,zoneID=3483}},coords={x=0.714,y=0.624,source="quest_giver",zoneID=3483},questType="standard"},
[10896] = {id=10896,name="The Infested Protectors",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="The trees of this land are ravaged by the power that was unleashed from Auchindoun. The foul magic that was unleashed blasted the land into the wastes you see all around. The trees that survived are now infested with wretched wood mites that crawl under their bark and gnaw at their flesh. Rotting forest-ragers and infested root-walkers are breeding grounds for the mites. They are found along the edge of the wood to the east. Destroy these creatures and then kill the mites that flee their husks.",starts={{npcID=22420,x=0.378,y=0.516,zoneID=3519}},ends={{npcID=22420,x=0.378,y=0.516,zoneID=3519}},coords={x=0.378,y=0.516,source="quest_giver",zoneID=3519},questType="standard"},
[10898] = {id=10898,name="Skywing",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="Skywing flutters around you. You get the feeling he wants you to follow him.",starts={{npcID=22424,x=0.538,y=0.722,zoneID=3519}},ends={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},coords={x=0.538,y=0.722,source="quest_giver",zoneID=3519},questType="standard"},
[10903] = {id=10903,name="Return to Honor Hold",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description=", while you were on your mission in Zeth'Gor, I received news of my commanding officer, Colonel Jules. He was stricken with a demonic corruption while fighting near the Gor'gaz Outpost, and his situation has grown very bad. You have made such great gains for us against the fel orcs. Your strength in battle is without question... is your spirit just as strong? Please, return to Honor Hold and speak with Klatu, in an upper room at the Honor Hold inn.",starts={{npcID=21133,x=0.708,y=0.634,zoneID=3483}},ends={{npcID=22430,x=0.542,y=0.636,zoneID=3483}},coords={x=0.708,y=0.634,source="quest_giver",zoneID=3483},questType="standard"},
[10904] = {id=10904,name="Harvesting the Fel Ammunition",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="We must shut down the Burning Legion's access to Death's Door, but first you're going to destroy their two warp-gates! The problem is, we can't even scratch one of those things, so you're going to need to use their own weapons against them. The death's might, death's watch, deathforge over-smiths and deathforge technicians carry the ammunition for the fel cannons. Normally it wouldn't affect any of them, but if you bring the cannonballs to me, I will imbue them with Nature's unbridled wrath!",starts={{npcID=22423,x=0.634,y=0.658,zoneID=3522}},ends={{npcID=22423,x=0.634,y=0.658,zoneID=3522}},coords={x=0.634,y=0.658,source="quest_giver",zoneID=3522},questType="standard"},
[10908] = {id=10908,name="Speak with Rilak the Redeemed",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="You look surprised to be talking to me. I do not blame you. My people, the arakkoa, deserve to be feared. Speak with Rilak the Redeemed in Shattrath City if you wish to know more. He can be found in the northern part of the Lower City, with the other outcasts of Skettis. And, , we will speak again.",starts={{npcID=22272,x=0.374,y=0.514,zoneID=3519}},ends={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},coords={x=0.374,y=0.514,source="quest_giver",zoneID=3519},questType="standard"},
[10909] = {id=10909,name="Fel Spirits",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Colonel Jules was cursed in a battle near the Gor'gaz Outpost, a haunt for Shattered Hand fel orcs. My master, Barada, works feverishly to cure the poor human, but he needs help. The Colonel's tormented spirit seeks peace, and his path to peace is, I fear, a path of vengeance. Take this anchorite relic to Gor'gaz Outpost. Place it upon the ground near Shattered Hand orcs and defeat them. This will release their fel spirits -- you must slay those fel spirits for Jules' own spirit's recovery.",starts={{npcID=22430,x=0.542,y=0.636,zoneID=3483}},ends={{npcID=22430,x=0.542,y=0.636,zoneID=3483}},coords={x=0.542,y=0.636,source="quest_giver",zoneID=3483},questType="standard"},
[10910] = {id=10910,name="Death's Door",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Now there is an even greater threat from the Burning Legion. To the south is a portal known as Death's Door, which opens upon the horrific world where the Legion breeds its deadly hounds. To get there, exit Evergrove by heading east up the ramp. Follow the path south, through the Bladed Gulch, Razaan's Landing, Razor Ridge and the Scalewing Shelf. Then, take the ramp down into the Vekhaar Stand and enter Death's Door through the tunnel, south of Mok'Nathal. Once there, use this druid signal .",starts={{npcID=22127,x=0.616,y=0.384,zoneID=3522}},ends={{npcID=22423,x=0.634,y=0.658,zoneID=3522}},coords={x=0.616,y=0.384,source="quest_giver",zoneID=3522},questType="standard"},
[10911] = {id=10911,name="Fire At Will!",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Now that the ammunition can affect the Burning Legion, it's time for you to use it. There are two warp-gates, which are used for teleportation and enhancement of the void terrors. One is in the south and the other in the north, and each is within range of a fel cannon. Use the naturalized ammunition to take control of each fel cannon and destroy the warp-gates. Attack the gate with artillery to begin, and be prepared to kill its defenders to keep the cannon alive if necessary.",starts={{npcID=22423,x=0.634,y=0.658,zoneID=3522}},ends={{npcID=22423,x=0.634,y=0.658,zoneID=3522}},coords={x=0.634,y=0.658,source="quest_giver",zoneID=3522},questType="standard"},
[10912] = {id=10912,name="The Hound-Master",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Baelmon the Hound-Master must die! He maintains the ritual that keeps the portal functioning. The Death's Door portal is located at the north end of the canyon. When you find it, you will find Baelmon. You're going to need help on this one, so take this wand. When you battle the Hound-Master, use it and a couple of my friends will come to your aid. After you have defeated Baelmon, return to Wildlord Antelarion . And, , thank you for all that you've gone through for us here.",starts={{npcID=22423,x=0.634,y=0.658,zoneID=3522}},ends={{npcID=22127,x=0.616,y=0.384,zoneID=3522}},coords={x=0.634,y=0.658,source="quest_giver",zoneID=3522},questType="standard"},
[10913] = {id=10913,name="An Improper Burial",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Is there nothing that can be done to stem the tide of corruption? My soldiers have been battling the Auchenai for days now with no end in sight. Each casualty, whether Auchenai or Sha'tar, is snatched from the battlefield - their souls lifted and taken to parts unknown. I will not have it! A proper burial is out of the question but those fiends will not have their souls! Take this torch and travel to the field of battle, directly east of here. Burn every corpse you see! We will not fuel their rituals.",starts={{npcID=22446,x=0.31,y=0.76,zoneID=3519}},ends={{npcID=22446,x=0.31,y=0.76,zoneID=3519}},coords={x=0.31,y=0.76,source="quest_giver",zoneID=3519},questType="standard"},
[10914] = {id=10914,name="A Hero Is Needed",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="It is not enough. A hero is needed. Our forces are overwhelmed as the Auchenai continue to grow in number. Commander Ra'vaj looks at you.> Will you be the hero? Return to the field of battle and strike at their soldiers. Keep them occupied so that my scouts can get behind their lines and see what they are creating.",starts={{npcID=22446,x=0.31,y=0.76,zoneID=3519}},ends={{npcID=22446,x=0.31,y=0.76,zoneID=3519}},coords={x=0.31,y=0.76,source="quest_giver",zoneID=3519},questType="standard"},
[10915] = {id=10915,name="The Fallen Exarch",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="They are feeding the souls they steal to a coffin that they have dragged out from the Auchenai Crypts. My scouts believe the contents of the coffin to contain the first exarch of the crypts. They seek to resurrect the ancient one! You must battle your way to the western side of Auchindoun and disturb the contents of that coffin before they feed it enough souls. Should you lose your way, follow the walking souls. Destroy whatever is inside that coffin!",starts={{npcID=22446,x=0.31,y=0.76,zoneID=3519}},ends={{npcID=22446,x=0.31,y=0.76,zoneID=3519}},coords={x=0.31,y=0.76,source="quest_giver",zoneID=3519},questType="standard"},
[10916] = {id=10916,name="Digging for Prayer Beads",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="Anchorite Barada plans to exorcise the corruption from Colonel Jules, and will require an assistant for the task. Such an assistant must be prepared... I am ashamed to admit that my prayer beads were lost in Honor Hold's courtyard. I believe the dog Fei Fei stole them and buried them, but I do not know where. If you speak with his master, Warrant Officer Tracy Proudwell, perhaps she will know where Fei Fei hides his stolen treasures.",starts={{npcID=22430,x=0.542,y=0.636,zoneID=3483}},ends={{npcID=22430,x=0.542,y=0.636,zoneID=3483}},coords={x=0.542,y=0.636,source="quest_giver",zoneID=3483},questType="standard"},
[10917] = {id=10917,name="The Outcast's Plight",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="As an outcast, I am marked for death by arakkoa loyal to the city of Skettis. I cannot leave these walls for fear of my life, but that doesn't mean I cannot strike at them in retaliation. I have a small cache of treasure that I'm willing to part with, should you help me strike back at my would-be assassins. Bring me feathers from the denizens of the various Veils of Terokkar as proof of their demise.",starts={{npcID=22429,x=0.522,y=0.164,zoneID=3703}},ends={{npcID=22429,x=0.522,y=0.164,zoneID=3703}},coords={x=0.522,y=0.164,source="quest_giver",zoneID=3703},questType="standard"},
[10918] = {id=10918,name="More Feathers",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,starts={{npcID=22429,x=0.522,y=0.164,zoneID=3703}},ends={{npcID=22429,x=0.522,y=0.164,zoneID=3703}},coords={x=0.522,y=0.164,source="quest_giver",zoneID=3703},questType="standard"},
[10919] = {id=10919,name="Fei Fei's Treat",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,starts={{npcID=20206,x=0.564,y=0.628,zoneID=3483}},ends={{npcID=20206,x=0.564,y=0.628,zoneID=3483}},coords={x=0.564,y=0.628,source="quest_giver",zoneID=3483},questType="standard"},
[10921] = {id=10921,name="Terokkarantula",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="You have slain many of the dreadfang widows but they will continue to spawn and soon they will strike at us again. Deep within Netherweb Ridge is the lair of the Terokkarantula , the brood-mother of these gruesome creatures. If we are to be safe, she must die.",starts={{npcID=22462,x=0.496,y=0.762,zoneID=3519}},ends={{npcID=22462,x=0.496,y=0.762,zoneID=3519}},coords={x=0.496,y=0.762,source="quest_giver",zoneID=3519},questType="standard"},
[10922] = {id=10922,name="Digging Through Bones",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Oy! You look like you can take care of yerself, . Me and the crew here are looking for a bodyguard to watch over us while we hit a dig site to the north. The pay is pretty good and all you gotta do is make sure no nasty creatures kill me or any of my employees. If you successfully make it back without any casualties, Dwarfowitz over there will pay ya.",starts={{npcID=22458,x=0.31,y=0.76,zoneID=3519}},ends={{npcID=22481,x=0.31,y=0.762,zoneID=3519}},coords={x=0.31,y=0.76,source="quest_giver",zoneID=3519},questType="standard"},
[10923] = {id=10923,name="Evil Draws Near",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Now you must use the Dread Relic in a foul necromantic ritual if you wish to challenge Teribus the Cursed . To the northeast, beyond Auchindoun, is the Writhing Mound, a place where necromancers gather. The auchenai death-speakers and doomsayers carry doom skulls that are laced with powerful necro-enchantments. If you collect enough skulls you can use their power along with the power of the Dread Relic to command Teribus to face you.",starts={{npcID=22456,x=0.31,y=0.764,zoneID=3519}},ends={{npcID=22456,x=0.31,y=0.764,zoneID=3519}},coords={x=0.31,y=0.764,source="quest_giver",zoneID=3519},questType="standard"},
[10924] = {id=10924,name="Bloody Imp-ossible!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="The blood of the warp chasers in this area is a powerful and rare reagent. It's one of my biggest sellers. Normally, I take my imp, Zeppit, out to help me gather it. Warp chaser blood is simply too caustic to be handled safely by you or I, but it doesn't bother Zeppit. Things are getting busier here at the shop, so if I send Zeppit with you, will you help gather the blood? Zeppit's attention tends to wander, so you'll need to be close to the chaser when it dies for Zeppit to do his work.",starts={{npcID=22479,x=0.664,y=0.672,zoneID=3523}},ends={{npcID=22479,x=0.664,y=0.672,zoneID=3523}},coords={x=0.664,y=0.672,source="quest_giver",zoneID=3523},questType="standard"},
[10926] = {id=10926,name="Return to Sha'tari Base Camp",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="We will not make it back on our own. The dreadfang poison is too strong. You must return to Sha'tari Base Camp for us. Scout Navrin will send a rescue party out to find us.",starts={{npcID=22462,x=0.496,y=0.762,zoneID=3519}},ends={{npcID=22364,x=0.314,y=0.756,zoneID=3519}},coords={x=0.496,y=0.762,source="quest_giver",zoneID=3519},questType="standard"},
[10927] = {id=10927,name="Killing the Crawlers",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="Commander Skyshadow wants this tunnel cleared out so we can expedite trade with the Harborage. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Commander Skyshadow at once!",starts={{npcID=22488,x=0.322,y=0.912,zoneID=3522}},ends={{npcID=21158,x=0.362,y=0.662,zoneID=3522}},coords={x=0.322,y=0.912,source="quest_giver",zoneID=3522},questType="standard"},
[10928] = {id=10928,name="Killing the Crawlers",level=20,requiredLevel=20,faction="horde",expansion=1,zoneID=3522,description="Tor'chunk Twoclaws wants this tunnel cleared out so we can expedite trade with Swamp Rat. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Tor'chunk Twoclaws at once!",starts={{npcID=22489,x=0.53,y=0.962,zoneID=3522}},ends={{npcID=21147,x=0.518,y=0.584,zoneID=3522}},coords={x=0.53,y=0.962,source="quest_giver",zoneID=3522},questType="standard"},
[10929] = {id=10929,name="Fumping",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="How would you like to do a little more work for the Explorers' League? These bone worms have us all quite intrigued. I've got a drum right here that you can use out in the Bone Wastes. Just bang on the damned thing and see what you get. If it's a worm, kill it and bring back the carcass for us to study. We'll need a good lot of carcasses to get a valid testing sample.",starts={{npcID=22481,x=0.31,y=0.762,zoneID=3519}},ends={{npcID=22481,x=0.31,y=0.762,zoneID=3519}},coords={x=0.31,y=0.762,source="quest_giver",zoneID=3519},questType="standard"},
[10930] = {id=10930,name="The Big Bone Worm",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="I was right! These carcasses you brought me belong to maturing worms. Do you know what that means? It means that somewhere out there is a big one! I think we can get it to come out if we can provide the right kind of food. Let's see... something big! Yes! I remember seeing clefthooves east of here on the other side of the Bone Wastes. Get out there and kill a clefthoof. Once it's dead, use the drums. Hopefully the big one will come up to feed. If you manage to kill it, bring me its organs!",starts={{npcID=22481,x=0.31,y=0.762,zoneID=3519}},ends={{npcID=22481,x=0.31,y=0.762,zoneID=3519}},coords={x=0.31,y=0.762,source="quest_giver",zoneID=3519},questType="standard"},
[10935] = {id=10935,name="The Exorcism of Colonel Jules",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description=", it is time to save Colonel Jules . His condition has worsened and Barada fears that, if we do not cleanse him of his corruption, he will be lost to us. Take the prayer beads you found and speak with Anchorite Barada to begin the ritual. Let no disruptions stop the ritual... and if all goes well, Colonel Jules will be saved. Speak with Jules when he is saved, then return to me.",starts={{npcID=22430,x=0.542,y=0.636,zoneID=3483}},ends={{npcID=22430,x=0.542,y=0.636,zoneID=3483}},coords={x=0.542,y=0.636,source="quest_giver",zoneID=3483},questType="standard"},
[10936] = {id=10936,name="Trollbane is Looking for You",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="While we were busy, a messenger was waiting out in the hall. I suppose he grew tired, or perhaps he simply ran away at the sight of Jules floating around the room. Either way, Force Commander Danath is looking for you. I suggest that you seek an audience with him inside the barracks as quickly as possible!",starts={{npcID=22430,x=0.542,y=0.636,zoneID=3483}},ends={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},coords={x=0.542,y=0.636,source="quest_giver",zoneID=3483},questType="standard"},
[10937] = {id=10937,name="Drill the Drillmaster",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3483,description="I'm receiving reports that the Shattered Hand fel orcs, out in front of Hellfire Citadel, are organizing for what looks like an all-out assault. No doubt, they're not happy about your successes against all of the clans. Get to the base of the citadel, where the Path of Glory ends. You'll find the fel orcs busy with their preparations, but you're going to catch them with their pants down. Eliminate the one that's in charge of that force. Kill Drillmaster Zurok !",starts={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},ends={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},coords={x=0.566,y=0.666,source="quest_giver",zoneID=3483},questType="standard"},
[10942] = {id=10942,name="Children's Week",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3703,description="One special little girl is going to be very happy to have you as a friend, even if it is for a short while. Take this whistle. With it, you will be able to call for the child that you have agreed to sponsor. It will only last for a limited time - not much longer than Children's Week itself, in fact. Please, , call upon your orphan. I know that she will be more than excited to meet you and have the opportunity to venture out of the city!",starts={{npcID=22819,x=0.748,y=0.478,zoneID=3703}},coords={x=0.748,y=0.478,source="quest_giver",zoneID=3703},questType="standard"},
[10943] = {id=10943,name="Children's Week",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3703,description="One special little girl is going to be very happy to have you as a friend, even if it is for a short while. Take this whistle. With it, you will be able to call for the child that you have agreed to sponsor. It will only last for a limited time - not much longer than Children's Week itself, in fact. Please, , call upon your orphan. I know that she will be more than excited to meet you and have the opportunity to venture out of the city!",starts={{npcID=22819,x=0.748,y=0.478,zoneID=3703}},coords={x=0.748,y=0.478,source="quest_giver",zoneID=3703},questType="standard"},
[10944] = {id=10944,name="The Secret Compromised",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3520,description="Thanks again, . I recognize your name. Akama has entrusted you with his plans and so I will trust you as well. The naga discovered I was working against Illidan and tried to get me to speak by torturing me. I did not tell them a thing - Akama himself taught me to master pain through meditation. Illidan asked the naga to bring me to him. He would have seen right through my flesh and into my soul's deepest secrets. Akama must be warned. Our plans are in jeopardy!",ends={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},questType="standard"},
[10945] = {id=10945,name="Hch'uu and the Mushroom People",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3521,description="I had a friend named Hch'uu . She told me that she ended up in the orphanage because she had to run away from an evil fungal giant and got lost. We had great fun until her people came and took her away last year. I think she said she was going to live at a place called Sporeggar. I'd like to go to see her and have a look at her mushroom village. The orphan matron told me that it is on the west side of Zangarmarsh, between the Sporewind and Marshlight lakes. Can we go? Can we go? Please?!",ends={{npcID=22823,x=0.192,y=0.512,zoneID=3521}},questType="standard"},
[10946] = {id=10946,name="Ruse of the Ashtongue",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3845,description="Olum's sacrifice was tremendous. I would never have asked him to give up his life myself. But it is done. If we're to lure Illidan back into a false sense of security, we need to do his bidding - at least for now. I command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted. You are to perform the deed that Illidan demands. Take this cowl; it is magical in nature. You will appear to be one of my men to any who see you slaying Kael's phoenix, Al'ar.",starts={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},ends={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},coords={x=0.58,y=0.482,source="quest_giver",zoneID=3520},questType="raid"},
[10947] = {id=10947,name="An Artifact From the Past",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3606,description="Illidan's attention is now on Kael'thas, thanks to you. The time has come to make our move. I've had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill. Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal. There might be a way to retrieve this artifact, however. Legend speaks of a place in Azeroth guarded by bronze dragons... a place where past and present meet. It is there you will find what we seek.",starts={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},ends={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},coords={x=0.58,y=0.482,source="quest_giver",zoneID=3520},questType="raid"},
[10948] = {id=10948,name="The Hostage Soul",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3703,description="You might wonder why I go to such lengths to hide my intentions. Why not throw my lot in openly with the naaru? My very essence - my soul - is held prisoner inside the Black Temple. Illidan could destroy me any moment... until now! This phylactery will allow me to regain control of my soul. The time has come, . I'll lead Maiev and my Deathsworn to Illidan's doorstep. Speak to A'dal and and tell him of our plan. If we strike together we'll break through Illidan's defenses.",starts={{npcID=21700,x=0.58,y=0.482,zoneID=3520}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.58,y=0.482,source="quest_giver",zoneID=3520},questType="standard"},
[10949] = {id=10949,name="Entry Into the Black Temple",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3520,description="A'dal shows you an image of a naaru outside of the Black Temple, fighting alongside draenei vindicators and blood elf magisters. You immediately understand that this is the distraction Akama is waiting for.>",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18528,x=0.652,y=0.44,zoneID=3520}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="standard"},
[10953] = {id=10953,name="Visit the Throne of the Elements",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3518,description="Have you heard of the Throne of the Elements? It's supposed to be this place in Nagrand where there are these powerful elementals. One day soon, I'm going to be a powerful mage, or maybe a warlock. I'm gonna have to learn about some of the elemental forces! Do you think maybe that we could go there? Ya know, it would be educational to go there. It's supposedly just north of Garadar, on the other side of Skysong Lake.",ends={{npcID=18072,x=0.606,y=0.222,zoneID=3518}},questType="standard"},
[10954] = {id=10954,name="Jheel is at Aeris Landing!",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3518,description="I miss my brother, Jheel . He's a couple of years older than me, so they let him start an apprenticeship with the ethereal in Nagrand. It sure would be nice to go visit him. He loves geology and stuff, so I bet he's having a great time. The orphan matron told me that he's training at a place called Aeris Landing in Nagrand. It's supposed to be along the road, far to the west of Telaar, and northwest of the great mountain, Oshu'gun.",ends={{npcID=22836,x=0.314,y=0.576,zoneID=3518}},questType="standard"},
[10956] = {id=10956,name="The Seat of the Naaru",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3557,description="Do you know anything about the naaru? They're these angelic beings that have been helping the draenei for a really long time. I've seen a bunch around Shattrath. They say that one naaru, O'ros , was with the Exodar when it traveled to your homeworld. I should like to see for myself. Can you take me there? I bet we could get there fast by using one of the portals inside the Temple of the Moon in Darnassus! When we get there, if you get lost, we could always just look at your map.",ends={{npcID=17538,x=0.576,y=0.412,zoneID=3557}},questType="standard"},
[10958] = {id=10958,name="Seek Out the Ashtongue",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3959,description="Xi'ri , your mind becomes focused and your will determined. Your work here is not done; you must go inside the Black Temple and find Akama's followers.>",starts={{npcID=18528,x=0.652,y=0.44,zoneID=3520}},coords={x=0.652,y=0.44,source="quest_giver",zoneID=3520},questType="raid"},
[10966] = {id=10966,name="Back to the Orphanage",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3703,description="Darn it all! I guess it's time to go back to the orphanage at Shattrath City. I've had such a great time. You're the best person in all of the worlds, ! You're my big now! I'm going to miss you so much! When I grow up, I'm going to be just like you!!!",ends={{npcID=22819,x=0.748,y=0.478,zoneID=3703}},questType="standard"},
[10967] = {id=10967,name="Back to the Orphanage",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3703,description="Darn it all! I guess it's time to go back to the orphanage at Shattrath City. I've had such a great time. You're the best person in all of the worlds, ! You're my big now! I'm going to miss you so much!!!",ends={{npcID=22819,x=0.748,y=0.478,zoneID=3703}},questType="standard"},
[10968] = {id=10968,name="Call on the Farseer",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3557,description="I am sensing something very special about this child indeed. You should take her to visit Farseer Nobundo , here in the Exodar. I believe that he has been expecting the two of you. Look for Nobundo upon the highest terrace in the Crystal Hall.",starts={{npcID=17538,x=0.576,y=0.412,zoneID=3557}},ends={{npcID=17204,x=0.312,y=0.28,zoneID=3557}},coords={x=0.576,y=0.412,source="quest_giver",zoneID=3557},questType="standard"},
[10969] = {id=10969,name="Seek Out Ameer",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="It would seem that an outside force has taken an interest in the business practices of the Consortium. Five Consortium dealers have gone missing in the past two days. We have reason to believe the Ethereum are involved. If you are interested in assisting, seek out Commander Ameer at the Protectorate Watch Post. You will find the Protectorate Watch Post directly east of here on the next island.",starts={{npcID=22899,x=0.458,y=0.362,zoneID=3523}},ends={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},coords={x=0.458,y=0.362,source="quest_giver",zoneID=3523},questType="standard"},
[10970] = {id=10970,name="A Mission of Mercy",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="We salvaged this prison orb on our last scouting mission into Ethereum territory. We'd have never found it had it not been for the distress signal that it was faintly emitting. We think one of our own might be locked up in there but we have no way of opening the orb up without harming whatever is inside. What we know about the Ethereum is that any of their members could - at any given time - be carrying a key to unlock an orb. Retrieve one and return so that we may uncover the mysteries of this orb.",starts={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},ends={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},coords={x=0.594,y=0.322,source="quest_giver",zoneID=3523},questType="standard"},
[10971] = {id=10971,name="Ethereum Secrets",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I found this prisoner I.D. tag with the remains of the fallen vanguard. I can only assume that all of their prisoners are tagged in the same manner. I'm going to start cataloguing the tags in hopes of making sense of their penal system. If in your adventures you find more Ethereum prison keys, you can use them to open the Ethereum prisons at the Ethereum Staging Grounds - directly south of here. Bring me back any and all I.D. tags that you find.",starts={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},ends={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},coords={x=0.594,y=0.322,source="quest_giver",zoneID=3523},questType="standard"},
[10972] = {id=10972,name="Ethereum Prisoner I.D. Catalogue",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I am in need of more I.D tags, . What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations! Once this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.",ends={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},questType="standard"},
[10973] = {id=10973,name="A Thousand Worlds",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="I have cracked the code! Each tag is broken up into several segments. The front side of the tag is always the same and states: \"A Thousand Worlds...\" I am unsure as to the meaning of this phrase but it sounds insidious. On the back side of the tag are the vital statistics. The first set of runes indicates location and the second indicates prisoner type. Furthermore, it would seem that the keys can be combined to form a special key that accesses another prison type. Now I just need more keys...",starts={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},ends={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},coords={x=0.594,y=0.322,source="quest_giver",zoneID=3523},questType="standard"},
[10974] = {id=10974,name="Stasis Chambers of Bash'ir",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3522,description="The Ethereum have a settlement on the northernmost shelf of Blade's Edge Mountains known as Bash'ir's Landing. According to the key tablet, much larger versions of the prisons are kept at Bash'ir's. It should also be noted that the Ethereum refer to those prisons as stasis chambers. The key tablet grants access to a very specific stasis chamber at the landing known as Stasis Chamber Alpha. Take the key and investigate. My image will be awaiting your return at Bash'ir's Landing. Speak to me there.",starts={{npcID=20448,x=0.594,y=0.322,zoneID=3523}},ends={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},coords={x=0.594,y=0.322,source="quest_giver",zoneID=3523},questType="standard"},
[10975] = {id=10975,name="Purging the Chambers of Bash'ir",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3522,starts={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},ends={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},coords={x=0.528,y=0.15,source="quest_giver",zoneID=3522},questType="standard"},
[10976] = {id=10976,name="The Mark of the Nexus-King",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3522,description="What I must now know is what the Ethereum have held inside the Mana-Tombs of Auchindoun. In your battles against the beasts of the stasis chambers of Bash'ir you may run across an item known as the Mark of the Nexus-King . Should you find such an item, return it to me immediately! It is the final piece in crafting a key that will allow access to the stasis chamber inside the Mana-Tombs.",starts={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},ends={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},coords={x=0.528,y=0.15,source="quest_giver",zoneID=3522},questType="standard"},
[10977] = {id=10977,name="Stasis Chambers of the Mana-Tombs",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3792,description="The Mark of the Nexus-King that you recovered has allowed me to forge a new key for the stasis chambers found inside the Mana-Tombs . According to the glyphs on the mark, two exist: one near the front and one near Nexus-Prince Shaffar. This key that I am about to give you will open the stasis chamber near the front. I want you to go to the Mana-Tombs of Auchindoun and open the Mana-Tombs Stasis Chamber.",starts={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},ends={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},coords={x=0.528,y=0.15,source="quest_giver",zoneID=3522},questType="dungeon"},
[10981] = {id=10981,name="Nexus-Prince Shaffar's Personal Chamber",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3522,starts={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},ends={{npcID=22919,x=0.528,y=0.15,zoneID=3522}},coords={x=0.528,y=0.15,source="quest_giver",zoneID=3522},questType="dungeon"},
[10982] = {id=10982,name="The Eye of Haramad",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3522,mapID=105,starts={{npcID=22919,x=0.528,y=0.15,mapID=105}},ends={{npcID=22919,x=0.528,y=0.15,mapID=105}},coords={x=0.528,y=0.15,source="quest_giver",mapID=105},questType="standard"},
[10983] = {id=10983,name="Mog'dorg the Wizened",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Mog'dorg wise! Him send Grok to city, look for help. Bloodmaul clan need help. Mog'dorg say, send powerful little ones to him at Blade's Edge Mountains . Him stand on tower at Circle of Blood. Mog'dorg wise!",starts={{npcID=22940,x=0.65,y=0.684,zoneID=3703}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.65,y=0.684,source="quest_giver",zoneID=3703},questType="standard"},
[10984] = {id=10984,name="Speak with the Ogre",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3703,description="V'eru 's voice fills your mind with crystalline tone and clarity.> There is an ogre down in the Lower City, pleading for the assistance of passersby. They have all turned a deaf ear upon his plight. Do you think you might aid him? His name is Grok , and he is sitting near the merchants to the southeast. Thank you, .",starts={{npcID=22497,x=0.564,y=0.492,zoneID=3703}},ends={{npcID=22940,x=0.65,y=0.684,zoneID=3703}},coords={x=0.564,y=0.492,source="quest_giver",zoneID=3703},questType="standard"},
[10985] = {id=10985,name="A Distraction for Akama",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3520,description="Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders. Xi'ri 's army is ready to push Illidan's forces back and create a distraction for Akama. The naaru awaits your request to begin the attack.>",starts={{npcID=18528,x=0.652,y=0.44,zoneID=3520}},ends={{npcID=18528,x=0.652,y=0.44,zoneID=3520}},coords={x=0.652,y=0.44,source="quest_giver",zoneID=3520},questType="standard"},
[10989] = {id=10989,name="Mog'dorg the Wizened",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Mog'dorg the Wizened waits for you at top of da tower. He tells me to look for a just like you. You go speak with him about smart things. Go now, but don't tell no one. It's a secret!",starts={{npcID=22995,x=0.554,y=0.452,zoneID=3522}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.554,y=0.452,source="quest_giver",zoneID=3522},questType="standard"},
[10995] = {id=10995,name="Grulloc Has Two Skulls",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="To the east, at the terminus of Dragons' End, is the Cursed Hollow. Therein, Grulloc, son of Gruul, plots his dimwitted schemes. I heard that one of his possessions was stolen from him through trickery. Was that you? Unfortunate that he was not slain in the process. If we are to regain our freedom, I would have you take his most prized possession, a dragon skull from when he rejoiced in his father's slaying of the black dragonflight. The only way you'll get the skull is to vanquish him.",starts={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.554,y=0.448,source="quest_giver",zoneID=3522},questType="standard"},
[10996] = {id=10996,name="Maggoc's Treasure Chest",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="On the Razor Ridge, above and to the southeast, Maggoc patrols. His father assigned him as the warden of the eastern mountain range, and he revels in terrorizing any creature that gets in his way. As a son of Gruul, he must be done away with if my clan is to survive. That's where you come in. Maggoc carries a treasure chest with him at all times. Prove to me that he has been slain by bringing me his precious chest. Feel free to keep whatever you find within it.",starts={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.554,y=0.448,source="quest_giver",zoneID=3522},questType="standard"},
[10997] = {id=10997,name="Even Gronn Have Standards",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Are you familiar with Shattrath City, ? Above it to the northwest is a place called the Barrier Hills, which you can only get to upon a flying mount. One of Gruul's sons, Slaag, exiled himself and took control of the Gordunni ogres that reside there. Even at such a distance, we cannot afford to leave him in peace, lest he return when the rest of his brothers have been slain. , you must travel there, and bring back his standard as proof that he has been dealt with.",starts={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.554,y=0.448,source="quest_giver",zoneID=3522},questType="standard"},
[10998] = {id=10998,name="Grim(oire) Business",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="There is one more gronn to be slain: Skulloc Soulgrinder. He keeps himself hidden away, but there is a way to coax him forth. He was trained by an ogre warlock known as Vim'gol the Vile, whose grimoire you must retrieve! Vim'gol must be summoned by standing within a fire ring at his circle. Find Vim'gol's Circle in the mountains, to the northeast, near the Broken Wilds.",starts={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.554,y=0.448,source="quest_giver",zoneID=3522},questType="standard"},
[11000] = {id=11000,name="Into the Soulgrinder",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="The grimoire is the key to Skulloc's downfall. Read aloud from the book at Soulgrinder's Barrow to initiate the ritual. An object known as the Soulgrinder will appear, as well as Skulloc's ghostly victims, who will try to destroy it. You must keep them from doing so long enough to force Skulloc fully into the world. Find the barrow by heading north through the Daggermaw Canyon on the other side of the Circle of Blood. It is on the right side before Gruul's Lair. Bring back Skulloc's soul .",starts={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.554,y=0.448,source="quest_giver",zoneID=3522},questType="standard"},
[11002] = {id=11002,name="The Fall of Magtheridon",level=30,requiredLevel=30,faction="alliance",expansion=1,zoneID=3836,description="The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Alliance. Return Magtheridon's head to Danath Trollbane at Honor Hold.",ends={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},questType="standard"},
[11003] = {id=11003,name="The Fall of Magtheridon",level=30,requiredLevel=30,faction="horde",expansion=1,zoneID=3836,description="The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Horde. Return Magtheridon's head to Nazgrel at Thrallmar.",ends={{npcID=3230,x=0.55,y=0.36,zoneID=3483}},questType="standard"},
[11004] = {id=11004,name="World of Shadows",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Sky Commander Adaris was seriously injured during a Skettis incursion. He's been in and out of consciousness since. I fear he has succumbed to a feverish delirium. During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa. He seems to believe it will allow him to see into a \"world of shadows\" where the arakkoa's true leaders dwell. I do not believe this nonsense for a second, but I fear he won't rest until I obtain such an elixir. Will you help?",starts={{npcID=23042,x=0.64,y=0.668,zoneID=3519}},ends={{npcID=23042,x=0.64,y=0.668,zoneID=3519}},coords={x=0.64,y=0.668,source="quest_giver",zoneID=3519},questType="standard"},
[11005] = {id=11005,name="Secrets of the Talonpriests",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Thank you for paying heed to my fevered rants. All along we had been trying to identify and destroy the Skettis chain of command; we had learned of three clerics known as the talonpriests, but we'd never seen them with our own two eyes. Now we know why. Talk to Severin to obtain more of the elixir he discovered. Use the elixir to find and kill the three talonpriests: Ishaal, Skizzik and Zellek. They're rumored to dwell in Veil Ala'rak, near the eastern shore of Blackwind Lake.",starts={{npcID=23038,x=0.64,y=0.668,zoneID=3519}},ends={{npcID=23038,x=0.64,y=0.668,zoneID=3519}},coords={x=0.64,y=0.668,source="quest_giver",zoneID=3519},questType="standard"},
[11006] = {id=11006,name="More Shadow Dust",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,starts={{npcID=23042,x=0.64,y=0.668,zoneID=3519}},ends={{npcID=23042,x=0.64,y=0.668,zoneID=3519}},coords={x=0.64,y=0.668,source="quest_giver",zoneID=3519},questType="standard"},
[11007] = {id=11007,name="Kael'thas and the Verdant Sphere",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3845,description="The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael'thas Sunstrider. What secrets could it hold? Perhaps A'dal in Shattrath City could make sense of the item.",ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},questType="standard"},
[11008] = {id=11008,name="Fires Over Skettis",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="You think you have what it takes to be part of the Skyguard? We'll have to see how you handle yerself in the air. The arakkoa are breeding a gargantuan variety of their attack pets and are using it against our scouts. I want you to take these blasting charges and use them to destroy hatcheries above the arakkoa's dwellings. Avoid the monstrous kaliri guarding the hatcheries. They'll knock you off your mount before you know what hit you.",starts={{npcID=23048,x=0.644,y=0.666,zoneID=3519}},ends={{npcID=23048,x=0.644,y=0.666,zoneID=3519}},coords={x=0.644,y=0.666,source="quest_giver",zoneID=3519},questType="standard"},
[11009] = {id=11009,name="Ogre Heaven",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Now that you have delivered us from bondage, we can begin the process of reunifying the clans. This will take some time; old grudges are difficult to overcome. But more pressing, you must go to Ogri'la in the heavens above to the west. You must defend it, and us, from those forces above that the gronn used to protect us from: ethereals, demons, and worst of all, the black dragonflight. When you find ogre heaven, seek out the wisdom of Chu'a'lor on how best to proceed.",starts={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},ends={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},coords={x=0.554,y=0.448,source="quest_giver",zoneID=3522},questType="standard"},
[11010] = {id=11010,name="Bombing Run",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="You have a flying mount... so what! You think you have what it takes to use it properly? Forge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la. With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business. You want to prove yourself? Take these bombs and knock out their ammo stacks. Just don't let them shoot you down, too!",starts={{npcID=23120,x=0.276,y=0.528,zoneID=3522}},ends={{npcID=23120,x=0.276,y=0.528,zoneID=3522}},coords={x=0.276,y=0.528,source="quest_giver",zoneID=3522},questType="standard"},
[11012] = {id=11012,name="Blood Oath of the Netherwing",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,mapID=104,starts={{npcID=22113,x=0.594,y=0.586,mapID=104}},ends={{npcID=22113,x=0.594,y=0.586,mapID=104}},coords={x=0.594,y=0.586,source="quest_giver",mapID=104},questType="standard"},
[11013] = {id=11013,name="In Service of the Illidari",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Netherwing Ledge... What was once a bastion of sanctuary for the Netherwing is now home to the Dragonmaw. While the orcs may have control of our territory, our magic there is still strong. Strong enough to cloak your true identity and allow you to infiltrate the ranks of Dragonmaw. I have prepared this letter for you to present to their leader, Overlord Mor'ghor . Fly headlong into the maw of our enemy and seek out Dragonmaw Base Camp to start your new life as a fel orc of Illidan Stormrage.",starts={{npcID=22113,x=0.594,y=0.586,zoneID=3520}},ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},coords={x=0.594,y=0.586,source="quest_giver",zoneID=3520},questType="standard"},
[11014] = {id=11014,name="Enter the Taskmaster",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Alright grunt, first things first. If you're gonna join my beloved Dragonmaw army, you'll need to work. Everyone works up here on the ledge. Get a job and don't screw it up and I'll see if there might be something more interesting for you to do later. Go talk to Taskmaster Varkule Dragonbreath . He's standin' in the middle of town. He'll assess your skills and assign work as he sees fit. Now get out of my face!",starts={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},ends={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},coords={x=0.662,y=0.856,source="quest_giver",zoneID=3520},questType="standard"},
[11015] = {id=11015,name="Netherwing Crystals",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="No good at nothin'? That's fine. Even lunkheads like you can be used around here. Just find creatures on the ledge and kill 'em. Sometimes they'll have nether crystals on their carcasses. Gather those and bring 'em back to me and I'll consider your work order for the day complete.",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11016] = {id=11016,name="Nethermine Flayer Hide",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="A skinner, eh? Well you'll find plenty to skin here! You gotta search for flayers around crystal formations. Take 'em down and take their hides. Sometimes they'll have a hide worth keepin'. Bring those to me.",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11017] = {id=11017,name="Netherdust Pollen",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="A flower picker?! Hilarious... Unfortunately, our mages and shaman need your services. The netherdust bushes that grow on this ledge have special pollen that is apparently very useful in their magical dealings. Bring me that stuff and I'll consider your work order complete.",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11018] = {id=11018,name="Nethercite Ore",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="A miner! An orc after my own heart! That's how Varkule got his start - minin'! There ain't nothin' better than getting down and dirty in the mines, is there? Now get out there and find those nethercite deposits. Strip 'em for all their worth and bring me back the ore.",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11019] = {id=11019,name="Your Friend On The Inside",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,mapID=104,starts={{npcID=23141,x=0.66,y=0.864,mapID=104}},ends={{npcID=23141,x=0.66,y=0.864,mapID=104}},coords={x=0.66,y=0.864,source="quest_giver",mapID=104},questType="standard"},
[11020] = {id=11020,name="A Slow Death",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The Dragonmaw have peons stationed at nearly every crystal formation up here. While the outright slaying of them would draw far too much unwanted attention to you, there is a way that we can thin their numbers and remain below the suspicious eyes of Mor'ghor. Venture into the wilds of Shadowmoon Valley and slay the tainted wildlife. Take from them their corrupt fel glands . Use those fel glands with this mutton that I'll give you near the peons. They'll take one bite and fall deathly ill!",starts={{npcID=23141,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23141,x=0.66,y=0.864,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11021] = {id=11021,name="Ishaal's Almanac",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="This mysterious tome was on Talonpriest Ishaal's body. It contains arcane symbols and charts of celestial bodies beyond your comprehension. All writing is in a language you don't understand; likely an ancient version of the arakkoa written tongue. Perhaps you should bring this to Sky Commander Adaris .",ends={{npcID=23038,x=0.64,y=0.668,zoneID=3519}},questType="standard"},
[11022] = {id=11022,name="Speak with Mog'dorg",level=20,requiredLevel=20,faction="alliance",expansion=1,zoneID=3522,description="! You speak with Mog'dorg the Wizened before you leave and go to Ogri'la!",starts={{npcID=23053,x=0.554,y=0.456,zoneID=3522}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.554,y=0.456,source="quest_giver",zoneID=3522},questType="standard"},
[11023] = {id=11023,name="Bomb Them Again!",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="We're still having problems with those flak cannons, . Don't get me wrong -- I think that you did an outstanding job the last time out -- but, that doesn't change the fact that those damned demons seem to be replenishing their ammo supplies faster than we can knock them out. And that means we're having a hell of a time getting our people through there, not to mention the risk those demons pose to Ogri'la. What do you say? Want to take another shot at it?",starts={{npcID=23120,x=0.276,y=0.528,zoneID=3522}},ends={{npcID=23120,x=0.276,y=0.528,zoneID=3522}},coords={x=0.276,y=0.528,source="quest_giver",zoneID=3522},questType="standard"},
[11024] = {id=11024,name="An Ally in Lower City",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3703,description="There is an arakkoa in Lower City by the name of Rilak... He can be trusted. Take the book... to him.",starts={{npcID=23038,x=0.64,y=0.668,zoneID=3519}},ends={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},coords={x=0.64,y=0.668,source="quest_giver",zoneID=3519},questType="standard"},
[11025] = {id=11025,name="The Crystals",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="When prepared correctly, the crystals of the mountains exhibit strange powers, such as the clarity of mind that we have found here in Ogri'la. All of the creatures atop the mountains covet the crystal shards and use them to further their own goals. An economy has even sprung up around them. To assist us, you must first learn about the Apexis shards . Bring me some. In addition to the creatures here having them, they can sometimes be found where the flayers dig at the larger crystals.",starts={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},ends={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},coords={x=0.288,y=0.574,source="quest_giver",zoneID=3522},questType="standard"},
[11026] = {id=11026,name="Banish the Demons",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="You've arrived at the perfect time, friend! We are in need of assistance. In return, you will receive something very rare, which will help us both in the end. We're not a violent ogre any longer, but the demons nearby threaten to overrun us and the Skyguard. The problem with demons is that, once killed, they come right back in new bodies! But, if you use this crystal to summon a banishing portal, when they die near it, their essences will be drawn in and banished back from whence they came!",starts={{npcID=23253,x=0.288,y=0.578,zoneID=3522}},ends={{npcID=23253,x=0.288,y=0.578,zoneID=3522}},coords={x=0.288,y=0.578,source="quest_giver",zoneID=3522},questType="standard"},
[11028] = {id=11028,name="Countdown to Doom",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="This almanac presages the return of Terokk, the most powerful and terrible Skettis king in arakkoa history. I always believed this to be the mere legend, . The return of the talonpriests and your recovery of this tome indicate otherwise. With each day, Terokk comes closer to returning to full strength. Your only chance is to bring him to our world prematurely. Return to Skettis and speak to Adaris about this. Let us hope he has the wisdom to do the right thing.",starts={{npcID=22292,x=0.526,y=0.208,zoneID=3703}},ends={{npcID=23038,x=0.64,y=0.668,zoneID=3519}},coords={x=0.526,y=0.208,source="quest_giver",zoneID=3703},questType="standard"},
[11029] = {id=11029,name="A Shabby Disguise",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Open the package, . It is a disguise. It doesn't look very convincing, does it? I craft them for ethereal smugglers in search of rare books. There is an arakkoa scribe who dwells in the central island in Skettis, Terokk's Rest; his name is Sahaak. He is old and nearly blind. Use the disguise to speak with him and obtain the book known as the Adversarial Bloodlines . Be careful, . The disguise won't fool the other arakkoa.",starts={{npcID=23306,x=0.642,y=0.668,zoneID=3519}},ends={{npcID=23306,x=0.642,y=0.668,zoneID=3519}},coords={x=0.642,y=0.668,source="quest_giver",zoneID=3519},questType="standard"},
[11030] = {id=11030,name="Our Boy Wants To Be A Skyguard Ranger",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description=", we've got a problem -- we have lots of sons. And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks. As a proud father, we want them to have every advantage for when they apply. So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons? You can't miss their green smoke. We think that they take ten apexis shards to make. We'd give you the shards, but we don't have any at the moment.",starts={{npcID=23316,x=0.284,y=0.576,zoneID=3522}},ends={{npcID=23316,x=0.284,y=0.576,zoneID=3522}},coords={x=0.284,y=0.576,source="quest_giver",zoneID=3522},questType="standard"},
[11035] = {id=11035,name="The Not-So-Friendly Skies...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="On the northeast edge of this island exists a dock used for the packaging and transport of Netherwing crystals and relics. Dragonmaw Transporters transport the goods from the dock to Dragonmaw Fortress while Dragonmaw Ascendants guard the ground from any would-be attackers. This leaves one opening for you to make a strike at the Dragonmaw: The Dragonmaw Skyway. Fly to the shattered islands of the Dragonmaw Skyway and ambush the transporters that use the route. Recover our stolen relics!",starts={{npcID=23141,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23141,x=0.66,y=0.864,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11036] = {id=11036,name="Out of This World Produce!",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3523,description="I'll be the first to admit I'm not quite sure what this order is for, but Rocket-Chief Fuselage 's instructions were very specific -- only the very best fruit, preserved to survive a long voyage and sealed against the elements. There were other specifications, zero-gravity this and low pressure that. I don't pretend to understand it, but the price is right, so he'll get his superfood. Bring this crate to him up at Area 52. After crossing into Netherstorm , keep following the road until you see the town.",starts={{npcID=19471,x=0.532,y=0.544,zoneID=3522}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.532,y=0.544,source="quest_giver",zoneID=3522},questType="standard"},
[11037] = {id=11037,name="A Strange Vision",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3523,description="I've had a most unusual vision, , and I don't know quite what to make of it. I've seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the product of magic. It will be unlike anything the people of Azeroth have ever achieved. You must seek out the people working on this, . Lend them your help, for without it, their efforts may yet fail.",starts={{npcID=23265,x=0.556,y=0.372,zoneID=3518}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.556,y=0.372,source="quest_giver",zoneID=3518},questType="standard"},
[11038] = {id=11038,name="Assist Exarch Orelis",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Not long ago, High Priestess Ishanah sent a small group of anchorites to Netherstorm, under the command of Exarch Orelis . They were to investigate the activities of Kael'thas and his minions, but we haven't received any reports of their findings yet. I worry that our presence in the area might not be strong enough to carry out the mission. I'm certain that the exarch could benefit from your knowledge and experience. Are you willing to travel to Area 52 and assist him?",starts={{npcID=23270,x=0.474,y=0.264,zoneID=3703},{npcID=23271,x=0.35,y=0.326,zoneID=3703}},ends={{npcID=19466,x=0.32,y=0.642,zoneID=3523}},coords={x=0.474,y=0.264,source="quest_giver",zoneID=3703},questType="standard"},
[11039] = {id=11039,name="Report to Spymaster Thalodien",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="Some time ago, Voren'thal dispatched a small team to Netherstorm to investigate the activities of Kael'thas. Our leader has the utmost confidence in Spymaster Thalodien and his compatriots, and has decided to honor his request for reinforcements. Thalodien's report was brief, but clear that he's encountered something of great importance. Report to him at Area 52 and assist him in any way possible, .",starts={{npcID=23272,x=0.446,y=0.762,zoneID=3703},{npcID=23273,x=0.606,y=0.632,zoneID=3703}},ends={{npcID=19468,x=0.32,y=0.64,zoneID=3523}},coords={x=0.446,y=0.762,source="quest_giver",zoneID=3703},questType="standard"},
[11040] = {id=11040,name="Parts for the Rocket-Chief",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3523,description="You can count on one hand the number of times I've collaborated with a goblin. We're far more likely to be in competition with them, but when I received Rocket-Chief Fuselage 's request, I just couldn't refuse him. This crate is full of parts I'm not using here, but that the rocket-chief might be able to put to use on his project. Would you be kind enough to deliver them if you're on your way to Area 52? Who knows, maybe some fine gnomish parts could keep his creation from exploding!",starts={{npcID=21112,x=0.606,y=0.69,zoneID=3522}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.606,y=0.69,source="quest_giver",zoneID=3522},questType="standard"},
[11041] = {id=11041,name="A Job Unfinished...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="In the name of our great master... For the glory of Illidan! By order of Overlord Mor'ghor , the great plateau of Netherwing Ledge is to be secured. With all Netherwing drakes captured or forced off of the land, rock flayers are running rampant and threatening crystal harvesting operations. Destroy them all, their den mother and her consort, Arvoar. Mor'ghor commands it!",ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},questType="group"},
[11042] = {id=11042,name="A Mystifying Vision",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3523,description="A strange vision haunts me, . I see a continuous cloud of smoke ascending toward the sky, left in the wake of a giant fire moving ever faster away. It is not a natural phenomenon, nor a creation of evil; that much I know. I have no knowledge of what it looks like, save that it is the product of the labor of many. Yet, without more hands, it may never come to be. Travel to Netherstorm , . Locate those responsible for this creation and offer them your aid.",starts={{npcID=23268,x=0.554,y=0.686,zoneID=3518}},ends={{npcID=19570,x=0.326,y=0.644,zoneID=3523}},coords={x=0.554,y=0.686,source="quest_giver",zoneID=3518},questType="standard"},
[11043] = {id=11043,name="Building a Better Gryphon",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="I've heard that the Wildhammer dwarves maintain a gryphon roost at their fortress down in southern Shadowmoon Valley . If you're going down there, would you speak to them on my behalf? I have some ideas on how to improve their gryphons! Why stop at armoring them when you could attach an altimeter, a rear view mirror, and rocket? Imagine how fast you could go with one of those babies strapped to your gryphon's back! I'll call it the TurboGryphon 8000!",starts={{npcID=21107,x=0.61,y=0.704,zoneID=3522}},ends={{npcID=20510,x=0.376,y=0.56,zoneID=3520}},coords={x=0.61,y=0.704,source="quest_giver",zoneID=3522},questType="standard"},
[11044] = {id=11044,name="Visions of Destruction",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="A vision of cataclysm often disturbs my rest -- a rain of green fire falling to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for weeks now, although I have only recently come to understand its meaning. To the far east, in Shadowmoon Valley , the Wildhammer dwarves endure constant attacks from the Burning Legion and numerous other foes. They fight bravely, but without relief, their enemies will triumph. Go to their side, . Help them in their fight.",starts={{npcID=23268,x=0.554,y=0.686,zoneID=3518}},ends={{npcID=21357,x=0.394,y=0.536,zoneID=3520}},coords={x=0.554,y=0.686,source="quest_giver",zoneID=3518},questType="standard"},
[11045] = {id=11045,name="Zorus the Judicator",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="The history of Shadowmoon Valley is a long and troubled one. Few delve into it for fear of breathing new life into the unspeakable atrocities that took place there. Not all are so timid, though. Zorus the Judicator searches for the truth about the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which he would welcome help, I'm sure. If you should venture into the valley, look for Zorus at Wildhammer Stronghold, in the central portion of the valley's southern region.",starts={{npcID=19678,x=0.646,y=0.702,zoneID=3703}},ends={{npcID=21774,x=0.366,y=0.554,zoneID=3520}},coords={x=0.646,y=0.702,source="quest_giver",zoneID=3703},questType="standard"},
[11046] = {id=11046,name="Chief Apothecary Hildagard",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="The history of Shadowmoon Valley is a long and troubled one. Few study it for fear of breathing new life into the unspeakable atrocities that took place there. Not all are so timid, though. Chief Apothecary Hildagard 's research delves into the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which she would welcome help, I'm sure. If your travels bring you there, seek Hildagard at Shadowmoon Village, in the northwestern reaches of the valley.",starts={{npcID=19678,x=0.646,y=0.702,zoneID=3703}},ends={{npcID=21772,x=0.298,y=0.276,zoneID=3520}},coords={x=0.646,y=0.702,source="quest_giver",zoneID=3703},questType="standard"},
[11047] = {id=11047,name="The Apprentice's Request",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="As an apprentice wind rider master, one of my tasks is to care for the beasts when they're not flying. The problem is that we have so few here, there's very little downtime for any of them. I'm afraid we'll work them all to death if we don't receive any replacements. There's a large stable down in Shadowmoon Village, in western Shadowmoon Valley . Dama Wildmane oversees the wind rider care and training there. Would you speak with her on our behalf and let her know about our situation?",starts={{npcID=23280,x=0.52,y=0.544,zoneID=3522}},ends={{npcID=20494,x=0.29,y=0.294,zoneID=3520}},coords={x=0.52,y=0.544,source="quest_giver",zoneID=3522},questType="standard"},
[11048] = {id=11048,name="Kroghan's Report",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="My original orders were to remain in Garadar for a short time, then continue on and report to Blood Guard Gulmok at Shadowmoon Village. What I've seen in my time here is that Garadar could benefit from a long term Horde liaison. I know that Blood Guard Gulmok needs all the troops he can get, but I know he'll understand that my mission here isn't yet complete. Travel to Shadowmoon Village, in northwestern Shadowmoon Valley , and inform Blood Guard Gulmok of my delayed arrival.",starts={{npcID=18090,x=0.554,y=0.374,zoneID=3518}},ends={{npcID=21359,x=0.304,y=0.324,zoneID=3520}},coords={x=0.554,y=0.374,source="quest_giver",zoneID=3518},questType="standard"},
[11049] = {id=11049,name="The Great Netherwing Egg Hunt",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Should you discover any Netherwing eggs while exploring, bring them to me. Be warned, a Netherwing egg is a rare discovery. Do not become frustrated if you cannot locate one. These Dragonmaw have been very thorough in collecting most of them and shipping them off to parts unknown. Eggs might be found on creatures of the island, near crystal formations, in the mines, or even inside a nethercite node or netherdust bush. Keep a low profile. We don't need Mor'ghor catching wind of your actions.",starts={{npcID=23141,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23141,x=0.66,y=0.864,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11050] = {id=11050,name="Accepting All Eggs",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,starts={{npcID=23141,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23141,x=0.66,y=0.864,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11051] = {id=11051,name="Banish More Demons",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="If we know the demons, and we do because we've studied them extensively, they're fast at work repairing any damage that has been done to their precious transporter. So, if you want a chance at another darkrune, take our banishing crystal back out there and eliminate more demons. Besides, you want to help us to lessen the threat that the demons pose, yes? We said \"chance\" because the process we use yields mixed results. You might get a darkrune, or you might get something else entirely.",starts={{npcID=23253,x=0.288,y=0.578,zoneID=3522}},ends={{npcID=23253,x=0.288,y=0.578,zoneID=3522}},coords={x=0.288,y=0.578,source="quest_giver",zoneID=3522},questType="standard"},
[11053] = {id=11053,name="Rise, Overseer!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Rare it is that a peon survives for as long as you have. Rarer still is when a peon rises from the dregs to attain a new rank. The Overlord has called for you, grunt. A new rank awaits, no doubt.",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11054] = {id=11054,name="Overseeing and You: Making the Right Choices",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,description="So you're the new overseer, eh? Well there's one thing any good overseer needs and that's the proper disciplinary weapon. Before you can go out there and knock some sense into these peons you need to have your \"piece.\" Each overseer has to gather the materials required to make their own \"piece\" and you'll be no different. I'll need knothide leather and the hardened hide of Tyrantus . You'll find Tyrantus in Eco-Dome Farfield, located in the northern reaches of Netherstorm.",starts={{npcID=23291,x=0.668,y=0.86,zoneID=3520}},ends={{npcID=23291,x=0.668,y=0.86,zoneID=3520}},coords={x=0.668,y=0.86,source="quest_giver",zoneID=3520},questType="standard"},
[11055] = {id=11055,name="The Booterang: A Cure For The Common Worthless Peon",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="This is your booterang . There are many like it but this one is yours. As an overseer you will use this booterang to sow terror into the hearts of defiant peons. Proper use of the booterang will instill obedience and ensure subservience. Venture forth to the crystal fields and discipline any peons that you see slacking off. Show them the might of the booterang !",starts={{npcID=23291,x=0.668,y=0.86,zoneID=3520}},ends={{npcID=23291,x=0.668,y=0.86,zoneID=3520}},coords={x=0.668,y=0.86,source="quest_giver",zoneID=3520},questType="standard"},
[11056] = {id=11056,name="Hazzik's Bargain",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Do not draw attention to our conversation. Adaris would not approve. I belong to the lowest caste of arakkoa, . During Terokk's rule I would've been sacrificed to the dark powers worshipped by his talonpriests. If what you say is true and the talonpriests are seeking Terokk's return, then you must prevent them from succeeding - regardless of what your leader says! I've something to offer you that you'll find useful. There is a package at my old dwelling in Upper Veil Shil'ak. Bring it to me!",starts={{npcID=23306,x=0.642,y=0.668,zoneID=3519}},ends={{npcID=23306,x=0.642,y=0.668,zoneID=3519}},coords={x=0.642,y=0.668,source="quest_giver",zoneID=3519},questType="standard"},
[11057] = {id=11057,name="The Trouble Below",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="We commend your zeal in wanting to help out here in Ogri'la, . However, we have a favor to ask of you before we can accept your assistance. Down below our brethren are enslaved to the Sons of Gruul. Please, speak with Mog'dorg the Wizened , who is leading an ogre resistance against their gronn masters. Seek him out atop the tower on the eastern side of the Circle of Blood arena.",starts={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},ends={{npcID=22941,x=0.554,y=0.448,zoneID=3522}},coords={x=0.288,y=0.574,source="quest_giver",zoneID=3522},questType="standard"},
[11058] = {id=11058,name="An Apexis Relic",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Long ago a now-extinct sect of the arakkoa known as the Apexis lived here. Remnants of their civilization are still present. We call them apexis relics. What we know about them is that, when properly used, they grant a boon. Each relic presents a colored sequence which, when the crystals are pressed in the correct order, leads through a series of levels, each harder than the last. An apexis shard is needed to power the relic. Return when you have attained the insight of the apexis vibration.",starts={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},ends={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},coords={x=0.288,y=0.574,source="quest_giver",zoneID=3522},questType="standard"},
[11059] = {id=11059,name="Guardian of the Monument",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="You've figured out how to use the single-person relics, but as you may have seen, there are bigger ones, which they surround. These larger apexis monuments function in much the same way, but they take 35 apexis shards to activate. Of greater concern to us are the guardians that are summoned through their use. These crystal constructs turned on their arakkoan masters long ago, and now endanger Ogri'la. We would ask that you destroy one and bring us proof.",starts={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},ends={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},coords={x=0.288,y=0.574,source="quest_giver",zoneID=3522},questType="standard"},
[11061] = {id=11061,name="A Father's Duty",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="As to that other magical flask, it can only be obtained from one spot: Bash'ir Landing. It's an ethereal base, and they aren't too friendly with outsiders, so it might be a little dangerous to obtain. Where's Bash'ir Landing, you ask? Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you'll eventually spot it. The Bash'ir crystalforge itself is at the northeast corner of the landing. Thank you for doing this, . It'll mean the world to our sons!",starts={{npcID=23316,x=0.284,y=0.576,zoneID=3522}},ends={{npcID=23316,x=0.284,y=0.576,zoneID=3522}},coords={x=0.284,y=0.576,source="quest_giver",zoneID=3522},questType="standard"},
[11062] = {id=11062,name="The Skyguard Outpost",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description=", we were wondering if you might be willing to visit our friends just to the north at the Skyguard Outpost? Sky Commander Keller and his Skyguard are here running missions for our mutual protection, and he's asked us to send along anyone that we feel would excel at helping out. That would be you! Head up there as soon as you can, and please, give him our regards.",starts={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},ends={{npcID=23334,x=0.274,y=0.526,zoneID=3522}},coords={x=0.288,y=0.574,source="quest_giver",zoneID=3522},questType="standard"},
[11063] = {id=11063,name="Earning Your Wings...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,mapID=104,starts={{npcID=22433,x=0.658,y=0.87,mapID=104}},ends={{npcID=22433,x=0.658,y=0.87,mapID=104}},coords={x=0.658,y=0.87,source="quest_giver",mapID=104},questType="standard"},
[11064] = {id=11064,name="Dragonmaw Race: The Ballad of Oldie McOld",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Don't let the gray hair fool you, grunt. I'm still ten times the rider that you are! And don't go thinking that this old dog doesn't have any tricks up his sleeve. Now all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat. We'll lift off as soon as you're ready.",starts={{npcID=23340,x=0.652,y=0.856,zoneID=3520}},ends={{npcID=22433,x=0.658,y=0.87,zoneID=3520}},coords={x=0.652,y=0.856,source="quest_giver",zoneID=3520},questType="standard"},
[11065] = {id=11065,name="Wrangle Some Aether Rays!",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Wanna help the Skyguard and Ogri'la? Just hear me out before you walk away, . We're in need of remounts! The bombing runs and missions to Bash'ir Landing have taken a toll on our mounts. The aether rays that fly around Vortex Summit, and the Crystal Spine to the northeast, look like they'd do just fine. You don't even have to bring them back here, though that would be nice. Just break and rope them, and we'll track them down later. Think you can wrangle me up some?",starts={{npcID=23335,x=0.28,y=0.514,zoneID=3522}},ends={{npcID=23335,x=0.28,y=0.514,zoneID=3522}},coords={x=0.28,y=0.514,source="quest_giver",zoneID=3522},questType="standard"},
[11066] = {id=11066,name="Wrangle More Aether Rays!",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="So, I hope that you're up to helping us wrangle up even more aether rays! From what I can see, you're a natural with the rope! And it's for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri'la, which the ogres appreciate. Remember, the aether rays fly around Vortex Summit, and the Crystal Spine to the northeast. Think you can wrangle me up some more?",starts={{npcID=23335,x=0.28,y=0.514,zoneID=3522}},ends={{npcID=23335,x=0.28,y=0.514,zoneID=3522}},coords={x=0.28,y=0.514,source="quest_giver",zoneID=3522},questType="standard"},
[11067] = {id=11067,name="Dragonmaw Race: Trope the Filth-Belcher",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Dragonmaw treat you right, . Even a worn out cursed being like me is given a chance. Now if you want to prove your worth to the Skybreakers, you will have to defeat me. I'm going to shake you off my tail like a bad case of fleas... We'll lift off when you are ready.",starts={{npcID=23342,x=0.652,y=0.854,zoneID=3520}},ends={{npcID=22433,x=0.658,y=0.87,zoneID=3520}},coords={x=0.652,y=0.854,source="quest_giver",zoneID=3520},questType="standard"},
[11068] = {id=11068,name="Dragonmaw Race: Corlok the Vet",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="You are challenging ME? Don't make me laugh! You're serious? Very well then! All you need to do is not die. You can manage to not die, right?? Even if I'm hurling skulls at you and flying circles around your pathetic riding skills? Just let me know when you're ready and we'll lift off.",starts={{npcID=23344,x=0.652,y=0.852,zoneID=3520}},ends={{npcID=22433,x=0.658,y=0.87,zoneID=3520}},coords={x=0.652,y=0.852,source="quest_giver",zoneID=3520},questType="standard"},
[11069] = {id=11069,name="Dragonmaw Race: Wing Commander Ichman",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Three years I spent in that hell hole. Three years a prisoner of war to the damnable Frostwolf Clan. Made to sit in their tower and listen to them endlessly whine about the bridge to Dun Baldar. About how it's \"unfair\" that blah, blah, blah, blah... War isn't fair! To hell with 'em all! The minute I was freed I left that place forever and came here to start a new life. Now Mulv and I are vying for the top orc spot. If you want it, you're gonna have to go through me, scrub. We go when you're ready.",starts={{npcID=23345,x=0.652,y=0.85,zoneID=3520}},ends={{npcID=22433,x=0.658,y=0.87,zoneID=3520}},coords={x=0.652,y=0.85,source="quest_giver",zoneID=3520},questType="standard"},
[11070] = {id=11070,name="Dragonmaw Race: Wing Commander Mulverick",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Three years of blood, sweat and tears. Mostly tears... The amount of crying that a hardened soldier does when it comes down to all-out war is amazing! \"They're jumping into our tower with their horses!\" \"Why is their base so well defended?\" \"They're taking our relief hut, I'm going A.W.O.L.!\" Wimps... I took the first train out of \"cry-town\" the minute the Dark Portal opened. Now I'm a top gun for the Dragonmaw. If you want to be top orc, you'll have to defeat me. We go when you are ready.",starts={{npcID=23346,x=0.652,y=0.85,zoneID=3520}},ends={{npcID=22433,x=0.658,y=0.87,zoneID=3520}},coords={x=0.652,y=0.85,source="quest_giver",zoneID=3520},questType="standard"},
[11071] = {id=11071,name="Dragonmaw Race: Captain Skyshatter",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="You dare challenge Skyshatter? The world around you will fall into darkness as the heavens are torn asunder by my meteors. You stand no chance, soldier. Yet it is your desire to die... I will entertain this morbid obsession if only to prove a point to any that might foolishly dream of making the same mistake. We ride when you are ready!",starts={{npcID=23348,x=0.654,y=0.854,zoneID=3520}},ends={{npcID=22433,x=0.658,y=0.87,zoneID=3520}},coords={x=0.654,y=0.854,source="quest_giver",zoneID=3520},questType="standard"},
[11072] = {id=11072,name="Adversarial Blood",level=15,requiredLevel=15,faction="none",expansion=1,zoneID=3519,mapID=108,description="The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager. They will all need to be slain before Terokk returns to this world. You will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis. Bring me a token from each one. These are powerful beings you will be facing; you would do well to bring friends.",questType="group"},
[11073] = {id=11073,name="Terokk's Downfall",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="I... I've turned a blind eye to your dealings with the arakkoa prisoner, . It looks like your instincts to cooperate with him were right. You must understand... I would've faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world. Take the items that Hazzik prepared for you and go ahead with your plan. I will command my men to back you up when the time comes. I recommend that you bring a force of your own as well. I fear you'll only get one chance at this.",starts={{npcID=23038,x=0.64,y=0.668,zoneID=3519}},ends={{npcID=23038,x=0.64,y=0.668,zoneID=3519}},coords={x=0.64,y=0.668,source="quest_giver",zoneID=3519},questType="group"},
[11074] = {id=11074,name="Tokens of the Descendants",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="The descendants held prisoner by the Skettis talonpriests are listed in this book. Gezzarak the Huntress, Garokk the Crystal Giant, the heretic known as Darkscreecher Akkarai and Vekkaz the Windrager. They will all need to be slain before Terokk returns to this world. You will need the scrolls carried by the time-lost arakkoa and burn them at the summoning circles all over Skettis. Bring me a token from each one. These are powerful beings you will be facing; you would do well to bring friends.",ends={{npcID=23306,x=0.642,y=0.668,zoneID=3519}},questType="standard"},
[11075] = {id=11075,name="The Netherwing Mines",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Your help is required at the Netherwing Mines, overseer . Two days ago our mining operations came to a grinding halt when we made a grim discovery. A miner was working in the depths of the mine and struck his pick upon an unusual crystal formation. Unfortunately, this crystal formation was attached to a very angry nether dragon. The beast woke from its slumber and annihilated all of our workers. Report to the Mistress of the Mines . They await you at the mouth of the mines, southwest of here.",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23149,x=0.63,y=0.878,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11076] = {id=11076,name="Picking Up The Pieces...",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Much of our hard work lies scattered about in these mines. Carts full of cargo are littered across every inch of this mine! We just can't get to any of it with the current infestation. That's where you come in, . Your daily duty here at this mine is to collect the cargo left behind by the miners and deep mine workers. Gather the nethermine cargo and return it to me or my sister.",starts={{npcID=23149,x=0.63,y=0.878,zoneID=3520}},ends={{npcID=23149,x=0.63,y=0.878,zoneID=3520}},coords={x=0.63,y=0.878,source="quest_giver",zoneID=3520},questType="standard"},
[11077] = {id=11077,name="Dragons are the Least of Our Problems",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="That dragon waking up riled up a host of other nasty creatures in these mines. Two types are proving to be a thorn in the side of the Dragonmaw: Nethermine flayers and Nethermine ravagers . You must help us by killing them off. All I ask is your involvement once per day. Get in there and kill as many as you can!",starts={{npcID=23376,x=0.634,y=0.874,zoneID=3520}},ends={{npcID=23376,x=0.634,y=0.874,zoneID=3520}},coords={x=0.634,y=0.874,source="quest_giver",zoneID=3520},questType="standard"},
[11078] = {id=11078,name="To Rule The Skies",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="As ye've flown around, ye must have noticed the dragons above. I trust ye haven't fallen victim ta their rage. Help us put an end ta it, ! Rivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast. Each has a perch on their respective domains. I be wondering if ye and yer friends will go ta one, , break open an egg with 35 apexis shards and attract the dragon down. Bring me some teeth as proof.",starts={{npcID=23334,x=0.274,y=0.526,zoneID=3522}},ends={{npcID=23334,x=0.274,y=0.526,zoneID=3522}},coords={x=0.274,y=0.526,source="quest_giver",zoneID=3522},questType="standard"},
[11079] = {id=11079,name="A Fel Whip For Gahk",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Gahk think being smart is dumb sometimes. Gahk not want to think. Me want little to smash big demons! Dey have some chiefs, and da chiefs all have whips to hurt da little demons. You bring Gahk a whip! You challenge demon chief in forge camps at burning, green, fel crystal prism. Use 35 apexis shards to get dem to come. Dey called Galvanoth, Braxxus, Zarcsin and da Mo'arg Incinerator.",starts={{npcID=23300,x=0.284,y=0.58,zoneID=3522}},ends={{npcID=23300,x=0.284,y=0.58,zoneID=3522}},coords={x=0.284,y=0.58,source="quest_giver",zoneID=3522},questType="standard"},
[11080] = {id=11080,name="The Relic's Emanation",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,mapID=105,description="Now that you have felt the enlightening vibrations of the apexis relics, it is time for you to further your understanding of their workings. We are very eager to benefit from your observations! As you progress in your ability to attune to the relics, you will gain a higher level of knowledge. This recognition will come in the form of an emanation from the relic. Return to us when you have attained such an emanation.",starts={{npcID=23233,x=0.288,y=0.574,mapID=105}},ends={{npcID=23233,x=0.288,y=0.574,mapID=105}},coords={x=0.288,y=0.574,source="quest_giver",mapID=105},questType="standard"},
[11081] = {id=11081,name="The Great Murkblood Revolt",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="This document outlines a revolt planned by the Murkblood broken. It seems that the dragon was to be used as a diversion to draw attention away from their escape. Looking at all of the corpses littering the mine, it would be safe to assume that their plans failed. Return the escape plans to the Mistress of the Mines .",ends={{npcID=23149,x=0.63,y=0.878,zoneID=3520}},questType="standard"},
[11082] = {id=11082,name="Seeker of Truth",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="These miners are far too stupid to concoct any type of escape plan. We must find and punish the source. Venture into the depths of the mine and seek out the Murkblood overseers. If they have not been overcome by the denizens of the mine, they will undoubtedly be hiding. Once you locate one, interrogate him until he reveals the true mastermind behind the escape. Return to me with the identity of this traitor and the hand of the overseer .",starts={{npcID=23149,x=0.63,y=0.878,zoneID=3520}},ends={{npcID=23149,x=0.63,y=0.878,zoneID=3520}},coords={x=0.63,y=0.878,source="quest_giver",zoneID=3520},questType="standard"},
[11083] = {id=11083,name="Crazed and Confused",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Don't worry about this dragon, . We've got plans for it... Deeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they've lost all sense of decency. They've resorted to cannibalism and the promotion of mayhem. We don't need that kind of madness in this place. Find 'em and kill 'em. All of 'em.",starts={{npcID=23166,x=0.716,y=0.876,zoneID=3520}},ends={{npcID=23166,x=0.716,y=0.876,zoneID=3520}},coords={x=0.716,y=0.876,source="quest_giver",zoneID=3520},questType="standard"},
[11084] = {id=11084,name="Stand Tall, Captain!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Well, well, well... still alive I see. That's good, because Mor'ghor has requested your presence in his tower at once. Get a move on!",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11085] = {id=11085,name="Escape from Skettis",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Hail, . I thank you for coming to my aid. The arakkoa's monstrous birds knocked me from my nether ray while on a scouting mission. Let's get out of here, while we can.",starts={{npcID=23383,x=0.75,y=0.862,zoneID=3519}},ends={{npcID=23048,x=0.644,y=0.666,zoneID=3519}},coords={x=0.75,y=0.862,source="quest_giver",zoneID=3519},questType="standard"},
[11086] = {id=11086,name="Disrupting the Twilight Portal",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3518,description="One of your responsibilities as a captain of Dragonmaw is to snuff out Burning Legion activity in Outland. It is your duty to silence those that defy Lord Illidan! The demons foolishly attempt to stabilize the portal found on the Twilight Ridge of western Nagrand. They must pay for their treachery, and you will be the orc that collects on their debt. Travel to the Twilight Ridge and lay waste to its inhabitants. You will be responsible for making at least one attack per day on their fortifications.",starts={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},coords={x=0.662,y=0.856,source="quest_giver",zoneID=3520},questType="standard"},
[11089] = {id=11089,name="The Soul Cannon of Reth'hedron",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3519,description="Reth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such power being loosed upon this world does not bode well for the Illidari. Alas, we do not have the resources required to slay Reth'hedron. Not with the war the Sha'tar have brought to the Black Temple. No... I have a better plan. You will subdue Reth'hedron, banishing him back through the Twilight Portal. For this a soul cannon must be fashioned. Return to me with the materials on this list.",starts={{npcID=23427,x=0.662,y=0.856,zoneID=3520}},ends={{npcID=23427,x=0.662,y=0.856,zoneID=3520}},coords={x=0.662,y=0.856,source="quest_giver",zoneID=3520},questType="standard"},
[11090] = {id=11090,name="Subdue the Subduer",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3518,description="This is a soul cannon . Its effects are devastating when attuned. This one is attuned to my blood. The same blood flowing through the veins of Reth'hedron - my brother. Aye, his misplaced allegiance will be the end of him. Take the cannon and fly to the Twilight Ridge in western Nagrand. Locate Reth'hedron and fire! You must stay on your mount and within range for the effects to take hold. Stand your ground against him and he will have no choice but to flee!",starts={{npcID=23427,x=0.662,y=0.856,zoneID=3520}},ends={{npcID=23427,x=0.662,y=0.856,zoneID=3520}},coords={x=0.662,y=0.856,source="quest_giver",zoneID=3520},questType="standard"},
[11091] = {id=11091,name="A Special Thank You",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="You honor us with your efforts on our behalf. And now there is someone that we would like for you to meet. Jho'nass is our most trusted quartermaster. He maintains a stock of goods that we provide for sale to only the most dedicated of friends to Ogri'la. You are one such friend, . When you find the time, go and speak with him. As we understand it, he has prepared a little something for you as a token of our appreciation.",starts={{npcID=23233,x=0.288,y=0.574,zoneID=3522}},ends={{npcID=23428,x=0.28,y=0.586,zoneID=3522}},coords={x=0.288,y=0.574,source="quest_giver",zoneID=3522},questType="standard"},
[11092] = {id=11092,name="Hail, Commander!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Captain ! Overlord Mor'ghor has asked to see you in his chambers at once!",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11093] = {id=11093,name="Hungry Nether Rays",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="Nether rays are surprisingly loyal and obedient once properly trained. Unfortunately the war on Skettis is taking a toll on them. We have dozens of sorties a day - the poor fellows rarely get a break. And with recent shortages on feed, if those blasted birdmen don't kill them on a mission then starvation will. If you can lend a hand, take one of our rays to the woods in the south. They don't mind warp chaser meat as long as it's a fresh kill.",starts={{npcID=23415,x=0.634,y=0.658,zoneID=3519}},ends={{npcID=23415,x=0.634,y=0.658,zoneID=3519}},coords={x=0.634,y=0.658,source="quest_giver",zoneID=3519},questType="standard"},
[11094] = {id=11094,name="Kill Them All!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Commander , stand at attention! You are to take a battalion of Skybreakers and sack the Scryers' outpost located at the foot of the Netherwing Fields. With the Sanctum of the Stars destroyed, our lines of communication to our posts at Eclipse Point and Illidari Point will once more be open. Go now! Use this flare gun to signal the Skybreakers for the attack!",starts={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},ends={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},coords={x=0.662,y=0.856,source="quest_giver",zoneID=3520},questType="standard"},
[11095] = {id=11095,name="Commander Hobb",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared. I want you to let them come, . Yes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb . He is standing guard right outside this building.",starts={{npcID=21955,x=0.562,y=0.594,zoneID=3520}},ends={{npcID=23434,x=0.564,y=0.586,zoneID=3520}},coords={x=0.562,y=0.594,source="quest_giver",zoneID=3520},questType="standard"},
[11096] = {id=11096,name="Threat from Above",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="So you want to join the Skyguard? Well, I know you can fly... but can you fight? The Skyguard is sworn to protect Shattrath from the dangers that loom above us, both near and far. The Gordunni ogres who dwell in the Barrier Hills to the north are an immediate threat to us. Reaching the ogres has been problematic for Shattrath's ground units. That's where we come in. See what you can do to help contain them.",starts={{npcID=23449,x=0.64,y=0.42,zoneID=3703}},ends={{npcID=23449,x=0.64,y=0.42,zoneID=3703}},coords={x=0.64,y=0.42,source="quest_giver",zoneID=3703},questType="standard"},
[11097] = {id=11097,name="The Deadliest Trap Ever Laid",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Take these Scryer medals . Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Scryer soldiers. Now all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.",starts={{npcID=23434,x=0.564,y=0.586,zoneID=3520}},ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},coords={x=0.564,y=0.586,source="quest_giver",zoneID=3520},questType="group"},
[11098] = {id=11098,name="To Skettis!",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="The Barrier Hills are only one of the fronts where we've been deployed. A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis. A few months ago our scouts detected a huge increase in arakkoa activity there. Several attacks against Shattrath followed. We've stationed forces outside of their city since. Take these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis. Tell him you're a new recruit.",starts={{npcID=23449,x=0.64,y=0.42,zoneID=3703}},ends={{npcID=23048,x=0.644,y=0.666,zoneID=3519}},coords={x=0.64,y=0.42,source="quest_giver",zoneID=3703},questType="standard"},
[11099] = {id=11099,name="Kill Them All!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Commander , stand at attention! You are to take a battalion of Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. With the Altar of Sha'tar destroyed, our lines of communication to our posts at Coilskar will once more be open. Go now! Use this flare gun to signal the Skybreakers for the attack!",starts={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},ends={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},coords={x=0.662,y=0.856,source="quest_giver",zoneID=3520},questType="standard"},
[11100] = {id=11100,name="Commander Arcus",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared. I want you to let them come, . Yes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus . He is standing guard right outside this building.",starts={{npcID=21402,x=0.624,y=0.284,zoneID=3520}},ends={{npcID=23452,x=0.624,y=0.292,zoneID=3520}},coords={x=0.624,y=0.284,source="quest_giver",zoneID=3520},questType="standard"},
[11101] = {id=11101,name="The Deadliest Trap Ever Laid",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="Take these Aldor medals . Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Aldor soldiers. Now all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.",starts={{npcID=23452,x=0.624,y=0.292,zoneID=3520}},ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},coords={x=0.624,y=0.292,source="quest_giver",zoneID=3520},questType="group"},
[11102] = {id=11102,name="Bombing Run",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="You can fly around as a crow... so what! Ever annihilate something on the ground while you were flying? Want to? Forge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la. With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business. Want to prove yourself? Take these bombs and knock out their ammo stacks. Just don't let them shoot you down, too!",starts={{npcID=23120,x=0.276,y=0.528,zoneID=3522}},ends={{npcID=23120,x=0.276,y=0.528,zoneID=3522}},coords={x=0.276,y=0.528,source="quest_giver",zoneID=3522},questType="standard"},
[11107] = {id=11107,name="Bow to the Highlord",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3520,description="I am unworthy to even carry a message directed at you, sir. Please forgive me for this indulgence. Overlord Mor'ghor has requested your presence in his chambers at once!",starts={{npcID=23140,x=0.66,y=0.864,zoneID=3520}},ends={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},coords={x=0.66,y=0.864,source="quest_giver",zoneID=3520},questType="standard"},
[11108] = {id=11108,name="Lord Illidan Stormrage",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="Come, highlord . Illidan himself awaits us!",starts={{npcID=23139,x=0.662,y=0.856,zoneID=3520}},ends={{npcID=23433,x=0.666,y=0.168,zoneID=3703}},coords={x=0.662,y=0.856,source="quest_giver",zoneID=3520},questType="standard"},
[11109] = {id=11109,name="Jorus the Cobalt Netherwing Drake",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,mapID=111,starts={{npcID=23462,x=0.676,y=0.172,mapID=111}},ends={{npcID=23462,x=0.676,y=0.172,mapID=111}},coords={x=0.676,y=0.172,source="quest_giver",mapID=111},questType="standard"},
