[11111] = {id=11111,name="Onyxien the Onyx Netherwing Drake",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,mapID=111,starts={{npcID=23463,x=0.674,y=0.184,mapID=111}},ends={{npcID=23463,x=0.674,y=0.184,mapID=111}},coords={x=0.674,y=0.184,source="quest_giver",mapID=111},questType="standard"},
[11112] = {id=11112,name="Suraku the Azure Netherwing Drake",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,mapID=111,starts={{npcID=23461,x=0.668,y=0.186,mapID=111}},ends={{npcID=23461,x=0.668,y=0.186,mapID=111}},coords={x=0.668,y=0.186,source="quest_giver",mapID=111},questType="standard"},
[11113] = {id=11113,name="Voranaku the Violet Netherwing Drake",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,mapID=111,starts={{npcID=23466,x=0.662,y=0.176,mapID=111}},ends={{npcID=23466,x=0.662,y=0.176,mapID=111}},coords={x=0.662,y=0.176,source="quest_giver",mapID=111},questType="standard"},
[11114] = {id=11114,name="Zoya the Veridian Netherwing Drake",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,mapID=111,starts={{npcID=23465,x=0.66,y=0.188,mapID=111}},ends={{npcID=23465,x=0.66,y=0.188,mapID=111}},coords={x=0.66,y=0.188,source="quest_giver",mapID=111},questType="standard"},
[11119] = {id=11119,name="Assault on Bash'ir Landing!",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,description="Heya, ! Up fer some fun are ye? Every couple o' hours, me aether-techs launch an assault on Bash'ir Landing, far ta the northeast in the Blade's Edge Mountains . They say that they're there 'studying' the Bash'ir crystalforge, but it's an assault; there be no two ways about it. We use the crystalforge to resupply, and there's always extra to be sold. Go on down ta the landin' pad and speak with the aether-tech apprentice . He'll tell ye when the next mission is ta launch.",starts={{npcID=23334,x=0.274,y=0.526,zoneID=3522}},ends={{npcID=23473,x=0.278,y=0.522,zoneID=3522}},coords={x=0.274,y=0.526,source="quest_giver",zoneID=3522},questType="standard"},
[11242] = {id=11242,name="Free at Last!",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3524,description="Rage was my prison, , and you have freed me. Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth. Thank you for leading me back to the Light. May I never again lose my way. Take this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.",ends={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},questType="standard"},
[11356] = {id=11356,name="Costumed Orphan Matron",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3524,description="During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages. Those poor children would love to see a real like yourself! Why don't you visit them? You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst. Speak to the children's ward, a costumed orphan matron , and she'll introduce you to the children.",starts={{npcID=18927,x=0.616,y=0.74,zoneID=1519},{npcID=19148,x=0.308,y=0.632,zoneID=1537},{npcID=19172,x=0.578,y=0.49,zoneID=1537},{npcID=19148,x=0.648,y=0.73,zoneID=6507},{npcID=19172,x=0.64,y=0.74,zoneID=6507},{npcID=19173,x=0.446,y=0.526,zoneID=1657},{npcID=20102,x=0.69,y=0.706,zoneID=17},{npcID=20102,x=0.406,y=0.844,zoneID=67},{npcID=20102,x=0.522,y=0.284,zoneID=440},{npcID=20102,x=0.598,y=0.496,zoneID=618},{npcID=20102,x=0.338,y=0.64,zoneID=3523},{npcID=20102,x=0.53,y=0.504,zoneID=3703},{npcID=20102,x=0.416,y=0.742,zoneID=5287},{npcID=199261,x=0.542,y=0.6,zoneID=13862},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},coords={x=0.616,y=0.74,source="quest_giver",zoneID=1519},questType="standard"},
[11357] = {id=11357,name="Masked Orphan Matron",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=85,description="For Hallow's End, several orphans were taken on a trip to different Horde villages. The orphan matrons thought it would be good for them to see real heroes adventuring in the field. Why don't you visit them? A brave like yourself could strengthen their spirits with tales of your valor! Go to Razor Hill in Durotar, Brill in Tirisfal Glades, or Falconwing Square in Eversong Woods. Speak with the masked orphan matron and she'll introduce you to the children.",starts={{npcID=19169,x=0.542,y=0.508,zoneID=3430},{npcID=19169,x=0.778,y=0.576,zoneID=3487},{npcID=19175,x=0.516,y=0.752,zoneID=1637},{npcID=19176,x=0.402,y=0.488,zoneID=1637},{npcID=19177,x=0.49,y=0.612,zoneID=1637},{npcID=19176,x=0.41,y=0.558,zoneID=1638},{npcID=19178,x=0.632,y=0.48,zoneID=1497},{npcID=20102,x=0.69,y=0.706,zoneID=17},{npcID=20102,x=0.406,y=0.844,zoneID=67},{npcID=20102,x=0.522,y=0.284,zoneID=440},{npcID=20102,x=0.598,y=0.496,zoneID=618},{npcID=20102,x=0.338,y=0.64,zoneID=3523},{npcID=20102,x=0.53,y=0.504,zoneID=3703},{npcID=20102,x=0.416,y=0.742,zoneID=5287},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=23973,x=0.472,y=0.464,zoneID=3430},{npcID=23973,x=0.526,y=0.412,zoneID=14},{npcID=23973,x=0.608,y=0.534,zoneID=85}},coords={x=0.542,y=0.508,source="quest_giver",zoneID=3430},questType="standard"},
[11360] = {id=11360,name="Fire Brigade Practice",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3524,description="With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade. Do you want to help? North of here, guards set up a small area to practice fighting fires. Go there and throw buckets onto the blazes. You can fill a bucket from the water barrel here, or the one near the fires. Good bye, . When you're done with fire brigade practice, please visit us again!",starts={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},ends={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},coords={x=0.532,y=0.514,source="quest_giver",zoneID=1},questType="standard"},
[11361] = {id=11361,name="Fire Training",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3430,description="The grunts set up a fire training area outside the village. These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter! Head west out of Razor Hill, then turn right as you pass the village's wall. Find the training area, then grab buckets and toss them on the practice fires.",starts={{npcID=23973,x=0.526,y=0.412,zoneID=14},{npcID=23973,x=0.608,y=0.534,zoneID=85},{npcID=23973,x=0.472,y=0.464,zoneID=3430}},ends={{npcID=23973,x=0.526,y=0.412,zoneID=14},{npcID=23973,x=0.608,y=0.534,zoneID=85},{npcID=23973,x=0.472,y=0.464,zoneID=3430}},coords={x=0.526,y=0.412,source="quest_giver",zoneID=14},questType="standard"},
[11364] = {id=11364,name="WANTED: Shattered Hand Centurions",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3714,description="Do you question your master? Neither does Mah'duun. The blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel. If you want the bounty, you will not return until you have slain them all.",starts={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},ends={{npcID=24370,x=0.752,y=0.372,zoneID=3703}},coords={x=0.752,y=0.372,source="quest_giver",zoneID=3703},questType="dungeon"},
[11377] = {id=11377,name="Revenge is Tasty",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3519,description="I'm providing the catering for some unusual party guests tonight. One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly. They've requested something special for his get well party: Kaliri Stew . I can loan you my cooking pot so you can whip up a batch of stew for me. The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.",starts={{npcID=24393,x=0.616,y=0.158,zoneID=3703}},ends={{npcID=24393,x=0.616,y=0.158,zoneID=3703}},coords={x=0.616,y=0.158,source="quest_giver",zoneID=3703},questType="standard"},
[11379] = {id=11379,name="Super Hot Stew",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3703,description="I'm trying to invent something with some real zing. But to be honest, I'm more of an idea goblin these days. I've lost my sense of adventure. But you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other. I want you to take my beloved cooking pot and head out to Blade's Edge. Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.",starts={{npcID=24393,x=0.616,y=0.158,zoneID=3703}},ends={{npcID=24393,x=0.616,y=0.158,zoneID=3703}},coords={x=0.616,y=0.158,source="quest_giver",zoneID=3703},questType="standard"},
[11380] = {id=11380,name="Manalicious",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3703,description="Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight. Unfortunately, mana berries are only found in the eco-domes of Netherstorm. Just don't bother looking around Stormspire--it's picked clean. I could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!",starts={{npcID=24393,x=0.616,y=0.158,zoneID=3703}},ends={{npcID=24393,x=0.616,y=0.158,zoneID=3703}},coords={x=0.616,y=0.158,source="quest_giver",zoneID=3703},questType="standard"},
[11381] = {id=11381,name="Soup for the Soul",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3703,description="Death is in the air. I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul. And I know a fellow cook when I see one! Would you like to help me out and get a cut of the profits? Here, take my cooking pot , gather some clefthoof meat and I'll let you in on a little secret. What makes my soup so good for the soul? It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.",starts={{npcID=24393,x=0.616,y=0.158,zoneID=3703}},ends={{npcID=24393,x=0.616,y=0.158,zoneID=3703}},coords={x=0.616,y=0.158,source="quest_giver",zoneID=3703},questType="standard"},
[11403] = {id=11403,name="Free at Last!",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3430,description="Rage was my prison, , and you have freed me. Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth. Thank you for leading me back to the Light. May I never again lose my way. Take this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.",ends={{npcID=23973,x=0.526,y=0.412,zoneID=14},{npcID=23973,x=0.608,y=0.534,zoneID=85},{npcID=23973,x=0.472,y=0.464,zoneID=3430}},questType="standard"},
[11439] = {id=11439,name="Fire Brigade Practice",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3524,description="The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help? South of here, the mountaineers set up a small area to practice fighting fires. Go there and throw buckets onto the blazes. You can fill a bucket from the water barrel here. Good bye, . When you're done with fire brigade practice, please visit us again!",starts={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},ends={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},coords={x=0.532,y=0.514,source="quest_giver",zoneID=1},questType="standard"},
[11440] = {id=11440,name="Fire Brigade Practice",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3524,description="With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help? West of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires. Go there and throw buckets onto the blazes. You can fill a bucket from the water barrel here. Good bye, . When you're done with fire brigade practice, please visit us again!",starts={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},ends={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},coords={x=0.532,y=0.514,source="quest_giver",zoneID=1},questType="standard"},
[11446] = {id=11446,name="Brewfest!",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=14,description="Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Orgrimmar--he'll give you a free beer to kick things off!",starts={{npcID=19169,x=0.542,y=0.508,zoneID=3430},{npcID=19169,x=0.778,y=0.576,zoneID=3487},{npcID=19175,x=0.516,y=0.752,zoneID=1637},{npcID=19176,x=0.402,y=0.488,zoneID=1637},{npcID=19177,x=0.49,y=0.612,zoneID=1637},{npcID=19176,x=0.41,y=0.558,zoneID=1638},{npcID=19178,x=0.632,y=0.48,zoneID=1497},{npcID=20102,x=0.69,y=0.706,zoneID=17},{npcID=20102,x=0.406,y=0.844,zoneID=67},{npcID=20102,x=0.522,y=0.284,zoneID=440},{npcID=20102,x=0.598,y=0.496,zoneID=618},{npcID=20102,x=0.338,y=0.64,zoneID=3523},{npcID=20102,x=0.53,y=0.504,zoneID=3703},{npcID=20102,x=0.416,y=0.742,zoneID=5287},{npcID=199261,x=0.542,y=0.6,zoneID=13862},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220865,x=0.568,y=0.288,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=24711,x=0.416,y=0.184,zoneID=14},{npcID=155194,x=0.416,y=0.184,zoneID=14}},coords={x=0.542,y=0.508,source="quest_giver",zoneID=3430},questType="standard"},
[11449] = {id=11449,name="Fire Training",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3430,description="The deathstalkers have set up a fire training area outside the town. We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter. Head west past the graveyard, following the road. You'll find the training area there.",starts={{npcID=23973,x=0.526,y=0.412,zoneID=14},{npcID=23973,x=0.608,y=0.534,zoneID=85},{npcID=23973,x=0.472,y=0.464,zoneID=3430}},ends={{npcID=23973,x=0.526,y=0.412,zoneID=14},{npcID=23973,x=0.608,y=0.534,zoneID=85},{npcID=23973,x=0.472,y=0.464,zoneID=3430}},coords={x=0.526,y=0.412,source="quest_giver",zoneID=14},questType="standard"},
[11450] = {id=11450,name="Fire Training",level=10,requiredLevel=10,faction="horde",expansion=1,zoneID=3430,description="The guards have set up a fire training area outside the town. We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter. Head south through the gate to the crossroads. You'll find the training area there.",starts={{npcID=23973,x=0.526,y=0.412,zoneID=14},{npcID=23973,x=0.608,y=0.534,zoneID=85},{npcID=23973,x=0.472,y=0.464,zoneID=3430}},ends={{npcID=23973,x=0.526,y=0.412,zoneID=14},{npcID=23973,x=0.608,y=0.534,zoneID=85},{npcID=23973,x=0.472,y=0.464,zoneID=3430}},coords={x=0.526,y=0.412,source="quest_giver",zoneID=14},questType="standard"},
[11451] = {id=11451,name="Alicia's Poem",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3703,description="Hi, I wrote a poem for my friend Caylee. She likes to hang out with the Aldor in Shattrath City . You know, in Outland? Could you take my poem to her? My mommy says I'm too young to go to Shattrath City !",starts={{npcID=24729,x=0.816,y=0.282,zoneID=1519}},ends={{npcID=24727,x=0.314,y=0.28,zoneID=3703}},coords={x=0.816,y=0.282,source="quest_giver",zoneID=1519},questType="standard"},
[11481] = {id=11481,name="Crisis at the Sunwell",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="By the naaru, I thank you, , for your efforts. Our work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued. Our forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau. You are needed there, . Report to Larethor. Tell him that I wish we could spare more men.",starts={{npcID=18537,x=0.306,y=0.174,zoneID=3523},{npcID=18537,x=0.306,y=0.344,zoneID=3703}},ends={{npcID=24967,x=0.474,y=0.306,zoneID=4080}},coords={x=0.306,y=0.174,source="quest_giver",zoneID=3523},questType="standard"},
[11482] = {id=11482,name="Duty Calls",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="Hear me, . Duty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately. I'm afraid I have no more information to share, except this: You'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive. Apparently, the situation calls for us to set our differences aside and join forces. Prepare yourself, friend. This sounds serious.",starts={{npcID=18594,x=0.544,y=0.808,zoneID=3703}},ends={{npcID=24967,x=0.474,y=0.306,zoneID=4080}},coords={x=0.544,y=0.808,source="quest_giver",zoneID=3703},questType="standard"},
[11496] = {id=11496,name="The Sanctum Wards",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=4080,description="Our first priority is to capture the Sun's Reach Sanctum. Once we've secured it, we'll be able to use its energy to open a portal from Shattrath. The sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves. Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards. Hunt down the Wretched and get the mana remnants they carry. Use them to energize the sanctum wards.",questType="standard"},
[11497] = {id=11497,name="Learning to Fly",level=25,requiredLevel=25,faction="alliance",expansion=1,zoneID=3520,description="Though it may end up hurting my business in the long run, you look the sort that dreams of flying own mount through the skies, rather than being flown from place to place. I understand the feeling completely. You, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley . When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.",questType="standard"},
[11498] = {id=11498,name="Learning to Fly",level=25,requiredLevel=25,faction="horde",expansion=1,zoneID=3520,description="Though it may end up hurting my business in the long run, you look the sort that dreams of flying own mount through the skies, rather than being flown from place to place. I understand the feeling completely. You, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley . When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.",questType="standard"},
[11502] = {id=11502,name="In Defense of Halaa",level=15,requiredLevel=15,faction="alliance",expansion=1,zoneID=3518,description="We are not a warlike race, . However when war comes to our lands, we do not run away from it. The Alliance and the Horde wage war in the city of Halaa, to the northwest. We do not know what the blood elves are scheming, but any victory for the Horde would be disastrous. The history between our people and the orcs is one of bloodshed and betrayal. Go and slay the enemy in Halaa and you will be rewarded in coin, honor and renown.",starts={{npcID=24866,x=0.558,y=0.736,zoneID=3518}},ends={{npcID=24866,x=0.558,y=0.736,zoneID=3518}},coords={x=0.558,y=0.736,source="quest_giver",zoneID=3518},questType="pvp"},
[11503] = {id=11503,name="Enemies, Old and New",level=15,requiredLevel=15,faction="horde",expansion=1,zoneID=3518,description="Our ancient enemy, the draenei, have returned with powerful allies. They wage war in Halaa, southwest of here. We cannot allow them a victory there as Garadar would be next without a doubt. Go and slay those who would aid our ancient enemy.",starts={{npcID=24881,x=0.528,y=0.36,zoneID=3518}},ends={{npcID=24881,x=0.528,y=0.36,zoneID=3518}},coords={x=0.528,y=0.36,source="quest_giver",zoneID=3518},questType="pvp"},
[11505] = {id=11505,name="Spirits of Auchindoun",level=15,requiredLevel=63,faction="alliance",expansion=1,zoneID=3519,description="Auchindoun's spirits have no stake in the conflict between the Alliance and the Horde, but incurring their favor will give our side an edge in the region. Ancient custom directs the living to pay their respects at spirit towers in the Bone Wastes - though only at specific times of the day. If you can help secure a tower during these times, you will have helped bring the spirits to our side. Should we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in our endeavors.",starts={{npcID=24885,x=0.558,y=0.538,zoneID=3519}},ends={{npcID=24885,x=0.558,y=0.538,zoneID=3519}},coords={x=0.558,y=0.538,source="quest_giver",zoneID=3519},questType="pvp"},
[11506] = {id=11506,name="Spirits of Auchindoun",level=15,requiredLevel=63,faction="horde",expansion=1,zoneID=3519,description="The draenei might be our enemies, but the spirits of their ancestors in Auchindoun are restless and have no allegiance. The draenei's custom required them to pay their respects at spirit towers at various times during the day. If you can help secure a tower during these times, you will help the spirits return to peace in Auchindoun. The Alliance will try to capture the towers in order to secure the dead's favor. We must ensure that our side succeeds instead.",starts={{npcID=24886,x=0.498,y=0.466,zoneID=3519}},ends={{npcID=24886,x=0.498,y=0.466,zoneID=3519}},coords={x=0.498,y=0.466,source="quest_giver",zoneID=3519},questType="pvp"},
[11513] = {id=11513,name="Intercepting the Mana Cells",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=3522,description="I have devised a plan to acquire a power source strong enough for the creation of our portal. The ethereal forces at Bash'ir Landing, atop the northwestern Blade's Edge Mountains , have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael'thas. They have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods. Just beware the mana cells' phase wyrm guardians.",questType="standard"},
[11514] = {id=11514,name="Maintaining the Sunwell Portal",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade's Edge Mountains , far to the north. Remember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods. Just be cautious of the phase wyrms that they use to guard the mana cells.",starts={{npcID=24932,x=0.492,y=0.424,zoneID=3703}},ends={{npcID=24932,x=0.492,y=0.424,zoneID=3703}},coords={x=0.492,y=0.424,source="quest_giver",zoneID=3703},questType="standard"},
[11515] = {id=11515,name="Blood for Blood",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3483,description="When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift. They stayed behind and gorged themselves on the blood of demons for days. The blood has changed them, given them new powers. It will also prove their undoing. Obtain blood samples from other demons. Use them to power this fel siphon and deprive these arrogant fools of their new powers. Slay them in their weakened state and return to me.",starts={{npcID=24937,x=0.582,y=0.176,zoneID=3483}},ends={{npcID=24937,x=0.582,y=0.176,zoneID=3483}},coords={x=0.582,y=0.176,source="quest_giver",zoneID=3483},questType="standard"},
[11516] = {id=11516,name="Blast the Gateway",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3483,description="We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas. Take these embers, they contain one of my creations: a living flare. It is designed to act as a powerful destructive force - as long as it has been provided enough energy. Find the fel sparks that wander the area and slay them near the living flare. The flare will grow in power each time, until it becomes unstable. Once you've achieved this bring the flare to the gateway. It will know what to do.",starts={{npcID=24937,x=0.582,y=0.176,zoneID=3483}},ends={{npcID=24937,x=0.582,y=0.176,zoneID=3483}},coords={x=0.582,y=0.176,source="quest_giver",zoneID=3483},questType="standard"},
[11517] = {id=11517,name="Report to Nasuun",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=3703,description="I am most glad that you are here, ! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland. My liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation. Please, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.",questType="standard"},
[11520] = {id=11520,name="Discovering Your Roots",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=3519,description="Greetings, . I'm afraid I have little to offer here until my reagents are stocked. Of the supplies I require, there is a special reagent, razorthorn root , that is particularly difficult to harvest. Fortunately, I know a secret.... Using the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root. To find the roots, travel to Outland and fly northeast from Shattrath until you reach Razorthorn Rise.",questType="standard"},
[11521] = {id=11521,name="Rediscovering Your Roots",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3519,description="My stocks are presently sufficient, but I'll need plenty of razorthorn roots to keep up with the demand. Collecting the roots is difficult, but I know a special method of extraction. Using the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root. To find the roots, travel to Outland and fly northeast from Shattrath until you reach Razorthorn Rise. Return to me, , once you have collected five of the roots.",starts={{npcID=24975,x=0.514,y=0.326,zoneID=4080}},ends={{npcID=24975,x=0.514,y=0.326,zoneID=4080}},coords={x=0.514,y=0.326,source="quest_giver",zoneID=4080},questType="standard"},
[11523] = {id=11523,name="Arm the Wards!",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="We've succeeded in reactivating the crystal wards around the sanctum, but why stop there? We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards. Hunt them down and get the mana remnants they carry. Use the remnants to energize the sanctum wards; the safety of our operation depends on it.",starts={{npcID=24967,x=0.474,y=0.306,zoneID=4080}},ends={{npcID=24967,x=0.474,y=0.306,zoneID=4080}},coords={x=0.474,y=0.306,source="quest_giver",zoneID=4080},questType="standard"},
[11524] = {id=11524,name="Erratic Behavior",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=4080,description="We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor. The loose energy from the Sunwell has caused the sentries that patrol this island to malfunction. The crystal cores that control their behavior are damaged beyond repair. I've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries. We will need all the help we can get.",questType="standard"},
[11525] = {id=11525,name="Further Conversions",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="My plan to replace the damaged crystals on the erratic sentries has been a success. We've managed to take the Sun's Reach Sanctum with their help. I've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries. We'll deploy them to other locations once they're converted.",starts={{npcID=24965,x=0.472,y=0.306,zoneID=4080}},ends={{npcID=24965,x=0.472,y=0.306,zoneID=4080}},coords={x=0.472,y=0.306,source="quest_giver",zoneID=4080},questType="standard"},
[11526] = {id=11526,name="The Missing Magistrix",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3483,description="We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here. She never returned. Take this scroll we found on one of the enemy corpses. We believe it will grant you access through the portal. Once through, find Magistrix Seyla and aid her in any way you can.",starts={{npcID=24967,x=0.474,y=0.306,zoneID=4080}},ends={{npcID=24937,x=0.582,y=0.176,zoneID=3483}},coords={x=0.474,y=0.306,source="quest_giver",zoneID=4080},questType="standard"},
[11531] = {id=11531,name="Strange Engine Part",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3521,description="This strange engine part doesn't look like it fits in a steam pump, much less anything else you've seen. Perhaps K. Lee Smallfry might know something about it.",ends={{npcID=17634,x=0.686,y=0.502,zoneID=3521}},questType="standard"},
[11532] = {id=11532,name="Distraction at the Dead Scar",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=4080,description="The Legion will move against us as soon as their forces to the south are freed up. The Scourge at the Dead Scar are keeping their forces occupied at the moment. It won't last long, however. I want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges . If all goes well, they won't even notice us taking the armory from Kael's lackeys. Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.",questType="standard"},
[11533] = {id=11533,name="The Air Strikes Must Continue",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar. As a matter of fact, it's gone so well that we're going to continue our air strikes against them. Take these arcane charges and use them against their forces. Talk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.",starts={{npcID=25057,x=0.476,y=0.352,zoneID=4080}},ends={{npcID=25057,x=0.476,y=0.352,zoneID=4080}},coords={x=0.476,y=0.352,source="quest_giver",zoneID=4080},questType="standard"},
[11534] = {id=11534,name="Report to Nasuun",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="I am most glad that you are here, ! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland. My liege lord, Exarch Nasuun , is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it. Please, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.",starts={{npcID=25034,x=0.472,y=0.35,zoneID=4080}},ends={{npcID=24932,x=0.492,y=0.424,zoneID=3703}},coords={x=0.472,y=0.35,source="quest_giver",zoneID=4080},questType="standard"},
[11535] = {id=11535,name="Making Ready",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=4080,description="Supplies are inbound, or so I'm told. Regardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have. As for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons. There are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....",questType="standard"},
[11536] = {id=11536,name="Don't Stop Now....",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="Now that we have an anvil, I can really get to work. No matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here. There are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....",starts={{npcID=25046,x=0.506,y=0.408,zoneID=4080}},ends={{npcID=25046,x=0.506,y=0.408,zoneID=4080}},coords={x=0.506,y=0.408,source="quest_giver",zoneID=4080},questType="standard"},
[11537] = {id=11537,name="The Battle Must Go On",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="We must continue to defeat and demoralize the armies of the Legion. The emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions. The enemy rallies around them for they fear them more than they fear us. Today we will change that. Take this banner and slay the demons of the Legion. When you meet the emissary, slay and impale him.",starts={{npcID=25061,x=0.476,y=0.352,zoneID=4080}},ends={{npcID=25061,x=0.476,y=0.352,zoneID=4080}},coords={x=0.476,y=0.352,source="quest_giver",zoneID=4080},questType="standard"},
[11538] = {id=11538,name="The Battle for the Sun's Reach Armory",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=4080,description="The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation. As long as their morale remains high we will not wrest the building from their control. The emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions. The enemy rallies around them for they fear them more than they fear us. Today we will change that. Take this banner and slay the demons of the Legion. When you meet the emissary, slay and impale him.",questType="standard"},
[11539] = {id=11539,name="Taking the Harbor",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=4080,description="One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village. The harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help. Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.",questType="standard"},
[11540] = {id=11540,name="Crush the Dawnblade",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="We've driven the Dawnblade army out of the Sun's Reach Harbor. Sun's Reach is ours in its entirety. Yet somehow... I'm not entirely satisfied. I want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants. They sealed their fate when they followed Kael to this place.",starts={{npcID=25069,x=0.494,y=0.402,zoneID=4080}},ends={{npcID=25069,x=0.494,y=0.402,zoneID=4080}},coords={x=0.494,y=0.402,source="quest_giver",zoneID=4080},questType="standard"},
[11541] = {id=11541,name="Disrupt the Greengill Coast",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs. It's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in. , I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free. My guess is that the murlocs will be incensed and turn on their masters.",starts={{npcID=25088,x=0.538,y=0.342,zoneID=4080}},ends={{npcID=25088,x=0.538,y=0.342,zoneID=4080}},coords={x=0.538,y=0.342,source="quest_giver",zoneID=4080},questType="standard"},
[11542] = {id=11542,name="Intercept the Reinforcements",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=4080,description="We're making a push to solidify our control of Sun's Reach by capturing the harbor next. Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there. Take this oil and secure a dragonhawk from Ayren Cloudbreaker. You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire. Land in one of the ships and attack the reservists. With their ship sails on fire they won't be able to mount much of a defense.",questType="standard"},
[11543] = {id=11543,name="Keeping the Enemy at Bay",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="We've managed to capture Sun's Reach in its entirety. Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor. Take this oil and secure a dragonhawk from Ayren Cloudbreaker. You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire. Land in one of the ships and attack the reservists. With their ship sails on fire they won't be able to mount much of a defense.",starts={{npcID=25108,x=0.504,y=0.39,zoneID=4080}},ends={{npcID=25108,x=0.504,y=0.39,zoneID=4080}},coords={x=0.504,y=0.39,source="quest_giver",zoneID=4080},questType="standard"},
[11544] = {id=11544,name="Ata'mal Armaments",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but is now overrun by fel orcs. They have dug up the special ore from that place and created corrupted weapons and armor. I need the armaments to form an alloy with the naga ore. Our anchorites have blessed my anvil with the ability to cleanse them. Retrieve the armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, breaking down and purifying them upon my anvil, and then hand me the cleansed results.",starts={{npcID=25046,x=0.506,y=0.408,zoneID=4080}},ends={{npcID=25046,x=0.506,y=0.408,zoneID=4080}},coords={x=0.506,y=0.408,source="quest_giver",zoneID=4080},questType="standard"},
[11545] = {id=11545,name="A Charitable Donation",level=25,requiredLevel=25,faction="none",expansion=1,zoneID=4080,description="We've taken Sun's Reach from the enemy and our final victory is at hand. The cost was high and many brave combatants gave their lives so we could achieve this. It is my goal to ensure that those who perished in combat are not forgotten. I ask that you take a moment to consider making a donation towards a memorial fund. Any leftover gold will go to the widows and orphans of the fallen.",questType="standard"},
[11546] = {id=11546,name="Open for Business",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="Welcome, . There are a number of ways I can assist you in your efforts here. For example, I've recently discovered a recipe for a unique elixir. The bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites. Bring me a sample from the nearby bushes and I'll show you what I mean.",starts={{npcID=24975,x=0.514,y=0.326,zoneID=4080}},ends={{npcID=24975,x=0.514,y=0.326,zoneID=4080}},coords={x=0.514,y=0.326,source="quest_giver",zoneID=4080},questType="standard"},
[11547] = {id=11547,name="Know Your Ley Lines",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="Freeloaders! You all want instant gratification - never giving thought to the effort required to create even the simplest of portals. Perhaps a little education will instill a bit of gratitude for my ceaseless efforts. Take this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast. Perhaps then you'll appreciate your precious translocations....",starts={{npcID=25133,x=0.476,y=0.352,zoneID=4080}},ends={{npcID=25133,x=0.476,y=0.352,zoneID=4080}},coords={x=0.476,y=0.352,source="quest_giver",zoneID=4080},questType="standard"},
[11548] = {id=11548,name="Your Continued Support",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="We've built a memorial to honor those slain in battle. It's but a small consolation to the families that lost their loved ones. I am taking up a collection to aid the orphans and spouses of our war heroes. If you can spare a small donation it would go a long way.",starts={{npcID=25112,x=0.484,y=0.366,zoneID=4080}},ends={{npcID=25112,x=0.484,y=0.366,zoneID=4080}},coords={x=0.484,y=0.366,source="quest_giver",zoneID=4080},questType="standard"},
[11549] = {id=11549,name="A Magnanimous Benefactor",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,description="You've done so much for us, . We greatly appreciate your assistance. You might have noticed Anchorite Ayuri's efforts outside. She has a big heart and is very convincing, but the donations do not quite add up to what she had expected. If you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide. What do you say?",starts={{npcID=25163,x=0.512,y=0.332,zoneID=4080}},ends={{npcID=25163,x=0.512,y=0.332,zoneID=4080}},coords={x=0.512,y=0.332,source="quest_giver",zoneID=4080},questType="standard"},
[11550] = {id=11550,name="Enter, the Deceiver...",level=30,requiredLevel=30,faction="alliance",expansion=1,zoneID=4080,description="Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival. The object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now. Report to Archmage Ne'thul at the Isle of Quel'Danas , north of Quel'Thalas.",ends={{npcID=25169,x=0.502,y=0.282,zoneID=4080}},questType="standard"},
[11554] = {id=11554,name="A Friend in the Frontlines",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,mapID=122,starts={{npcID=25032,x=0.472,y=0.306,mapID=122}},ends={{npcID=25032,x=0.472,y=0.306,mapID=122}},coords={x=0.472,y=0.306,source="quest_giver",mapID=122},questType="standard"},
[11555] = {id=11555,name="Honored by Your Allies",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,mapID=122,starts={{npcID=25032,x=0.472,y=0.306,mapID=122}},ends={{npcID=25032,x=0.472,y=0.306,mapID=122}},coords={x=0.472,y=0.306,source="quest_giver",mapID=122},questType="standard"},
[11556] = {id=11556,name="Revered in the Field of Battle",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,mapID=122,starts={{npcID=25032,x=0.472,y=0.306,mapID=122}},ends={{npcID=25032,x=0.472,y=0.306,mapID=122}},coords={x=0.472,y=0.306,source="quest_giver",mapID=122},questType="standard"},
[11557] = {id=11557,name="Exalted Among All Combatants",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=4080,mapID=122,starts={{npcID=25032,x=0.472,y=0.306,mapID=122}},ends={{npcID=25032,x=0.472,y=0.306,mapID=122}},coords={x=0.472,y=0.306,source="quest_giver",mapID=122},questType="standard"},
[11665] = {id=11665,name="Crocolisks in the City",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3519,description="Hello . I'm glad you've stopped by to talk to this old man--there's trouble back home. A traveling merchant recently sold a batch of baby crocolisks to some gullible children. Crocolisks are wild beasts, and many have escaped and now lurk in city waterways. Grab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me. I'm anxious to see one.",starts={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},ends={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},coords={x=0.386,y=0.128,source="quest_giver",zoneID=3519},questType="standard"},
[11666] = {id=11666,name="Bait Bandits",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3519,description="You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests. But here's one you haven't heard of: the blackfin darter . The fish is notoriously crafty and difficult to catch. You have to pull your line at the last possible second, because they nibble at the bait before they take it. Drop your line in the rivers of Terokkar and bring me a blackfin darter . Avoid the lakes, as the blackfin only thrive in moving water.",starts={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},ends={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},coords={x=0.386,y=0.128,source="quest_giver",zoneID=3519},questType="standard"},
[11667] = {id=11667,name="The One That Got Away",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3519,description="Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand. They grow their entire lives and are well known as fighters. Years ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped. A fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.",starts={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},ends={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},coords={x=0.386,y=0.128,source="quest_giver",zoneID=3519},questType="standard"},
[11668] = {id=11668,name="Shrimpin' Ain't Easy",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3519,description="There's a lot of big fish in the Zangarmarsh lakes. Ever wonder what they eat? Shrimp. Giant freshwater shrimp . The Rokk tells me the dishes you can make with shrimp are nearly endless. But shrimp are too small to catch with a fishing line. So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.",starts={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},ends={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},coords={x=0.386,y=0.128,source="quest_giver",zoneID=3519},questType="standard"},
[11669] = {id=11669,name="Felblood Fillet",level=30,requiredLevel=30,faction="both",expansion=1,zoneID=3519,description="This old man is going hunting soon. I'm gonna take down a mammoth shark off the coast of Azshara. The thing is, I need a toxin that'll stay on a spear tip while it's underwater. To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper. Such a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley. Bring me back a whopper and I'll be a happy old man.",starts={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},ends={{npcID=25580,x=0.386,y=0.128,zoneID=3519}},coords={x=0.386,y=0.128,source="quest_giver",zoneID=3519},questType="standard"},
[11875] = {id=11875,name="Gaining the Advantage",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="The troops of the Shattered Sun Offensive will need every advantage they can get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils which will strengthen the blades and armor of our troops. The key ingredient, nether residue , pervades Outland -- if you know where to look. Any master herbalist, skinner, or miner who knows the signs can gather it while plying trade. Those herbs, ores, and beasts native to Outland may all bear the residue.",starts={{npcID=19202,x=0.626,y=0.358,zoneID=3703}},ends={{npcID=19202,x=0.626,y=0.358,zoneID=3703}},coords={x=0.626,y=0.358,source="quest_giver",zoneID=3703},questType="standard"},
[11877] = {id=11877,name="Sunfury Attack Plans",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="As we press the offensive on Quel'Danas, we've discovered that Kael'thas' minions are planning a counterattack. By ordering the Sunfury blood elves, based in Netherstorm , to attack our operations in Outland, he hopes to draw troops and attention away from the Sunwell. We must not allow this to happen, . Each and every blade is needed on the front lines. Go to Netherstorm and capture their attack plans. Any of the Sunfury blood elves up there could be in possession of the plans. Good luck, .",starts={{npcID=25140,x=0.626,y=0.36,zoneID=3703}},ends={{npcID=25140,x=0.626,y=0.36,zoneID=3703}},coords={x=0.626,y=0.36,source="quest_giver",zoneID=3703},questType="standard"},
[11880] = {id=11880,name="The Multiphase Survey",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3703,description="I'm sure that 'gnomish inventor' is a crackpot. He was babbling about some dark distortions that have begun to appear in the Spirit Fields around Oshu'gun in Nagrand . According to him, these, uh, multiphase... um, spectro-goggles will allow the wearer to see the distortions and take readings from them. He insisted that recording this data was fundamental to our campaign at the Sunwell. I think he's nuts, but I'm under orders to investigate anything that might help. Would you mind taking some readings?",starts={{npcID=19475,x=0.614,y=0.522,zoneID=3703}},ends={{npcID=19475,x=0.614,y=0.522,zoneID=3703}},coords={x=0.614,y=0.522,source="quest_giver",zoneID=3703},questType="standard"},
[11885] = {id=11885,name="Adversarial Blood",level=15,requiredLevel=15,faction="both",expansion=1,zoneID=3519,description="The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress , Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager . They will all need to be slain before Terokk returns to this world. You will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis. These are powerful beings you will be facing; you would do well to bring friends.",starts={{npcID=23306,x=0.642,y=0.668,zoneID=3519}},ends={{npcID=23306,x=0.642,y=0.668,zoneID=3519}},coords={x=0.642,y=0.668,source="quest_giver",zoneID=3519},questType="group"},
[11933] = {id=11933,name="Stealing the Exodar's Flame",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=3703,description="This flame, stolen from the heart of the Exodar itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...",ends={{npcID=16818,x=0.62,y=0.668,zoneID=85},{npcID=16818,x=0.674,y=0.08,zoneID=1497},{npcID=16818,x=0.478,y=0.384,zoneID=1637},{npcID=16818,x=0.214,y=0.278,zoneID=1638},{npcID=16818,x=0.698,y=0.426,zoneID=3487},{npcID=16818,x=0.62,y=0.322,zoneID=3703}},questType="standard"},
[11935] = {id=11935,name="Stealing Silvermoon's Flame",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3703,description="This flame, stolen from Silvermoon, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...",ends={{npcID=16817,x=0.496,y=0.72,zoneID=1519},{npcID=16817,x=0.64,y=0.258,zoneID=1537},{npcID=16817,x=0.622,y=0.486,zoneID=1657},{npcID=16817,x=0.414,y=0.252,zoneID=3557},{npcID=16817,x=0.612,y=0.322,zoneID=3703}},questType="standard"},
[11954] = {id=11954,name="Striking Back",level=1,requiredLevel=1,faction="both",expansion=1,zoneID=3483,description="We must act to preserve the balance! Time is against us. In order to ensure Ahune's success, the cult has established a base near the Dark Portal itself in Draenor. They use ice stones to coordinate the frost lord's arrival. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's templar protectors and destroy it. Perhaps this forestalling action will be enough...",starts={{npcID=26221,x=0.62,y=0.678,zoneID=85},{npcID=26221,x=0.67,y=0.13,zoneID=1497},{npcID=26221,x=0.494,y=0.72,zoneID=1519},{npcID=26221,x=0.648,y=0.274,zoneID=1537},{npcID=26221,x=0.472,y=0.376,zoneID=1637},{npcID=26221,x=0.212,y=0.244,zoneID=1638},{npcID=26221,x=0.622,y=0.492,zoneID=1657},{npcID=26221,x=0.688,y=0.426,zoneID=3487},{npcID=26221,x=0.432,y=0.258,zoneID=3557},{npcID=26221,x=0.604,y=0.308,zoneID=3703}},ends={{npcID=26221,x=0.62,y=0.678,zoneID=85},{npcID=26221,x=0.67,y=0.13,zoneID=1497},{npcID=26221,x=0.494,y=0.72,zoneID=1519},{npcID=26221,x=0.648,y=0.274,zoneID=1537},{npcID=26221,x=0.472,y=0.376,zoneID=1637},{npcID=26221,x=0.212,y=0.244,zoneID=1638},{npcID=26221,x=0.622,y=0.492,zoneID=1657},{npcID=26221,x=0.688,y=0.426,zoneID=3487},{npcID=26221,x=0.432,y=0.258,zoneID=3557},{npcID=26221,x=0.604,y=0.308,zoneID=3703}},coords={x=0.62,y=0.678,source="quest_giver",zoneID=85},questType="standard"},
[11971] = {id=11971,name="The Spinner of Summer Tales",level=1,requiredLevel=1,faction="horde",expansion=1,zoneID=85,description="Let there be no mistake, the festival is a time for fun and laughter! However it's important that you understand the origins of this holiday. Education should be sought out and savored! . The Festival Talespinner in the Horde capitals can guide your way. Go now and learn.",starts={{npcID=19169,x=0.542,y=0.508,zoneID=3430},{npcID=19169,x=0.778,y=0.576,zoneID=3487},{npcID=19175,x=0.516,y=0.752,zoneID=1637},{npcID=19176,x=0.402,y=0.488,zoneID=1637},{npcID=19177,x=0.49,y=0.612,zoneID=1637},{npcID=19176,x=0.41,y=0.558,zoneID=1638},{npcID=19178,x=0.632,y=0.48,zoneID=1497},{npcID=20102,x=0.69,y=0.706,zoneID=17},{npcID=20102,x=0.406,y=0.844,zoneID=67},{npcID=20102,x=0.522,y=0.284,zoneID=440},{npcID=20102,x=0.598,y=0.496,zoneID=618},{npcID=20102,x=0.338,y=0.64,zoneID=3523},{npcID=20102,x=0.53,y=0.504,zoneID=3703},{npcID=20102,x=0.416,y=0.742,zoneID=5287}},ends={{npcID=16818,x=0.698,y=0.426,zoneID=3487},{npcID=16818,x=0.478,y=0.384,zoneID=1637},{npcID=16818,x=0.214,y=0.278,zoneID=1638},{npcID=16818,x=0.674,y=0.08,zoneID=1497},{npcID=16818,x=0.62,y=0.322,zoneID=3703},{npcID=16818,x=0.62,y=0.668,zoneID=85}},coords={x=0.542,y=0.508,source="quest_giver",zoneID=3430},questType="standard"},
[11972] = {id=11972,name="Shards of Ahune",level=1,requiredLevel=1,faction="both",expansion=1,zoneID=3717,mapID=102,description="These shards pulse with foreboding. Do they hold the last essence of the Frost Lord?",questType="standard"},
[12012] = {id=12012,name="Inform the Elder",level=1,requiredLevel=1,faction="both",expansion=1,zoneID=3703,description="This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!",starts={{npcID=25324,x=0.146,y=0.226,zoneID=331}},ends={{npcID=26221,x=0.62,y=0.678,zoneID=85},{npcID=26221,x=0.67,y=0.13,zoneID=1497},{npcID=26221,x=0.494,y=0.72,zoneID=1519},{npcID=26221,x=0.648,y=0.274,zoneID=1537},{npcID=26221,x=0.472,y=0.376,zoneID=1637},{npcID=26221,x=0.212,y=0.244,zoneID=1638},{npcID=26221,x=0.622,y=0.492,zoneID=1657},{npcID=26221,x=0.688,y=0.426,zoneID=3487},{npcID=26221,x=0.432,y=0.258,zoneID=3557},{npcID=26221,x=0.604,y=0.308,zoneID=3703}},coords={x=0.146,y=0.226,source="quest_giver",zoneID=331},questType="standard"},
[12133] = {id=12133,name="Smash the Pumpkin",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3524,description="This large jack-o'-lantern rests in the middle of the village. It eyes those who look upon it, betraying a dark menace within. Smashing the pumpkin reveals an old, scorched holy symbol .",starts={{npcID=186887,x=0.535,y=0.505,zoneID=1},{npcID=186887,x=0.424,y=0.658,zoneID=12},{npcID=186887,x=0.526,y=0.424,zoneID=14},{npcID=186887,x=0.609,y=0.527,zoneID=85},{npcID=186887,x=0.475,y=0.463,zoneID=3430},{npcID=186887,x=0.489,y=0.51,zoneID=3524}},ends={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},coords={x=0.535,y=0.505,source="quest_giver",zoneID=1},questType="standard"},
[12135] = {id=12135,name="\"Let the Fires Come!\"",level=10,requiredLevel=10,faction="alliance",expansion=1,zoneID=3524,description="You must help us! The Headless Horseman will attack the village at any moment! Fires will be everywhere! The children aren't safe! Please, , will you face the fires of the Headless Horseman? When he comes, you must join the fire brigade. Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze. If you put out all the fires then we may yet be saved!",starts={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},ends={{npcID=24519,x=0.532,y=0.514,zoneID=1},{npcID=24519,x=0.426,y=0.644,zoneID=12},{npcID=24519,x=0.492,y=0.514,zoneID=3524}},coords={x=0.532,y=0.514,source="quest_giver",zoneID=1},questType="standard"},
